use crate::flow::build_graph;
use crate::host::{HostProfile, excel};
use crate::lexer::{Token, TokenKind, lex};
use crate::model::*;
use crate::parser::{is_def_type_directive_keyword, parse_expression_source, parse_module};
use crate::paths::{
    associate_data_access_paths, associate_data_access_predicates, associate_data_flow_paths,
    associate_interprocedural_argument_value_paths, associate_interprocedural_byref_write_paths,
    associate_interprocedural_data_flow_paths, associate_interprocedural_error_paths,
    associate_interprocedural_return_paths, build_static_private_parameter_values,
    compose_interprocedural_argument_value_paths, compose_interprocedural_byref_value_paths,
    compose_interprocedural_return_paths, decision_rows, derive_data_access_value_flows,
    derive_path_alias_dispatches, derive_path_aliases, derive_path_value_flows,
    enrich_interprocedural_return_values, enumerate_graph_paths,
    enumerate_graph_paths_for_project_procedure_with_calls, extend_interprocedural_return_chains,
    unique_path_procedure,
};
use crate::preprocessor::{PreprocessOptions, preprocess};
use crate::source::mask_designer_preamble;
use crate::typecheck::{
    array_index_diagnostics, declared_parameter_type, declared_symbol_type,
    effective_project_type_name, infer_assignment_types, infer_expression_type,
    set_assignment_diagnostics, user_type_owner_index, with_expression_diagnostics,
};
use std::collections::{HashMap, HashSet, VecDeque};

#[derive(Clone, Debug, Default)]
pub struct AnalysisOptions {
    pub limits: Limits,
    pub conditional_constants: std::collections::BTreeMap<String, String>,
    /// Names exposed by referenced VBA projects or Automation type libraries.
    /// External declarations remain unresolved, but these names participate in
    /// project-level symbol collision checks.
    pub project_references: Vec<String>,
    pub host_profile: HostProfile,
}

pub fn analyze(sources: &[SourceUnit], options: &AnalysisOptions) -> Result<Analysis, String> {
    analyze_with_project_metadata(sources, options, None, "exported_vba_text", &HashMap::new())
}

pub(crate) fn analyze_with_project_metadata(
    sources: &[SourceUnit],
    options: &AnalysisOptions,
    project_name: Option<String>,
    input_kind: &str,
    module_kinds: &HashMap<String, String>,
) -> Result<Analysis, String> {
    if sources.is_empty() {
        return Err("at least one VBA source unit is required".into());
    }
    if sources.len() > options.limits.max_modules {
        return Err("source module count exceeds configured limit".into());
    }
    let mut project = Project {
        name: project_name,
        input_kind: input_kind.into(),
        references: options.project_references.clone(),
        conditional_constants: options.conditional_constants.clone(),
        ..Project::default()
    };
    let mut diagnostics = Vec::new();
    let mut names = HashSet::new();
    let mut option_explicit = Vec::new();
    let mut conditional_unknown = Vec::new();
    let mut total_source_bytes = 0usize;
    let mut total_tokens = 0usize;
    for source in sources {
        if source.text.len() > options.limits.max_input_bytes {
            return Err(format!(
                "source unit {} exceeds configured input limit",
                source.name
            ));
        }
        let base = source
            .name
            .rsplit(['/', '\\'])
            .next()
            .unwrap_or(&source.name);
        let name = base.rsplit_once('.').map(|x| x.0).unwrap_or(base);
        let parse_source = mask_designer_preamble(&source.name, &source.text);
        let preprocessed = preprocess(
            &source.name,
            &parse_source,
            &PreprocessOptions {
                constants: options.conditional_constants.clone(),
            },
        );
        total_source_bytes = total_source_bytes
            .checked_add(preprocessed.text.len())
            .ok_or("total VBA source size overflow")?;
        if total_source_bytes > options.limits.max_input_bytes {
            return Err("total VBA source size exceeds configured limit".into());
        }
        let (tokenized, _) = lex(&preprocessed.text, options.limits.max_tokens);
        total_tokens = total_tokens
            .checked_add(tokenized.len())
            .ok_or("total VBA token count overflow")?;
        if total_tokens > options.limits.max_tokens {
            return Err("total VBA token count exceeds configured limit".into());
        }
        conditional_unknown.push(preprocessed.had_unknown_condition);
        let mut module = parse_module(
            name,
            &source.name,
            &preprocessed.text,
            options.limits.max_tokens,
            options.limits.max_nesting,
        );
        module.module_kind = module_kinds.get(&canon(&module.name)).cloned().or_else(|| {
            base.rsplit_once('.')
                .and_then(|(_, ext)| match ext.to_ascii_lowercase().as_str() {
                    "bas" => Some("standard".into()),
                    "cls" => Some("class".into()),
                    "frm" => Some("form".into()),
                    _ => None,
                })
        });
        let (module_options, option_diagnostics) = parse_module_options(
            &tokenized,
            &module,
            &source.name,
            options.host_profile,
            preprocessed.had_unknown_condition,
        );
        module.options = module_options;
        let (implicit_types, implicit_type_diagnostics) = parse_implicit_types(
            &tokenized,
            &module,
            &source.name,
            preprocessed.had_unknown_condition,
        );
        module.implicit_types = implicit_types;
        option_explicit.push(module.options.explicit);
        module.diagnostics.extend(option_diagnostics);
        module.diagnostics.extend(implicit_type_diagnostics);
        module.conditional_constants = preprocessed.conditional_constants;
        module.analysis_text = preprocessed.text;
        module.text = source.text.clone();
        module.diagnostics.extend(preprocessed.diagnostics);
        if !names.insert(canon(&module.name)) {
            diagnostics.push(Diagnostic {
                code: "VBA2001",
                severity: Severity::Error,
                message: format!("duplicate module name '{}'", module.name),
                source: source.name.clone(),
                span: Span::default(),
            });
        }
        diagnostics.append(&mut module.diagnostics);
        project.modules.push(module);
    }
    populate_enum_member_values(&mut project, &mut diagnostics);
    populate_cross_module_enum_member_values(&mut project, &mut diagnostics);
    validate_enum_member_name_collisions_and_initializer_order(&project, &mut diagnostics);
    validate_udt_name_collisions(&project, &mut diagnostics);
    validate_enum_type_name_collisions(&project, &mut diagnostics);
    let mut procedure_index: HashMap<String, Vec<(usize, usize)>> = HashMap::new();
    for (mi, m) in project.modules.iter().enumerate() {
        for (pi, p) in m.procedures.iter().enumerate() {
            procedure_index
                .entry(canon(&p.name))
                .or_default()
                .push((mi, pi));
        }
    }
    for (module_index, m) in project.modules.iter().enumerate() {
        validate_implemented_interfaces(&project, module_index, &mut diagnostics);
        validate_event_semantics(&project, module_index, &mut diagnostics);
        validate_excel_document_event_signatures(
            &project,
            module_index,
            m,
            options.host_profile,
            &mut diagnostics,
        );
        validate_excel_application_event_signatures(
            &project,
            module_index,
            m,
            options.host_profile,
            &mut diagnostics,
        );
        validate_default_member_attributes(&project, module_index, &mut diagnostics);
        validate_property_accessor_contracts(&project, module_index, &mut diagnostics);
        validate_procedure_name_collisions(m, &mut diagnostics);
        validate_global_namespace_attribute(&project, module_index, &mut diagnostics);
        validate_predeclared_instance_assignments(m, &mut diagnostics);
        let mut seen = HashMap::<String, Vec<(String, Span)>>::new();
        for p in &m.procedures {
            let mut procedure_labels = HashMap::new();
            validate_label_definitions(
                &p.statements,
                &mut procedure_labels,
                &mut diagnostics,
                &m.source_name,
            );
            let labels = procedure_labels.keys().cloned().collect::<HashSet<_>>();
            validate_jump_targets(&p.statements, &labels, &mut diagnostics, &m.source_name);
            let n = canon(&p.name);
            let declarations = seen.entry(n).or_default();
            let is_property = p.kind.to_ascii_lowercase().starts_with("property ");
            let previous = declarations
                .iter()
                .find(|(kind, _)| {
                    let previous_is_property = kind.to_ascii_lowercase().starts_with("property ");
                    !is_property || !previous_is_property || kind.eq_ignore_ascii_case(&p.kind)
                })
                .map(|(_, span)| *span);
            if let Some(previous) = previous {
                diagnostics.push(Diagnostic {
                    code: "VBA2002",
                    severity: if conditional_unknown[module_index]{Severity::Warning}else{Severity::Error},
                    message: if conditional_unknown[module_index]{format!("procedure '{}' may be duplicated across unresolved conditional-compilation branches (first declaration at line {})",p.name,previous.line)}else{format!("duplicate procedure '{}' (first declaration at line {})",p.name,previous.line)},
                    source: m.source_name.clone(),
                    span: p.span,
                });
            } else {
                declarations.push((p.kind.clone(), p.span));
            }
        }
        for d in &m.declarations {
            if let Some(t) = &d.type_name {
                validate_declared_type_name(
                    TypeValidationContext {
                        project: &project,
                        module_index,
                        module: m,
                        procedure: None,
                        host_profile: options.host_profile,
                    },
                    t,
                    d.span,
                    &mut diagnostics,
                );
            }
        }
        for p in &m.procedures {
            validate_parameter_rules(
                &p.name,
                &p.parameters,
                &m.source_name,
                p.kind.eq_ignore_ascii_case("property let")
                    || p.kind.eq_ignore_ascii_case("property set"),
                p.kind.eq_ignore_ascii_case("function")
                    || p.kind.eq_ignore_ascii_case("property get"),
                &mut diagnostics,
            );
            validate_optional_parameter_semantics(
                OptionalConstantContext {
                    project: &project,
                    module_index,
                    module: m,
                    procedure: Some(p),
                    parameters: &p.parameters,
                    host_profile: options.host_profile,
                },
                &p.name,
                &mut diagnostics,
            );
            validate_optional_deftype_parameter_defaults(
                m,
                &p.name,
                &p.parameters,
                &m.source_name,
                &mut diagnostics,
            );
            validate_array_operations(m, p, &mut diagnostics);
            validate_typeof_is_expressions(
                &project,
                module_index,
                m,
                p,
                options.host_profile,
                &mut diagnostics,
            );
            validate_preserve_constraints(m, p, &mut diagnostics);
            validate_local_declared_type_names(
                TypeValidationContext {
                    project: &project,
                    module_index,
                    module: m,
                    procedure: Some(p),
                    host_profile: options.host_profile,
                },
                &p.statements,
                &mut diagnostics,
            );
            for parameter in &p.parameters {
                if let Some(type_name) = &parameter.type_name {
                    validate_declared_type_name(
                        TypeValidationContext {
                            project: &project,
                            module_index,
                            module: m,
                            procedure: None,
                            host_profile: options.host_profile,
                        },
                        type_name,
                        parameter.span,
                        &mut diagnostics,
                    );
                }
            }
            if let Some(type_name) = &p.return_type {
                validate_declared_type_name(
                    TypeValidationContext {
                        project: &project,
                        module_index,
                        module: m,
                        procedure: None,
                        host_profile: options.host_profile,
                    },
                    type_name,
                    p.span,
                    &mut diagnostics,
                );
            }
        }
        for declaration in m
            .declarations
            .iter()
            .filter(|d| d.kind == "event" || d.kind == "external_declare")
        {
            validate_parameter_rules(
                &declaration.name,
                &declaration.parameters,
                &m.source_name,
                false,
                false,
                &mut diagnostics,
            );
            validate_optional_parameter_semantics(
                OptionalConstantContext {
                    project: &project,
                    module_index,
                    module: m,
                    procedure: None,
                    parameters: &declaration.parameters,
                    host_profile: options.host_profile,
                },
                &declaration.name,
                &mut diagnostics,
            );
            validate_optional_deftype_parameter_defaults(
                m,
                &declaration.name,
                &declaration.parameters,
                &m.source_name,
                &mut diagnostics,
            );
            for parameter in &declaration.parameters {
                if let Some(type_name) = &parameter.type_name {
                    validate_declared_type_name(
                        TypeValidationContext {
                            project: &project,
                            module_index,
                            module: m,
                            procedure: None,
                            host_profile: options.host_profile,
                        },
                        type_name,
                        parameter.span,
                        &mut diagnostics,
                    );
                }
            }
            if declaration.kind == "external_declare"
                && options.conditional_constants.iter().any(|(name, value)| {
                    name.eq_ignore_ascii_case("Win64") && constant_is_true(value)
                })
                && !declaration.is_ptr_safe
            {
                diagnostics.push(Diagnostic {
                    code: "VBA2057",
                    severity: Severity::Error,
                    message: format!(
                        "Declare '{}' is missing PtrSafe for the selected Win64 target",
                        declaration.name
                    ),
                    source: m.source_name.clone(),
                    span: declaration.span,
                });
            }
            if declaration.kind == "external_declare"
                && matches!(
                    m.module_kind.as_deref(),
                    Some(
                        "class"
                            | "form"
                            | "workbook_document"
                            | "worksheet_document"
                            | "class_or_document"
                    )
                )
                && !declaration.visibility.eq_ignore_ascii_case("private")
            {
                diagnostics.push(Diagnostic {
                    code: "VBA2058",
                    severity: Severity::Error,
                    message: format!(
                        "external Declare '{}' in an object module must be Private",
                        declaration.name
                    ),
                    source: m.source_name.clone(),
                    span: declaration.span,
                });
            }
        }
        project.metadata.insert(
            format!("module:{}:option_explicit", m.name),
            option_explicit[module_index].to_string(),
        );
        project.metadata.insert(
            format!("module:{}:conditional_compile_unknown", m.name),
            conditional_unknown[module_index].to_string(),
        );
    }
    let facts = collect_facts(
        &project,
        &procedure_index,
        &mut diagnostics,
        &options.limits,
        options.host_profile,
    );
    let entry_points = detect_entry_points(&project, options.host_profile);
    let mut control_flow: Vec<ControlFlowGraph> = Vec::new();
    for m in &project.modules {
        for p in &m.procedures {
            let mut graph = build_graph(m, p);
            let has_error_policy = graph
                .nodes
                .iter()
                .any(|node| matches!(node.kind.as_str(), "on_error" | "resume"));
            let host_entry_candidate = entry_points.iter().any(|entry| {
                entry.module.eq_ignore_ascii_case(&m.name)
                    && entry.procedure.eq_ignore_ascii_case(&p.name)
                    && crate::host::direct_host_entry_candidate(&entry.trigger)
            });
            let mut findings = Vec::new();
            if has_error_policy || host_entry_candidate {
                findings = crate::error_handling::
                    add_error_flow_edges_with_host_entry_candidate_and_findings(
                        &mut graph,
                        100_000,
                        host_entry_candidate,
                    );
            }
            let mut return_findings = findings
                .iter()
                .filter(|finding| {
                    finding.kind == crate::error_handling::ErrorFlowFindingKind::ReturnWithoutGoSub
                })
                .map(|finding| finding.node_id)
                .collect::<HashSet<_>>();
            for edge in &graph.edges {
                if edge
                    .condition
                    .as_deref()
                    .is_some_and(|condition| condition.contains("Return without an active GoSub"))
                    && return_findings.insert(edge.from)
                {
                    findings.push(crate::error_handling::ErrorFlowFinding {
                        node_id: edge.from,
                        kind: crate::error_handling::ErrorFlowFindingKind::ReturnWithoutGoSub,
                    });
                }
            }
            for finding in findings {
                match finding.kind {
                    crate::error_handling::ErrorFlowFindingKind::ResumeWithoutActiveError => {
                        let Some(node) = graph.nodes.get(finding.node_id) else {
                            graph.complete = false;
                            continue;
                        };
                        diagnostics.push(Diagnostic {
                            code: "VBA2122",
                            severity: Severity::Warning,
                            message: "Resume may be reached without an active error and raise runtime error 20; control-flow and fault-path feasibility are not proven".into(),
                            source: m.source_name.clone(),
                            span: node.span,
                        });
                    }
                    crate::error_handling::ErrorFlowFindingKind::ReturnWithoutGoSub => {
                        let Some(node) = graph.nodes.get(finding.node_id) else {
                            graph.complete = false;
                            continue;
                        };
                        diagnostics.push(Diagnostic {
                            code: "VBA2123",
                            severity: Severity::Warning,
                            message: "Return may be reached without a matching active GoSub and raise runtime error 3; control-flow and path feasibility are not proven".into(),
                            source: m.source_name.clone(),
                            span: node.span,
                        });
                    }
                }
            }
            if project
                .metadata
                .get(&format!("module:{}:conditional_compile_unknown", m.name))
                .is_some_and(|v| v == "true")
            {
                graph.complete = false;
            }
            control_flow.push(graph);
        }
    }
    let static_parameter_values = build_static_private_parameter_values(
        &project,
        &facts.calls,
        options.limits.max_path_value_flow_steps,
    );
    let mut paths = Vec::new();
    let mut decision_table = Vec::new();
    let mut path_budget = options.limits.max_paths;
    let mut path_enumeration_truncated = false;
    for graph in &control_flow {
        if path_budget == 0 {
            path_enumeration_truncated = true;
            break;
        }
        let local_limits = Limits {
            max_paths: path_budget,
            ..options.limits.clone()
        };
        let found = if let Some((module, procedure)) =
            unique_path_procedure(&project, &graph.module, &graph.procedure)
        {
            enumerate_graph_paths_for_project_procedure_with_calls(
                graph,
                &project,
                &facts.calls,
                &static_parameter_values,
                module,
                procedure,
                &local_limits,
            )
        } else {
            enumerate_graph_paths(graph, &local_limits)
        };
        path_budget = path_budget.saturating_sub(found.paths.len());
        path_enumeration_truncated |= found.truncated;
        decision_table.extend(decision_rows(graph, &found.paths));
        paths.extend(found.paths);
    }
    let data_flow_paths = associate_data_flow_paths(
        &facts.data_flow,
        &control_flow,
        &paths,
        options.limits.max_path_fact_associations,
        options.limits.max_path_fact_association_steps,
    );
    let interprocedural_data_flow_paths = associate_interprocedural_data_flow_paths(
        &project,
        &facts.data_flow,
        &data_flow_paths.facts,
        options.limits.max_path_value_flows,
        options.limits.max_path_value_flow_steps,
    );
    let interprocedural_argument_value_paths = associate_interprocedural_argument_value_paths(
        &project,
        &facts.calls,
        &facts.data_flow,
        &data_flow_paths.facts,
        &control_flow,
        &paths,
        &static_parameter_values,
        options.limits.max_path_value_flows,
        options.limits.max_path_value_flow_steps,
    );
    let interprocedural_argument_composition_paths = compose_interprocedural_argument_value_paths(
        &project,
        &interprocedural_argument_value_paths.facts,
        &control_flow,
        &paths,
        &facts.calls,
        &static_parameter_values,
        options.limits.max_path_value_flows,
        options.limits.max_path_value_flow_steps,
    );
    let mut interprocedural_return_paths = associate_interprocedural_return_paths(
        &facts.data_flow,
        &data_flow_paths.facts,
        &control_flow,
        &paths,
        &project,
        options.limits.max_path_value_flows,
        options.limits.max_path_value_flow_steps,
    );
    let mut interprocedural_return_compositions = compose_interprocedural_return_paths(
        &interprocedural_return_paths.facts,
        &facts.data_flow,
        &control_flow,
        &paths,
        &project,
        options.limits.max_path_value_flows,
        options.limits.max_path_value_flow_steps,
    );
    let return_chain_truncated = extend_interprocedural_return_chains(
        &interprocedural_return_paths.facts,
        &mut interprocedural_return_compositions.facts,
        &facts.data_flow,
        &control_flow,
        &paths,
        &project,
        options.limits.max_path_value_flows,
        options.limits.max_path_value_flow_steps,
        4,
    );
    interprocedural_return_compositions.truncated |= return_chain_truncated;
    let return_value_enrichment_truncated = enrich_interprocedural_return_values(
        &mut interprocedural_return_paths.facts,
        &mut interprocedural_return_compositions.facts,
        &facts.data_flow,
        &interprocedural_argument_value_paths.facts,
        &project,
        options.limits.max_path_value_flow_steps,
    );
    interprocedural_return_paths.truncated |= return_value_enrichment_truncated;
    interprocedural_return_compositions.truncated |= return_value_enrichment_truncated;
    let interprocedural_byref_write_paths = associate_interprocedural_byref_write_paths(
        &project,
        &facts.data_flow,
        &data_flow_paths.facts,
        options.limits.max_path_value_flows,
        options.limits.max_path_value_flow_steps,
    );
    let interprocedural_byref_value_paths = compose_interprocedural_byref_value_paths(
        &project,
        &facts.data_flow,
        &interprocedural_argument_value_paths.facts,
        &interprocedural_byref_write_paths.facts,
        options.limits.max_path_value_flows,
        options.limits.max_path_value_flow_steps,
    );
    let interprocedural_error_paths = associate_interprocedural_error_paths(
        &project,
        &facts.calls,
        &entry_points,
        &control_flow,
        &paths,
        options.limits.max_path_value_flows,
        options.limits.max_path_value_flow_steps,
    );
    let data_access_paths = associate_data_access_paths(
        &facts.data_accesses,
        &control_flow,
        &paths,
        options.limits.max_path_fact_associations,
        options.limits.max_path_fact_association_steps,
    );
    let data_access_path_facts = data_access_paths
        .facts
        .iter()
        .map(|fact| DataAccessPathFact {
            data_access_index: fact.data_flow_index,
            excel_worksheet_access_index: None,
            path_index: fact.path_index,
            path_position: fact.path_position,
            flow_node_id: fact.flow_node_id,
            module: fact.module.clone(),
            procedure: fact.procedure.clone(),
            conditions: fact.conditions.clone(),
            feasibility: fact.feasibility.clone(),
            path_complete: fact.path_complete,
            span: fact.span,
        })
        .collect::<Vec<_>>();
    let path_value_flows = derive_path_value_flows(
        &project,
        &facts.data_flow,
        &data_flow_paths.facts,
        options.limits.max_path_value_flows,
        options.limits.max_path_value_flow_steps,
    );
    let path_aliases = derive_path_aliases(
        &facts.data_flow,
        &data_flow_paths.facts,
        options.limits.max_path_value_flows,
        options.limits.max_path_value_flow_steps,
    );
    let path_alias_dispatches = derive_path_alias_dispatches(
        &project,
        &facts.calls,
        &facts.data_flow,
        &data_flow_paths.facts,
        &path_aliases.facts,
        options.limits.max_path_value_flows,
        options.limits.max_path_value_flow_steps,
    );
    let data_access_value_flows = derive_data_access_value_flows(
        &facts.data_accesses,
        &facts.data_flow,
        &data_access_path_facts,
        &data_flow_paths.facts,
        options.limits.max_data_access_value_flows,
        options.limits.max_data_access_value_flow_steps,
    );
    let data_access_predicates = associate_data_access_predicates(
        &facts.data_accesses,
        &control_flow,
        &paths,
        &data_access_path_facts,
    );
    let mut type_facts = infer_assignment_types(&project, options.host_profile);
    type_facts.extend(facts.type_facts);
    diagnostics.extend(set_assignment_diagnostics(&project, options.host_profile));
    diagnostics.extend(array_index_diagnostics(&project));
    diagnostics.extend(with_expression_diagnostics(&project, options.host_profile));
    for fact in type_facts
        .iter()
        .filter(|fact| fact.status == "invalid_longlong_implicit_coercion")
    {
        diagnostics.push(Diagnostic {
            code: "VBA2086",
            severity: Severity::Error,
            message: format!(
                "LongLong value assigned to '{}' cannot be implicitly Let-coerced to {}",
                fact.target,
                fact.target_type.as_deref().unwrap_or("the declared type")
            ),
            source: project
                .modules
                .iter()
                .find(|module| module.name.eq_ignore_ascii_case(&fact.module))
                .map(|module| module.source_name.clone())
                .unwrap_or_default(),
            span: fact.span,
        });
    }
    for fact in type_facts
        .iter()
        .filter(|fact| fact.status == "invalid_udt_let_coercion")
    {
        diagnostics.push(Diagnostic {
            code: "VBA2127",
            severity: Severity::Error,
            message: format!(
                "Value of declared type {} cannot be Let-coerced to '{}' of type {}",
                fact.value_type,
                fact.target,
                fact.target_type.as_deref().unwrap_or("the declared type")
            ),
            source: project
                .modules
                .iter()
                .find(|module| module.name.eq_ignore_ascii_case(&fact.module))
                .map(|module| module.source_name.clone())
                .unwrap_or_default(),
            span: fact.span,
        });
    }
    for fact in type_facts
        .iter()
        .filter(|fact| fact.status == "invalid_class_default_let_coercion")
    {
        diagnostics.push(Diagnostic {
            code: "VBA2132",
            severity: Severity::Error,
            message: format!(
                "Class expression has no default member value that can be Let-coerced to '{}' of type {}",
                fact.target,
                fact.target_type.as_deref().unwrap_or("the declared type")
            ),
            source: project
                .modules
                .iter()
                .find(|module| module.name.eq_ignore_ascii_case(&fact.module))
                .map(|module| module.source_name.clone())
                .unwrap_or_default(),
            span: fact.span,
        });
    }
    for fact in type_facts
        .iter()
        .filter(|fact| fact.status == "nothing_let_coercion_runtime_error")
    {
        diagnostics.push(Diagnostic {
            code: "VBA2128",
            severity: Severity::Warning,
            message: format!(
                "Let-assignment of Nothing to '{}' can raise runtime error 91",
                fact.target
            ),
            source: project
                .modules
                .iter()
                .find(|module| module.name.eq_ignore_ascii_case(&fact.module))
                .map(|module| module.source_name.clone())
                .unwrap_or_default(),
            span: fact.span,
        });
    }
    for fact in type_facts.iter().filter(|fact| {
        matches!(
            fact.status.as_str(),
            "null_let_coercion_runtime_error_13" | "null_let_coercion_runtime_error_94"
        )
    }) {
        let error_number = if fact.status.ends_with("_13") { 13 } else { 94 };
        diagnostics.push(Diagnostic {
            code: "VBA2131",
            severity: Severity::Warning,
            message: format!(
                "Let-coercion from Null to '{}' can raise runtime error {error_number}",
                fact.target
            ),
            source: project
                .modules
                .iter()
                .find(|module| module.name.eq_ignore_ascii_case(&fact.module))
                .map(|module| module.source_name.clone())
                .unwrap_or_default(),
            span: fact.span,
        });
    }
    for fact in type_facts
        .iter()
        .filter(|fact| fact.status == "string_literal_numeric_coercion_runtime_error_13")
    {
        diagnostics.push(Diagnostic {
            code: "VBA2135",
            severity: Severity::Warning,
            message: format!(
                "String literal Let-coercion to '{}' can raise runtime error 13",
                fact.target_type.as_deref().unwrap_or("the declared type")
            ),
            source: project
                .modules
                .iter()
                .find(|module| module.name.eq_ignore_ascii_case(&fact.module))
                .map(|module| module.source_name.clone())
                .unwrap_or_default(),
            span: fact.span,
        });
    }
    for fact in type_facts
        .iter()
        .filter(|fact| fact.status == "invalid_object_let_coercion")
    {
        diagnostics.push(Diagnostic {
            code: "VBA2129",
            severity: Severity::Error,
            message: format!(
                "Value of declared type {} cannot be Let-coerced to object target '{}' of type {}",
                fact.value_type,
                fact.target,
                fact.target_type.as_deref().unwrap_or("the declared type")
            ),
            source: project
                .modules
                .iter()
                .find(|module| module.name.eq_ignore_ascii_case(&fact.module))
                .map(|module| module.source_name.clone())
                .unwrap_or_default(),
            span: fact.span,
        });
    }
    for fact in type_facts
        .iter()
        .filter(|fact| fact.status == "invalid_array_let_coercion")
    {
        diagnostics.push(Diagnostic {
            code: "VBA2130",
            severity: Severity::Error,
            message: format!(
                "Array Let-coercion between value type {} and target '{}' is statically invalid",
                fact.value_type, fact.target
            ),
            source: project
                .modules
                .iter()
                .find(|module| module.name.eq_ignore_ascii_case(&fact.module))
                .map(|module| module.source_name.clone())
                .unwrap_or_default(),
            span: fact.span,
        });
    }
    let error_handling = collect_error_handling_facts(&project);
    for fact in &error_handling {
        if matches!(fact.operation.as_str(), "goto_label" | "resume_label")
            && fact.target_resolved == Some(false)
        {
            diagnostics.push(Diagnostic {
                code: "VBA2041",
                severity: Severity::Error,
                message: format!(
                    "label '{}' referenced by {} is not defined in this procedure",
                    fact.target.as_deref().unwrap_or(""),
                    fact.operation
                ),
                source: project
                    .modules
                    .iter()
                    .find(|m| m.name == fact.module)
                    .map(|m| m.source_name.clone())
                    .unwrap_or_default(),
                span: fact.span,
            });
        }
    }
    let semantic_analysis_complete = false; // VBA host libraries and some dynamic/runtime semantics remain open-world.
    Ok(Analysis {
        project,
        diagnostics,
        procedures: facts.procedures,
        references: facts.references,
        calls: facts.calls,
        data_accesses: facts.data_accesses,
        excel_worksheet_accesses: Vec::new(),
        semantic_analysis_complete,
        control_flow,
        data_flow: facts.data_flow,
        data_flow_paths: data_flow_paths.facts,
        data_flow_paths_truncated: data_flow_paths.truncated,
        data_flow_path_unassociated_count: data_flow_paths.unassociated_count,
        interprocedural_data_flow_paths: interprocedural_data_flow_paths.facts,
        interprocedural_data_flow_paths_truncated: interprocedural_data_flow_paths.truncated,
        interprocedural_argument_value_paths: interprocedural_argument_value_paths.facts,
        interprocedural_argument_value_paths_truncated: interprocedural_argument_value_paths
            .truncated,
        interprocedural_argument_composition_paths: interprocedural_argument_composition_paths
            .facts,
        interprocedural_argument_composition_paths_truncated:
            interprocedural_argument_composition_paths.truncated,
        interprocedural_return_paths: interprocedural_return_paths.facts,
        interprocedural_return_paths_truncated: interprocedural_return_paths.truncated,
        interprocedural_return_compositions: interprocedural_return_compositions.facts,
        interprocedural_return_compositions_truncated: interprocedural_return_compositions
            .truncated,
        interprocedural_byref_write_paths: interprocedural_byref_write_paths.facts,
        interprocedural_byref_write_paths_truncated: interprocedural_byref_write_paths.truncated,
        interprocedural_byref_value_paths: interprocedural_byref_value_paths.facts,
        interprocedural_byref_value_paths_truncated: interprocedural_byref_value_paths.truncated,
        interprocedural_error_paths: interprocedural_error_paths.facts,
        interprocedural_error_paths_truncated: interprocedural_error_paths.truncated,
        data_access_paths: data_access_path_facts,
        data_access_paths_truncated: data_access_paths.truncated,
        data_access_path_unassociated_count: data_access_paths.unassociated_count,
        path_value_flows: path_value_flows.facts,
        path_value_flows_truncated: path_value_flows.truncated,
        path_aliases: path_aliases.facts,
        path_aliases_truncated: path_aliases.truncated,
        path_alias_dispatches: path_alias_dispatches.facts,
        path_alias_dispatches_truncated: path_alias_dispatches.truncated,
        data_access_value_flows: data_access_value_flows.facts,
        data_access_value_flows_truncated: data_access_value_flows.truncated,
        data_access_predicates: data_access_predicates.facts,
        data_access_predicate_unassociated_count: data_access_predicates.unassociated_count,
        type_facts,
        error_handling,
        host_profile: options.host_profile,
        paths,
        decision_table,
        path_enumeration_truncated,
        entry_points,
    })
}

fn constant_is_true(value: &str) -> bool {
    let value = value.trim();
    value.eq_ignore_ascii_case("true") || value.parse::<i64>().is_ok_and(|number| number != 0)
}

fn parse_module_options(
    tokens: &[Token],
    module: &Module,
    source: &str,
    host_profile: HostProfile,
    had_unknown_condition: bool,
) -> (ModuleOptions, Vec<Diagnostic>) {
    let mut options = ModuleOptions::default();
    if had_unknown_condition
        && tokens.windows(2).any(|pair| {
            pair[0].text.eq_ignore_ascii_case("option")
                && pair[1].text.eq_ignore_ascii_case("compare")
        })
    {
        options.compare_valid = false;
    }
    let mut diagnostics = Vec::new();
    let mut seen_explicit = false;
    let mut seen_compare = false;
    let mut seen_base = false;
    let mut seen_private = false;
    let first_procedure = module
        .procedures
        .first()
        .map(|procedure| procedure.span.start);
    let mut line = Vec::new();
    let mut lines = Vec::new();
    for token in tokens {
        if matches!(token.kind, TokenKind::Newline | TokenKind::Eof) {
            if !line.is_empty() {
                lines.push(std::mem::take(&mut line));
            }
        } else {
            line.push(token);
        }
    }
    if !line.is_empty() {
        lines.push(line);
    }
    for line in lines {
        if !line
            .first()
            .is_some_and(|token| token.text.eq_ignore_ascii_case("option"))
        {
            continue;
        }
        let words = line
            .iter()
            .map(|token| canon(&token.text))
            .collect::<Vec<_>>();
        if first_procedure.is_some_and(|first| line[0].span.start > first) {
            diagnostics.push(Diagnostic {
                code: "VBA2066",
                severity: Severity::Error,
                message: "module Option statements must appear before all procedures".into(),
                source: source.into(),
                span: line_span_tokens(&line),
            });
            if words.get(1).is_some_and(|word| word == "base") {
                options.array_base_valid = false;
            }
            if words.get(1).is_some_and(|word| word == "compare") {
                options.compare_valid = false;
            }
        }
        match words.as_slice() {
            [_, explicit] if explicit == "explicit" => {
                if seen_explicit {
                    diagnostics.push(option_diagnostic(
                        "VBA2067",
                        "Option Explicit appears more than once in the module",
                        source,
                        &line,
                    ));
                }
                seen_explicit = true;
                options.explicit = true;
            }
            [_, compare, mode] if compare == "compare" => {
                if seen_compare {
                    options.compare_valid = false;
                    diagnostics.push(option_diagnostic(
                        "VBA2067",
                        "Option Compare appears more than once in the module",
                        source,
                        &line,
                    ));
                    continue;
                }
                seen_compare = true;
                match mode.as_str() {
                    "binary" => options.compare_mode = "Binary".into(),
                    "text" => options.compare_mode = "Text".into(),
                    "database" => {
                        options.compare_mode = "Database".into();
                        if host_profile == HostProfile::Excel {
                            options.compare_valid = false;
                            diagnostics.push(option_diagnostic(
                                "VBA2068",
                                "Option Compare Database is supported only by Microsoft Access",
                                source,
                                &line,
                            ));
                        }
                    }
                    _ => {
                        options.compare_valid = false;
                        diagnostics.push(option_diagnostic(
                            "VBA2068",
                            "Option Compare must be Binary, Text, or Database",
                            source,
                            &line,
                        ));
                    }
                }
                options.compare_explicit = true;
            }
            [_, base, value] if base == "base" => {
                if seen_base {
                    options.array_base_valid = false;
                    diagnostics.push(option_diagnostic(
                        "VBA2067",
                        "Option Base appears more than once in the module",
                        source,
                        &line,
                    ));
                    continue;
                }
                seen_base = true;
                match value.parse::<u8>() {
                    Ok(value @ 0..=1) => options.array_base = value,
                    _ => {
                        options.array_base_valid = false;
                        diagnostics.push(option_diagnostic(
                            "VBA2069",
                            "Option Base must be either 0 or 1",
                            source,
                            &line,
                        ));
                    }
                }
                options.array_base_explicit = true;
                if module.declarations.iter().any(|declaration| {
                    declaration.is_array && declaration.span.start < line[0].span.start
                }) {
                    options.array_base_valid = false;
                    diagnostics.push(option_diagnostic(
                        "VBA2071",
                        "Option Base must precede module-level array declarations",
                        source,
                        &line,
                    ));
                }
            }
            [_, private, module_word] if private == "private" && module_word == "module" => {
                if seen_private {
                    diagnostics.push(option_diagnostic(
                        "VBA2067",
                        "Option Private Module appears more than once in the module",
                        source,
                        &line,
                    ));
                }
                seen_private = true;
                options.private_module = true;
                if matches!(
                    module.module_kind.as_deref(),
                    Some(
                        "class"
                            | "form"
                            | "workbook_document"
                            | "worksheet_document"
                            | "class_or_document"
                            | "document_or_class"
                    )
                ) {
                    diagnostics.push(option_diagnostic(
                        "VBA2070",
                        "Option Private Module is not permitted in an object module",
                        source,
                        &line,
                    ));
                }
            }
            _ => {
                if words.get(1).is_some_and(|word| word == "base") {
                    options.array_base_valid = false;
                }
                if words.get(1).is_some_and(|word| word == "compare") {
                    options.compare_valid = false;
                }
                diagnostics.push(option_diagnostic(
                    "VBA2066",
                    "unrecognized or malformed module Option statement",
                    source,
                    &line,
                ));
            }
        }
    }
    (options, diagnostics)
}

fn parse_implicit_types(
    tokens: &[Token],
    module: &Module,
    source: &str,
    conditional_unknown: bool,
) -> (ImplicitTypeRules, Vec<Diagnostic>) {
    let mut rules = ImplicitTypeRules::default();
    let mut diagnostics = Vec::new();
    let mut line = Vec::new();
    let mut lines = Vec::new();
    for token in tokens {
        if matches!(token.kind, TokenKind::Newline | TokenKind::Eof) {
            if !line.is_empty() {
                lines.push(std::mem::take(&mut line));
            }
        } else {
            line.push(token);
        }
    }
    if !line.is_empty() {
        lines.push(line);
    }

    if conditional_unknown
        && let Some(line) = lines.iter().find(|line| {
            line.first()
                .is_some_and(|token| is_def_type_directive_keyword(&token.text))
        })
    {
        diagnostics.push(Diagnostic {
            code: "VBA2084",
            severity: Severity::Warning,
            message: "DefType defaults remain unresolved because conditional-compilation alternatives are unknown".into(),
            source: source.into(),
            span: line_span_tokens(line),
        });
        rules.valid = false;
        return (rules, diagnostics);
    }

    for line in lines {
        let Some(keyword) = line.first().map(|token| canon(&token.text)) else {
            continue;
        };
        if !is_def_type_directive_keyword(&keyword) {
            continue;
        }
        let span = line_span_tokens(&line);
        let in_procedure = module.procedures.iter().any(|procedure| {
            span.start >= procedure.span.start && span.start <= procedure.span.end
        });
        let after_procedure = module
            .procedures
            .first()
            .is_some_and(|procedure| span.start > procedure.span.start);
        let after_declaration = module
            .declarations
            .iter()
            .any(|declaration| declaration.span.start < span.start);
        if in_procedure || after_procedure || after_declaration {
            diagnostics.push(Diagnostic {
                code: "VBA2082",
                severity: Severity::Error,
                message: "DefType directives must appear at module level before declarations and procedures".into(),
                source: source.into(),
                span,
            });
            rules.valid = false;
            continue;
        }

        let Some(type_name) = implicit_type_for_directive(&keyword) else {
            diagnostics.push(Diagnostic {
                code: "VBA2080",
                severity: Severity::Error,
                message: format!(
                    "DefType directive '{}' is unsupported or malformed",
                    line[0].text
                ),
                source: source.into(),
                span,
            });
            rules.valid = false;
            continue;
        };
        let specs = split_def_type_specs(&line[1..]);
        if specs.is_empty() {
            diagnostics.push(Diagnostic {
                code: "VBA2080",
                severity: Severity::Error,
                message: format!(
                    "DefType directive '{}' requires at least one letter spec",
                    line[0].text
                ),
                source: source.into(),
                span,
            });
            rules.valid = false;
            continue;
        }

        let mut expanded = Vec::new();
        let mut universal_specs = 0usize;
        let mut malformed = false;
        for spec in specs {
            match expand_def_type_spec(spec) {
                Some(DefTypeSpec::Letters(letters)) => expanded.extend(letters),
                Some(DefTypeSpec::Universal) => universal_specs += 1,
                None => malformed = true,
            }
        }
        if malformed {
            diagnostics.push(Diagnostic {
                code: "VBA2080",
                severity: Severity::Error,
                message: format!(
                    "DefType directive '{}' contains an invalid letter range",
                    line[0].text
                ),
                source: source.into(),
                span,
            });
            rules.valid = false;
            continue;
        }
        let universal = universal_specs > 0;
        let has_overlap = if universal {
            universal_specs > 1
                || rules.universal_type.is_some()
                || !rules.by_initial.is_empty()
                || !expanded.is_empty()
        } else {
            rules.universal_type.is_some()
                || expanded
                    .iter()
                    .any(|letter| rules.by_initial.contains_key(letter))
                || {
                    let mut unique = HashSet::new();
                    expanded.iter().any(|letter| !unique.insert(*letter))
                }
        };
        if has_overlap {
            diagnostics.push(Diagnostic {
                code: "VBA2081",
                severity: Severity::Error,
                message: "DefType letter specs overlap within the module".into(),
                source: source.into(),
                span,
            });
            rules.valid = false;
            continue;
        }
        if universal {
            rules.universal_type = Some(type_name.into());
        } else {
            for letter in expanded {
                rules.by_initial.insert(letter, type_name.into());
            }
        }
    }
    (rules, diagnostics)
}

enum DefTypeSpec {
    Letters(Vec<char>),
    Universal,
}

fn implicit_type_for_directive(keyword: &str) -> Option<&'static str> {
    match keyword {
        "defbool" => Some("Boolean"),
        "defbyte" => Some("Byte"),
        "defcur" => Some("Currency"),
        "defdate" => Some("Date"),
        "defdbl" => Some("Double"),
        "defint" => Some("Integer"),
        "deflng" => Some("Long"),
        "deflnglng" => Some("LongLong"),
        "deflngptr" => Some("LongPtr"),
        "defobj" => Some("Object"),
        "defsng" => Some("Single"),
        "defstr" => Some("String"),
        "defvar" => Some("Variant"),
        _ => None,
    }
}

fn split_def_type_specs<'slice, 'token>(
    tokens: &'slice [&'token Token],
) -> Vec<&'slice [&'token Token]> {
    let mut specs = Vec::new();
    let mut start = 0;
    for (index, token) in tokens.iter().enumerate() {
        if token.text == "," {
            specs.push(&tokens[start..index]);
            start = index + 1;
        }
    }
    specs.push(&tokens[start..]);
    specs
}

fn expand_def_type_spec(spec: &[&Token]) -> Option<DefTypeSpec> {
    match spec {
        [single] => {
            let letter = single_identifier_letter(single)?;
            Some(DefTypeSpec::Letters(vec![letter.to_ascii_uppercase()]))
        }
        [first, hyphen, last] if hyphen.text == "-" => {
            let first_letter = single_identifier_letter(first)?;
            let last_letter = single_identifier_letter(last)?;
            if first.text == "A" && last.text == "Z" {
                return Some(DefTypeSpec::Universal);
            }
            let start = first_letter.to_ascii_uppercase() as u8;
            let end = last_letter.to_ascii_uppercase() as u8;
            let letters = if start <= end {
                (start..=end).map(char::from).collect()
            } else {
                (end..=start).rev().map(char::from).collect()
            };
            Some(DefTypeSpec::Letters(letters))
        }
        _ => None,
    }
}

fn single_identifier_letter(token: &Token) -> Option<char> {
    let mut chars = token.text.chars();
    let letter = chars.next()?;
    (token.kind == TokenKind::Identifier && chars.next().is_none() && letter.is_ascii_alphabetic())
        .then_some(letter)
}

fn option_diagnostic(
    code: &'static str,
    message: &str,
    source: &str,
    line: &[&Token],
) -> Diagnostic {
    Diagnostic {
        code,
        severity: Severity::Error,
        message: message.into(),
        source: source.into(),
        span: line_span_tokens(line),
    }
}

fn line_span_tokens(line: &[&Token]) -> Span {
    match (line.first(), line.last()) {
        (Some(first), Some(last)) => first.span.join(last.span),
        _ => Span::default(),
    }
}

fn validate_parameter_rules(
    signature: &str,
    parameters: &[Parameter],
    source: &str,
    property_value_parameter: bool,
    has_function_result_variable: bool,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let mut optional_seen = false;
    let mut names = HashSet::new();
    for (index, parameter) in parameters.iter().enumerate() {
        let is_property_value_parameter = property_value_parameter && index + 1 == parameters.len();
        let canonical_name = canon(&parameter.name);
        if !names.insert(canonical_name) {
            diagnostics.push(Diagnostic {
                code: "VBA2050",
                severity: Severity::Error,
                message: format!(
                    "signature '{}' declares parameter '{}' more than once",
                    signature, parameter.name
                ),
                source: source.into(),
                span: parameter.span,
            });
        }
        if has_function_result_variable && canon(&parameter.name) == canon(signature) {
            diagnostics.push(Diagnostic {
                code: "VBA2140",
                severity: Severity::Error,
                message: format!(
                    "parameter '{}' conflicts with the result variable of function '{}'",
                    parameter.name, signature
                ),
                source: source.into(),
                span: parameter.span,
            });
        }
        if !is_property_value_parameter {
            if parameter.optional {
                optional_seen = true;
            } else if optional_seen && !parameter.is_param_array {
                diagnostics.push(Diagnostic {
                    code: "VBA2051",
                    severity: Severity::Error,
                    message: format!(
                        "required parameter '{}' follows an Optional parameter in '{}'",
                        parameter.name, signature
                    ),
                    source: source.into(),
                    span: parameter.span,
                });
            }
        }
        if parameter.is_param_array && !is_property_value_parameter {
            if !parameter.is_array {
                diagnostics.push(Diagnostic {
                    code: "VBA2055",
                    severity: Severity::Error,
                    message: format!(
                        "ParamArray '{}' must be declared as an array",
                        parameter.name
                    ),
                    source: source.into(),
                    span: parameter.span,
                });
            }
            let final_parameter_index = if property_value_parameter {
                parameters.len().saturating_sub(2)
            } else {
                parameters.len().saturating_sub(1)
            };
            if index != final_parameter_index {
                diagnostics.push(Diagnostic {
                    code: "VBA2052",
                    severity: Severity::Error,
                    message: format!(
                        "ParamArray '{}' must be the final parameter of '{}'",
                        parameter.name, signature
                    ),
                    source: source.into(),
                    span: parameter.span,
                });
            }
            if parameter.optional || parameter.passing_explicit {
                diagnostics.push(Diagnostic {
                    code: "VBA2053",
                    severity: Severity::Error,
                    message: format!(
                        "ParamArray '{}' cannot be combined with Optional, ByVal, or ByRef",
                        parameter.name
                    ),
                    source: source.into(),
                    span: parameter.span,
                });
            }
            if parameter
                .type_name
                .as_deref()
                .is_some_and(|t| !t.eq_ignore_ascii_case("Variant"))
            {
                diagnostics.push(Diagnostic {
                    code: "VBA2054",
                    severity: Severity::Error,
                    message: format!(
                        "ParamArray '{}' must have Variant element type",
                        parameter.name
                    ),
                    source: source.into(),
                    span: parameter.span,
                });
            }
        }
    }
}

fn validate_optional_deftype_parameter_defaults(
    module: &Module,
    signature: &str,
    parameters: &[Parameter],
    source: &str,
    diagnostics: &mut Vec<Diagnostic>,
) {
    for parameter in parameters {
        if !parameter.optional
            || parameter.default_value.is_some()
            || parameter.is_param_array
            || parameter.type_name.is_some()
            || type_suffix_name(&parameter.name).is_some()
        {
            continue;
        }
        let Some(type_name) = module
            .implicit_types
            .type_for_identifier(&parameter.name)
            .filter(|type_name| !type_name.eq_ignore_ascii_case("Variant"))
        else {
            continue;
        };
        diagnostics.push(Diagnostic {
            code: "VBA2083",
            severity: Severity::Error,
            message: format!(
                "Optional parameter '{}' in '{}' has implicit type {}; this DefType parameter requires a default value",
                parameter.name, signature, type_name
            ),
            source: source.into(),
            span: parameter.span,
        });
    }
}

#[derive(Clone, Copy)]
struct OptionalConstantContext<'a> {
    project: &'a Project,
    module_index: usize,
    module: &'a Module,
    procedure: Option<&'a Procedure>,
    parameters: &'a [Parameter],
    host_profile: HostProfile,
}

fn validate_optional_parameter_semantics(
    context: OptionalConstantContext<'_>,
    signature: &str,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let project = context.project;
    let module_index = context.module_index;
    let module = context.module;
    let parameters = context.parameters;
    let host_profile = context.host_profile;
    for parameter in parameters.iter().filter(|parameter| parameter.optional) {
        if !parameter.is_array
            && declared_parameter_type(project, module_index, module, parameter).is_some_and(
                |type_name| user_type_owner_index(project, module_index, &type_name).is_some(),
            )
        {
            diagnostics.push(Diagnostic {
                code: "VBA2059",
                severity: Severity::Error,
                message: format!(
                    "Optional parameter '{}' in '{}' cannot have a UDT declared type",
                    parameter.name, signature
                ),
                source: module.source_name.clone(),
                span: parameter.span,
            });
        }

        let Some(default_value) = parameter.default_value.as_deref() else {
            continue;
        };
        let Some(expression) = parse_expression_source(default_value) else {
            // Keep expressions outside the parser's supported subset unresolved.
            continue;
        };
        let constant_status = optional_constant_expression_status(&context, &expression, 0);
        if constant_status == Some(false) {
            diagnostics.push(Diagnostic {
                code: "VBA2133",
                severity: Severity::Error,
                message: format!(
                    "default value for Optional parameter '{}' in '{}' is not a constant expression",
                    parameter.name, signature
                ),
                source: module.source_name.clone(),
                span: parameter.span,
            });
            continue;
        }
        if constant_status != Some(true) {
            continue;
        }
        if crate::typecheck::is_explicit_null_expression(&expression)
            && let Some(formal_type) =
                declared_parameter_type(project, module_index, module, parameter)
            && (parameter.is_array
                || user_type_owner_index(project, module_index, &formal_type).is_none())
            && let Some(error_number) = null_call_argument_runtime_error_number(
                project,
                module_index,
                module,
                parameter,
                &formal_type,
                host_profile,
            )
        {
            diagnostics.push(Diagnostic {
                code: "VBA2131",
                severity: Severity::Warning,
                message: format!(
                    "Default Null for Optional parameter '{}' in '{}' can raise runtime error {error_number} when the argument is omitted",
                    parameter.name, signature
                ),
                source: module.source_name.clone(),
                span: parameter.span,
            });
            continue;
        }
        if crate::typecheck::is_explicit_nothing_expression(&expression) {
            // Invocation processing Set-assigns a Nothing default. Leave its
            // destination-specific behavior to the separate object semantics.
            continue;
        }
        let Some(formal_type) = declared_parameter_type(project, module_index, module, parameter)
        else {
            continue;
        };
        if crate::typecheck::string_literal_let_coercion_error_13(&expression, &formal_type) {
            diagnostics.push(Diagnostic {
                code: "VBA2135",
                severity: Severity::Warning,
                message: format!(
                    "Optional default string for '{}' in '{}' can raise runtime error 13 during Let-coercion when omitted",
                    parameter.name, signature
                ),
                source: module.source_name.clone(),
                span: parameter.span,
            });
            continue;
        }
        if canon(&formal_type) == "any" {
            // External Declare's Any type does not expose a destination value
            // type for Let-coercion analysis.
            continue;
        }
        let Some(actual_type) =
            optional_default_expression_type(&context, default_value, &expression)
        else {
            continue;
        };
        if parameter.is_array {
            if optional_default_array_let_coercion_invalid(
                project,
                module_index,
                module,
                &formal_type,
                &actual_type,
                host_profile,
            ) {
                diagnostics.push(Diagnostic {
                    code: "VBA2130",
                    severity: Severity::Error,
                    message: format!(
                        "Optional default value of type {} cannot be Let-coerced to array parameter '{}'",
                        actual_type, parameter.name
                    ),
                    source: module.source_name.clone(),
                    span: parameter.span,
                });
            }
            continue;
        }
        if user_type_owner_index(project, module_index, &formal_type).is_some() {
            // Optional UDT types were diagnosed above; do not cascade a
            // second coercion finding from their default value.
            continue;
        }
        if is_object_parameter_type(project, &formal_type, host_profile) {
            if object_argument_compatibility(
                project,
                module_index,
                module,
                &actual_type,
                host_profile,
            ) == Some(false)
            {
                diagnostics.push(Diagnostic {
                    code: "VBA2129",
                    severity: Severity::Error,
                    message: format!(
                        "Optional default value of type {} cannot be Let-coerced to object parameter '{}' of type {}",
                        actual_type, parameter.name, formal_type
                    ),
                    source: module.source_name.clone(),
                    span: parameter.span,
                });
            }
            continue;
        }
        if canon(&actual_type) == "longlong"
            && !matches!(
                canon(&formal_type).as_str(),
                "longlong" | "longptr" | "variant"
            )
        {
            diagnostics.push(Diagnostic {
                code: "VBA2086",
                severity: Severity::Error,
                message: format!(
                    "Optional default value for '{}' has type LongLong, which cannot be implicitly Let-coerced to {}",
                    parameter.name, formal_type
                ),
                source: module.source_name.clone(),
                span: parameter.span,
            });
        }
    }
}

fn optional_default_expression_type(
    context: &OptionalConstantContext<'_>,
    source: &str,
    expression: &Expr,
) -> Option<String> {
    if let Some(procedure) = context.procedure {
        return infer_expression_type(
            context.project,
            context.module_index,
            context.module,
            &procedure.name,
            source,
            context.host_profile,
        );
    }
    match expression {
        Expr::Literal(value, LiteralKind::Number, _) => {
            Some(crate::typecheck::numeric_literal_type(value))
        }
        Expr::Literal(_, LiteralKind::String, _) => Some("String".into()),
        Expr::Literal(_, LiteralKind::Date, _) => Some("Date".into()),
        Expr::Identifier(name, _) if matches!(canon(name).as_str(), "true" | "false") => {
            Some("Boolean".into())
        }
        Expr::Identifier(name, _) if canon(name) == "empty" => Some("Variant".into()),
        Expr::Identifier(name, _) => declared_symbol_type(
            context.project,
            context.module_index,
            context.module,
            None,
            name,
        ),
        Expr::Group(value, _) => optional_default_expression_type(context, source, value),
        _ => None,
    }
}

fn optional_default_array_let_coercion_invalid(
    project: &Project,
    module_index: usize,
    module: &Module,
    target_element_type: &str,
    source_type: &str,
    host_profile: HostProfile,
) -> bool {
    let target_is_byte = canon(target_element_type) == "byte";
    if target_is_byte {
        return matches!(
            canon(source_type).as_str(),
            "byte"
                | "integer"
                | "long"
                | "longlong"
                | "single"
                | "double"
                | "currency"
                | "boolean"
                | "date"
        );
    }
    if canon(source_type) == "variant"
        || canon(source_type).starts_with("host-dependent")
        || canon(source_type).starts_with("array<")
    {
        return false;
    }
    crate::typecheck::known_non_udt_type(project, module_index, module, source_type, host_profile)
        || user_type_owner_index(project, module_index, source_type).is_some()
}

fn optional_constant_expression_status(
    context: &OptionalConstantContext<'_>,
    expression: &Expr,
    depth: usize,
) -> Option<bool> {
    if depth >= 64 {
        return None;
    }
    match expression {
        Expr::Literal(..) => Some(true),
        Expr::Identifier(name, _) => optional_constant_identifier_status(context, name),
        Expr::Group(value, _) => optional_constant_expression_status(context, value, depth + 1),
        Expr::Unary { op, value, .. } => {
            if !matches!(canon(op).as_str(), "+" | "-" | "not") {
                return Some(false);
            }
            optional_constant_expression_status(context, value, depth + 1)
        }
        Expr::Binary {
            left, op, right, ..
        } => {
            if canon(op) == "is" {
                return Some(false);
            }
            combine_constant_expression_status(
                optional_constant_expression_status(context, left, depth + 1),
                optional_constant_expression_status(context, right, depth + 1),
            )
        }
        Expr::Member {
            object,
            member,
            access: MemberAccessKind::Dot,
            ..
        } => {
            if let Expr::Identifier(owner, _) = object.as_ref() {
                optional_constant_qualified_name_status(context, owner, member)
            } else {
                Some(false)
            }
        }
        Expr::Call { .. } | Expr::NamedArgument { .. } | Expr::TypeOfIs { .. } => Some(false),
        Expr::Member { .. } => Some(false),
        Expr::Unknown(..) => None,
    }
}

fn combine_constant_expression_status(left: Option<bool>, right: Option<bool>) -> Option<bool> {
    match (left, right) {
        (Some(false), _) | (_, Some(false)) => Some(false),
        (Some(true), Some(true)) => Some(true),
        _ => None,
    }
}

fn optional_constant_identifier_status(
    context: &OptionalConstantContext<'_>,
    name: &str,
) -> Option<bool> {
    if matches!(
        canon(name).as_str(),
        "true" | "false" | "null" | "nothing" | "empty"
    ) {
        return Some(true);
    }
    if context
        .parameters
        .iter()
        .any(|parameter| canon(&parameter.name) == canon(name))
    {
        return Some(false);
    }
    if let Some(status) = module_constant_value_status(context.module, name, false) {
        return Some(status);
    }
    if context
        .module
        .procedures
        .iter()
        .any(|procedure| canon(&procedure.name) == canon(name))
    {
        return Some(false);
    }

    let candidates = context
        .project
        .modules
        .iter()
        .enumerate()
        .filter(|(index, _)| *index != context.module_index)
        .flat_map(|(_, module)| {
            module.declarations.iter().filter_map(move |declaration| {
                let visible = if declaration.kind == "enum_member" {
                    declaration.type_name.as_deref().is_some_and(|enum_name| {
                        module.declarations.iter().any(|enum_declaration| {
                            enum_declaration.kind == "enum"
                                && canon(&enum_declaration.name) == canon(enum_name)
                                && (enum_declaration.visibility.eq_ignore_ascii_case("public")
                                    || enum_declaration.visibility.eq_ignore_ascii_case("global"))
                        })
                    })
                } else {
                    matches!(module.module_kind.as_deref(), Some("standard") | None)
                        && (declaration.visibility.eq_ignore_ascii_case("public")
                            || declaration.visibility.eq_ignore_ascii_case("global"))
                };
                let is_value = matches!(
                    declaration.kind.as_str(),
                    "constant" | "enum_member" | "variable" | "global" | "static"
                );
                (visible && is_value && canon(&declaration.name) == canon(name))
                    .then_some((module, declaration))
            })
        })
        .collect::<Vec<_>>();
    if candidates.len() == 1 {
        return Some(matches!(
            candidates[0].1.kind.as_str(),
            "constant" | "enum_member"
        ));
    }
    if candidates.len() > 1 {
        return None;
    }
    if context
        .project
        .modules
        .iter()
        .enumerate()
        .any(|(index, module)| {
            module.procedures.iter().any(|procedure| {
                canon(&procedure.name) == canon(name)
                    && (index == context.module_index
                        || procedure.visibility.eq_ignore_ascii_case("public")
                        || procedure.visibility.eq_ignore_ascii_case("global"))
            })
        })
    {
        return Some(false);
    }
    if context.host_profile == HostProfile::Excel && excel::is_constant(name) {
        return Some(true);
    }
    if context
        .module
        .procedures
        .iter()
        .any(|procedure| canon(&procedure.name) == canon(name))
        || context.module.declarations.iter().any(|declaration| {
            canon(&declaration.name) == canon(name)
                && matches!(
                    declaration.kind.as_str(),
                    "variable" | "global" | "static" | "with_events" | "external_declare"
                )
        })
    {
        return Some(false);
    }
    None
}

fn optional_constant_qualified_name_status(
    context: &OptionalConstantContext<'_>,
    owner_name: &str,
    member_name: &str,
) -> Option<bool> {
    let modules = context
        .project
        .modules
        .iter()
        .enumerate()
        .filter(|(_, module)| canon(&module.name) == canon(owner_name))
        .collect::<Vec<_>>();
    if modules.len() == 1 && matches!(modules[0].1.module_kind.as_deref(), Some("standard") | None)
    {
        let (owner_index, owner) = modules[0];
        let public_only = owner_index != context.module_index;
        if let Some(status) = module_constant_value_status(owner, member_name, public_only) {
            return Some(status);
        }
        if owner.procedures.iter().any(|procedure| {
            canon(&procedure.name) == canon(member_name)
                && (!public_only
                    || procedure.visibility.eq_ignore_ascii_case("public")
                    || procedure.visibility.eq_ignore_ascii_case("global"))
        }) || owner.declarations.iter().any(|declaration| {
            canon(&declaration.name) == canon(member_name)
                && (!public_only
                    || declaration.visibility.eq_ignore_ascii_case("public")
                    || declaration.visibility.eq_ignore_ascii_case("global"))
        }) {
            return Some(false);
        }
        return None;
    }

    let enum_members = context
        .project
        .modules
        .iter()
        .enumerate()
        .flat_map(|(index, module)| {
            module.declarations.iter().filter(move |declaration| {
                let is_member = declaration.kind == "enum_member"
                    && canon(&declaration.name) == canon(member_name)
                    && declaration
                        .type_name
                        .as_deref()
                        .is_some_and(|type_name| canon(type_name) == canon(owner_name));
                let enum_is_accessible = index == context.module_index
                    || declaration.type_name.as_deref().is_some_and(|enum_name| {
                        module.declarations.iter().any(|enum_declaration| {
                            enum_declaration.kind == "enum"
                                && canon(&enum_declaration.name) == canon(enum_name)
                                && (enum_declaration.visibility.eq_ignore_ascii_case("public")
                                    || enum_declaration.visibility.eq_ignore_ascii_case("global"))
                        })
                    });
                is_member && enum_is_accessible
            })
        })
        .collect::<Vec<_>>();
    if enum_members.len() == 1 {
        return Some(true);
    }
    if enum_members.len() > 1 {
        return None;
    }
    let known_enum = context
        .project
        .modules
        .iter()
        .enumerate()
        .any(|(index, module)| {
            let enum_visible = index == context.module_index
                || module.declarations.iter().any(|declaration| {
                    declaration.kind == "enum"
                        && canon(&declaration.name) == canon(owner_name)
                        && (declaration.visibility.eq_ignore_ascii_case("public")
                            || declaration.visibility.eq_ignore_ascii_case("global"))
                });
            enum_visible
                && module.declarations.iter().any(|declaration| {
                    declaration.kind == "enum" && canon(&declaration.name) == canon(owner_name)
                })
        });
    if known_enum {
        return Some(false);
    }
    optional_constant_identifier_status(context, owner_name).map(|_| false)
}

fn module_constant_value_status(module: &Module, name: &str, public_only: bool) -> Option<bool> {
    let declarations = module
        .declarations
        .iter()
        .filter(|declaration| {
            canon(&declaration.name) == canon(name)
                && matches!(
                    declaration.kind.as_str(),
                    "constant" | "enum_member" | "variable" | "global" | "static" | "with_events"
                )
                && (!public_only
                    || declaration.visibility.eq_ignore_ascii_case("public")
                    || declaration.visibility.eq_ignore_ascii_case("global"))
        })
        .collect::<Vec<_>>();
    if declarations.len() != 1 {
        return None;
    }
    Some(matches!(
        declarations[0].kind.as_str(),
        "constant" | "enum_member"
    ))
}

#[derive(Clone, Copy)]
struct TypeValidationContext<'a> {
    project: &'a Project,
    module_index: usize,
    module: &'a Module,
    procedure: Option<&'a Procedure>,
    host_profile: HostProfile,
}

fn validate_local_declared_type_names(
    context: TypeValidationContext<'_>,
    statements: &[Statement],
    diagnostics: &mut Vec<Diagnostic>,
) {
    for statement in statements {
        if let Some(declaration) = &statement.declaration
            && is_variable_declaration(declaration)
            && let Some(type_name) = &declaration.type_name
        {
            validate_declared_type_name(context, type_name, declaration.span, diagnostics);
        }
        validate_local_declared_type_names(context, &statement.children, diagnostics);
    }
}

#[derive(Clone, Copy)]
struct ArrayTargetInfo {
    is_array: bool,
    is_fixed_array: bool,
    is_variant: bool,
    type_is_known: bool,
    is_param_array: bool,
    is_constant: bool,
}

fn validate_array_operations(
    module: &Module,
    procedure: &Procedure,
    diagnostics: &mut Vec<Diagnostic>,
) {
    validate_array_operations_in_statements(&procedure.statements, module, procedure, diagnostics);
}

fn validate_array_operations_in_statements(
    statements: &[Statement],
    module: &Module,
    procedure: &Procedure,
    diagnostics: &mut Vec<Diagnostic>,
) {
    for statement in statements {
        match statement.kind.as_str() {
            "redim" => {
                for target in &statement.children {
                    let Some(declaration) = target.declaration.as_ref() else {
                        continue;
                    };
                    let Some(name) = simple_array_target_name(&declaration.name) else {
                        continue;
                    };
                    if declaration.type_name.as_deref().is_some_and(|type_name| {
                        type_name
                            .trim_start()
                            .to_ascii_lowercase()
                            .starts_with("new ")
                    }) {
                        diagnostics.push(Diagnostic {
                            code: "VBA2075",
                            severity: Severity::Error,
                            message: format!(
                                "ReDim target '{}' cannot use an As New type clause",
                                declaration.name
                            ),
                            source: module.source_name.clone(),
                            span: declaration.span,
                        });
                    }
                    if let Some(info) = resolve_array_target(module, procedure, &name) {
                        diagnose_array_target_operation(
                            "ReDim",
                            &name,
                            info,
                            declaration.span,
                            &module.source_name,
                            diagnostics,
                        );
                    }
                }
            }
            "erase_target" => {
                if let Some(target) = statement.expression.as_deref()
                    && let Some(name) = simple_array_target_name(target)
                    && let Some(info) = resolve_array_target(module, procedure, &name)
                {
                    diagnose_array_target_operation(
                        "Erase",
                        &name,
                        info,
                        statement.span,
                        &module.source_name,
                        diagnostics,
                    );
                }
            }
            _ => {}
        }
        validate_array_operations_in_statements(
            &statement.children,
            module,
            procedure,
            diagnostics,
        );
    }
}

fn resolve_array_target(
    module: &Module,
    procedure: &Procedure,
    name: &str,
) -> Option<ArrayTargetInfo> {
    if let Some(parameter) = procedure
        .parameters
        .iter()
        .find(|parameter| canon(&parameter.name) == canon(name))
    {
        let parameter_type = parameter
            .type_name
            .clone()
            .or_else(|| implicit_type_for_name(module, &parameter.name));
        return Some(ArrayTargetInfo {
            is_array: parameter.is_array,
            is_fixed_array: false,
            is_variant: parameter_type
                .as_deref()
                .is_some_and(|type_name| type_name.trim().eq_ignore_ascii_case("Variant")),
            type_is_known: parameter_type.is_some(),
            is_param_array: parameter.is_param_array,
            is_constant: false,
        });
    }
    if let Some(declaration) = local_variable_declaration(&procedure.statements, name) {
        return Some(array_target_info(module, declaration));
    }
    module
        .declarations
        .iter()
        .find(|declaration| {
            is_variable_declaration(declaration) && canon(&declaration.name) == canon(name)
        })
        .map(|declaration| array_target_info(module, declaration))
}

fn local_variable_declaration<'a>(
    statements: &'a [Statement],
    name: &str,
) -> Option<&'a Declaration> {
    for statement in statements {
        if let Some(declaration) = statement.declaration.as_ref()
            && is_variable_declaration(declaration)
            && canon(&declaration.name) == canon(name)
        {
            return Some(declaration);
        }
        if let Some(declaration) = local_variable_declaration(&statement.children, name) {
            return Some(declaration);
        }
    }
    None
}

fn is_variable_declaration(declaration: &Declaration) -> bool {
    matches!(
        declaration.kind.as_str(),
        "variable" | "global" | "static" | "constant" | "with_events"
    )
}

fn array_target_info(module: &Module, declaration: &Declaration) -> ArrayTargetInfo {
    let declared_type = declaration_type_name(module, declaration);
    ArrayTargetInfo {
        is_array: declaration.is_array,
        is_fixed_array: declaration.is_array && !declaration.array_dimensions.is_empty(),
        is_variant: declared_type
            .as_deref()
            .is_some_and(|type_name| type_name.trim().eq_ignore_ascii_case("Variant")),
        type_is_known: declared_type.is_some(),
        is_param_array: false,
        is_constant: declaration.kind == "constant",
    }
}

fn simple_array_target_name(expression: &str) -> Option<String> {
    let (tokens, _) = lex(expression, 32);
    let values = tokens
        .into_iter()
        .filter(|token| !matches!(token.kind, TokenKind::Newline | TokenKind::Eof))
        .collect::<Vec<_>>();
    (values.len() == 1 && values[0].kind == TokenKind::Identifier).then(|| values[0].text.clone())
}

fn diagnose_array_target_operation(
    operation: &str,
    name: &str,
    info: ArrayTargetInfo,
    span: Span,
    source: &str,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let issue = if info.is_param_array {
        Some((
            "VBA2074",
            format!("{operation} cannot target ParamArray '{name}'"),
        ))
    } else if info.is_constant || (info.type_is_known && !info.is_array && !info.is_variant) {
        Some((
            "VBA2073",
            format!("{operation} target '{name}' is declared as a non-array, non-Variant value"),
        ))
    } else if operation == "ReDim" && info.is_fixed_array {
        Some((
            "VBA2072",
            format!("ReDim target '{name}' is declared as a fixed-size array"),
        ))
    } else {
        None
    };
    if let Some((code, message)) = issue {
        diagnostics.push(Diagnostic {
            code,
            severity: Severity::Error,
            message,
            source: source.into(),
            span,
        });
    }
}

fn validate_preserve_constraints(
    module: &Module,
    procedure: &Procedure,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let mut shapes = HashMap::<String, Vec<ArrayDimension>>::new();
    validate_preserve_sequence(
        &procedure.statements,
        module,
        procedure,
        &mut shapes,
        diagnostics,
    );
}

fn validate_preserve_sequence(
    statements: &[Statement],
    module: &Module,
    procedure: &Procedure,
    shapes: &mut HashMap<String, Vec<ArrayDimension>>,
    diagnostics: &mut Vec<Diagnostic>,
) {
    for statement in statements {
        match statement.kind.as_str() {
            "redim" => {
                for target in &statement.children {
                    let Some(declaration) = target.declaration.as_ref() else {
                        shapes.clear();
                        continue;
                    };
                    let Some(name) = simple_array_target_name(&declaration.name) else {
                        shapes.clear();
                        continue;
                    };
                    let key = canon(&name);
                    if !array_target_can_be_resized(module, procedure, declaration) {
                        shapes.remove(&key);
                        continue;
                    }
                    let Some(next_shape) = known_array_shape(declaration) else {
                        shapes.remove(&key);
                        continue;
                    };
                    let mut preserve_valid = true;
                    if declaration.kind == "redim_preserve"
                        && let Some(previous_shape) = shapes.get(&key)
                    {
                        preserve_valid = validate_preserve_shape_change(
                            &name,
                            previous_shape,
                            &next_shape,
                            module,
                            statement.span,
                            &module.source_name,
                            diagnostics,
                        );
                    }
                    if preserve_valid {
                        shapes.insert(key, next_shape);
                    } else {
                        shapes.remove(&key);
                    }
                }
            }
            "erase" => {
                if statement.children.is_empty() {
                    shapes.clear();
                }
                for target in &statement.children {
                    if let Some(expression) = target.expression.as_deref()
                        && let Some(name) = simple_array_target_name(expression)
                    {
                        shapes.remove(&canon(&name));
                    } else {
                        shapes.clear();
                    }
                }
            }
            "if" | "single_line_if" | "select_case" => {
                for branch in &statement.children {
                    let mut branch_shapes = HashMap::new();
                    if matches!(
                        branch.kind.as_str(),
                        "then_branch" | "else_branch" | "elseif_branch" | "case"
                    ) {
                        validate_preserve_sequence(
                            &branch.children,
                            module,
                            procedure,
                            &mut branch_shapes,
                            diagnostics,
                        );
                    } else {
                        validate_preserve_sequence(
                            std::slice::from_ref(branch),
                            module,
                            procedure,
                            &mut branch_shapes,
                            diagnostics,
                        );
                    }
                }
                shapes.clear();
            }
            "for" | "for_each" | "while" | "do" | "do_pre" | "loop" | "with" => {
                let mut body_shapes = HashMap::new();
                validate_preserve_sequence(
                    &statement.children,
                    module,
                    procedure,
                    &mut body_shapes,
                    diagnostics,
                );
                shapes.clear();
            }
            _ => shapes.clear(),
        }
    }
}

fn array_target_can_be_resized(
    module: &Module,
    procedure: &Procedure,
    target: &Declaration,
) -> bool {
    if target.type_name.as_deref().is_some_and(|type_name| {
        type_name
            .trim_start()
            .to_ascii_lowercase()
            .starts_with("new ")
    }) {
        return false;
    }
    simple_array_target_name(&target.name)
        .and_then(|name| resolve_array_target(module, procedure, &name))
        .is_none_or(|info| {
            !info.is_param_array
                && !info.is_fixed_array
                && !info.is_constant
                && (!info.type_is_known || info.is_array || info.is_variant)
        })
}

fn known_array_shape(declaration: &Declaration) -> Option<Vec<ArrayDimension>> {
    if declaration.array_dimensions.is_empty()
        || declaration.array_dimensions.iter().any(|dimension| {
            dimension
                .upper_bound
                .as_deref()
                .is_none_or(|bound| bound.trim().is_empty())
        })
    {
        None
    } else {
        Some(declaration.array_dimensions.clone())
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum BoundComparison {
    Same,
    DifferentConstant,
    DifferentExpression,
    Unknown,
}

fn compare_array_bounds(previous: Option<&str>, next: Option<&str>) -> BoundComparison {
    let (Some(previous), Some(next)) = (previous, next) else {
        return BoundComparison::Unknown;
    };
    let (Some(previous_key), Some(next_key)) =
        (canonical_array_bound(previous), canonical_array_bound(next))
    else {
        return BoundComparison::Unknown;
    };
    if previous_key == next_key {
        return BoundComparison::Same;
    }
    match (parse_integer_bound(previous), parse_integer_bound(next)) {
        (Some(previous), Some(next)) if previous != next => BoundComparison::DifferentConstant,
        (Some(_), Some(_)) => BoundComparison::Same,
        _ => BoundComparison::DifferentExpression,
    }
}

fn canonical_array_bound(expression: &str) -> Option<String> {
    let (tokens, _) = lex(expression, 128);
    let values = tokens
        .into_iter()
        .filter(|token| !matches!(token.kind, TokenKind::Newline | TokenKind::Eof))
        .map(|token| token.text.to_ascii_lowercase())
        .collect::<Vec<_>>();
    (!values.is_empty()).then(|| values.join(" "))
}

fn parse_integer_bound(expression: &str) -> Option<i64> {
    parse_integer_constant_expression(expression).map(|value| value.value)
}

fn parse_integer_constant_expression(expression: &str) -> Option<FoldedInteger> {
    if expression.len() > 256 {
        return None;
    }
    parse_expression_source(expression)
        .and_then(|expression| evaluate_integer_constant_expression(&expression, 0))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum FoldedIntegerWidth {
    Byte,
    Integer,
    Long,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct FoldedInteger {
    value: i64,
    width: FoldedIntegerWidth,
}

impl FoldedInteger {
    fn new(value: i64, width: FoldedIntegerWidth) -> Option<Self> {
        let valid = match width {
            FoldedIntegerWidth::Byte => (0..=u8::MAX as i64).contains(&value),
            FoldedIntegerWidth::Integer => (i16::MIN as i64..=i16::MAX as i64).contains(&value),
            FoldedIntegerWidth::Long => (i32::MIN as i64..=i32::MAX as i64).contains(&value),
        };
        valid.then_some(Self { value, width })
    }

    fn promote(left: Self, right: Self) -> FoldedIntegerWidth {
        if left.width == FoldedIntegerWidth::Long || right.width == FoldedIntegerWidth::Long {
            FoldedIntegerWidth::Long
        } else if left.width == FoldedIntegerWidth::Integer
            || right.width == FoldedIntegerWidth::Integer
        {
            FoldedIntegerWidth::Integer
        } else {
            FoldedIntegerWidth::Byte
        }
    }
}

fn evaluate_integer_constant_expression(expression: &Expr, depth: usize) -> Option<FoldedInteger> {
    evaluate_integer_constant_expression_with(expression, depth, &mut |_| None)
}

fn evaluate_integer_constant_expression_with(
    expression: &Expr,
    depth: usize,
    resolve_identifier: &mut impl FnMut(&Expr) -> Option<FoldedInteger>,
) -> Option<FoldedInteger> {
    if depth >= 128 {
        return None;
    }
    match expression {
        Expr::Literal(value, LiteralKind::Number, _) => parse_integer_constant_literal(value),
        Expr::Identifier(name, _) => match canon(name).as_str() {
            "true" => FoldedInteger::new(-1, FoldedIntegerWidth::Integer),
            "false" | "empty" => FoldedInteger::new(0, FoldedIntegerWidth::Integer),
            _ => resolve_identifier(expression),
        },
        Expr::Group(value, _) => {
            evaluate_integer_constant_expression_with(value, depth + 1, resolve_identifier)
        }
        Expr::Unary { op, value, .. } => {
            let value =
                evaluate_integer_constant_expression_with(value, depth + 1, resolve_identifier)?;
            let result = match canon(op).as_str() {
                "+" => value.value,
                "-" => value.value.checked_neg()?,
                "not" => match value.width {
                    FoldedIntegerWidth::Byte => (!(value.value as u8)) as i64,
                    FoldedIntegerWidth::Integer => (!(value.value as i16)) as i64,
                    FoldedIntegerWidth::Long => (!(value.value as i32)) as i64,
                },
                _ => return None,
            };
            let result_width = if canon(op) == "-" && value.width == FoldedIntegerWidth::Byte {
                FoldedIntegerWidth::Integer
            } else {
                value.width
            };
            FoldedInteger::new(result, result_width)
        }
        Expr::Binary {
            left, op, right, ..
        } => {
            let left =
                evaluate_integer_constant_expression_with(left, depth + 1, resolve_identifier)?;
            let right =
                evaluate_integer_constant_expression_with(right, depth + 1, resolve_identifier)?;
            let width = FoldedInteger::promote(left, right);
            let value = match canon(op).as_str() {
                "+" => left.value.checked_add(right.value)?,
                "-" => left.value.checked_sub(right.value)?,
                "*" => left.value.checked_mul(right.value)?,
                "\\" => left.value.checked_div(right.value)?,
                "mod" => {
                    let quotient = left.value.checked_div(right.value)?;
                    left.value
                        .checked_sub(quotient.checked_mul(right.value)?)?
                        .checked_abs()?
                }
                "and" | "or" | "xor" | "eqv" | "imp" => {
                    let bits = match width {
                        FoldedIntegerWidth::Byte => 8,
                        FoldedIntegerWidth::Integer => 16,
                        FoldedIntegerWidth::Long => 32,
                    };
                    let mask = (1u64 << bits) - 1;
                    let left_bits = left.value as u64 & mask;
                    let right_bits = right.value as u64 & mask;
                    let result_bits = match canon(op).as_str() {
                        "and" => left_bits & right_bits,
                        "or" => left_bits | right_bits,
                        "xor" => left_bits ^ right_bits,
                        "eqv" => !(left_bits ^ right_bits) & mask,
                        _ => (!left_bits | right_bits) & mask,
                    };
                    let sign_bit = 1u64 << (bits - 1);
                    if result_bits & sign_bit == 0 {
                        result_bits as i64
                    } else {
                        (result_bits as i64) - (1i64 << bits)
                    }
                }
                "^" if (0..=u32::MAX as i64).contains(&right.value) => {
                    let result = left.value.checked_pow(right.value as u32)?;
                    return FoldedInteger::new(result, FoldedIntegerWidth::Long);
                }
                _ => return None,
            };
            FoldedInteger::new(value, width)
        }
        Expr::Member {
            access: MemberAccessKind::Dot,
            ..
        } => resolve_identifier(expression),
        _ => None,
    }
}

fn parse_integer_constant_literal(literal: &str) -> Option<FoldedInteger> {
    let suffix = literal
        .chars()
        .next_back()
        .filter(|character| matches!(character, '%' | '&' | '^' | '!' | '#' | '@'));
    let digits = suffix
        .map(|_| &literal[..literal.len() - 1])
        .unwrap_or(literal);
    let lower = digits.to_ascii_lowercase();
    if let Some(hex) = lower.strip_prefix("&h") {
        let raw = u64::from_str_radix(hex, 16).ok()?;
        parse_radix_integer_constant(raw, suffix)
    } else if let Some(octal) = lower.strip_prefix("&o") {
        let raw = u64::from_str_radix(octal, 8).ok()?;
        parse_radix_integer_constant(raw, suffix)
    } else {
        let raw = digits.parse::<u64>().ok()?;
        match suffix {
            Some('%') if raw <= i16::MAX as u64 => {
                FoldedInteger::new(raw as i64, FoldedIntegerWidth::Integer)
            }
            Some('&') if raw <= i32::MAX as u64 => {
                FoldedInteger::new(raw as i64, FoldedIntegerWidth::Long)
            }
            Some('^') | Some('!') | Some('#') | Some('@') => None,
            None if raw <= i16::MAX as u64 => {
                FoldedInteger::new(raw as i64, FoldedIntegerWidth::Integer)
            }
            None if raw <= i32::MAX as u64 => {
                FoldedInteger::new(raw as i64, FoldedIntegerWidth::Long)
            }
            _ => None,
        }
    }
}

fn parse_radix_integer_constant(value: u64, suffix: Option<char>) -> Option<FoldedInteger> {
    let (signed, width) = match suffix {
        None | Some('%') if value <= u16::MAX as u64 => {
            (sign_extend_constant(value, 16), FoldedIntegerWidth::Integer)
        }
        None | Some('&') if value <= u32::MAX as u64 => {
            (sign_extend_constant(value, 32), FoldedIntegerWidth::Long)
        }
        // LongLong literals cannot be implicitly coerced to a Long bound.
        Some('^') | Some('!') | Some('#') | Some('@') => return None,
        _ => return None,
    };
    FoldedInteger::new(signed, width)
}

fn sign_extend_constant(value: u64, bits: u32) -> i64 {
    let signed = value as i64;
    if signed & (1i64 << (bits - 1)) == 0 {
        signed
    } else {
        signed - (1i64 << bits)
    }
}

fn parse_integer_literal(literal: &str) -> Option<i64> {
    let (tokens, errors) = lex(literal, 4);
    if !errors.is_empty() {
        return None;
    }
    let values = tokens
        .into_iter()
        .filter(|token| !matches!(token.kind, TokenKind::Newline | TokenKind::Eof))
        .collect::<Vec<_>>();
    match values.as_slice() {
        [token] if token.kind == TokenKind::Number => {
            parse_integer_constant_literal(&token.text).map(|value| value.value)
        }
        _ => None,
    }
}

impl FoldedInteger {
    fn coerce_to_long(self) -> Option<i64> {
        let value = self.value;
        (i32::MIN as i64..=i32::MAX as i64)
            .contains(&value)
            .then_some(value)
    }
}

fn validate_preserve_shape_change(
    name: &str,
    previous: &[ArrayDimension],
    next: &[ArrayDimension],
    module: &Module,
    span: Span,
    source: &str,
    diagnostics: &mut Vec<Diagnostic>,
) -> bool {
    if previous.len() != next.len() {
        diagnostics.push(Diagnostic {
            code: "VBA2076",
            severity: Severity::Warning,
            message: format!(
                "ReDim Preserve for '{}' changes the dimension count from {} to {}; it would raise Error 9 if the preceding ReDim succeeded and this statement executes",
                name,
                previous.len(),
                next.len()
            ),
            source: source.into(),
            span,
        });
        return false;
    }

    let mut different_constant = false;
    let mut different_expression = false;
    for (index, (previous_dimension, next_dimension)) in previous.iter().zip(next).enumerate() {
        let previous_lower = effective_lower_bound(previous_dimension, module);
        let next_lower = effective_lower_bound(next_dimension, module);
        match compare_array_bounds(previous_lower.as_deref(), next_lower.as_deref()) {
            BoundComparison::DifferentConstant => different_constant = true,
            BoundComparison::DifferentExpression => different_expression = true,
            BoundComparison::Same | BoundComparison::Unknown => {}
        }
        if index + 1 < previous.len() {
            match compare_array_bounds(
                previous_dimension.upper_bound.as_deref(),
                next_dimension.upper_bound.as_deref(),
            ) {
                BoundComparison::DifferentConstant => different_constant = true,
                BoundComparison::DifferentExpression => different_expression = true,
                BoundComparison::Same | BoundComparison::Unknown => {}
            }
        }
    }
    if different_constant || different_expression {
        let (detail, outcome) = if different_constant {
            (
                "a lower bound or non-final upper bound has a different integer constant",
                "would raise Error 9 if the preceding ReDim succeeded and this statement executes",
            )
        } else {
            (
                "a lower bound or non-final upper-bound expression differs textually; value equivalence is not proven",
                "may raise Error 9 if the preceding ReDim succeeded, this statement executes, and the evaluated bounds differ",
            )
        };
        diagnostics.push(Diagnostic {
            code: "VBA2076",
            severity: Severity::Warning,
            message: format!(
                "ReDim Preserve for '{}' changes {detail}; it {outcome}",
                name,
            ),
            source: source.into(),
            span,
        });
        return false;
    }
    true
}

fn effective_lower_bound(dimension: &ArrayDimension, module: &Module) -> Option<String> {
    dimension.lower_bound.clone().or_else(|| {
        module
            .options
            .array_base_valid
            .then(|| module.options.array_base.to_string())
    })
}

fn is_object_module(module: &Module) -> bool {
    matches!(
        module.module_kind.as_deref(),
        Some(
            "class"
                | "form"
                | "workbook_document"
                | "worksheet_document"
                | "document_or_class"
                | "class_or_document"
        )
    )
}

fn validate_event_semantics(
    project: &Project,
    module_index: usize,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let module = &project.modules[module_index];
    let mut event_names = HashSet::new();
    for event in module
        .declarations
        .iter()
        .filter(|declaration| declaration.kind == "event")
    {
        if !is_object_module(module) {
            let severity = if module.module_kind.is_some() {
                Severity::Error
            } else {
                Severity::Warning
            };
            diagnostics.push(Diagnostic {
                code: "VBA2094",
                severity,
                message: format!(
                    "event '{}' requires a class or object module; this module's kind is {}",
                    event.name,
                    if module.module_kind.is_some() {
                        "not an object module"
                    } else {
                        "unknown"
                    }
                ),
                source: module.source_name.clone(),
                span: event.span,
            });
        }
        if !event.visibility.eq_ignore_ascii_case("public") {
            diagnostics.push(Diagnostic {
                code: "VBA2094",
                severity: Severity::Error,
                message: format!("event '{}' must have Public visibility", event.name),
                source: module.source_name.clone(),
                span: event.span,
            });
        }
        let key = canon(&event.name);
        if !event_names.insert(key) {
            diagnostics.push(Diagnostic {
                code: "VBA2095",
                severity: Severity::Error,
                message: format!("event '{}' duplicates another event name", event.name),
                source: module.source_name.clone(),
                span: event.span,
            });
        }
        if event.name.contains('_') {
            diagnostics.push(Diagnostic {
                code: "VBA2095",
                severity: Severity::Error,
                message: format!("event name '{}' cannot contain an underscore", event.name),
                source: module.source_name.clone(),
                span: event.span,
            });
        }
        for parameter in &event.parameters {
            if parameter.optional || parameter.is_param_array {
                diagnostics.push(Diagnostic {
                    code: "VBA2095",
                    severity: Severity::Error,
                    message: format!(
                        "event '{}' cannot declare Optional or ParamArray parameter '{}'",
                        event.name, parameter.name
                    ),
                    source: module.source_name.clone(),
                    span: parameter.span,
                });
            }
        }
    }

    let mut local_with_events = Vec::new();
    collect_with_events_from_statements(
        module
            .procedures
            .iter()
            .flat_map(|procedure| procedure.statements.as_slice()),
        &mut local_with_events,
    );
    for declaration in local_with_events {
        diagnostics.push(Diagnostic {
            code: "VBA2090",
            severity: Severity::Error,
            message: format!(
                "WithEvents variable '{}' must be declared at class-module scope",
                declaration.name
            ),
            source: module.source_name.clone(),
            span: declaration.span,
        });
    }

    for declaration in module
        .declarations
        .iter()
        .filter(|declaration| declaration.kind == "with_events")
    {
        if !is_object_module(module) {
            let severity = if module.module_kind.is_some() {
                Severity::Error
            } else {
                Severity::Warning
            };
            diagnostics.push(Diagnostic {
                code: "VBA2090",
                severity,
                message: format!(
                    "WithEvents variable '{}' requires a class-level object module; this module's kind is {}",
                    declaration.name,
                    if module.module_kind.is_some() { "not an object module" } else { "unknown" }
                ),
                source: module.source_name.clone(),
                span: declaration.span,
            });
            if module.module_kind.is_some() {
                continue;
            }
        }
        let Some(type_name) = declaration.type_name.as_deref() else {
            diagnostics.push(Diagnostic {
                code: "VBA2091",
                severity: Severity::Error,
                message: format!(
                    "WithEvents variable '{}' must declare a specific class type",
                    declaration.name
                ),
                source: module.source_name.clone(),
                span: declaration.span,
            });
            continue;
        };
        if declaration.is_array {
            diagnostics.push(Diagnostic {
                code: "VBA2091",
                severity: Severity::Error,
                message: format!(
                    "WithEvents variable '{}' cannot be an array",
                    declaration.name
                ),
                source: module.source_name.clone(),
                span: declaration.span,
            });
            continue;
        }
        let base_type = type_name
            .trim()
            .trim_start_matches("New ")
            .trim_end_matches("()");
        let matching_modules = project
            .modules
            .iter()
            .enumerate()
            .filter(|(_, candidate)| canon(&candidate.name) == canon(base_type))
            .collect::<Vec<_>>();
        if matching_modules.len() == 1 {
            let (source_index, event_source) = matching_modules[0];
            if event_source.module_kind.is_none() {
                diagnostics.push(Diagnostic {
                    code: "VBA2092",
                    severity: Severity::Warning,
                    message: format!(
                        "WithEvents type '{}' is present in source but its module kind is unknown",
                        base_type
                    ),
                    source: module.source_name.clone(),
                    span: declaration.span,
                });
                continue;
            }
            if !is_object_module(event_source) {
                diagnostics.push(Diagnostic {
                    code: "VBA2091",
                    severity: Severity::Error,
                    message: format!(
                        "WithEvents variable '{}' has type '{}', which is not a class or object module",
                        declaration.name, base_type
                    ),
                    source: module.source_name.clone(),
                    span: declaration.span,
                });
                continue;
            }
            if source_index == module_index {
                diagnostics.push(Diagnostic {
                    code: "VBA2091",
                    severity: Severity::Error,
                    message: format!(
                        "WithEvents variable '{}' cannot have the containing class type '{}'",
                        declaration.name, base_type
                    ),
                    source: module.source_name.clone(),
                    span: declaration.span,
                });
                continue;
            }
            let events = event_source
                .declarations
                .iter()
                .filter(|candidate| {
                    candidate.kind == "event" && candidate.visibility.eq_ignore_ascii_case("public")
                })
                .collect::<Vec<_>>();
            if events.is_empty() {
                diagnostics.push(Diagnostic {
                    code: "VBA2091",
                    severity: Severity::Error,
                    message: format!(
                        "WithEvents type '{}' has no declared event members",
                        event_source.name
                    ),
                    source: module.source_name.clone(),
                    span: declaration.span,
                });
                continue;
            }
            for event in events {
                let handler_name = format!("{}_{}", declaration.name, event.name);
                if let Some(handler) = module
                    .procedures
                    .iter()
                    .find(|procedure| canon(&procedure.name) == canon(&handler_name))
                    && !event_handler_signature_matches(
                        project,
                        source_index,
                        event_source,
                        module_index,
                        module,
                        event,
                        handler,
                    )
                {
                    diagnostics.push(Diagnostic {
                        code: "VBA2093",
                        severity: Severity::Error,
                        message: format!(
                            "event handler '{}' must be a Sub whose parameters match '{}.{}'",
                            handler.name, event_source.name, event.name
                        ),
                        source: module.source_name.clone(),
                        span: handler.span,
                    });
                }
            }
        } else if matching_modules.len() > 1 {
            diagnostics.push(Diagnostic {
                code: "VBA2092",
                severity: Severity::Warning,
                message: format!(
                    "WithEvents type '{}' matches multiple source modules; event members remain unresolved",
                    base_type
                ),
                source: module.source_name.clone(),
                span: declaration.span,
            });
        } else if known_type(base_type)
            || module.declarations.iter().any(|candidate| {
                matches!(candidate.kind.as_str(), "user_type" | "enum")
                    && canon(&candidate.name) == canon(base_type)
            })
        {
            diagnostics.push(Diagnostic {
                code: "VBA2091",
                severity: Severity::Error,
                message: format!(
                    "WithEvents variable '{}' must use a specific class type that exposes events; '{}' is not an in-project class type",
                    declaration.name, base_type
                ),
                source: module.source_name.clone(),
                span: declaration.span,
            });
        } else {
            diagnostics.push(Diagnostic {
                code: "VBA2092",
                severity: Severity::Warning,
                message: format!(
                    "WithEvents type '{}' is not present in source modules; external event signatures remain unresolved",
                    base_type
                ),
                source: module.source_name.clone(),
                span: declaration.span,
            });
        }
    }

    validate_raiseevent_locations(module, diagnostics);
}

fn validate_default_member_attributes(
    project: &Project,
    module_index: usize,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let module = &project.modules[module_index];
    let defaults = module
        .procedures
        .iter()
        .filter(|procedure| procedure.automation_member_id == Some(0))
        .collect::<Vec<_>>();
    if defaults.is_empty() {
        return;
    }
    if !is_object_module(module) {
        diagnostics.push(Diagnostic {
            code: "VBA2100",
            severity: if module.module_kind.is_some() {
                Severity::Error
            } else {
                Severity::Warning
            },
            message: "VB_UserMemId = 0 is a default-member marker for an object module; the containing module kind is not confirmed as an object module".into(),
            source: module.source_name.clone(),
            span: defaults[0].span,
        });
    }
    for procedure in defaults
        .iter()
        .filter(|procedure| !procedure.visibility.eq_ignore_ascii_case("public"))
    {
        diagnostics.push(Diagnostic {
            code: "VBA2100",
            severity: Severity::Error,
            message: format!("default member '{}' must be Public", procedure.name),
            source: module.source_name.clone(),
            span: procedure.span,
        });
    }
    let distinct_names = defaults
        .iter()
        .map(|procedure| canon(&procedure.name))
        .collect::<HashSet<_>>();
    if distinct_names.len() > 1 {
        diagnostics.push(Diagnostic {
            code: "VBA2101",
            severity: Severity::Error,
            message: "a class module exposes multiple members marked with VB_UserMemId = 0".into(),
            source: module.source_name.clone(),
            span: defaults[1].span,
        });
    }
}

fn property_index_parameters(procedure: &Procedure) -> Option<&[Parameter]> {
    if procedure.kind.eq_ignore_ascii_case("property get") {
        return Some(&procedure.parameters);
    }
    if procedure.kind.eq_ignore_ascii_case("property let")
        || procedure.kind.eq_ignore_ascii_case("property set")
    {
        return procedure
            .parameters
            .len()
            .checked_sub(1)
            .map(|index| &procedure.parameters[..index]);
    }
    None
}

fn property_index_parameter_lists_compatible(
    project: &Project,
    module_index: usize,
    module: &Module,
    left: &Procedure,
    right: &Procedure,
) -> Option<bool> {
    let left_parameters = property_index_parameters(left)?;
    let right_parameters = property_index_parameters(right)?;
    if left_parameters.len() != right_parameters.len() {
        return Some(false);
    }
    for (left_parameter, right_parameter) in left_parameters.iter().zip(right_parameters) {
        if canon(&left_parameter.name) != canon(&right_parameter.name)
            || left_parameter.optional != right_parameter.optional
            || left_parameter.is_param_array != right_parameter.is_param_array
            || left_parameter.is_array != right_parameter.is_array
            || !left_parameter
                .passing
                .eq_ignore_ascii_case(&right_parameter.passing)
        {
            return Some(false);
        }
        match (
            effective_parameter_type_name(project, module_index, module, left_parameter),
            effective_parameter_type_name(project, module_index, module, right_parameter),
        ) {
            (Some(left_type), Some(right_type)) if canon(&left_type) != canon(&right_type) => {
                return Some(false);
            }
            (None, _) | (_, None) => return None,
            _ => {}
        }
    }
    Some(true)
}

fn validate_property_accessor_contracts(
    project: &Project,
    module_index: usize,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let module = &project.modules[module_index];
    let mut properties = HashMap::<String, Vec<&Procedure>>::new();
    for procedure in &module.procedures {
        if procedure.kind.to_ascii_lowercase().starts_with("property ") {
            properties
                .entry(canon(&procedure.name))
                .or_default()
                .push(procedure);
        }
    }
    for procedures in properties.values() {
        for procedure in procedures {
            if let Some(conflict) = module.declarations.iter().find(|declaration| {
                matches!(
                    declaration.kind.as_str(),
                    "variable"
                        | "global"
                        | "static"
                        | "with_events"
                        | "constant"
                        | "enum_member"
                        | "external_declare"
                ) && canon(&declaration.name) == canon(&procedure.name)
            }) {
                diagnostics.push(Diagnostic {
                    code: "VBA2136",
                    severity: Severity::Error,
                    message: format!(
                        "property '{}' conflicts with module declaration '{}'",
                        procedure.name, conflict.name
                    ),
                    source: module.source_name.clone(),
                    span: procedure.span,
                });
            }
        }
        let getters = procedures
            .iter()
            .copied()
            .filter(|procedure| procedure.kind.eq_ignore_ascii_case("property get"))
            .collect::<Vec<_>>();
        let lets = procedures
            .iter()
            .copied()
            .filter(|procedure| procedure.kind.eq_ignore_ascii_case("property let"))
            .collect::<Vec<_>>();
        let setters = procedures
            .iter()
            .copied()
            .filter(|procedure| procedure.kind.eq_ignore_ascii_case("property set"))
            .collect::<Vec<_>>();

        for setter in lets.iter().chain(&setters) {
            let Some(value_parameter) = setter.parameters.last() else {
                diagnostics.push(Diagnostic {
                    code: "VBA2079",
                    severity: Severity::Error,
                    message: format!(
                        "property setter '{}' requires a final value parameter",
                        setter.name
                    ),
                    source: module.source_name.clone(),
                    span: setter.span,
                });
                continue;
            };
            if value_parameter.optional
                || value_parameter.is_param_array
                || value_parameter.is_array
            {
                diagnostics.push(Diagnostic {
                    code: "VBA2079",
                    severity: Severity::Error,
                    message: format!(
                        "property setter '{}' value parameter cannot be Optional, ParamArray, or an array",
                        setter.name
                    ),
                    source: module.source_name.clone(),
                    span: value_parameter.span,
                });
            }
            if setter.kind.eq_ignore_ascii_case("property set")
                && !value_parameter.is_array
                && effective_parameter_type_name(project, module_index, module, value_parameter)
                    .as_deref()
                    .and_then(|type_name| {
                        interface_member_is_object_type(project, module_index, type_name)
                    })
                    == Some(false)
            {
                diagnostics.push(Diagnostic {
                    code: "VBA2078",
                    severity: Severity::Error,
                    message: format!(
                        "Property Set '{}' value parameter must be Object, Variant, or a named class",
                        setter.name
                    ),
                    source: module.source_name.clone(),
                    span: value_parameter.span,
                });
            }
        }

        let duplicate_accessor_kind = getters.len() > 1 || lets.len() > 1 || setters.len() > 1;
        if duplicate_accessor_kind {
            continue;
        }
        let mut accessors = Vec::new();
        accessors.extend(getters.iter().copied());
        accessors.extend(lets.iter().copied());
        accessors.extend(setters.iter().copied());
        for left_index in 0..accessors.len() {
            for right_index in left_index + 1..accessors.len() {
                let left = accessors[left_index];
                let right = accessors[right_index];
                if property_index_parameter_lists_compatible(
                    project,
                    module_index,
                    module,
                    left,
                    right,
                ) == Some(false)
                {
                    diagnostics.push(Diagnostic {
                        code: "VBA2077",
                        severity: Severity::Error,
                        message: format!(
                            "property accessors '{}' and '{}' must have equivalent index parameter lists",
                            left.name, right.name
                        ),
                        source: module.source_name.clone(),
                        span: right.span,
                    });
                }
            }
        }

        if let (Some(getter), Some(setter)) = (getters.first(), lets.first())
            && let (Some(getter_type), Some(value_parameter)) = (
                effective_procedure_return_type_name(project, module_index, module, getter),
                setter.parameters.last(),
            )
            && let Some(value_type) =
                effective_parameter_type_name(project, module_index, module, value_parameter)
            && canon(&getter_type) != canon(&value_type)
        {
            diagnostics.push(Diagnostic {
                code: "VBA2078",
                severity: Severity::Error,
                message: format!(
                    "Property Let '{}' value type '{}' differs from its Property Get return type '{}'",
                    setter.name, value_type, getter_type
                ),
                source: module.source_name.clone(),
                span: setter.span,
            });
        }
    }
}

fn validate_procedure_name_collisions(module: &Module, diagnostics: &mut Vec<Diagnostic>) {
    let module_symbols = |name: &str| {
        module.declarations.iter().find(|declaration| {
            matches!(
                declaration.kind.as_str(),
                "variable"
                    | "global"
                    | "static"
                    | "with_events"
                    | "constant"
                    | "enum_member"
                    | "external_declare"
            ) && canon(&declaration.name) == canon(name)
        })
    };
    for procedure in module
        .procedures
        .iter()
        .filter(|procedure| !procedure.kind.to_ascii_lowercase().starts_with("property "))
    {
        if let Some(conflict) = module_symbols(&procedure.name) {
            diagnostics.push(Diagnostic {
                code: "VBA2137",
                severity: Severity::Error,
                message: format!(
                    "procedure '{}' conflicts with module declaration '{}'",
                    procedure.name, conflict.name
                ),
                source: module.source_name.clone(),
                span: procedure.span,
            });
        }
    }
    for (declaration_index, declaration) in module.declarations.iter().enumerate() {
        if declaration.kind != "external_declare" {
            continue;
        }
        if let Some(conflict) = module.declarations.iter().find(|candidate| {
            matches!(
                candidate.kind.as_str(),
                "variable" | "global" | "static" | "with_events" | "constant" | "enum_member"
            ) && canon(&candidate.name) == canon(&declaration.name)
        }) {
            diagnostics.push(Diagnostic {
                code: "VBA2137",
                severity: Severity::Error,
                message: format!(
                    "external procedure '{}' conflicts with module declaration '{}'",
                    declaration.name, conflict.name
                ),
                source: module.source_name.clone(),
                span: declaration.span,
            });
        }
        if module.declarations[..declaration_index]
            .iter()
            .any(|candidate| {
                candidate.kind == "external_declare"
                    && canon(&candidate.name) == canon(&declaration.name)
            })
        {
            diagnostics.push(Diagnostic {
                code: "VBA2137",
                severity: Severity::Error,
                message: format!(
                    "external procedure '{}' is declared more than once",
                    declaration.name
                ),
                source: module.source_name.clone(),
                span: declaration.span,
            });
        }
    }
}

fn validate_predeclared_instance_assignments(module: &Module, diagnostics: &mut Vec<Diagnostic>) {
    if module.predeclared_id != Some(true) || !is_object_module(module) {
        return;
    }
    fn visit(module: &Module, statements: &[Statement], diagnostics: &mut Vec<Diagnostic>) {
        for statement in statements {
            if statement.kind == "assignment"
                && statement.expression.as_deref().is_some_and(|source| {
                    source
                        .split_whitespace()
                        .next()
                        .is_some_and(|keyword| keyword.eq_ignore_ascii_case("set"))
                })
                && let Some(Expr::Identifier(name, _)) = statement.parsed_target.as_ref()
                && canon(name) == canon(&module.name)
            {
                diagnostics.push(Diagnostic {
                    code: "VBA2120",
                    severity: Severity::Error,
                    message: format!(
                        "predeclared instance '{}' cannot be the target of a Set assignment",
                        module.name
                    ),
                    source: module.source_name.clone(),
                    span: statement.span,
                });
            }
            visit(module, &statement.children, diagnostics);
        }
    }
    for procedure in &module.procedures {
        visit(module, &procedure.statements, diagnostics);
    }
}

fn validate_global_namespace_attribute(
    project: &Project,
    module_index: usize,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let module = &project.modules[module_index];
    if module.global_namespace != Some(true) {
        return;
    }
    diagnostics.push(Diagnostic {
        code: "VBA2121",
        severity: if project.input_kind == "xlsm_vba_project" {
            Severity::Error
        } else {
            Severity::Warning
        },
        message: format!(
            "module '{}' sets VB_GlobalNameSpace=True; this is invalid in a VBA source project, while referenced library-project namespaces are not included in this analysis",
            module.name
        ),
        source: module.source_name.clone(),
        span: Span::default(),
    });
}

fn collect_with_events_from_statements<'a>(
    statements: impl Iterator<Item = &'a Statement>,
    out: &mut Vec<&'a Declaration>,
) {
    fn visit<'a>(statement: &'a Statement, out: &mut Vec<&'a Declaration>) {
        if let Some(declaration) = statement.declaration.as_ref()
            && declaration.kind == "with_events"
        {
            out.push(declaration);
        }
        for child in &statement.children {
            visit(child, out);
        }
    }
    for statement in statements {
        visit(statement, out);
    }
}

fn event_handler_signature_matches(
    project: &Project,
    event_module_index: usize,
    event_module: &Module,
    handler_module_index: usize,
    handler_module: &Module,
    event: &Declaration,
    handler: &Procedure,
) -> bool {
    handler.kind.eq_ignore_ascii_case("Sub")
        && event.parameters.len() == handler.parameters.len()
        && event.parameters.iter().zip(&handler.parameters).all(
            |(event_parameter, handler_parameter)| {
                let event_type = effective_parameter_type_name(
                    project,
                    event_module_index,
                    event_module,
                    event_parameter,
                );
                let handler_type = effective_parameter_type_name(
                    project,
                    handler_module_index,
                    handler_module,
                    handler_parameter,
                );
                option_type_equal(event_type.as_deref(), handler_type.as_deref())
                    && event_parameter
                        .passing
                        .eq_ignore_ascii_case(&handler_parameter.passing)
                    && event_parameter.is_array == handler_parameter.is_array
                    && event_parameter.optional == handler_parameter.optional
                    && event_parameter.is_param_array == handler_parameter.is_param_array
            },
        )
}

fn validate_raiseevent_locations(module: &Module, diagnostics: &mut Vec<Diagnostic>) {
    fn visit(module: &Module, statements: &[Statement], diagnostics: &mut Vec<Diagnostic>) {
        for statement in statements {
            if statement.kind == "raise_event" {
                let (event_name, has_named_arguments) = statement
                    .parsed_expression
                    .as_ref()
                    .and_then(|expression| match expression {
                        Expr::Call { callee, args, .. } => {
                            let name = match callee.as_ref() {
                                Expr::Identifier(name, _) => Some(name.as_str()),
                                _ => None,
                            };
                            Some((
                                name,
                                args.iter()
                                    .any(|argument| matches!(argument, Expr::NamedArgument { .. })),
                            ))
                        }
                        _ => None,
                    })
                    .unwrap_or((None, false));
                if has_named_arguments {
                    diagnostics.push(Diagnostic {
                        code: "VBA2098",
                        severity: Severity::Error,
                        message: "RaiseEvent arguments must be positional expressions".into(),
                        source: module.source_name.clone(),
                        span: statement.span,
                    });
                }
                if !is_object_module(module) {
                    let severity = if module.module_kind.is_some() {
                        Severity::Error
                    } else {
                        Severity::Warning
                    };
                    diagnostics.push(Diagnostic {
                        code: "VBA2096",
                        severity,
                        message: format!(
                            "RaiseEvent requires a class or object module; this module's kind is {}",
                            if module.module_kind.is_some() { "not an object module" } else { "unknown" }
                        ),
                        source: module.source_name.clone(),
                        span: statement.span,
                    });
                }
                if event_name.is_none_or(|name| {
                    !module.declarations.iter().any(|declaration| {
                        declaration.kind == "event" && canon(&declaration.name) == canon(name)
                    })
                }) {
                    diagnostics.push(Diagnostic {
                        code: "VBA2097",
                        severity: Severity::Error,
                        message: format!(
                            "RaiseEvent target '{}' is not an event declared in the containing class module",
                            event_name.unwrap_or("<unresolved>")
                        ),
                        source: module.source_name.clone(),
                        span: statement.span,
                    });
                }
            }
            visit(module, &statement.children, diagnostics);
        }
    }
    for procedure in &module.procedures {
        visit(module, &procedure.statements, diagnostics);
    }
}

fn validate_implemented_interfaces(
    project: &Project,
    module_index: usize,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let implementing = &project.modules[module_index];
    if implementing.implemented_interfaces.is_empty() {
        return;
    }
    if implementing.module_kind.as_deref() == Some("standard") {
        diagnostics.push(Diagnostic {
            code: "VBA2060",
            severity: Severity::Error,
            message: "Implements is valid only in an object module".into(),
            source: implementing.source_name.clone(),
            span: Span::default(),
        });
        return;
    }
    let mut seen = HashSet::new();
    for interface_name in &implementing.implemented_interfaces {
        let key = canon(interface_name);
        if !seen.insert(key.clone()) {
            diagnostics.push(Diagnostic {
                code: "VBA2061",
                severity: Severity::Error,
                message: format!(
                    "interface '{}' is implemented more than once",
                    interface_name
                ),
                source: implementing.source_name.clone(),
                span: Span::default(),
            });
            continue;
        }
        let mut matches = project
            .modules
            .iter()
            .enumerate()
            .filter(|(_, module)| canon(&module.name) == key);
        let Some((interface_index, interface)) = matches.next() else {
            diagnostics.push(Diagnostic {
                code: "VBA2062",
                severity: Severity::Warning,
                message: format!(
                    "interface '{}' is not present in source modules; referenced type-library members remain unresolved",
                    interface_name
                ),
                source: implementing.source_name.clone(),
                span: Span::default(),
            });
            continue;
        };
        if matches.next().is_some() {
            diagnostics.push(Diagnostic {
                code: "VBA2062",
                severity: Severity::Warning,
                message: format!("interface '{}' matches multiple modules", interface_name),
                source: implementing.source_name.clone(),
                span: Span::default(),
            });
            continue;
        }
        if matches!(interface.module_kind.as_deref(), Some("standard" | "form")) {
            diagnostics.push(Diagnostic {
                code: "VBA2062",
                severity: Severity::Warning,
                message: format!(
                    "module '{}' is not recognized as an interface class module",
                    interface.name
                ),
                source: implementing.source_name.clone(),
                span: Span::default(),
            });
            continue;
        }
        for prototype in interface
            .procedures
            .iter()
            .filter(|procedure| procedure.visibility.eq_ignore_ascii_case("public"))
        {
            let expected_name = format!("{}_{}", interface_name, prototype.name);
            let Some(implementation) = implementing
                .procedures
                .iter()
                .find(|procedure| canon(&procedure.name) == canon(&expected_name))
            else {
                diagnostics.push(Diagnostic {
                    code: "VBA2063",
                    severity: Severity::Error,
                    message: format!(
                        "class '{}' does not implement interface member '{}_{}'",
                        implementing.name, interface_name, prototype.name
                    ),
                    source: implementing.source_name.clone(),
                    span: Span::default(),
                });
                continue;
            };
            let compatible = prototype.kind.eq_ignore_ascii_case(&implementation.kind)
                && option_type_equal(
                    effective_procedure_return_type_name(
                        project,
                        interface_index,
                        interface,
                        prototype,
                    )
                    .as_deref(),
                    effective_procedure_return_type_name(
                        project,
                        module_index,
                        implementing,
                        implementation,
                    )
                    .as_deref(),
                )
                && prototype.parameters.len() == implementation.parameters.len()
                && prototype
                    .parameters
                    .iter()
                    .zip(&implementation.parameters)
                    .all(|(left, right)| {
                        let left_type = effective_parameter_type_name(
                            project,
                            interface_index,
                            interface,
                            left,
                        );
                        let right_type = effective_parameter_type_name(
                            project,
                            module_index,
                            implementing,
                            right,
                        );
                        option_type_equal(left_type.as_deref(), right_type.as_deref())
                            && left.passing.eq_ignore_ascii_case(&right.passing)
                            && left.optional == right.optional
                            && left.is_array == right.is_array
                            && left.is_param_array == right.is_param_array
                    });
            if !compatible {
                diagnostics.push(Diagnostic {
                    code: "VBA2064",
                    severity: Severity::Error,
                    message: format!(
                        "implementation '{}' has a signature that differs from interface member '{}_{}'",
                        implementation.name, interface_name, prototype.name
                    ),
                    source: implementing.source_name.clone(),
                    span: implementation.span,
                });
            }
        }
        for declaration in interface.declarations.iter().filter(|declaration| {
            matches!(
                declaration.kind.as_str(),
                "variable" | "global" | "with_events"
            ) && declaration.visibility.eq_ignore_ascii_case("public")
        }) {
            if declaration.kind == "with_events" || declaration.is_array {
                diagnostics.push(Diagnostic {
                    code: "VBA2065",
                    severity: Severity::Note,
                    message: format!(
                        "interface data member '{}' uses a WithEvents or array shape whose accessor contract is not validated",
                        declaration.name
                    ),
                    source: implementing.source_name.clone(),
                    span: declaration.span,
                });
                continue;
            }
            let member_type =
                effective_declaration_type_name(project, interface_index, interface, declaration);
            let Some(is_object) = member_type.as_deref().and_then(|type_name| {
                interface_member_is_object_type(project, interface_index, type_name)
            }) else {
                diagnostics.push(Diagnostic {
                    code: "VBA2065",
                    severity: Severity::Note,
                    message: format!(
                        "interface data member '{}' has an unresolved property type; accessor mapping is not verified",
                        declaration.name
                    ),
                    source: implementing.source_name.clone(),
                    span: declaration.span,
                });
                continue;
            };
            let expected_name = format!("{}_{}", interface_name, declaration.name);
            let getter = implementing.procedures.iter().find(|procedure| {
                canon(&procedure.name) == canon(&expected_name)
                    && procedure.kind.eq_ignore_ascii_case("property get")
            });
            let Some(getter) = getter else {
                diagnostics.push(Diagnostic {
                    code: "VBA2063",
                    severity: Severity::Error,
                    message: format!(
                        "class '{}' does not implement interface property getter '{}_{}'",
                        implementing.name, interface_name, declaration.name
                    ),
                    source: implementing.source_name.clone(),
                    span: declaration.span,
                });
                continue;
            };
            if !option_type_equal(
                effective_procedure_return_type_name(project, module_index, implementing, getter)
                    .as_deref(),
                member_type.as_deref(),
            ) {
                diagnostics.push(Diagnostic {
                    code: "VBA2064",
                    severity: Severity::Error,
                    message: format!(
                        "property getter '{}' returns a type that differs from interface member '{}'",
                        getter.name, declaration.name
                    ),
                    source: implementing.source_name.clone(),
                    span: getter.span,
                });
            }
            let setter_kind = if is_object {
                "Property Set"
            } else {
                "Property Let"
            };
            let setter = implementing.procedures.iter().find(|procedure| {
                canon(&procedure.name) == canon(&expected_name)
                    && procedure.kind.eq_ignore_ascii_case(setter_kind)
            });
            let Some(setter) = setter else {
                diagnostics.push(Diagnostic {
                    code: "VBA2063",
                    severity: Severity::Error,
                    message: format!(
                        "class '{}' does not implement interface property setter '{}_{}' as {}",
                        implementing.name, interface_name, declaration.name, setter_kind
                    ),
                    source: implementing.source_name.clone(),
                    span: declaration.span,
                });
                continue;
            };
            let setter_value_type = setter.parameters.first().and_then(|parameter| {
                effective_parameter_type_name(project, module_index, implementing, parameter)
            });
            let compatible = setter.parameters.len() == 1
                && option_type_equal(setter_value_type.as_deref(), member_type.as_deref());
            if !compatible {
                diagnostics.push(Diagnostic {
                    code: "VBA2064",
                    severity: Severity::Error,
                    message: format!(
                        "property setter '{}' has a value parameter that differs from interface member '{}'",
                        setter.name, declaration.name
                    ),
                    source: implementing.source_name.clone(),
                    span: setter.span,
                });
            }
        }
    }
}

fn option_type_equal(left: Option<&str>, right: Option<&str>) -> bool {
    match (left, right) {
        (None, None) => true,
        (Some(left), Some(right)) => left.eq_ignore_ascii_case(right),
        _ => false,
    }
}

fn type_suffix_name(name: &str) -> Option<String> {
    match name.chars().last()? {
        '%' => Some("Integer".into()),
        '&' => Some("Long".into()),
        '^' => Some("LongLong".into()),
        '@' => Some("Currency".into()),
        '!' => Some("Single".into()),
        '#' => Some("Double".into()),
        '$' => Some("String".into()),
        _ => None,
    }
}

fn implicit_type_for_name(module: &Module, name: &str) -> Option<String> {
    type_suffix_name(name).or_else(|| {
        module.implicit_types.valid.then(|| {
            module
                .implicit_types
                .type_for_identifier(name)
                .unwrap_or_else(|| "Variant".into())
        })
    })
}

fn implicit_type_candidate(module: &Module, name: &str) -> Option<String> {
    if type_suffix_name(name).is_some() || !module.implicit_types.valid {
        return None;
    }
    module
        .implicit_types
        .type_for_identifier(name)
        .or_else(|| Some("Variant".into()))
}

fn declaration_type_name(module: &Module, declaration: &Declaration) -> Option<String> {
    if declaration.kind == "field" && declaration.type_name.is_none() {
        return None;
    }
    declaration
        .type_name
        .clone()
        .or_else(|| type_suffix_name(&declaration.name))
        .or_else(|| {
            (declaration.kind != "constant")
                .then(|| implicit_type_for_name(module, &declaration.name))
                .flatten()
        })
}

fn parameter_type_name(module: &Module, parameter: &Parameter) -> Option<String> {
    parameter
        .type_name
        .clone()
        .or_else(|| implicit_type_for_name(module, &parameter.name))
}

fn procedure_return_type_name(module: &Module, procedure: &Procedure) -> Option<String> {
    if matches!(
        procedure.kind.to_ascii_lowercase().as_str(),
        "function" | "property get"
    ) {
        procedure
            .return_type
            .clone()
            .or_else(|| implicit_type_for_name(module, &procedure.name))
    } else {
        procedure.return_type.clone()
    }
}

fn effective_declaration_type_name(
    project: &Project,
    module_index: usize,
    module: &Module,
    declaration: &Declaration,
) -> Option<String> {
    declaration_type_name(module, declaration)
        .map(|name| effective_project_type_name(project, module_index, module, &name))
}

fn effective_parameter_type_name(
    project: &Project,
    module_index: usize,
    module: &Module,
    parameter: &Parameter,
) -> Option<String> {
    parameter_type_name(module, parameter)
        .map(|name| effective_project_type_name(project, module_index, module, &name))
}

fn effective_procedure_return_type_name(
    project: &Project,
    module_index: usize,
    module: &Module,
    procedure: &Procedure,
) -> Option<String> {
    procedure_return_type_name(module, procedure)
        .map(|name| effective_project_type_name(project, module_index, module, &name))
}

fn interface_member_is_object_type(
    project: &Project,
    interface_index: usize,
    type_name: &str,
) -> Option<bool> {
    let name = canon(
        type_name
            .trim()
            .trim_start_matches("New ")
            .trim_end_matches("()"),
    );
    if name == "object" {
        return Some(true);
    }
    if name == "variant" {
        return None;
    }
    if matches!(
        name.as_str(),
        "boolean"
            | "byte"
            | "integer"
            | "long"
            | "longlong"
            | "longptr"
            | "single"
            | "double"
            | "currency"
            | "decimal"
            | "date"
            | "string"
            | "error"
    ) {
        return Some(false);
    }
    project.modules.get(interface_index)?;
    let non_object_matches = project
        .modules
        .iter()
        .enumerate()
        .flat_map(|(owner_index, module)| {
            let name = name.as_str();
            module.declarations.iter().filter(move |declaration| {
                matches!(declaration.kind.as_str(), "user_type" | "enum")
                    && canon(&declaration.name) == name
                    && (owner_index == interface_index
                        || declaration.visibility.eq_ignore_ascii_case("public")
                        || declaration.visibility.eq_ignore_ascii_case("global"))
            })
        })
        .count();
    let object_matches = project
        .modules
        .iter()
        .filter(|module| {
            matches!(
                module.module_kind.as_deref(),
                Some(
                    "class"
                        | "form"
                        | "workbook_document"
                        | "worksheet_document"
                        | "class_or_document"
                        | "document_or_class"
                )
            ) && canon(&module.name) == name
        })
        .count();
    match (non_object_matches, object_matches) {
        (1, 0) => Some(false),
        (0, 1) => Some(true),
        _ => None,
    }
}

fn expected_excel_document_event_parameter_types(
    module: &Module,
    procedure: &Procedure,
) -> Option<&'static [&'static str]> {
    const NONE: &[&str] = &[];
    const BOOL: &[&str] = &["Boolean"];
    const BOOL_BOOL: &[&str] = &["Boolean", "Boolean"];
    const OBJECT_RANGE: &[&str] = &["Object", "Range"];
    const OBJECT_RANGE_BOOL: &[&str] = &["Object", "Range", "Boolean"];
    const RANGE: &[&str] = &["Range"];
    const RANGE_BOOL: &[&str] = &["Range", "Boolean"];

    let module_name = canon(&module.name);
    let module_kind = module.module_kind.as_deref().unwrap_or("");
    let is_workbook = module_kind == "workbook_document" || module_name == "thisworkbook";
    let is_worksheet = module_kind == "worksheet_document" || module_name.starts_with("sheet");
    let procedure_name = canon(&procedure.name);
    if is_workbook {
        match procedure_name.as_str() {
            "workbook_open" | "workbook_activate" | "workbook_deactivate" => Some(NONE),
            "workbook_beforeclose" => Some(BOOL),
            "workbook_beforesave" => Some(BOOL_BOOL),
            "workbook_sheetchange" | "workbook_sheetselectionchange" => Some(OBJECT_RANGE),
            "workbook_sheetbeforedoubleclick" | "workbook_sheetbeforerightclick" => {
                Some(OBJECT_RANGE_BOOL)
            }
            _ => None,
        }
    } else if is_worksheet {
        match procedure_name.as_str() {
            "worksheet_activate" | "worksheet_deactivate" | "worksheet_calculate" => Some(NONE),
            "worksheet_change" | "worksheet_selectionchange" => Some(RANGE),
            "worksheet_beforedoubleclick" | "worksheet_beforerightclick" => Some(RANGE_BOOL),
            _ => None,
        }
    } else {
        None
    }
}

fn excel_document_event_signature_matches(
    project: &Project,
    module_index: usize,
    module: &Module,
    procedure: &Procedure,
    expected_types: &[&str],
) -> bool {
    procedure.kind.eq_ignore_ascii_case("sub")
        && procedure.parameters.len() == expected_types.len()
        && procedure
            .parameters
            .iter()
            .zip(expected_types)
            .all(|(parameter, expected)| {
                !parameter.optional
                    && !parameter.is_param_array
                    && !parameter.is_array
                    && declared_parameter_type(project, module_index, module, parameter)
                        .is_some_and(|actual| {
                            let actual = canon(&actual);
                            let actual = actual.strip_prefix("excel.").unwrap_or(&actual);
                            actual.eq_ignore_ascii_case(expected)
                        })
            })
}

fn excel_document_event_signature_status(
    project: &Project,
    module_index: usize,
    module: &Module,
    procedure: &Procedure,
) -> Option<bool> {
    let expected_types = expected_excel_document_event_parameter_types(module, procedure)?;
    Some(excel_document_event_signature_matches(
        project,
        module_index,
        module,
        procedure,
        expected_types,
    ))
}

fn validate_excel_document_event_signatures(
    project: &Project,
    module_index: usize,
    module: &Module,
    host_profile: HostProfile,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if host_profile != HostProfile::Excel {
        return;
    }
    for procedure in &module.procedures {
        let Some(expected_types) = expected_excel_document_event_parameter_types(module, procedure)
        else {
            continue;
        };
        if !excel_document_event_signature_matches(
            project,
            module_index,
            module,
            procedure,
            expected_types,
        ) {
            diagnostics.push(Diagnostic {
                code: "VBA2143",
                severity: Severity::Error,
                message: format!(
                    "Excel document event '{}' does not match the supported Sub parameter signature ({})",
                    procedure.name,
                    expected_types.join(", ")
                ),
                source: module.source_name.clone(),
                span: procedure.span,
            });
        }
    }
}

fn excel_application_event_signatures() -> &'static [(&'static str, &'static [&'static str])] {
    const WORKBOOK: &[&str] = &["Workbook"];
    const WORKBOOK_BOOLEAN: &[&str] = &["Workbook", "Boolean"];
    const WORKBOOK_BOOLEAN_BOOLEAN: &[&str] = &["Workbook", "Boolean", "Boolean"];
    const OBJECT_RANGE: &[&str] = &["Object", "Range"];
    const OBJECT_RANGE_BOOLEAN: &[&str] = &["Object", "Range", "Boolean"];
    const OBJECT: &[&str] = &["Object"];
    &[
        ("WorkbookOpen", WORKBOOK),
        ("WorkbookBeforeClose", WORKBOOK_BOOLEAN),
        ("WorkbookBeforeSave", WORKBOOK_BOOLEAN_BOOLEAN),
        ("WorkbookActivate", WORKBOOK),
        ("WorkbookDeactivate", WORKBOOK),
        ("SheetChange", OBJECT_RANGE),
        ("SheetSelectionChange", OBJECT_RANGE),
        ("SheetBeforeDoubleClick", OBJECT_RANGE_BOOLEAN),
        ("SheetBeforeRightClick", OBJECT_RANGE_BOOLEAN),
        ("SheetActivate", OBJECT),
        ("SheetDeactivate", OBJECT),
        ("SheetCalculate", OBJECT),
    ]
}

fn is_excel_application_type(project: &Project, declaration: &Declaration) -> bool {
    let Some(type_name) = declaration.type_name.as_deref() else {
        return false;
    };
    let normalized_type = type_name.trim();
    let normalized_type = if normalized_type
        .get(..4)
        .is_some_and(|prefix| prefix.eq_ignore_ascii_case("new "))
    {
        &normalized_type[4..]
    } else {
        normalized_type
    };
    let base_type = canon(normalized_type.trim_end_matches("()"));
    if !matches!(base_type.as_str(), "application" | "excel.application") {
        return false;
    }
    !project.modules.iter().any(|module| {
        (is_object_module(module) && canon(&module.name) == "application")
            || module.declarations.iter().any(|candidate| {
                candidate.kind == "user_type" && canon(&candidate.name) == "application"
            })
            || (base_type == "excel.application" && canon(&module.name) == "excel")
    })
}

fn excel_application_event_handler_matches(
    project: &Project,
    module_index: usize,
    module: &Module,
    procedure: &Procedure,
    expected_types: &[&str],
) -> bool {
    procedure.kind.eq_ignore_ascii_case("sub")
        && procedure.parameters.len() == expected_types.len()
        && procedure
            .parameters
            .iter()
            .zip(expected_types)
            .all(|(parameter, expected)| {
                !parameter.optional
                    && !parameter.is_param_array
                    && !parameter.is_array
                    && declared_parameter_type(project, module_index, module, parameter)
                        .is_some_and(|actual| {
                            let actual = canon(&actual);
                            let actual = actual.strip_prefix("excel.").unwrap_or(&actual);
                            actual.eq_ignore_ascii_case(expected)
                        })
            })
}

fn validate_excel_application_event_signatures(
    project: &Project,
    module_index: usize,
    module: &Module,
    host_profile: HostProfile,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if host_profile != HostProfile::Excel || !is_object_module(module) {
        return;
    }
    for subscription in module
        .declarations
        .iter()
        .filter(|declaration| declaration.kind == "with_events" && !declaration.is_array)
        .filter(|declaration| is_excel_application_type(project, declaration))
    {
        for (event_name, expected_types) in excel_application_event_signatures() {
            let handler_name = format!("{}_{}", subscription.name, event_name);
            let Some(handler) = module
                .procedures
                .iter()
                .find(|procedure| canon(&procedure.name) == canon(&handler_name))
            else {
                continue;
            };
            if !excel_application_event_handler_matches(
                project,
                module_index,
                module,
                handler,
                expected_types,
            ) {
                diagnostics.push(Diagnostic {
                    code: "VBA2144",
                    severity: Severity::Error,
                    message: format!(
                        "Excel Application event handler '{}' does not match the supported Sub parameter signature ({})",
                        handler.name,
                        expected_types.join(", ")
                    ),
                    source: module.source_name.clone(),
                    span: handler.span,
                });
            }
        }
    }
}

pub fn detect_entry_points(project: &Project, host_profile: HostProfile) -> Vec<EntryPointFact> {
    let mut out = Vec::new();
    for (module_index, m) in project.modules.iter().enumerate() {
        for p in &m.procedures {
            let proc = canon(&p.name);
            let module = canon(&m.name);
            let kind = m.module_kind.as_deref().unwrap_or("");
            let (trigger, reason) = if (kind == "class" || kind == "class_or_document")
                && matches!(proc.as_str(), "class_initialize" | "class_terminate")
            {
                (
                    "class_lifecycle_candidate",
                    "class lifecycle procedure name pattern",
                )
            } else if host_profile == HostProfile::Excel
                && matches!(
                    proc.as_str(),
                    "auto_open" | "auto_close" | "auto_add" | "auto_remove"
                )
            {
                (
                    "legacy_excel_auto_macro_candidate",
                    "Excel legacy automatic macro naming convention",
                )
            } else if host_profile == HostProfile::Excel
                && (kind == "workbook_document" || module == "thisworkbook")
                && proc.starts_with("workbook_")
                && excel_document_event_signature_status(project, module_index, m, p) != Some(false)
            {
                (
                    "workbook_event_candidate",
                    "ThisWorkbook procedure name matches an Excel workbook event pattern",
                )
            } else if host_profile == HostProfile::Excel
                && (kind == "worksheet_document" || module.starts_with("sheet"))
                && proc.starts_with("worksheet_")
                && excel_document_event_signature_status(project, module_index, m, p) != Some(false)
            {
                (
                    "worksheet_event_candidate",
                    "worksheet module procedure name matches an Excel worksheet event pattern",
                )
            } else if proc == "main"
                && p.visibility.eq_ignore_ascii_case("public")
                && p.parameters.iter().all(|a| a.optional || a.is_param_array)
            {
                (
                    "manual_macro_candidate",
                    "public no-required-argument Main procedure",
                )
            } else {
                continue;
            };
            out.push(EntryPointFact {
                module: m.name.clone(),
                procedure: p.name.clone(),
                trigger: trigger.into(),
                reason: reason.into(),
                span: p.span,
            });
        }
    }
    if host_profile == HostProfile::Excel {
        for (module_index, module) in project.modules.iter().enumerate() {
            for procedure in &module.procedures {
                let mut uses = Vec::new();
                collect_excel_ontime_uses(
                    &procedure.statements,
                    ExcelApplicationRunAnalysis {
                        project,
                        module_index,
                        module,
                        procedure,
                        source: &module.analysis_text,
                        host_profile,
                    },
                    &mut uses,
                );
                let mut seen = HashSet::new();
                uses.retain(|usage| seen.insert((usage.call_span.start, usage.call_span.end)));
                for usage in uses {
                    if usage.schedule_false || !usage.has_required_arguments {
                        continue;
                    }
                    let Some((macro_name, _)) = usage.procedure_name.as_ref() else {
                        continue;
                    };
                    for candidate in excel_ontime_macro_candidates(project, macro_name) {
                        let Some((target_module_name, target_procedure_name)) =
                            candidate.split_once('.')
                        else {
                            continue;
                        };
                        let Some((target_module, target_procedure)) = project
                            .modules
                            .iter()
                            .find(|candidate| canon(&candidate.name) == canon(target_module_name))
                            .and_then(|target_module| {
                                target_module
                                    .procedures
                                    .iter()
                                    .find(|candidate| {
                                        canon(&candidate.name) == canon(target_procedure_name)
                                    })
                                    .map(|target_procedure| (target_module, target_procedure))
                            })
                        else {
                            continue;
                        };
                        if !out.iter().any(|entry| {
                            entry.module.eq_ignore_ascii_case(&target_module.name)
                                && entry.procedure.eq_ignore_ascii_case(&target_procedure.name)
                                && entry.trigger == "excel_ontime_scheduled_macro_candidate"
                        }) {
                            out.push(EntryPointFact {
                                module: target_module.name.clone(),
                                procedure: target_procedure.name.clone(),
                                trigger: "excel_ontime_scheduled_macro_candidate".into(),
                                reason: format!(
                                    "Excel Application.OnTime in {}.{} names a public zero-argument procedure; schedule execution and cancellation state are not established",
                                    module.name, procedure.name
                                ),
                                span: target_procedure.span,
                            });
                        }
                    }
                }
            }
        }
    }
    for (listener_index, listener) in project.modules.iter().enumerate() {
        if !is_object_module(listener) {
            continue;
        }
        for subscription in listener
            .declarations
            .iter()
            .filter(|declaration| declaration.kind == "with_events")
        {
            if subscription.is_array
                || subscription.type_name.as_deref().is_none_or(|type_name| {
                    canon(
                        type_name
                            .trim()
                            .trim_start_matches("New ")
                            .trim_end_matches("()"),
                    ) == canon(&listener.name)
                })
            {
                continue;
            }
            let Some(type_name) = subscription.type_name.as_deref() else {
                continue;
            };
            let source_type = canon(
                type_name
                    .trim()
                    .trim_start_matches("New ")
                    .trim_end_matches("()"),
            );
            let sources = project
                .modules
                .iter()
                .enumerate()
                .filter(|(index, candidate)| {
                    *index != listener_index
                        && canon(&candidate.name) == source_type
                        && is_object_module(candidate)
                })
                .collect::<Vec<_>>();
            if sources.len() != 1 {
                continue;
            }
            let (source_index, source_module) = sources[0];
            for event in source_module.declarations.iter().filter(|declaration| {
                declaration.kind == "event"
                    && declaration.visibility.eq_ignore_ascii_case("public")
                    && !declaration.name.contains('_')
                    && declaration
                        .parameters
                        .iter()
                        .all(|parameter| !parameter.optional && !parameter.is_param_array)
            }) {
                let handler_name = format!("{}_{}", subscription.name, event.name);
                if let Some(handler) = listener
                    .procedures
                    .iter()
                    .find(|procedure| canon(&procedure.name) == canon(&handler_name))
                    && event_handler_signature_matches(
                        project,
                        source_index,
                        source_module,
                        listener_index,
                        listener,
                        event,
                        handler,
                    )
                    && !out.iter().any(|entry| {
                        entry.module.eq_ignore_ascii_case(&listener.name)
                            && entry.procedure.eq_ignore_ascii_case(&handler.name)
                            && entry.trigger == "withevents_event_handler_candidate"
                    })
                {
                    out.push(EntryPointFact {
                        module: listener.name.clone(),
                        procedure: handler.name.clone(),
                        trigger: "withevents_event_handler_candidate".into(),
                        reason: format!(
                            "WithEvents variable '{}' can receive event '{}' from class '{}'; runtime assignment is not established",
                            subscription.name, event.name, source_module.name
                        ),
                        span: handler.span,
                    });
                }
            }
        }
    }
    if host_profile == HostProfile::Excel {
        for (module_index, listener) in project.modules.iter().enumerate() {
            if !is_object_module(listener) {
                continue;
            }
            for subscription in listener
                .declarations
                .iter()
                .filter(|declaration| declaration.kind == "with_events" && !declaration.is_array)
                .filter(|declaration| is_excel_application_type(project, declaration))
            {
                for (event_name, expected_types) in excel_application_event_signatures() {
                    let handler_name = format!("{}_{}", subscription.name, event_name);
                    let Some(handler) = listener
                        .procedures
                        .iter()
                        .find(|procedure| canon(&procedure.name) == canon(&handler_name))
                    else {
                        continue;
                    };
                    if excel_application_event_handler_matches(
                        project,
                        module_index,
                        listener,
                        handler,
                        expected_types,
                    ) && !out.iter().any(|entry| {
                        entry.module.eq_ignore_ascii_case(&listener.name)
                            && entry.procedure.eq_ignore_ascii_case(&handler.name)
                            && entry.trigger == "excel_application_event_handler_candidate"
                    }) {
                        out.push(EntryPointFact {
                            module: listener.name.clone(),
                            procedure: handler.name.clone(),
                            trigger: "excel_application_event_handler_candidate".into(),
                            reason: format!(
                                "WithEvents variable '{}' can receive Excel Application event '{}'; runtime assignment and event delivery are not established",
                                subscription.name, event_name
                            ),
                            span: handler.span,
                        });
                    }
                }
            }
        }
    }
    out
}

fn matching_event_handlers(
    project: &Project,
    source_module_index: usize,
    event: &Declaration,
) -> Vec<String> {
    let Some(source_module) = project.modules.get(source_module_index) else {
        return Vec::new();
    };
    if !is_object_module(source_module)
        || event.kind != "event"
        || !event.visibility.eq_ignore_ascii_case("public")
        || event.name.contains('_')
        || event
            .parameters
            .iter()
            .any(|parameter| parameter.optional || parameter.is_param_array)
    {
        return Vec::new();
    }
    let source_name = canon(&source_module.name);
    let mut handlers = Vec::new();
    for (listener_index, listener) in project.modules.iter().enumerate() {
        if listener_index == source_module_index || !is_object_module(listener) {
            continue;
        }
        for subscription in listener
            .declarations
            .iter()
            .filter(|declaration| declaration.kind == "with_events" && !declaration.is_array)
        {
            let Some(type_name) = subscription.type_name.as_deref() else {
                continue;
            };
            let declared_source = canon(
                type_name
                    .trim()
                    .trim_start_matches("New ")
                    .trim_end_matches("()"),
            );
            if declared_source != source_name {
                continue;
            }
            let handler_name = format!("{}_{}", subscription.name, event.name);
            if let Some(handler) = listener
                .procedures
                .iter()
                .find(|procedure| canon(&procedure.name) == canon(&handler_name))
                && event_handler_signature_matches(
                    project,
                    source_module_index,
                    source_module,
                    listener_index,
                    listener,
                    event,
                    handler,
                )
            {
                handlers.push(format!("{}.{}", listener.name, handler.name));
            }
        }
    }
    handlers.sort_by_key(|name| canon(name));
    handlers.dedup_by(|left, right| canon(left) == canon(right));
    handlers
}

#[derive(Default)]
struct FactSet {
    procedures: Vec<ProcedureFact>,
    references: Vec<ReferenceFact>,
    calls: Vec<CallFact>,
    data_accesses: Vec<DataAccessFact>,
    data_flow: Vec<DataFlowFact>,
    type_facts: Vec<TypeFact>,
}

fn is_direct_nothing_expression(expression: &Expr) -> bool {
    match expression {
        Expr::Identifier(name, _) => canon(name) == "nothing",
        Expr::Group(value, _) => is_direct_nothing_expression(value),
        _ => false,
    }
}

fn is_typeof_test_type_known(
    project: &Project,
    module_index: usize,
    type_name: &str,
    host_profile: HostProfile,
) -> bool {
    type_is_known(project, module_index, type_name, host_profile)
        || (host_profile == HostProfile::Excel
            && canon(type_name)
                .strip_prefix("excel.")
                .is_some_and(excel::is_known_type))
}

fn validate_typeof_is_expressions(
    project: &Project,
    module_index: usize,
    module: &Module,
    procedure: &Procedure,
    host_profile: HostProfile,
    diagnostics: &mut Vec<Diagnostic>,
) {
    fn visit_expression(
        project: &Project,
        module_index: usize,
        module: &Module,
        procedure: &Procedure,
        host_profile: HostProfile,
        expression: &Expr,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        match expression {
            Expr::TypeOfIs {
                expression, span, ..
            } => {
                if is_direct_nothing_expression(expression) {
                    diagnostics.push(Diagnostic {
                        code: "VBA2146",
                        severity: Severity::Warning,
                        message:
                            "TypeOf...Is on Nothing can raise runtime error 91 before the type test returns"
                                .into(),
                        source: module.source_name.clone(),
                        span: *span,
                    });
                } else {
                    let object_source = expression_source(&module.analysis_text, expression);
                    if let Some(object_type) = infer_expression_type(
                        project,
                        module_index,
                        module,
                        &procedure.name,
                        &object_source,
                        host_profile,
                    ) && crate::typecheck::user_type_owner_index(
                        project,
                        module_index,
                        &object_type,
                    )
                    .is_none()
                        && object_argument_compatibility(
                            project,
                            module_index,
                            module,
                            &object_type,
                            host_profile,
                        ) == Some(false)
                    {
                        diagnostics.push(Diagnostic {
                            code: "VBA2145",
                            severity: Severity::Error,
                            message: format!(
                                "TypeOf...Is requires an object-compatible or Variant expression; '{}' has known non-object type '{}'",
                                expression_source(&module.analysis_text, expression),
                                object_type
                            ),
                            source: module.source_name.clone(),
                            span: *span,
                        });
                    }
                }
                visit_expression(
                    project,
                    module_index,
                    module,
                    procedure,
                    host_profile,
                    expression,
                    diagnostics,
                );
            }
            Expr::Call { callee, args, .. } => {
                visit_expression(
                    project,
                    module_index,
                    module,
                    procedure,
                    host_profile,
                    callee,
                    diagnostics,
                );
                for argument in args {
                    visit_expression(
                        project,
                        module_index,
                        module,
                        procedure,
                        host_profile,
                        argument,
                        diagnostics,
                    );
                }
            }
            Expr::Unary { value, .. } | Expr::Group(value, _) => visit_expression(
                project,
                module_index,
                module,
                procedure,
                host_profile,
                value,
                diagnostics,
            ),
            Expr::Binary {
                left,
                op,
                right,
                span,
            } => {
                if canon(op) == "is" {
                    let operand_types = [left.as_ref(), right.as_ref()].map(|operand| {
                        let source = expression_source(&module.analysis_text, operand);
                        infer_expression_type(
                            project,
                            module_index,
                            module,
                            &procedure.name,
                            &source,
                            host_profile,
                        )
                    });
                    let invalid_operands = operand_types
                        .iter()
                        .flatten()
                        .filter(|type_name| {
                            object_argument_compatibility(
                                project,
                                module_index,
                                module,
                                type_name,
                                host_profile,
                            ) == Some(false)
                        })
                        .cloned()
                        .collect::<Vec<_>>();
                    if !invalid_operands.is_empty() {
                        diagnostics.push(Diagnostic {
                            code: "VBA2147",
                            severity: Severity::Error,
                            message: format!(
                                "Is operator requires each operand to have a class, Object, or Variant type; known incompatible operand type(s): {}",
                                invalid_operands.join(", ")
                            ),
                            source: module.source_name.clone(),
                            span: *span,
                        });
                    }
                }
                visit_expression(
                    project,
                    module_index,
                    module,
                    procedure,
                    host_profile,
                    left,
                    diagnostics,
                );
                visit_expression(
                    project,
                    module_index,
                    module,
                    procedure,
                    host_profile,
                    right,
                    diagnostics,
                );
            }
            Expr::Member { object, .. } => visit_expression(
                project,
                module_index,
                module,
                procedure,
                host_profile,
                object,
                diagnostics,
            ),
            Expr::NamedArgument { value, .. } => visit_expression(
                project,
                module_index,
                module,
                procedure,
                host_profile,
                value,
                diagnostics,
            ),
            Expr::Identifier(..) | Expr::Literal(..) | Expr::Unknown(..) => {}
        }
    }

    fn visit_statements(
        project: &Project,
        module_index: usize,
        module: &Module,
        procedure: &Procedure,
        host_profile: HostProfile,
        statements: &[Statement],
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        for statement in statements {
            for expression in [
                statement.parsed_expression.as_ref(),
                statement.parsed_target.as_ref(),
                statement.parsed_exit_condition.as_ref(),
                statement.parsed_loop_start.as_ref(),
                statement.parsed_loop_end.as_ref(),
                statement.parsed_loop_step.as_ref(),
            ]
            .into_iter()
            .flatten()
            {
                visit_expression(
                    project,
                    module_index,
                    module,
                    procedure,
                    host_profile,
                    expression,
                    diagnostics,
                );
            }
            for case_range in &statement.case_ranges {
                for expression in [
                    case_range.parsed_expression.as_ref(),
                    case_range.parsed_start_value.as_ref(),
                    case_range.parsed_end_value.as_ref(),
                ]
                .into_iter()
                .flatten()
                {
                    visit_expression(
                        project,
                        module_index,
                        module,
                        procedure,
                        host_profile,
                        expression,
                        diagnostics,
                    );
                }
            }
            visit_statements(
                project,
                module_index,
                module,
                procedure,
                host_profile,
                &statement.children,
                diagnostics,
            );
        }
    }

    visit_statements(
        project,
        module_index,
        module,
        procedure,
        host_profile,
        &procedure.statements,
        diagnostics,
    );
}

fn canonical_typeof_type_name(name: &str) -> String {
    let canonical = canon(name);
    canonical
        .strip_prefix("excel.")
        .unwrap_or(&canonical)
        .to_owned()
}

fn typeof_type_compatibility_status(
    project: &Project,
    module_index: usize,
    module: &Module,
    object_type: Option<&str>,
    tested_type: &str,
    direct_nothing: bool,
    host_profile: HostProfile,
) -> String {
    if direct_nothing {
        return "runtime_error_91_candidate".into();
    }
    let Some(object_type) = object_type else {
        return "unresolved_object_type".into();
    };
    if object_argument_compatibility(project, module_index, module, object_type, host_profile)
        == Some(false)
        && crate::typecheck::user_type_owner_index(project, module_index, object_type).is_none()
    {
        return "invalid_non_object_operand".into();
    }
    let source_name = canonical_typeof_type_name(object_type);
    let tested_name = canonical_typeof_type_name(tested_type);
    if source_name == tested_name {
        return if crate::typecheck::user_type_owner_index(project, module_index, object_type)
            .is_some()
        {
            "same_declared_udt_candidate".into()
        } else {
            "same_declared_type_candidate".into()
        };
    }
    if let Some(owner) = crate::typecheck::class_type_owner_index(project, object_type)
        && project.modules.get(owner).is_some_and(|class_module| {
            class_module
                .implemented_interfaces
                .iter()
                .any(|interface| canonical_typeof_type_name(interface) == tested_name)
        })
    {
        return "implemented_interface_candidate".into();
    }
    if tested_name == "object"
        && (crate::typecheck::class_type_owner_index(project, object_type).is_some()
            || host_profile == HostProfile::Excel && excel::is_known_type(object_type))
    {
        return "object_supertype_candidate".into();
    }
    if matches!(canon(object_type).as_str(), "object" | "variant") {
        "runtime_type_check_required".into()
    } else {
        "runtime_type_check_unresolved".into()
    }
}

struct TypeOfTestOperand<'a> {
    procedure: &'a Procedure,
    expression: &'a Expr,
    type_name: &'a str,
    type_span: Span,
    span: Span,
}

fn collect_typeof_type_operands_in_statements<'a>(
    procedure: &'a Procedure,
    statements: &'a [Statement],
    out: &mut Vec<TypeOfTestOperand<'a>>,
) {
    for statement in statements {
        for expression in [
            statement.parsed_expression.as_ref(),
            statement.parsed_target.as_ref(),
            statement.parsed_exit_condition.as_ref(),
            statement.parsed_loop_start.as_ref(),
            statement.parsed_loop_end.as_ref(),
            statement.parsed_loop_step.as_ref(),
        ]
        .into_iter()
        .flatten()
        {
            collect_typeof_type_operands_in_expression(procedure, expression, out);
        }
        for case_range in &statement.case_ranges {
            for expression in [
                case_range.parsed_expression.as_ref(),
                case_range.parsed_start_value.as_ref(),
                case_range.parsed_end_value.as_ref(),
            ]
            .into_iter()
            .flatten()
            {
                collect_typeof_type_operands_in_expression(procedure, expression, out);
            }
        }
        collect_typeof_type_operands_in_statements(procedure, &statement.children, out);
    }
}

fn collect_typeof_type_operands_in_expression<'a>(
    procedure: &'a Procedure,
    expression: &'a Expr,
    out: &mut Vec<TypeOfTestOperand<'a>>,
) {
    match expression {
        Expr::TypeOfIs {
            expression,
            type_name,
            type_span,
            span,
        } => {
            out.push(TypeOfTestOperand {
                procedure,
                expression,
                type_name,
                type_span: *type_span,
                span: *span,
            });
            collect_typeof_type_operands_in_expression(procedure, expression, out);
        }
        Expr::Call { callee, args, .. } => {
            collect_typeof_type_operands_in_expression(procedure, callee, out);
            for argument in args {
                collect_typeof_type_operands_in_expression(procedure, argument, out);
            }
        }
        Expr::Unary { value, .. } | Expr::Group(value, _) => {
            collect_typeof_type_operands_in_expression(procedure, value, out)
        }
        Expr::Binary { left, right, .. } => {
            collect_typeof_type_operands_in_expression(procedure, left, out);
            collect_typeof_type_operands_in_expression(procedure, right, out);
        }
        Expr::Member { object, .. } => {
            collect_typeof_type_operands_in_expression(procedure, object, out)
        }
        Expr::NamedArgument { value, .. } => {
            collect_typeof_type_operands_in_expression(procedure, value, out)
        }
        Expr::Identifier(..) | Expr::Literal(..) | Expr::Unknown(..) => {}
    }
}

fn collect_facts(
    project: &Project,
    index: &HashMap<String, Vec<(usize, usize)>>,
    diagnostics: &mut Vec<Diagnostic>,
    limits: &Limits,
    host_profile: HostProfile,
) -> FactSet {
    let mut pf = Vec::new();
    let mut rf = Vec::new();
    let mut cf = Vec::new();
    let mut df = Vec::new();
    let mut data_flow = Vec::new();
    let mut typeof_type_facts = Vec::new();
    let public_symbol_index = build_public_symbol_index(project);
    let standard_module_names = build_standard_module_name_index(project);
    let intrinsic_name_set = intrinsic_names();
    let module_names = project
        .modules
        .iter()
        .map(|module| canon(&module.name))
        .collect::<HashSet<_>>();
    let predeclared_module_names = project
        .modules
        .iter()
        .filter(|module| module.predeclared_id == Some(true))
        .map(|module| canon(&module.name))
        .collect::<HashSet<_>>();
    let public_external_names = project
        .modules
        .iter()
        .filter(|module| matches!(module.module_kind.as_deref(), Some("standard") | None))
        .flat_map(|module| {
            module
                .declarations
                .iter()
                .filter(|declaration| {
                    declaration.kind == "external_declare"
                        && (declaration.visibility.eq_ignore_ascii_case("public")
                            || declaration.visibility.eq_ignore_ascii_case("global"))
                })
                .map(|declaration| canon(&declaration.name))
        })
        .collect::<HashSet<_>>();
    let module_value_names = project
        .modules
        .iter()
        .map(|module| {
            module
                .declarations
                .iter()
                .filter(|declaration| {
                    is_variable_declaration(declaration) || declaration.kind == "enum_member"
                })
                .map(|declaration| canon(&declaration.name))
                .collect::<HashSet<_>>()
        })
        .collect::<Vec<_>>();
    let module_external_names = project
        .modules
        .iter()
        .map(|module| {
            module
                .declarations
                .iter()
                .filter(|declaration| declaration.kind == "external_declare")
                .map(|declaration| canon(&declaration.name))
                .collect::<HashSet<_>>()
        })
        .collect::<Vec<_>>();
    for (module_index, module) in project.modules.iter().enumerate() {
        collect_assignment_facts(project, module_index, module, &mut data_flow);
        for procedure in &module.procedures {
            let mut procedure_value_names = procedure
                .parameters
                .iter()
                .map(|parameter| canon(&parameter.name))
                .collect::<HashSet<_>>();
            collect_declared_variable_names(&procedure.statements, &mut procedure_value_names);
            collect_loop_control_variable_names(&procedure.statements, &mut procedure_value_names);
            let expression_scope = ExpressionReadScope {
                project,
                module_index,
                module,
                procedure,
                host_profile,
                intrinsic_name_set: &intrinsic_name_set,
                public_symbol_index: &public_symbol_index,
                procedure_index: index,
                module_names: &module_names,
                predeclared_module_names: &predeclared_module_names,
                public_external_names: &public_external_names,
                module_value_names: &module_value_names[module_index],
                module_external_names: &module_external_names[module_index],
                procedure_value_names: &procedure_value_names,
            };
            collect_procedure_expression_reads(
                &expression_scope,
                &procedure.statements,
                &mut data_flow,
            );
        }
    }
    for (mi, m) in project.modules.iter().enumerate() {
        for p in &m.procedures {
            pf.push(ProcedureFact {
                module: m.name.clone(),
                name: p.name.clone(),
                kind: p.kind.clone(),
                visibility: p.visibility.clone(),
                span: p.span,
            });
        }
        let (tokens, lex_errors) = lex(&m.analysis_text, limits.max_tokens);
        for (span, msg) in lex_errors {
            diagnostics.push(Diagnostic {
                code: "VBA1001",
                severity: Severity::Warning,
                message: msg,
                source: m.source_name.clone(),
                span,
            });
        }
        let mut typeof_type_operands = Vec::new();
        for procedure in &m.procedures {
            collect_typeof_type_operands_in_statements(
                procedure,
                &procedure.statements,
                &mut typeof_type_operands,
            );
        }
        let mut typeof_type_tokens = HashSet::new();
        let mut typeof_type_references = HashMap::new();
        for type_test in &typeof_type_operands {
            for token in &tokens {
                if token.kind == TokenKind::Identifier
                    && token.span.start >= type_test.type_span.start
                    && token.span.end <= type_test.type_span.end
                {
                    let token_key = (token.span.start, token.span.end);
                    typeof_type_tokens.insert(token_key);
                    if token.span.start == type_test.type_span.start {
                        typeof_type_references.insert(
                            token_key,
                            (type_test.type_name.to_owned(), type_test.type_span),
                        );
                    }
                }
            }
            let object_expression = expression_source(&m.analysis_text, type_test.expression);
            let object_type = infer_expression_type(
                project,
                mi,
                m,
                &type_test.procedure.name,
                &object_expression,
                host_profile,
            );
            typeof_type_facts.push(TypeFact {
                module: m.name.clone(),
                procedure: Some(type_test.procedure.name.clone()),
                target: object_expression,
                target_type: Some(type_test.type_name.to_owned()),
                value_type: object_type.clone().unwrap_or_else(|| "unresolved".into()),
                status: typeof_type_compatibility_status(
                    project,
                    mi,
                    m,
                    object_type.as_deref(),
                    type_test.type_name,
                    is_direct_nothing_expression(type_test.expression),
                    host_profile,
                ),
                span: type_test.span,
            });
        }
        let explicit = m.options.explicit;
        let mut procedure_labels = HashMap::new();
        let mut procedure_jump_target_spans = HashMap::new();
        let mut module_variable_names = HashSet::new();
        for declaration in &m.declarations {
            if !matches!(
                declaration.kind.as_str(),
                "user_type" | "enum" | "field" | "event" | "external_declare"
            ) {
                module_variable_names.insert(canon(&declaration.name));
            }
        }
        let mut procedure_variable_names = HashMap::new();
        for p in &m.procedures {
            let key = canon(&p.name);
            let mut labels = HashSet::new();
            collect_labels(&p.statements, &mut labels);
            procedure_labels.insert(key.clone(), labels);
            let mut jump_target_spans = HashSet::new();
            collect_jump_target_spans(&p.statements, &mut jump_target_spans);
            procedure_jump_target_spans.insert(key.clone(), jump_target_spans);
            let mut names = p
                .parameters
                .iter()
                .map(|parameter| canon(&parameter.name))
                .collect::<HashSet<_>>();
            collect_declared_variable_names(&p.statements, &mut names);
            procedure_variable_names.insert(key, names);
        }
        let mut i = 0;
        let mut procedure_cursor = 0usize;
        while i < tokens.len() {
            let tok = &tokens[i];
            while procedure_cursor < m.procedures.len()
                && m.procedures[procedure_cursor].span.end < tok.span.start
            {
                procedure_cursor += 1;
            }
            let proc = m.procedures.get(procedure_cursor).and_then(|procedure| {
                (tok.span.start >= procedure.span.start && tok.span.start <= procedure.span.end)
                    .then(|| procedure.name.clone())
            });
            let prev = i.checked_sub(1).and_then(|index| tokens.get(index));
            if tok.kind != TokenKind::Identifier {
                i += 1;
                continue;
            }
            let token_key = (tok.span.start, tok.span.end);
            if typeof_type_tokens.contains(&token_key) {
                if let Some((type_name, type_span)) = typeof_type_references.get(&token_key) {
                    rf.push(ReferenceFact {
                        module: m.name.clone(),
                        procedure: proc.clone(),
                        name: type_name.clone(),
                        resolution: if is_typeof_test_type_known(
                            project,
                            mi,
                            type_name,
                            host_profile,
                        ) {
                            "typeof_type_reference_candidate"
                        } else {
                            "unresolved_typeof_type_reference"
                        }
                        .into(),
                        implicit_type: None,
                        span: *type_span,
                    });
                }
                i += 1;
                continue;
            }
            if tok.bracket_delimited {
                if host_profile == HostProfile::Excel
                    && proc.is_some()
                    && prev.is_none_or(|previous| previous.text != "!")
                {
                    df.push(DataAccessFact {
                        module: m.name.clone(),
                        procedure: proc.clone(),
                        operation: "excel_evaluate_candidate".into(),
                        target: data_access_target(&tokens, i),
                        host_dependent: true,
                        span: tok.span,
                    });
                }
                i += 1;
                continue;
            }
            let name = canon(&tok.text);
            let next = tokens.get(i + 1);
            if proc.as_ref().is_some_and(|procedure| {
                procedure_jump_target_spans
                    .get(&canon(procedure))
                    .is_some_and(|spans| spans.contains(&(tok.span.start, tok.span.end)))
            }) {
                rf.push(ReferenceFact {
                    module: m.name.clone(),
                    procedure: proc.clone(),
                    name: tok.text.clone(),
                    resolution: if proc.as_ref().is_some_and(|procedure| {
                        procedure_labels
                            .get(&canon(procedure))
                            .is_some_and(|labels| {
                                labels.contains(&canonical_statement_label(&tok.text))
                            })
                    }) {
                        "resolved_local_label"
                    } else {
                        "unresolved_label"
                    }
                    .into(),
                    implicit_type: None,
                    span: tok.span,
                });
                i += 1;
                continue;
            }
            if line_starts_with(&tokens, i, "attribute") {
                i += 1;
                continue;
            }
            if proc.is_none() && line_starts_with(&tokens, i, "option") {
                while i < tokens.len() && tokens[i].kind != TokenKind::Newline {
                    i += 1;
                }
                continue;
            }
            if is_def_type_directive_keyword(&tok.text) && line_starts_with(&tokens, i, &tok.text) {
                while i < tokens.len() && tokens[i].kind != TokenKind::Newline {
                    i += 1;
                }
                continue;
            }
            if next.is_some_and(|t| t.text == ":=") {
                i += 1;
                continue;
            }
            if prev.is_some_and(|token| token.text == "!") {
                // The identifier after a bang access is a literal default-member
                // key, not a variable/member reference. Its call candidate is
                // collected from the expression tree in the dedicated pass.
                i += 1;
                continue;
            }
            let declared_locally = module_variable_names.contains(&name)
                || proc.as_ref().is_some_and(|procedure| {
                    procedure_variable_names
                        .get(&canon(procedure))
                        .is_some_and(|names| names.contains(&name))
                });
            if next.is_some_and(|t| t.text == ".")
                && !declared_locally
                && standard_module_names.contains_key(&name)
            {
                rf.push(ReferenceFact {
                    module: m.name.clone(),
                    procedure: proc.clone(),
                    name: tok.text.clone(),
                    resolution: "resolved_standard_module_qualifier".into(),
                    implicit_type: None,
                    span: tok.span,
                });
                i += 1;
                continue;
            }
            if next.is_some_and(|token| token.text == ".")
                && !declared_locally
                && project.modules.iter().any(|candidate| {
                    canon(&candidate.name) == name
                        && candidate.predeclared_id == Some(true)
                        && is_object_module(candidate)
                })
            {
                rf.push(ReferenceFact {
                    module: m.name.clone(),
                    procedure: proc.clone(),
                    name: tok.text.clone(),
                    resolution: "predeclared_class_default_instance_reference".into(),
                    implicit_type: None,
                    span: tok.span,
                });
                i += 1;
                continue;
            }
            if prev.is_some_and(|x| x.text == "." || x.text == "!") {
                let self_qualified = i >= 2 && canon(&tokens[i - 2].text) == "me";
                if prev.is_some_and(|x| x.text == ".")
                    && i >= 2
                    && let Some(owner) = standard_module_names
                        .get(&canon(&tokens[i - 2].text))
                        .copied()
                        .or_else(|| {
                            let is_object_module = matches!(
                                m.module_kind.as_deref(),
                                Some(
                                    "class"
                                        | "form"
                                        | "workbook_document"
                                        | "worksheet_document"
                                        | "class_or_document"
                                        | "document_or_class"
                                )
                            );
                            let has_member = m
                                .procedures
                                .iter()
                                .any(|candidate| canon(&candidate.name) == name)
                                || m.declarations.iter().any(|declaration| {
                                    canon(&declaration.name) == name
                                        && !matches!(
                                            declaration.kind.as_str(),
                                            "user_type"
                                                | "enum"
                                                | "field"
                                                | "event"
                                                | "external_declare"
                                        )
                                });
                            (self_qualified && is_object_module && has_member).then_some(mi)
                        })
                {
                    let target_module = &project.modules[owner];
                    let is_rvalue = statement_assignment_eq(&tokens, i).is_some_and(|eq| i > eq);
                    let no_argument_function = is_rvalue
                        && next
                            .is_some_and(|t| matches!(t.kind, TokenKind::Newline | TokenKind::Eof))
                        && target_module.procedures.iter().any(|candidate| {
                            canon(&candidate.name) == name
                                && (owner == mi
                                    || candidate.visibility.eq_ignore_ascii_case("public"))
                                && (candidate.kind.eq_ignore_ascii_case("function")
                                    || candidate.kind.eq_ignore_ascii_case("property get"))
                                && candidate
                                    .parameters
                                    .iter()
                                    .all(|parameter| parameter.optional || parameter.is_param_array)
                        });
                    let property_setter_candidates = target_module
                        .procedures
                        .iter()
                        .enumerate()
                        .filter(|(_, candidate)| {
                            canon(&candidate.name) == name
                                && matches!(
                                    candidate.kind.to_ascii_lowercase().as_str(),
                                    "property let" | "property set"
                                )
                                && (owner == mi
                                    || candidate.visibility.eq_ignore_ascii_case("public"))
                        })
                        .map(|(procedure_index, _)| (owner, procedure_index))
                        .collect::<Vec<_>>();
                    let property_set_equal =
                        statement_assignment_eq(&tokens, i).filter(|eq| i < *eq);
                    let property_assignment =
                        property_set_equal.is_some() && !property_setter_candidates.is_empty();
                    let module_call_statement =
                        line_starts_with(&tokens, i - 2, &tokens[i - 2].text)
                            || line_starts_with(&tokens, i - 2, "call");
                    let next_starts_argument = next.is_some_and(|token| {
                        !matches!(
                            token.text.to_ascii_lowercase().as_str(),
                            "=" | ":="
                                | "."
                                | "!"
                                | "+"
                                | "-"
                                | "*"
                                | "/"
                                | "&"
                                | "<"
                                | ">"
                                | "<="
                                | ">="
                                | "<>"
                                | ","
                                | ":"
                                | "as"
                                | "then"
                                | "else"
                        ) && !matches!(token.kind, TokenKind::Newline | TokenKind::Eof)
                    });
                    let qualified_call = next.is_some_and(|t| t.text == "(")
                        || no_argument_function
                        || property_assignment
                        || (module_call_statement && next_starts_argument)
                        || (next.is_some_and(|t| {
                            matches!(t.kind, TokenKind::Newline | TokenKind::Eof) || t.text == ":"
                        }) && (line_starts_with(&tokens, i - 2, "call")
                            || line_starts_with(&tokens, i - 2, &tokens[i - 2].text)));
                    if qualified_call {
                        let mut candidates = if property_assignment {
                            property_setter_candidates
                        } else {
                            procedure_candidates_for_call(project, index, owner, &name)
                        };
                        if owner != mi && !property_assignment {
                            candidates.retain(|(_, candidate)| {
                                !target_module.procedures[*candidate]
                                    .visibility
                                    .eq_ignore_ascii_case("private")
                            });
                        }
                        let has_private = owner != mi
                            && target_module.procedures.iter().any(|candidate| {
                                canon(&candidate.name) == name
                                    && candidate.visibility.eq_ignore_ascii_case("private")
                            });
                        let arguments = if let Some(equal) = property_set_equal {
                            let mut arguments = if next.is_some_and(|token| token.text == "(") {
                                call_arguments(&tokens, i).unwrap_or_default()
                            } else {
                                Vec::new()
                            };
                            let mut end = equal + 1;
                            while end < tokens.len()
                                && tokens[end].kind != TokenKind::Newline
                                && tokens[end].text != ":"
                            {
                                end += 1;
                            }
                            arguments.push(render_call_argument(&tokens[equal + 1..end]));
                            arguments
                        } else {
                            call_arguments(&tokens, i).unwrap_or_default()
                        };
                        let resolution = match candidates.as_slice() {
                            [_] if property_assignment && self_qualified => {
                                "resolved_self_property_setter"
                            }
                            [_] if property_assignment => {
                                "resolved_qualified_module_property_setter"
                            }
                            [_] if self_qualified => "resolved_self_procedure",
                            [_] => "resolved_qualified_module_procedure",
                            [_, ..] if property_assignment => {
                                "ambiguous_qualified_module_property_setter"
                            }
                            [_, ..] => "ambiguous_qualified_module_procedure",
                            [] if has_private => "inaccessible_private_procedure",
                            [] => "unresolved_qualified_module_member",
                        };
                        if candidates.len() == 1 {
                            let (_, procedure_index) = candidates[0];
                            let callee = &target_module.procedures[procedure_index];
                            let (bindings, issues) = if property_assignment {
                                bind_property_setter_arguments(&callee.parameters, &arguments)
                            } else {
                                bind_arguments(&callee.parameters, &arguments, false)
                            };
                            diagnose_argument_binding(
                                &callee.name,
                                &callee.parameters,
                                arguments.len(),
                                &bindings,
                                &issues,
                                ArgumentBindingSite {
                                    source: &m.source_name,
                                    span: tok.span,
                                },
                                diagnostics,
                            );
                            if !issues.is_empty() {
                                diagnostics.push(Diagnostic {
                                    code: "VBA2022",
                                    severity: argument_binding_issue_severity(&issues),
                                    message: format!(
                                        "call to '{}' has invalid arguments: {}",
                                        callee.name,
                                        issues.join("; ")
                                    ),
                                    source: m.source_name.clone(),
                                    span: tok.span,
                                });
                            }
                            diagnose_byval_array_arguments(
                                &callee.parameters,
                                &bindings,
                                m,
                                proc.as_deref(),
                                &m.source_name,
                                tok.span,
                                diagnostics,
                            );
                            diagnose_call_argument_type_mismatches(
                                CallTypeContext {
                                    project,
                                    caller_module_index: mi,
                                    caller_module: m,
                                    caller_procedure: proc.as_deref(),
                                    callee_module: target_module,
                                    callee_name: &callee.name,
                                    callee_kind: &callee.kind,
                                    source: &m.source_name,
                                    host_profile,
                                    span: tok.span,
                                },
                                &callee.parameters,
                                &bindings,
                                diagnostics,
                            );
                            append_argument_input_facts(
                                CallInputContext {
                                    project,
                                    module_index: mi,
                                    module: m,
                                    procedure: proc.clone(),
                                },
                                &format!("{}.{}", target_module.name, callee.name),
                                (&callee.parameters, &bindings),
                                if property_assignment {
                                    "property_set_argument_candidate"
                                } else {
                                    "procedure_argument_input_candidate"
                                },
                                tok.span,
                                &mut data_flow,
                            );
                            let return_target = statement_assignment_eq(&tokens, i)
                                .filter(|eq| i > *eq)
                                .and_then(|eq| call_assignment_target(&tokens, i, eq));
                            if matches!(
                                callee.kind.to_ascii_lowercase().as_str(),
                                "function" | "property get"
                            ) && let Some(lhs) = return_target
                            {
                                let return_sources = data_flow
                                    .iter()
                                    .filter(|fact| {
                                        fact.module.eq_ignore_ascii_case(&target_module.name)
                                            && fact.procedure.as_deref().is_some_and(|name| {
                                                name.eq_ignore_ascii_case(&callee.name)
                                            })
                                            && canon(&fact.target) == canon(&callee.name)
                                            && matches!(
                                                fact.transfer.as_str(),
                                                "assignment" | "object_assignment"
                                            )
                                    })
                                    .cloned()
                                    .collect::<Vec<_>>();
                                append_function_return_facts(
                                    project,
                                    (m, proc.clone(), &lhs),
                                    (target_module, callee),
                                    (&bindings, &return_sources),
                                    tok.span,
                                    &mut data_flow,
                                );
                            }
                            for (formal_index, actual) in bindings {
                                let formal = &callee.parameters[formal_index];
                                if parameter_is_effectively_byref(callee, formal_index, formal)
                                    && parameter_is_written(callee, &formal.name)
                                    && is_assignable_argument(&actual)
                                {
                                    data_flow.push(DataFlowFact {
                                        module: m.name.clone(),
                                        procedure: proc.clone(),
                                        target: actual,
                                        inputs: vec![callee.name.clone(), formal.name.clone()],
                                        transfer: "byref_argument_write".into(),
                                        argument_slot_index: None,
                                        value_expression: None,
                                        call_callee_module: Some(target_module.name.clone()),
                                        call_callee_procedure: Some(callee.name.clone()),
                                        span: tok.span,
                                    });
                                }
                            }
                        } else if has_private {
                            diagnostics.push(Diagnostic {
                                    code: "VBA2021",
                                    severity: Severity::Warning,
                                    message: format!(
                                        "qualified call to private procedure '{}' from another module is not accessible",
                                        tok.text
                                    ),
                                    source: m.source_name.clone(),
                                    span: tok.span,
                                });
                        }
                        cf.push(CallFact {
                            module: m.name.clone(),
                            procedure: proc.clone(),
                            target: tok.text.clone(),
                            resolution: resolution.into(),
                            argument_count: Some(arguments.len()),
                            arguments,
                            external_library: None,
                            external_alias: None,
                            dispatch_candidates: Vec::new(),
                            span: tok.span,
                        });
                        rf.push(ReferenceFact {
                            module: m.name.clone(),
                            procedure: proc.clone(),
                            name: tok.text.clone(),
                            resolution: if property_assignment && self_qualified {
                                "resolved_self_property_write_reference"
                            } else if property_assignment {
                                "qualified_module_property_write_reference"
                            } else if self_qualified {
                                "resolved_self_procedure_reference"
                            } else {
                                "qualified_module_procedure_reference"
                            }
                            .into(),
                            implicit_type: None,
                            span: tok.span,
                        });
                    } else if let Some(declaration) = target_module.declarations.iter().find(|d| {
                        canon(&d.name) == name
                            && !matches!(
                                d.kind.as_str(),
                                "user_type" | "enum" | "field" | "event" | "external_declare"
                            )
                            && (owner == mi || declaration_is_public_value(target_module, d))
                    }) {
                        rf.push(ReferenceFact {
                            module: m.name.clone(),
                            procedure: proc.clone(),
                            name: tok.text.clone(),
                            resolution: if self_qualified {
                                "resolved_self_module_symbol"
                            } else {
                                "resolved_qualified_module_symbol"
                            }
                            .into(),
                            implicit_type: None,
                            span: tok.span,
                        });
                        if host_profile == HostProfile::Excel && excel::is_data_access_name(&name) {
                            let eq = statement_assignment_eq(&tokens, i);
                            df.push(DataAccessFact {
                                module: m.name.clone(),
                                procedure: proc.clone(),
                                operation: if name.eq_ignore_ascii_case("add")
                                    || name.eq_ignore_ascii_case("delete")
                                    || name.eq_ignore_ascii_case("resize")
                                    || eq.is_some_and(|e| i < e)
                                {
                                    "write_candidate"
                                } else {
                                    "read_candidate"
                                }
                                .into(),
                                target: format!("{}.{}", target_module.name, declaration.name),
                                host_dependent: true,
                                span: tok.span,
                            });
                        }
                    } else {
                        rf.push(ReferenceFact {
                            module: m.name.clone(),
                            procedure: proc.clone(),
                            name: tok.text.clone(),
                            resolution: "unresolved_qualified_module_member".into(),
                            implicit_type: None,
                            span: tok.span,
                        });
                    }
                    i += 1;
                    continue;
                }
                if prev.is_some_and(|previous| previous.text == ".")
                    && i >= 2
                    && let Some(current_procedure) = proc.as_deref().and_then(|procedure| {
                        m.procedures
                            .iter()
                            .find(|candidate| candidate.name.eq_ignore_ascii_case(procedure))
                    })
                {
                    let receiver = Expr::Identifier(tokens[i - 2].text.clone(), tokens[i - 2].span);
                    if let Some((owner, self_access)) =
                        crate::typecheck::member_owner(project, mi, m, current_procedure, &receiver)
                    {
                        let target_module = &project.modules[owner];
                        let is_rvalue =
                            statement_assignment_eq(&tokens, i).is_some_and(|eq| i > eq);
                        let no_arg_function = is_rvalue
                            && next.is_some_and(|token| {
                                matches!(token.kind, TokenKind::Newline | TokenKind::Eof)
                            })
                            && target_module.procedures.iter().any(|candidate| {
                                canon(&candidate.name) == name
                                    && (self_access
                                        || !candidate.visibility.eq_ignore_ascii_case("private"))
                                    && (candidate.kind.eq_ignore_ascii_case("function")
                                        || candidate.kind.eq_ignore_ascii_case("property get"))
                                    && candidate.parameters.iter().all(|parameter| {
                                        parameter.optional || parameter.is_param_array
                                    })
                            });
                        let statement_call = line_starts_with(&tokens, i - 2, &tokens[i - 2].text)
                            || line_starts_with(&tokens, i - 2, "call");
                        let next_is_argument = next.is_some_and(|token| {
                            !matches!(
                                token.text.to_ascii_lowercase().as_str(),
                                "=" | ":="
                                    | "."
                                    | "!"
                                    | "+"
                                    | "-"
                                    | "*"
                                    | "/"
                                    | "&"
                                    | "<"
                                    | ">"
                                    | "<="
                                    | ">="
                                    | "<>"
                                    | ","
                                    | ":"
                                    | "as"
                                    | "then"
                                    | "else"
                            ) && !matches!(token.kind, TokenKind::Newline | TokenKind::Eof)
                        });
                        let typed_member_call = next.is_some_and(|token| token.text == "(")
                            || no_arg_function
                            || (statement_call && next_is_argument)
                            || (statement_call
                                && next.is_some_and(|token| {
                                    matches!(token.kind, TokenKind::Newline | TokenKind::Eof)
                                        || token.text == ":"
                                }));
                        let property_setters = target_module
                            .procedures
                            .iter()
                            .enumerate()
                            .filter(|(_, candidate)| {
                                canon(&candidate.name) == name
                                    && matches!(
                                        candidate.kind.to_ascii_lowercase().as_str(),
                                        "property let" | "property set"
                                    )
                                    && (self_access
                                        || !candidate.visibility.eq_ignore_ascii_case("private"))
                            })
                            .collect::<Vec<_>>();
                        if let Some(equal) =
                            statement_assignment_eq(&tokens, i).filter(|equal| i < *equal)
                            && property_setters.len() == 1
                        {
                            let (_, setter) = property_setters[0];
                            let mut arguments = if next.is_some_and(|token| token.text == "(") {
                                call_arguments(&tokens, i).unwrap_or_default()
                            } else {
                                Vec::new()
                            };
                            let mut value_end = equal + 1;
                            while value_end < tokens.len()
                                && tokens[value_end].kind != TokenKind::Newline
                                && tokens[value_end].text != ":"
                            {
                                value_end += 1;
                            }
                            arguments.push(render_call_argument(&tokens[equal + 1..value_end]));
                            let (bindings, issues) =
                                bind_property_setter_arguments(&setter.parameters, &arguments);
                            diagnose_argument_binding(
                                &setter.name,
                                &setter.parameters,
                                arguments.len(),
                                &bindings,
                                &issues,
                                ArgumentBindingSite {
                                    source: &m.source_name,
                                    span: tok.span,
                                },
                                diagnostics,
                            );
                            if !issues.is_empty() {
                                diagnostics.push(Diagnostic {
                                    code: "VBA2022",
                                    severity: argument_binding_issue_severity(&issues),
                                    message: format!(
                                        "property assignment to '{}' has invalid arguments: {}",
                                        setter.name,
                                        issues.join("; ")
                                    ),
                                    source: m.source_name.clone(),
                                    span: tok.span,
                                });
                            }
                            append_argument_input_facts(
                                CallInputContext {
                                    project,
                                    module_index: mi,
                                    module: m,
                                    procedure: proc.clone(),
                                },
                                &format!("{}.{}", target_module.name, setter.name),
                                (&setter.parameters, &bindings),
                                "property_set_argument_candidate",
                                tok.span,
                                &mut data_flow,
                            );
                            let interface_is_implemented =
                                project.modules.iter().any(|candidate| {
                                    candidate.implemented_interfaces.iter().any(|interface| {
                                        canon(interface) == canon(&target_module.name)
                                    })
                                });
                            let dispatch_candidates = if interface_is_implemented {
                                interface_implementation_candidates(
                                    project,
                                    &target_module.name,
                                    &name,
                                    Some(&setter.kind),
                                )
                            } else {
                                Vec::new()
                            };
                            cf.push(CallFact {
                                module: m.name.clone(),
                                procedure: proc.clone(),
                                target: tok.text.clone(),
                                resolution: if dispatch_candidates.is_empty() {
                                    "resolved_typed_object_property_setter"
                                } else if dispatch_candidates.len() == 1 {
                                    "interface_property_set_dispatch_candidate"
                                } else {
                                    "ambiguous_interface_property_set_dispatch_candidates"
                                }
                                .into(),
                                argument_count: Some(arguments.len()),
                                arguments,
                                external_library: None,
                                external_alias: None,
                                dispatch_candidates,
                                span: tok.span,
                            });
                            rf.push(ReferenceFact {
                                module: m.name.clone(),
                                procedure: proc.clone(),
                                name: tok.text.clone(),
                                resolution: "typed_object_property_write_reference".into(),
                                implicit_type: None,
                                span: tok.span,
                            });
                            i += 1;
                            continue;
                        }
                        let interface_field =
                            target_module.declarations.iter().find(|declaration| {
                                canon(&declaration.name) == name
                                    && matches!(
                                        declaration.kind.as_str(),
                                        "variable"
                                            | "global"
                                            | "static"
                                            | "constant"
                                            | "with_events"
                                    )
                                    && (self_access
                                        || owner == mi
                                        || !declaration.visibility.eq_ignore_ascii_case("private"))
                            });
                        if let Some(field) = interface_field {
                            let is_write =
                                statement_assignment_eq(&tokens, i).is_some_and(|equal| i < equal);
                            let interface_is_implemented =
                                project.modules.iter().any(|candidate| {
                                    candidate.implemented_interfaces.iter().any(|interface| {
                                        canon(interface) == canon(&target_module.name)
                                    })
                                });
                            if is_write && interface_is_implemented {
                                let field_type = declaration_type_name(target_module, field);
                                let setter_kinds =
                                    match field_type.as_deref().and_then(|type_name| {
                                        interface_member_is_object_type(project, owner, type_name)
                                    }) {
                                        Some(true) => vec!["Property Set"],
                                        Some(false) => vec!["Property Let"],
                                        None => vec!["Property Let", "Property Set"],
                                    };
                                let mut dispatch_candidates = Vec::new();
                                for setter_kind in setter_kinds {
                                    dispatch_candidates.extend(
                                        interface_implementation_candidates(
                                            project,
                                            &target_module.name,
                                            &name,
                                            Some(setter_kind),
                                        ),
                                    );
                                }
                                dispatch_candidates.sort();
                                dispatch_candidates.dedup();
                                let equal = statement_assignment_eq(&tokens, i).unwrap();
                                let mut end = equal + 1;
                                while end < tokens.len()
                                    && tokens[end].kind != TokenKind::Newline
                                    && tokens[end].text != ":"
                                {
                                    end += 1;
                                }
                                let value = render_call_argument(&tokens[equal + 1..end]);
                                let resolution = match dispatch_candidates.len() {
                                    0 => "incomplete_interface_property_set_dispatch",
                                    1 => "interface_property_set_dispatch_candidate",
                                    _ => "ambiguous_interface_property_set_dispatch_candidates",
                                };
                                let arguments = vec![value];
                                append_argument_input_facts(
                                    CallInputContext {
                                        project,
                                        module_index: mi,
                                        module: m,
                                        procedure: proc.clone(),
                                    },
                                    &format!("{}.{}", target_module.name, field.name),
                                    (&[], &[(0, arguments[0].clone())]),
                                    "interface_property_set_argument_candidate",
                                    tok.span,
                                    &mut data_flow,
                                );
                                cf.push(CallFact {
                                    module: m.name.clone(),
                                    procedure: proc.clone(),
                                    target: tok.text.clone(),
                                    resolution: resolution.into(),
                                    argument_count: Some(arguments.len()),
                                    arguments,
                                    external_library: None,
                                    external_alias: None,
                                    dispatch_candidates,
                                    span: tok.span,
                                });
                                rf.push(ReferenceFact {
                                    module: m.name.clone(),
                                    procedure: proc.clone(),
                                    name: tok.text.clone(),
                                    resolution: "interface_property_write_reference".into(),
                                    implicit_type: None,
                                    span: tok.span,
                                });
                            } else if !is_write && interface_is_implemented {
                                let dispatch_candidates = interface_implementation_candidates(
                                    project,
                                    &target_module.name,
                                    &name,
                                    Some("Property Get"),
                                );
                                let resolution = match dispatch_candidates.len() {
                                    0 => "incomplete_interface_property_get_dispatch",
                                    1 => "interface_property_get_dispatch_candidate",
                                    _ => "ambiguous_interface_property_get_dispatch_candidates",
                                };
                                cf.push(CallFact {
                                    module: m.name.clone(),
                                    procedure: proc.clone(),
                                    target: tok.text.clone(),
                                    resolution: resolution.into(),
                                    argument_count: Some(0),
                                    arguments: Vec::new(),
                                    external_library: None,
                                    external_alias: None,
                                    dispatch_candidates,
                                    span: tok.span,
                                });
                                rf.push(ReferenceFact {
                                    module: m.name.clone(),
                                    procedure: proc.clone(),
                                    name: tok.text.clone(),
                                    resolution: "interface_property_read_reference".into(),
                                    implicit_type: None,
                                    span: tok.span,
                                });
                            } else {
                                rf.push(ReferenceFact {
                                    module: m.name.clone(),
                                    procedure: proc.clone(),
                                    name: tok.text.clone(),
                                    resolution: if is_write {
                                        "resolved_typed_object_property_write_candidate"
                                    } else {
                                        "resolved_typed_object_member"
                                    }
                                    .into(),
                                    implicit_type: None,
                                    span: tok.span,
                                });
                            }
                            i += 1;
                            continue;
                        }
                        if typed_member_call {
                            let mut candidates =
                                procedure_candidates_for_call(project, index, owner, &name);
                            if !self_access {
                                candidates.retain(|(_, candidate)| {
                                    !target_module.procedures[*candidate]
                                        .visibility
                                        .eq_ignore_ascii_case("private")
                                });
                            }
                            let has_private = !self_access
                                && target_module.procedures.iter().any(|candidate| {
                                    canon(&candidate.name) == name
                                        && candidate.visibility.eq_ignore_ascii_case("private")
                                });
                            let interface_is_implemented =
                                project.modules.iter().any(|candidate| {
                                    candidate.implemented_interfaces.iter().any(|interface| {
                                        canon(interface) == canon(&target_module.name)
                                    })
                                });
                            let dispatch_candidates = if interface_is_implemented {
                                let interface_member_kind = candidates
                                    .first()
                                    .map(|(_, idx)| target_module.procedures[*idx].kind.as_str());
                                interface_implementation_candidates(
                                    project,
                                    &target_module.name,
                                    &name,
                                    interface_member_kind,
                                )
                            } else {
                                Vec::new()
                            };
                            let arguments = call_arguments(&tokens, i).unwrap_or_default();
                            let resolution = if interface_is_implemented {
                                match dispatch_candidates.len() {
                                    0 => "incomplete_interface_dispatch_candidate",
                                    1 => "interface_dispatch_candidate",
                                    _ => "ambiguous_interface_dispatch_candidates",
                                }
                            } else {
                                match candidates.as_slice() {
                                    [_] => "resolved_typed_object_member",
                                    [_, ..] => "ambiguous_typed_object_member",
                                    [] if has_private => "inaccessible_private_object_member",
                                    [] => "unresolved_typed_object_member",
                                }
                            };
                            if candidates.len() == 1 {
                                let (_, procedure_index) = candidates[0];
                                let callee = &target_module.procedures[procedure_index];
                                let (bindings, issues) =
                                    bind_arguments(&callee.parameters, &arguments, false);
                                diagnose_argument_binding(
                                    &callee.name,
                                    &callee.parameters,
                                    arguments.len(),
                                    &bindings,
                                    &issues,
                                    ArgumentBindingSite {
                                        source: &m.source_name,
                                        span: tok.span,
                                    },
                                    diagnostics,
                                );
                                if !issues.is_empty() {
                                    diagnostics.push(Diagnostic {
                                        code: "VBA2022",
                                        severity: argument_binding_issue_severity(&issues),
                                        message: format!(
                                            "call to '{}' has invalid arguments: {}",
                                            callee.name,
                                            issues.join("; ")
                                        ),
                                        source: m.source_name.clone(),
                                        span: tok.span,
                                    });
                                }
                                diagnose_byval_array_arguments(
                                    &callee.parameters,
                                    &bindings,
                                    m,
                                    proc.as_deref(),
                                    &m.source_name,
                                    tok.span,
                                    diagnostics,
                                );
                                diagnose_call_argument_type_mismatches(
                                    CallTypeContext {
                                        project,
                                        caller_module_index: mi,
                                        caller_module: m,
                                        caller_procedure: proc.as_deref(),
                                        callee_module: target_module,
                                        callee_name: &callee.name,
                                        callee_kind: &callee.kind,
                                        source: &m.source_name,
                                        host_profile,
                                        span: tok.span,
                                    },
                                    &callee.parameters,
                                    &bindings,
                                    diagnostics,
                                );
                                append_argument_input_facts(
                                    CallInputContext {
                                        project,
                                        module_index: mi,
                                        module: m,
                                        procedure: proc.clone(),
                                    },
                                    &format!("{}.{}", target_module.name, callee.name),
                                    (&callee.parameters, &bindings),
                                    "procedure_argument_input_candidate",
                                    tok.span,
                                    &mut data_flow,
                                );
                                let return_target = statement_assignment_eq(&tokens, i)
                                    .filter(|eq| i > *eq)
                                    .and_then(|eq| call_assignment_target(&tokens, i, eq));
                                if matches!(
                                    callee.kind.to_ascii_lowercase().as_str(),
                                    "function" | "property get"
                                ) && let Some(lhs) = return_target
                                {
                                    let return_sources = data_flow
                                        .iter()
                                        .filter(|fact| {
                                            fact.module.eq_ignore_ascii_case(&target_module.name)
                                                && fact.procedure.as_deref().is_some_and(|name| {
                                                    name.eq_ignore_ascii_case(&callee.name)
                                                })
                                                && canon(&fact.target) == canon(&callee.name)
                                                && matches!(
                                                    fact.transfer.as_str(),
                                                    "assignment" | "object_assignment"
                                                )
                                        })
                                        .cloned()
                                        .collect::<Vec<_>>();
                                    append_function_return_facts(
                                        project,
                                        (m, proc.clone(), &lhs),
                                        (target_module, callee),
                                        (&bindings, &return_sources),
                                        tok.span,
                                        &mut data_flow,
                                    );
                                }
                                for (formal_index, actual) in bindings {
                                    let formal = &callee.parameters[formal_index];
                                    if parameter_is_effectively_byref(callee, formal_index, formal)
                                        && parameter_is_written(callee, &formal.name)
                                        && is_assignable_argument(&actual)
                                    {
                                        data_flow.push(DataFlowFact {
                                            module: m.name.clone(),
                                            procedure: proc.clone(),
                                            target: actual,
                                            inputs: vec![callee.name.clone(), formal.name.clone()],
                                            transfer: "byref_argument_write".into(),
                                            argument_slot_index: None,
                                            value_expression: None,
                                            call_callee_module: Some(target_module.name.clone()),
                                            call_callee_procedure: Some(callee.name.clone()),
                                            span: tok.span,
                                        });
                                    }
                                }
                            } else if has_private {
                                diagnostics.push(Diagnostic {
                                    code: "VBA2021",
                                    severity: Severity::Warning,
                                    message: format!(
                                        "call to private member '{}' through an object reference is not accessible",
                                        tok.text
                                    ),
                                    source: m.source_name.clone(),
                                    span: tok.span,
                                });
                            }
                            cf.push(CallFact {
                                module: m.name.clone(),
                                procedure: proc.clone(),
                                target: tok.text.clone(),
                                resolution: resolution.into(),
                                argument_count: Some(arguments.len()),
                                arguments,
                                external_library: None,
                                external_alias: None,
                                dispatch_candidates,
                                span: tok.span,
                            });
                            rf.push(ReferenceFact {
                                module: m.name.clone(),
                                procedure: proc.clone(),
                                name: tok.text.clone(),
                                resolution: "typed_object_member_call_reference".into(),
                                implicit_type: None,
                                span: tok.span,
                            });
                            i += 1;
                            continue;
                        }
                    } else {
                        let statement_call = line_starts_with(&tokens, i - 2, &tokens[i - 2].text)
                            || line_starts_with(&tokens, i - 2, "call");
                        if next.is_some_and(|token| token.text == "(") || statement_call {
                            let arguments = call_arguments(&tokens, i).unwrap_or_default();
                            cf.push(CallFact {
                                module: m.name.clone(),
                                procedure: proc.clone(),
                                target: tok.text.clone(),
                                resolution: "unresolved_member_call_candidate".into(),
                                argument_count: Some(arguments.len()),
                                arguments,
                                external_library: None,
                                external_alias: None,
                                dispatch_candidates: Vec::new(),
                                span: tok.span,
                            });
                        }
                    }
                }
                let excel_member =
                    host_profile == HostProfile::Excel && excel::is_known_member(&name);
                rf.push(ReferenceFact {
                    module: m.name.clone(),
                    procedure: proc.clone(),
                    name: tok.text.clone(),
                    resolution: if excel_member {
                        "excel_object_model_member_candidate"
                    } else {
                        "member_or_host_property_unresolved"
                    }
                    .into(),
                    implicit_type: None,
                    span: tok.span,
                });
                if excel_member && next.is_some_and(|t| t.text == "(") {
                    let arguments = call_arguments(&tokens, i);
                    cf.push(CallFact {
                        module: m.name.clone(),
                        procedure: proc.clone(),
                        target: tok.text.clone(),
                        resolution: "excel_object_model_call_candidate".into(),
                        argument_count: arguments.as_ref().map(Vec::len),
                        arguments: arguments.unwrap_or_default(),
                        external_library: None,
                        external_alias: None,
                        dispatch_candidates: Vec::new(),
                        span: tok.span,
                    });
                }
                if host_profile == HostProfile::Excel && excel::is_data_access_name(&name) {
                    let eq = statement_assignment_eq(&tokens, i);
                    df.push(DataAccessFact {
                        module: m.name.clone(),
                        procedure: proc.clone(),
                        operation: if name.eq_ignore_ascii_case("add")
                            || name.eq_ignore_ascii_case("delete")
                            || name.eq_ignore_ascii_case("resize")
                            || eq.is_some_and(|e| i < e)
                        {
                            "write_candidate"
                        } else {
                            "read_candidate"
                        }
                        .into(),
                        target: data_access_target(&tokens, i),
                        host_dependent: true,
                        span: tok.span,
                    });
                }
                i += 1;
                continue;
            }
            if canon(&tok.text) == "get" && line_starts_with(&tokens, i, "get") {
                df.push(DataAccessFact {
                    module: m.name.clone(),
                    procedure: proc.clone(),
                    operation: "file_io_candidate".into(),
                    target: data_access_target(&tokens, i),
                    host_dependent: true,
                    span: tok.span,
                });
                append_vba_file_flow_fact(
                    &tokens,
                    i,
                    &name,
                    m,
                    proc.clone(),
                    tok.span,
                    &mut data_flow,
                );
                rf.push(ReferenceFact {
                    module: m.name.clone(),
                    procedure: proc.clone(),
                    name: tok.text.clone(),
                    resolution: "vba_file_io_statement".into(),
                    implicit_type: None,
                    span: tok.span,
                });
                i += 1;
                continue;
            }
            if is_declaration_position(prev) || is_keyword(&tok.text) {
                i += 1;
                continue;
            }
            if is_function_result_assignment(m, proc.as_deref(), &tokens, i, &tok.text) {
                rf.push(ReferenceFact {
                    module: m.name.clone(),
                    procedure: proc.clone(),
                    name: tok.text.clone(),
                    resolution: "function_result_assignment".into(),
                    implicit_type: None,
                    span: tok.span,
                });
                i += 1;
                continue;
            }
            let is_lvalue = is_assignment_lvalue(&tokens, i);
            if prev.is_some_and(|x| matches!(canon(&x.text).as_str(), "goto" | "gosub" | "resume"))
            {
                rf.push(ReferenceFact {
                    module: m.name.clone(),
                    procedure: proc.clone(),
                    name: tok.text.clone(),
                    resolution: if proc.as_ref().is_some_and(|procedure| {
                        procedure_labels
                            .get(&canon(procedure))
                            .is_some_and(|labels| {
                                labels.contains(&canonical_statement_label(&tok.text))
                            })
                    }) {
                        "resolved_local_label"
                    } else {
                        "unresolved_label"
                    }
                    .into(),
                    implicit_type: None,
                    span: tok.span,
                });
                i += 1;
                continue;
            }
            let public_symbols = public_symbol_index
                .get(&name)
                .into_iter()
                .flatten()
                .filter(|(owner, _)| *owner != mi)
                .map(|(owner, declaration)| {
                    (
                        &project.modules[*owner],
                        &project.modules[*owner].declarations[*declaration],
                    )
                })
                .collect::<Vec<_>>();
            let declared_variable = declared_locally || !public_symbols.is_empty();
            let explicit_call = prev.is_some_and(|t| t.text.eq_ignore_ascii_case("call"));
            let has_visible_procedure = index.get(&name).is_some_and(|entries| {
                entries.iter().any(|(owner, proc_index)| {
                    *owner == mi
                        || (matches!(
                            project.modules[*owner].module_kind.as_deref(),
                            Some("standard") | None
                        ) && !project.modules[*owner].procedures[*proc_index]
                            .visibility
                            .eq_ignore_ascii_case("private"))
                })
            });
            let call = explicit_call
                || (!is_lvalue
                    && !declared_variable
                    && (has_visible_procedure
                        || next.is_some_and(|t| t.text == "(")
                        || is_bare_call(&tokens, i)));
            if call {
                let procedure_candidates = procedure_candidates_for_call(project, index, mi, &name);
                let inaccessible_procedure = procedure_candidates.is_empty()
                    && index.get(&name).is_some_and(|entries| {
                        entries.iter().any(|(owner, proc_index)| {
                            *owner != mi
                                && project.modules[*owner].procedures[*proc_index]
                                    .visibility
                                    .eq_ignore_ascii_case("private")
                        })
                    });
                let declared_external =
                    project.modules.iter().enumerate().any(|(index, module)| {
                        module.declarations.iter().any(|d| {
                            d.kind == "external_declare"
                                && canon(&d.name) == name
                                && (index == mi || !d.visibility.eq_ignore_ascii_case("private"))
                        })
                    });
                let inaccessible_external =
                    project.modules.iter().enumerate().any(|(index, module)| {
                        index != mi
                            && module.declarations.iter().any(|d| {
                                d.kind == "external_declare"
                                    && canon(&d.name) == name
                                    && d.visibility.eq_ignore_ascii_case("private")
                            })
                    });
                let is_raise_event = statement_starts_with_keyword(&tokens, i, "raiseevent");
                let arguments = call_arguments(&tokens, i);
                let has_named_event_argument = is_raise_event
                    && arguments.as_ref().is_some_and(|arguments| {
                        arguments.iter().any(|argument| argument.contains(":="))
                    });
                let event_declaration = m.declarations.iter().find(|declaration| {
                    declaration.kind == "event" && canon(&declaration.name) == name
                });
                let declared_event = event_declaration.is_some();
                let unqualified_requires_qualification = !is_raise_event
                    && !declared_variable
                    && procedure_candidates.is_empty()
                    && !declared_external
                    && !inaccessible_external
                    && !declared_event
                    && unqualified_procedure_requires_qualification(project, index, mi, &name);
                if unqualified_requires_qualification {
                    diagnostics.push(Diagnostic {
                        code: "VBA2138",
                        severity: Severity::Error,
                        message: format!(
                            "public procedure '{}' shares a project or module name and must be qualified outside its defining module",
                            tok.text
                        ),
                        source: m.source_name.clone(),
                        span: tok.span,
                    });
                }
                let event_dispatch_candidates = event_declaration
                    .filter(|_| is_raise_event && !has_named_event_argument)
                    .map(|event| matching_event_handlers(project, mi, event))
                    .unwrap_or_default();
                let mut resolution = if is_raise_event {
                    if has_named_event_argument {
                        "invalid_event_argument_list"
                    } else if declared_event {
                        if event_dispatch_candidates.is_empty() {
                            "resolved_module_event"
                        } else {
                            "event_dispatch_candidate"
                        }
                    } else {
                        "unresolved_raiseevent_target"
                    }
                } else {
                    match procedure_candidates.as_slice() {
                        [candidate] => {
                            if candidate.0 == mi {
                                "resolved_project_procedure"
                            } else {
                                "resolved_cross_module_procedure"
                            }
                        }
                        [_, ..] => "ambiguous_procedure_name",
                        [] if inaccessible_procedure => "inaccessible_private_procedure",
                        [] if unqualified_requires_qualification => {
                            "unqualified_procedure_requires_qualification"
                        }
                        [] if declared_event => "resolved_module_event",
                        [] if declared_external => "resolved_external_declaration",
                        [] if inaccessible_external => "inaccessible_private_external_declaration",
                        [] if host_profile == HostProfile::Excel
                            && excel::is_known_member(&name) =>
                        {
                            "excel_object_model_call_candidate"
                        }
                        [] => {
                            if intrinsic_names().contains(name.as_str()) {
                                "intrinsic_or_host_function"
                            } else {
                                "unresolved_external_or_host_call"
                            }
                        }
                    }
                };
                let argument_count = arguments.as_ref().map(Vec::len);
                let declared_signature = if is_raise_event {
                    (!has_named_event_argument)
                        .then_some(event_declaration)
                        .flatten()
                } else {
                    event_declaration.or_else(|| {
                        project
                            .modules
                            .iter()
                            .enumerate()
                            .find_map(|(index, module)| {
                                module.declarations.iter().find(|d| {
                                    d.kind == "external_declare"
                                        && canon(&d.name) == name
                                        && (index == mi
                                            || !d.visibility.eq_ignore_ascii_case("private"))
                                })
                            })
                    })
                };
                if is_raise_event && let Some(arguments) = arguments.as_deref() {
                    append_event_handler_argument_facts(
                        project,
                        &event_dispatch_candidates,
                        arguments,
                        m,
                        proc.clone(),
                        tok.span,
                        &mut data_flow,
                    );
                }
                if procedure_candidates.len() == 1 && !is_raise_event {
                    let (target_module, target_proc) = procedure_candidates[0];
                    let callee = &project.modules[target_module].procedures[target_proc];
                    if target_module != mi && callee.visibility.eq_ignore_ascii_case("private") {
                        resolution = "inaccessible_private_procedure";
                        diagnostics.push(Diagnostic{code:"VBA2021",severity:Severity::Warning,message:format!("call to private procedure '{}' from another module is not accessible",callee.name),source:m.source_name.clone(),span:tok.span});
                    }
                    if let Some(arguments) = &arguments {
                        let (bindings, argument_issues) =
                            bind_arguments(&callee.parameters, arguments, false);
                        diagnose_argument_binding(
                            &callee.name,
                            &callee.parameters,
                            arguments.len(),
                            &bindings,
                            &argument_issues,
                            ArgumentBindingSite {
                                source: &m.source_name,
                                span: tok.span,
                            },
                            diagnostics,
                        );
                        if !argument_issues.is_empty() {
                            diagnostics.push(Diagnostic {
                                code: "VBA2022",
                                severity: argument_binding_issue_severity(&argument_issues),
                                message: format!(
                                    "call to '{}' has invalid arguments: {}",
                                    callee.name,
                                    argument_issues.join("; ")
                                ),
                                source: m.source_name.clone(),
                                span: tok.span,
                            });
                        }
                        diagnose_byval_array_arguments(
                            &callee.parameters,
                            &bindings,
                            m,
                            proc.as_deref(),
                            &m.source_name,
                            tok.span,
                            diagnostics,
                        );
                        diagnose_call_argument_type_mismatches(
                            CallTypeContext {
                                project,
                                caller_module_index: mi,
                                caller_module: m,
                                caller_procedure: proc.as_deref(),
                                callee_module: &project.modules[target_module],
                                callee_name: &callee.name,
                                callee_kind: &callee.kind,
                                source: &m.source_name,
                                host_profile,
                                span: tok.span,
                            },
                            &callee.parameters,
                            &bindings,
                            diagnostics,
                        );
                        append_argument_input_facts(
                            CallInputContext {
                                project,
                                module_index: mi,
                                module: m,
                                procedure: proc.clone(),
                            },
                            &format!("{}.{}", project.modules[target_module].name, callee.name),
                            (&callee.parameters, &bindings),
                            "procedure_argument_input_candidate",
                            tok.span,
                            &mut data_flow,
                        );
                        let return_target = statement_assignment_eq(&tokens, i)
                            .filter(|eq| i > *eq)
                            .and_then(|eq| call_assignment_target(&tokens, i, eq));
                        if matches!(
                            callee.kind.to_ascii_lowercase().as_str(),
                            "function" | "property get"
                        ) && let Some(lhs) = return_target
                        {
                            let return_sources = data_flow
                                .iter()
                                .filter(|fact| {
                                    fact.module
                                        .eq_ignore_ascii_case(&project.modules[target_module].name)
                                        && fact.procedure.as_deref().is_some_and(|name| {
                                            name.eq_ignore_ascii_case(&callee.name)
                                        })
                                        && canon(&fact.target) == canon(&callee.name)
                                        && matches!(
                                            fact.transfer.as_str(),
                                            "assignment" | "object_assignment"
                                        )
                                })
                                .cloned()
                                .collect::<Vec<_>>();
                            append_function_return_facts(
                                project,
                                (m, proc.clone(), &lhs),
                                (&project.modules[target_module], callee),
                                (&bindings, &return_sources),
                                tok.span,
                                &mut data_flow,
                            );
                        }
                        for (formal_index, actual) in bindings {
                            let formal = &callee.parameters[formal_index];
                            let by_ref =
                                parameter_is_effectively_byref(callee, formal_index, formal);
                            if by_ref
                                && parameter_is_written(callee, &formal.name)
                                && is_assignable_argument(&actual)
                            {
                                data_flow.push(DataFlowFact {
                                    module: m.name.clone(),
                                    procedure: proc.clone(),
                                    target: actual.clone(),
                                    inputs: vec![callee.name.clone(), formal.name.clone()],
                                    transfer: "byref_argument_write".into(),
                                    argument_slot_index: None,
                                    value_expression: None,
                                    call_callee_module: Some(
                                        project.modules[target_module].name.clone(),
                                    ),
                                    call_callee_procedure: Some(callee.name.clone()),
                                    span: tok.span,
                                });
                            }
                        }
                    }
                } else if let (Some(declaration), Some(arguments)) =
                    (declared_signature, arguments.as_ref())
                {
                    let (bindings, argument_issues) = bind_arguments(
                        &declaration.parameters,
                        arguments,
                        declaration.kind == "external_declare",
                    );
                    diagnose_argument_binding(
                        &declaration.name,
                        &declaration.parameters,
                        arguments.len(),
                        &bindings,
                        &argument_issues,
                        ArgumentBindingSite {
                            source: &m.source_name,
                            span: tok.span,
                        },
                        diagnostics,
                    );
                    if !argument_issues.is_empty() {
                        diagnostics.push(Diagnostic {
                            code: "VBA2022",
                            severity: argument_binding_issue_severity(&argument_issues),
                            message: format!(
                                "call to '{}' has invalid arguments: {}",
                                declaration.name,
                                argument_issues.join("; ")
                            ),
                            source: m.source_name.clone(),
                            span: tok.span,
                        });
                    }
                    diagnose_byval_array_arguments(
                        &declaration.parameters,
                        &bindings,
                        m,
                        proc.as_deref(),
                        &m.source_name,
                        tok.span,
                        diagnostics,
                    );
                    if declaration.kind == "external_declare"
                        && let Some(declaration_module) = project.modules.iter().find(|module| {
                            module
                                .declarations
                                .iter()
                                .any(|candidate| std::ptr::eq(candidate, declaration))
                        })
                    {
                        diagnose_call_argument_type_mismatches(
                            CallTypeContext {
                                project,
                                caller_module_index: mi,
                                caller_module: m,
                                caller_procedure: proc.as_deref(),
                                callee_module: declaration_module,
                                callee_name: &declaration.name,
                                callee_kind: &declaration.kind,
                                source: &m.source_name,
                                host_profile,
                                span: tok.span,
                            },
                            &declaration.parameters,
                            &bindings,
                            diagnostics,
                        );
                    }
                    let (target, transfer) = if declaration.kind == "external_declare" {
                        let library = declaration
                            .external_library
                            .as_deref()
                            .unwrap_or(&declaration.name);
                        let alias = declaration
                            .external_alias
                            .as_deref()
                            .unwrap_or(&declaration.name);
                        (
                            format!("{library}!{alias}"),
                            "external_argument_input_candidate",
                        )
                    } else {
                        (declaration.name.clone(), "event_argument_input_candidate")
                    };
                    append_argument_input_facts(
                        CallInputContext {
                            project,
                            module_index: mi,
                            module: m,
                            procedure: proc.clone(),
                        },
                        &target,
                        (&declaration.parameters, &bindings),
                        transfer,
                        tok.span,
                        &mut data_flow,
                    );
                }
                let external_metadata = (resolution == "resolved_external_declaration")
                    .then_some(declared_signature)
                    .flatten()
                    .filter(|declaration| declaration.kind == "external_declare");
                cf.push(CallFact {
                    module: m.name.clone(),
                    procedure: proc.clone(),
                    target: tok.text.clone(),
                    resolution: resolution.into(),
                    argument_count,
                    arguments: arguments.unwrap_or_default(),
                    external_library: external_metadata
                        .and_then(|declaration| declaration.external_library.clone()),
                    external_alias: external_metadata
                        .and_then(|declaration| declaration.external_alias.clone()),
                    dispatch_candidates: event_dispatch_candidates,
                    span: tok.span,
                });
                if declared_external && !is_raise_event {
                    df.push(DataAccessFact {
                        module: m.name.clone(),
                        procedure: proc.clone(),
                        operation: "external_api_call_candidate".into(),
                        target: call_target(&tokens, i),
                        host_dependent: true,
                        span: tok.span,
                    });
                }
                if inaccessible_external && !is_raise_event {
                    diagnostics.push(Diagnostic {
                        code: "VBA2021",
                        severity: Severity::Warning,
                        message: format!(
                            "call to private external declaration '{}' from another module is not accessible",
                            tok.text
                        ),
                        source: m.source_name.clone(),
                        span: tok.span,
                    });
                }
                if inaccessible_procedure && !is_raise_event {
                    diagnostics.push(Diagnostic {
                        code: "VBA2021",
                        severity: Severity::Warning,
                        message: format!(
                            "call to private procedure '{}' from another module is not accessible",
                            tok.text
                        ),
                        source: m.source_name.clone(),
                        span: tok.span,
                    });
                }
                if let Some(op) = external_operation(&tok.text, &tokens, i) {
                    df.push(DataAccessFact {
                        module: m.name.clone(),
                        procedure: proc.clone(),
                        operation: op.into(),
                        target: call_target(&tokens, i),
                        host_dependent: true,
                        span: tok.span,
                    });
                    if op == "file_io_candidate" {
                        append_vba_file_flow_fact(
                            &tokens,
                            i,
                            &name,
                            m,
                            proc.clone(),
                            tok.span,
                            &mut data_flow,
                        );
                    }
                }
            } else {
                let resolution = if is_intrinsic_constant(&tok.text) {
                    "intrinsic_constant"
                } else if host_profile == HostProfile::Excel && excel::is_constant(&tok.text) {
                    "excel_type_library_constant_candidate"
                } else if declared_locally {
                    "declared_symbol"
                } else if public_symbols.len() > 1 {
                    let modules = public_symbols
                        .iter()
                        .map(|(module, _)| module.name.as_str())
                        .collect::<Vec<_>>()
                        .join(", ");
                    diagnostics.push(Diagnostic {
                        code: "VBA2031",
                        severity: Severity::Error,
                        message: format!(
                            "unqualified name '{}' matches multiple public module-level symbols: {}",
                            tok.text, modules
                        ),
                        source: m.source_name.clone(),
                        span: tok.span,
                    });
                    "ambiguous_public_project_symbol"
                } else if public_symbols.len() == 1 {
                    let (owner, declaration) = &public_symbols[0];
                    if owner.module_kind.as_deref() == Some("standard") {
                        "resolved_public_project_symbol"
                    } else if owner.module_kind.is_none() {
                        "public_project_symbol_candidate"
                    } else if declaration.kind == "enum_member" {
                        "public_enum_member_candidate"
                    } else {
                        "public_project_symbol_candidate"
                    }
                } else if m
                    .procedures
                    .iter()
                    .any(|procedure| canon(&procedure.name) == name)
                {
                    "resolved_module_procedure"
                } else if is_variant_type_constant(&tok.text)
                    || is_compare_method_constant(&tok.text)
                {
                    "intrinsic_constant"
                } else if intrinsic_names().contains(name.as_str()) {
                    "intrinsic_or_host_function"
                } else {
                    "unresolved_name_or_implicit_variant"
                };
                let implicit_type = if resolution == "unresolved_name_or_implicit_variant" {
                    implicit_type_candidate(m, &tok.text)
                } else {
                    None
                };
                if explicit && resolution == "unresolved_name_or_implicit_variant" {
                    diagnostics.push(Diagnostic {
                        code: "VBA2030",
                        severity: Severity::Warning,
                        message: if let Some(type_name) = &implicit_type {
                            format!("'{}' is unresolved under Option Explicit; its implicit type candidate would be {}, but a referenced or host-provided symbol may still exist", tok.text, type_name)
                        } else {
                            format!("'{}' is unresolved under Option Explicit; a referenced or host-provided symbol may still exist", tok.text)
                        },
                        source: m.source_name.clone(),
                        span: tok.span,
                    });
                }
                rf.push(ReferenceFact {
                    module: m.name.clone(),
                    procedure: proc.clone(),
                    name: tok.text.clone(),
                    resolution: resolution.into(),
                    implicit_type,
                    span: tok.span,
                });
            }
            if host_profile == HostProfile::Excel && excel::is_data_access_name(&name) {
                let eq = statement_assignment_eq(&tokens, i);
                df.push(DataAccessFact {
                    module: m.name.clone(),
                    procedure: proc.clone(),
                    operation: if name.eq_ignore_ascii_case("add")
                        || name.eq_ignore_ascii_case("delete")
                        || name.eq_ignore_ascii_case("resize")
                        || eq.is_some_and(|e| i < e)
                    {
                        "write_candidate"
                    } else {
                        "read_candidate"
                    }
                    .into(),
                    target: data_access_target(&tokens, i),
                    host_dependent: true,
                    span: tok.span,
                });
            }
            if name == "iif" {
                diagnostics.push(Diagnostic{code:"VBA2010",severity:Severity::Note,message:"VBA IIf evaluates both result expressions; both operands are retained rather than modeled as short-circuit branches".into(),source:m.source_name.clone(),span:tok.span});
            }
            i += 1;
        }
        collect_with_bound_calls(
            WithCallAnalysis {
                project,
                index,
                module_index: mi,
                module: m,
                tokens: &tokens,
                host_profile,
            },
            WithCallFacts {
                diagnostics,
                calls: &mut cf,
                references: &mut rf,
                data_flow: &mut data_flow,
            },
        );
        collect_default_member_index_facts(
            DefaultMemberAnalysis {
                project,
                module_index: mi,
                module: m,
                host_profile,
            },
            DefaultMemberFacts {
                diagnostics,
                calls: &mut cf,
                references: &mut rf,
                data_flow: &mut data_flow,
            },
        );
        collect_callbyname_member_candidates(
            DefaultMemberAnalysis {
                project,
                module_index: mi,
                module: m,
                host_profile,
            },
            DefaultMemberFacts {
                diagnostics,
                calls: &mut cf,
                references: &mut rf,
                data_flow: &mut data_flow,
            },
        );
        collect_excel_application_run_candidates(
            project,
            mi,
            m,
            host_profile,
            &mut cf,
            &mut rf,
            diagnostics,
        );
        collect_excel_ontime_call_facts(
            project,
            mi,
            m,
            host_profile,
            &mut cf,
            &mut rf,
            diagnostics,
        );
        if m.procedures
            .iter()
            .any(|p| contains_statement(&p.statements, "on_error"))
        {
            diagnostics.push(Diagnostic{code:"VBA2012",severity:Severity::Warning,message:"possible On Error transfers are over-approximated; statement faultability and host/runtime error outcomes are not proven".into(),source:m.source_name.clone(),span:Span::default()});
        }
    }
    compose_local_call_return_candidates(project, &mut data_flow);
    compose_transitive_byref_write_candidates(project, &cf, &mut data_flow);
    FactSet {
        procedures: pf,
        references: rf,
        calls: cf,
        data_accesses: df,
        data_flow,
        type_facts: typeof_type_facts,
    }
}

#[derive(Clone)]
struct OmittedWithCall {
    receiver: Expr,
    member: String,
    arguments: Vec<String>,
    member_span: Span,
    assignment_target: Option<String>,
}

struct WithCallAnalysis<'a> {
    project: &'a Project,
    index: &'a HashMap<String, Vec<(usize, usize)>>,
    module_index: usize,
    module: &'a Module,
    tokens: &'a [Token],
    host_profile: HostProfile,
}

struct WithCallFacts<'a> {
    diagnostics: &'a mut Vec<Diagnostic>,
    calls: &'a mut Vec<CallFact>,
    references: &'a mut Vec<ReferenceFact>,
    data_flow: &'a mut Vec<DataFlowFact>,
}

fn collect_with_bound_calls(analysis: WithCallAnalysis<'_>, facts: WithCallFacts<'_>) {
    let WithCallAnalysis {
        project,
        index,
        module_index,
        module,
        tokens,
        host_profile,
    } = analysis;
    let WithCallFacts {
        diagnostics,
        calls,
        references,
        data_flow,
    } = facts;
    for procedure in &module.procedures {
        let mut omitted_calls = Vec::new();
        collect_omitted_with_calls_in_statements(
            &procedure.statements,
            tokens,
            &module.analysis_text,
            &mut omitted_calls,
        );
        for omitted_call in omitted_calls {
            let Some((owner, self_access)) = crate::typecheck::member_owner(
                project,
                module_index,
                module,
                procedure,
                &omitted_call.receiver,
            ) else {
                continue;
            };
            let target_module = &project.modules[owner];
            let mut candidates =
                procedure_candidates_for_call(project, index, owner, &canon(&omitted_call.member));
            candidates.retain(|(candidate_module, _)| *candidate_module == owner);
            if !self_access {
                candidates.retain(|(candidate_module, candidate)| {
                    !project.modules[*candidate_module].procedures[*candidate]
                        .visibility
                        .eq_ignore_ascii_case("private")
                });
            }
            let has_private = !self_access
                && target_module.procedures.iter().any(|candidate| {
                    canon(&candidate.name) == canon(&omitted_call.member)
                        && candidate.visibility.eq_ignore_ascii_case("private")
                });
            let interface_is_implemented = project.modules.iter().any(|candidate| {
                candidate
                    .implemented_interfaces
                    .iter()
                    .any(|interface| canon(interface) == canon(&target_module.name))
            });
            let dispatch_candidates = if interface_is_implemented {
                let member_kind = candidates
                    .first()
                    .map(|(_, candidate)| target_module.procedures[*candidate].kind.as_str());
                interface_implementation_candidates(
                    project,
                    &target_module.name,
                    &omitted_call.member,
                    member_kind,
                )
            } else {
                Vec::new()
            };
            let resolution = if interface_is_implemented {
                match dispatch_candidates.len() {
                    0 => "incomplete_interface_dispatch_candidate",
                    1 => "interface_dispatch_candidate",
                    _ => "ambiguous_interface_dispatch_candidates",
                }
            } else {
                match candidates.as_slice() {
                    [_] => "resolved_typed_object_member",
                    [_, ..] => "ambiguous_typed_object_member",
                    [] if has_private => "inaccessible_private_object_member",
                    [] => "unresolved_typed_object_member",
                }
            };
            if candidates.len() == 1 {
                let (_, callee_index) = candidates[0];
                let callee = &target_module.procedures[callee_index];
                let (bindings, issues) =
                    bind_arguments(&callee.parameters, &omitted_call.arguments, false);
                diagnose_argument_binding(
                    &callee.name,
                    &callee.parameters,
                    omitted_call.arguments.len(),
                    &bindings,
                    &issues,
                    ArgumentBindingSite {
                        source: &module.source_name,
                        span: omitted_call.member_span,
                    },
                    diagnostics,
                );
                if !issues.is_empty() {
                    diagnostics.push(Diagnostic {
                        code: "VBA2022",
                        severity: argument_binding_issue_severity(&issues),
                        message: format!(
                            "call to '{}' has invalid arguments: {}",
                            callee.name,
                            issues.join("; ")
                        ),
                        source: module.source_name.clone(),
                        span: omitted_call.member_span,
                    });
                }
                diagnose_call_argument_type_mismatches(
                    CallTypeContext {
                        project,
                        caller_module_index: module_index,
                        caller_module: module,
                        caller_procedure: Some(&procedure.name),
                        callee_module: target_module,
                        callee_name: &callee.name,
                        callee_kind: &callee.kind,
                        source: &module.source_name,
                        host_profile,
                        span: omitted_call.member_span,
                    },
                    &callee.parameters,
                    &bindings,
                    diagnostics,
                );
                diagnose_byval_array_arguments(
                    &callee.parameters,
                    &bindings,
                    module,
                    Some(&procedure.name),
                    &module.source_name,
                    omitted_call.member_span,
                    diagnostics,
                );
                append_argument_input_facts(
                    CallInputContext {
                        project,
                        module_index,
                        module,
                        procedure: Some(procedure.name.clone()),
                    },
                    &format!("{}.{}", target_module.name, callee.name),
                    (&callee.parameters, &bindings),
                    "procedure_argument_input_candidate",
                    omitted_call.member_span,
                    data_flow,
                );
                if let Some(target) = omitted_call.assignment_target.as_deref()
                    && matches!(
                        callee.kind.to_ascii_lowercase().as_str(),
                        "function" | "property get"
                    )
                {
                    let return_sources = data_flow
                        .iter()
                        .filter(|fact| {
                            fact.module.eq_ignore_ascii_case(&target_module.name)
                                && fact
                                    .procedure
                                    .as_deref()
                                    .is_some_and(|name| name.eq_ignore_ascii_case(&callee.name))
                                && canon(&fact.target) == canon(&callee.name)
                                && matches!(
                                    fact.transfer.as_str(),
                                    "assignment" | "object_assignment"
                                )
                        })
                        .cloned()
                        .collect::<Vec<_>>();
                    append_function_return_facts(
                        project,
                        (module, Some(procedure.name.clone()), target),
                        (target_module, callee),
                        (&bindings, &return_sources),
                        omitted_call.member_span,
                        data_flow,
                    );
                }
                for (formal_index, actual) in bindings {
                    let formal = &callee.parameters[formal_index];
                    if parameter_is_effectively_byref(callee, formal_index, formal)
                        && parameter_is_written(callee, &formal.name)
                        && is_assignable_argument(&actual)
                    {
                        data_flow.push(DataFlowFact {
                            module: module.name.clone(),
                            procedure: Some(procedure.name.clone()),
                            target: actual,
                            inputs: vec![callee.name.clone(), formal.name.clone()],
                            transfer: "byref_argument_write".into(),
                            argument_slot_index: None,
                            value_expression: None,
                            call_callee_module: Some(target_module.name.clone()),
                            call_callee_procedure: Some(callee.name.clone()),
                            span: omitted_call.member_span,
                        });
                    }
                }
            } else if has_private {
                diagnostics.push(Diagnostic {
                    code: "VBA2021",
                    severity: Severity::Warning,
                    message: format!(
                        "call to private member '{}' through an object reference is not accessible",
                        omitted_call.member
                    ),
                    source: module.source_name.clone(),
                    span: omitted_call.member_span,
                });
            }
            if !calls.iter().any(|call| {
                call.module == module.name
                    && call.procedure.as_deref() == Some(&procedure.name)
                    && call.span == omitted_call.member_span
            }) {
                calls.push(CallFact {
                    module: module.name.clone(),
                    procedure: Some(procedure.name.clone()),
                    target: omitted_call.member.clone(),
                    resolution: resolution.into(),
                    argument_count: Some(omitted_call.arguments.len()),
                    arguments: omitted_call.arguments.clone(),
                    external_library: None,
                    external_alias: None,
                    dispatch_candidates,
                    span: omitted_call.member_span,
                });
            }
            if let Some(reference) = references.iter_mut().find(|reference| {
                reference.module == module.name
                    && reference.procedure.as_deref() == Some(&procedure.name)
                    && canon(&reference.name) == canon(&omitted_call.member)
                    && reference.span == omitted_call.member_span
            }) {
                reference.resolution = "typed_object_member_call_reference".into();
            } else {
                references.push(ReferenceFact {
                    module: module.name.clone(),
                    procedure: Some(procedure.name.clone()),
                    name: omitted_call.member,
                    resolution: "typed_object_member_call_reference".into(),
                    implicit_type: None,
                    span: omitted_call.member_span,
                });
            }
        }
    }
}

fn collect_omitted_with_calls_in_statements(
    statements: &[Statement],
    tokens: &[Token],
    source: &str,
    out: &mut Vec<OmittedWithCall>,
) {
    for statement in statements {
        if let Some(expression) = &statement.parsed_expression {
            let direct_call_span = omitted_with_call_member_span(expression, tokens);
            let direct_call_target = (statement.kind == "assignment")
                .then(|| {
                    statement.parsed_target.as_ref().and_then(|target| {
                        source
                            .get(target.span().start..target.span().end)
                            .map(|value| value.trim().to_string())
                    })
                })
                .flatten();
            let start = out.len();
            collect_omitted_with_calls_in_expression(expression, tokens, source, out);
            if let (Some(member_span), Some(target)) = (direct_call_span, direct_call_target)
                && let Some(call) = out[start..]
                    .iter_mut()
                    .find(|call| call.member_span == member_span)
            {
                call.assignment_target = Some(target);
            }
        }
        if let Some(target) = &statement.parsed_target {
            collect_omitted_with_calls_in_expression(target, tokens, source, out);
        }
        collect_omitted_with_calls_in_statements(&statement.children, tokens, source, out);
    }
}

fn omitted_with_call_member_span(expression: &Expr, tokens: &[Token]) -> Option<Span> {
    let Expr::Call { callee, .. } = expression else {
        return None;
    };
    let Expr::Member {
        member,
        span,
        access: MemberAccessKind::Dot,
        ..
    } = callee.as_ref()
    else {
        return None;
    };
    if !tokens
        .iter()
        .any(|token| token.span.start == span.start && matches!(token.text.as_str(), "." | "!"))
    {
        return None;
    }
    tokens
        .iter()
        .find(|token| {
            token.span.end == span.end
                && token.kind == TokenKind::Identifier
                && canon(&token.text) == canon(member)
        })
        .map(|token| token.span)
}

fn collect_omitted_with_calls_in_expression(
    expression: &Expr,
    tokens: &[Token],
    source: &str,
    out: &mut Vec<OmittedWithCall>,
) {
    match expression {
        Expr::Call { callee, args, .. } => {
            if let Expr::Member {
                object,
                member,
                span,
                access: MemberAccessKind::Dot,
                ..
            } = callee.as_ref()
                && tokens.iter().any(|token| {
                    token.span.start == span.start && matches!(token.text.as_str(), "." | "!")
                })
                && let Some(member_token) = tokens.iter().find(|token| {
                    token.span.end == span.end
                        && token.kind == TokenKind::Identifier
                        && canon(&token.text) == canon(member)
                })
            {
                out.push(OmittedWithCall {
                    receiver: object.as_ref().clone(),
                    member: member.clone(),
                    arguments: args
                        .iter()
                        .map(|argument| {
                            source
                                .get(argument.span().start..argument.span().end)
                                .unwrap_or("")
                                .trim()
                                .to_string()
                        })
                        .collect(),
                    member_span: member_token.span,
                    assignment_target: None,
                });
            }
            collect_omitted_with_calls_in_expression(callee, tokens, source, out);
            for argument in args {
                collect_omitted_with_calls_in_expression(argument, tokens, source, out);
            }
        }
        Expr::Unary { value, .. }
        | Expr::Group(value, _)
        | Expr::TypeOfIs {
            expression: value, ..
        } => {
            collect_omitted_with_calls_in_expression(value, tokens, source, out);
        }
        Expr::Binary { left, right, .. } => {
            collect_omitted_with_calls_in_expression(left, tokens, source, out);
            collect_omitted_with_calls_in_expression(right, tokens, source, out);
        }
        Expr::Member { object, .. } => {
            collect_omitted_with_calls_in_expression(object, tokens, source, out);
        }
        Expr::NamedArgument { value, .. } => {
            collect_omitted_with_calls_in_expression(value, tokens, source, out);
        }
        Expr::Identifier(..) | Expr::Literal(..) | Expr::Unknown(..) => {}
    }
}

#[derive(Clone, Copy)]
enum DefaultMemberAccess {
    Get,
    Let,
    Set,
    Invoke,
}

#[derive(Clone)]
struct DefaultMemberIndexUse {
    receiver_name: String,
    span: Span,
    arguments: Vec<String>,
    access: DefaultMemberAccess,
    assignment_target: Option<String>,
}

struct DefaultMemberAnalysis<'a> {
    project: &'a Project,
    module_index: usize,
    module: &'a Module,
    host_profile: HostProfile,
}

struct DefaultMemberFacts<'a> {
    diagnostics: &'a mut Vec<Diagnostic>,
    calls: &'a mut Vec<CallFact>,
    references: &'a mut Vec<ReferenceFact>,
    data_flow: &'a mut Vec<DataFlowFact>,
}

fn collect_default_member_index_facts(
    analysis: DefaultMemberAnalysis<'_>,
    facts: DefaultMemberFacts<'_>,
) {
    let DefaultMemberAnalysis {
        project,
        module_index,
        module,
        host_profile,
    } = analysis;
    let DefaultMemberFacts {
        diagnostics,
        calls,
        references,
        data_flow,
    } = facts;
    for procedure in &module.procedures {
        let mut uses = Vec::new();
        collect_default_member_uses_in_statements(
            &procedure.statements,
            &module.analysis_text,
            &mut uses,
        );
        for member_use in uses {
            if resolve_array_target(module, procedure, &member_use.receiver_name)
                .is_some_and(|info| info.is_array)
                || project
                    .modules
                    .iter()
                    .enumerate()
                    .any(|(owner, candidate)| {
                        owner != module_index
                            && matches!(candidate.module_kind.as_deref(), Some("standard") | None)
                            && candidate.declarations.iter().any(|declaration| {
                                declaration.is_array
                                    && canon(&declaration.name) == canon(&member_use.receiver_name)
                                    && declaration_is_public_value(candidate, declaration)
                            })
                    })
            {
                continue;
            }
            let receiver = Expr::Identifier(member_use.receiver_name.clone(), member_use.span);
            let Some((owner, _self_access)) =
                crate::typecheck::member_owner(project, module_index, module, procedure, &receiver)
            else {
                continue;
            };
            let target_module = &project.modules[owner];
            if !is_object_module(target_module) {
                continue;
            }
            let default_members = target_module
                .procedures
                .iter()
                .filter(|candidate| {
                    candidate.automation_member_id == Some(0)
                        && candidate.visibility.eq_ignore_ascii_case("public")
                })
                .collect::<Vec<_>>();
            if default_members.is_empty() {
                diagnostics.push(Diagnostic {
                    code: "VBA2110",
                    severity: Severity::Warning,
                    message: format!(
                        "indexed class variable '{}' has no explicit in-project VB_UserMemId = 0 default member; source attributes or external type metadata may be missing",
                        member_use.receiver_name
                    ),
                    source: module.source_name.clone(),
                    span: member_use.span,
                });
                record_default_member_use(
                    member_use,
                    module,
                    procedure,
                    "unresolved_default_member_index",
                    &[],
                    calls,
                    references,
                );
                continue;
            }

            let accessors = default_members
                .iter()
                .copied()
                .filter(|candidate| match member_use.access {
                    DefaultMemberAccess::Get => {
                        candidate.kind.eq_ignore_ascii_case("Property Get")
                            || candidate.kind.eq_ignore_ascii_case("Function")
                    }
                    DefaultMemberAccess::Let => candidate.kind.eq_ignore_ascii_case("Property Let"),
                    DefaultMemberAccess::Set => candidate.kind.eq_ignore_ascii_case("Property Set"),
                    DefaultMemberAccess::Invoke => {
                        candidate.kind.eq_ignore_ascii_case("Function")
                            || candidate.kind.eq_ignore_ascii_case("Sub")
                    }
                })
                .collect::<Vec<_>>();
            let matching = accessors
                .iter()
                .copied()
                .filter_map(|candidate| {
                    bind_default_member_arguments(
                        &candidate.parameters,
                        &member_use.arguments,
                        matches!(
                            member_use.access,
                            DefaultMemberAccess::Let | DefaultMemberAccess::Set
                        ),
                    )
                    .map(|bindings| (candidate, bindings))
                })
                .collect::<Vec<_>>();
            if matching.len() == 1 {
                let (callee, bindings) = &matching[0];
                let arguments = &member_use.arguments;
                let call_span = member_use.span;
                diagnose_argument_binding(
                    &callee.name,
                    &callee.parameters,
                    arguments.len(),
                    bindings,
                    &[],
                    ArgumentBindingSite {
                        source: &module.source_name,
                        span: call_span,
                    },
                    diagnostics,
                );
                diagnose_call_argument_type_mismatches(
                    CallTypeContext {
                        project,
                        caller_module_index: module_index,
                        caller_module: module,
                        caller_procedure: Some(&procedure.name),
                        callee_module: target_module,
                        callee_name: &callee.name,
                        callee_kind: &callee.kind,
                        source: &module.source_name,
                        host_profile,
                        span: call_span,
                    },
                    &callee.parameters,
                    bindings,
                    diagnostics,
                );
                diagnose_byval_array_arguments(
                    &callee.parameters,
                    bindings,
                    module,
                    Some(&procedure.name),
                    &module.source_name,
                    call_span,
                    diagnostics,
                );
                append_argument_input_facts(
                    CallInputContext {
                        project,
                        module_index,
                        module,
                        procedure: Some(procedure.name.clone()),
                    },
                    &format!("{}.{}", target_module.name, callee.name),
                    (&callee.parameters, bindings),
                    "default_member_argument_input_candidate",
                    call_span,
                    data_flow,
                );
                if let Some(target) = member_use.assignment_target.as_deref()
                    && matches!(
                        callee.kind.to_ascii_lowercase().as_str(),
                        "function" | "property get"
                    )
                {
                    let return_sources = data_flow
                        .iter()
                        .filter(|fact| {
                            fact.module.eq_ignore_ascii_case(&target_module.name)
                                && fact
                                    .procedure
                                    .as_deref()
                                    .is_some_and(|name| name.eq_ignore_ascii_case(&callee.name))
                                && canon(&fact.target) == canon(&callee.name)
                                && matches!(
                                    fact.transfer.as_str(),
                                    "assignment" | "object_assignment"
                                )
                        })
                        .cloned()
                        .collect::<Vec<_>>();
                    append_function_return_facts(
                        project,
                        (module, Some(procedure.name.clone()), target),
                        (target_module, callee),
                        (bindings, &return_sources),
                        call_span,
                        data_flow,
                    );
                }
                for (parameter_index, actual) in bindings {
                    let formal = &callee.parameters[*parameter_index];
                    let setter_value = matches!(
                        callee.kind.to_ascii_lowercase().as_str(),
                        "property let" | "property set"
                    ) && *parameter_index + 1 == callee.parameters.len();
                    if !setter_value
                        && !formal.is_param_array
                        && formal.passing.eq_ignore_ascii_case("ByRef")
                        && parameter_is_written(callee, &formal.name)
                        && is_assignable_argument(actual)
                    {
                        data_flow.push(DataFlowFact {
                            module: module.name.clone(),
                            procedure: Some(procedure.name.clone()),
                            target: actual.clone(),
                            inputs: vec![callee.name.clone(), formal.name.clone()],
                            transfer: "default_member_byref_write_candidate".into(),
                            argument_slot_index: None,
                            value_expression: None,
                            call_callee_module: Some(target_module.name.clone()),
                            call_callee_procedure: Some(callee.name.clone()),
                            span: call_span,
                        });
                    }
                }
                record_default_member_use(
                    member_use,
                    module,
                    procedure,
                    "resolved_default_member_candidate",
                    &[format!("{}.{}", target_module.name, callee.name)],
                    calls,
                    references,
                );
            } else if matching.len() > 1 {
                let candidates = matching
                    .iter()
                    .map(|(candidate, _)| format!("{}.{}", target_module.name, candidate.name))
                    .collect::<Vec<_>>();
                diagnostics.push(Diagnostic {
                    code: "VBA2112",
                    severity: Severity::Warning,
                    message: format!(
                        "indexed default member call on '{}' matches multiple members: {}",
                        member_use.receiver_name,
                        candidates.join(", ")
                    ),
                    source: module.source_name.clone(),
                    span: member_use.span,
                });
                record_default_member_use(
                    member_use,
                    module,
                    procedure,
                    "ambiguous_default_member_candidate",
                    &candidates,
                    calls,
                    references,
                );
            } else {
                let message = if accessors.is_empty()
                    && matches!(member_use.access, DefaultMemberAccess::Invoke)
                    && default_members.iter().any(|candidate| {
                        matches!(
                            candidate.kind.to_ascii_lowercase().as_str(),
                            "property get" | "property let" | "property set"
                        )
                    }) {
                    format!(
                        "Call cannot invoke default property member(s) of '{}' as a Sub or Function",
                        target_module.name
                    )
                } else {
                    format!(
                        "indexed default member call on '{}' has no accessor compatible with {} argument(s)",
                        member_use.receiver_name,
                        member_use.arguments.len()
                    )
                };
                diagnostics.push(Diagnostic {
                    code: if accessors.is_empty()
                        && matches!(member_use.access, DefaultMemberAccess::Invoke)
                    {
                        "VBA2113"
                    } else {
                        "VBA2111"
                    },
                    severity: Severity::Error,
                    message,
                    source: module.source_name.clone(),
                    span: member_use.span,
                });
                let member_name = default_members
                    .first()
                    .map(|candidate| candidate.name.clone())
                    .unwrap_or_else(|| member_use.receiver_name.clone());
                record_default_member_use(
                    member_use,
                    module,
                    procedure,
                    "invalid_default_member_argument_list",
                    &[format!("{}.{}", target_module.name, member_name)],
                    calls,
                    references,
                );
            }
        }
    }
}

fn bind_property_setter_arguments(
    parameters: &[Parameter],
    arguments: &[String],
) -> (Vec<(usize, String)>, Vec<String>) {
    let Some(value_index) = parameters.len().checked_sub(1) else {
        return bind_arguments(parameters, arguments, false);
    };
    if !parameters[..value_index]
        .iter()
        .any(|parameter| parameter.is_param_array)
    {
        return bind_arguments(parameters, arguments, false);
    }
    if arguments
        .iter()
        .any(|argument| argument.split_once(":=").is_some())
    {
        return bind_arguments(parameters, arguments, false);
    }
    if arguments.is_empty()
        || arguments
            .last()
            .is_some_and(|argument| argument.trim().is_empty())
    {
        return (
            Vec::new(),
            vec![format!(
                "required positional parameter '{}' is omitted",
                parameters[value_index].name
            )],
        );
    }

    let (index_arguments, value_arguments) = arguments.split_at(arguments.len() - 1);
    let (mut bindings, mut issues) =
        bind_arguments(&parameters[..value_index], index_arguments, false);
    let (value_bindings, value_issues) =
        bind_arguments(&parameters[value_index..], value_arguments, false);
    bindings.extend(
        value_bindings
            .into_iter()
            .map(|(index, argument)| (index + value_index, argument)),
    );
    issues.extend(value_issues);
    (bindings, issues)
}

fn bind_default_member_arguments(
    parameters: &[Parameter],
    arguments: &[String],
    property_setter: bool,
) -> Option<Vec<(usize, String)>> {
    let (bindings, issues) = if property_setter {
        bind_property_setter_arguments(parameters, arguments)
    } else {
        bind_arguments(parameters, arguments, false)
    };
    if !issues.is_empty() {
        return None;
    }
    let assigned = bindings
        .iter()
        .map(|(index, _)| *index)
        .collect::<HashSet<_>>();
    parameters
        .iter()
        .enumerate()
        .all(|(index, parameter)| {
            parameter.optional || parameter.is_param_array || assigned.contains(&index)
        })
        .then_some(bindings)
}

fn record_default_member_use(
    member_use: DefaultMemberIndexUse,
    module: &Module,
    procedure: &Procedure,
    resolution: &str,
    candidates: &[String],
    calls: &mut Vec<CallFact>,
    references: &mut [ReferenceFact],
) {
    let target = candidates
        .first()
        .and_then(|candidate| {
            candidate
                .split_once('.')
                .map(|(_, member)| member.to_string())
        })
        .unwrap_or_else(|| member_use.receiver_name.clone());
    if let Some(existing) = calls.iter_mut().find(|call| {
        call.module == module.name
            && call.procedure.as_deref() == Some(&procedure.name)
            && call.span == member_use.span
    }) {
        existing.target = target;
        existing.resolution = resolution.into();
        existing.argument_count = Some(member_use.arguments.len());
        existing.arguments = member_use.arguments.clone();
        existing.dispatch_candidates = candidates.to_vec();
    } else {
        calls.push(CallFact {
            module: module.name.clone(),
            procedure: Some(procedure.name.clone()),
            target,
            resolution: resolution.into(),
            argument_count: Some(member_use.arguments.len()),
            arguments: member_use.arguments.clone(),
            dispatch_candidates: candidates.to_vec(),
            span: member_use.span,
            ..CallFact::default()
        });
    }
    if let Some(reference) = references.iter_mut().find(|reference| {
        reference.module == module.name
            && reference.procedure.as_deref() == Some(&procedure.name)
            && canon(&reference.name) == canon(&member_use.receiver_name)
            && reference.span == member_use.span
    }) {
        reference.resolution = "default_member_receiver_reference".into();
    }
}

fn collect_default_member_uses_in_statements(
    statements: &[Statement],
    source: &str,
    out: &mut Vec<DefaultMemberIndexUse>,
) {
    for statement in statements {
        if statement.kind == "assignment" {
            if let Some(target) = &statement.parsed_target {
                let set = statement.expression.as_deref().is_some_and(|text| {
                    text.trim_start().starts_with("Set ") || text.trim_start().starts_with("set ")
                });
                let access = if set {
                    DefaultMemberAccess::Set
                } else {
                    DefaultMemberAccess::Let
                };
                if let Some(mut member_use) = bang_default_member_use(target, access, None) {
                    if let Some(value) = statement.parsed_expression.as_ref() {
                        member_use.arguments.push(expression_source(source, value));
                    }
                    out.push(member_use);
                    if let Expr::Member { object, .. } = target {
                        collect_nested_default_calls(object, source, out);
                    }
                } else if let Some((receiver, mut arguments, span)) =
                    simple_object_index_call(target, source)
                {
                    if let Some(value) = statement.parsed_expression.as_ref() {
                        arguments.push(expression_source(source, value));
                    }
                    out.push(DefaultMemberIndexUse {
                        receiver_name: receiver,
                        span,
                        arguments,
                        access,
                        assignment_target: None,
                    });
                    collect_nested_default_calls(target, source, out);
                } else {
                    collect_nested_default_calls(target, source, out);
                }
            }
            if let Some(expression) = &statement.parsed_expression {
                let target = match expression {
                    Expr::Call { callee, .. }
                        if matches!(callee.as_ref(), Expr::Identifier(..)) =>
                    {
                        statement
                            .parsed_target
                            .as_ref()
                            .map(|target| expression_source(source, target))
                    }
                    Expr::Member {
                        access: MemberAccessKind::Bang,
                        ..
                    } => statement
                        .parsed_target
                        .as_ref()
                        .map(|target| expression_source(source, target)),
                    _ => None,
                };
                collect_default_member_calls_in_expression(
                    expression,
                    source,
                    DefaultMemberAccess::Get,
                    target,
                    out,
                );
            }
        } else if matches!(statement.kind.as_str(), "call" | "call_or_expression") {
            if let Some(expression) = &statement.parsed_expression {
                let direct_object_call = matches!(
                    expression,
                    Expr::Call { callee, .. } if matches!(callee.as_ref(), Expr::Identifier(..))
                );
                if direct_object_call {
                    collect_default_member_calls_in_expression(
                        expression,
                        source,
                        DefaultMemberAccess::Invoke,
                        None,
                        out,
                    );
                } else {
                    collect_default_member_calls_in_expression(
                        expression,
                        source,
                        DefaultMemberAccess::Get,
                        None,
                        out,
                    );
                }
            }
        } else if let Some(expression) = &statement.parsed_expression {
            collect_default_member_calls_in_expression(
                expression,
                source,
                DefaultMemberAccess::Get,
                None,
                out,
            );
        }
        collect_default_member_uses_in_statements(&statement.children, source, out);
    }
}

fn simple_object_index_call(
    expression: &Expr,
    source: &str,
) -> Option<(String, Vec<String>, Span)> {
    let Expr::Call { callee, args, .. } = expression else {
        return None;
    };
    let Expr::Identifier(receiver, span) = callee.as_ref() else {
        return None;
    };
    Some((
        receiver.clone(),
        args.iter()
            .map(|argument| expression_source(source, argument))
            .collect(),
        *span,
    ))
}

fn expression_source(source: &str, expression: &Expr) -> String {
    source
        .get(expression.span().start..expression.span().end)
        .unwrap_or("")
        .trim()
        .to_string()
}

fn bang_default_member_use(
    expression: &Expr,
    access: DefaultMemberAccess,
    assignment_target: Option<String>,
) -> Option<DefaultMemberIndexUse> {
    let Expr::Member {
        object,
        member,
        access: MemberAccessKind::Bang,
        span,
    } = expression
    else {
        return None;
    };
    let Expr::Identifier(receiver_name, _) = object.as_ref() else {
        return None;
    };
    Some(DefaultMemberIndexUse {
        receiver_name: receiver_name.clone(),
        span: *span,
        arguments: vec![format!("\"{}\"", member.replace('"', "\"\""))],
        access,
        assignment_target,
    })
}

fn collect_nested_default_calls(
    expression: &Expr,
    source: &str,
    out: &mut Vec<DefaultMemberIndexUse>,
) {
    match expression {
        Expr::Call { callee, args, .. } => {
            for argument in args {
                collect_default_member_calls_in_expression(
                    argument,
                    source,
                    DefaultMemberAccess::Get,
                    None,
                    out,
                );
            }
            collect_nested_default_calls(callee, source, out);
        }
        Expr::Unary { value, .. }
        | Expr::Group(value, _)
        | Expr::TypeOfIs {
            expression: value, ..
        } => {
            collect_nested_default_calls(value, source, out);
        }
        Expr::Binary { left, right, .. } => {
            collect_nested_default_calls(left, source, out);
            collect_nested_default_calls(right, source, out);
        }
        Expr::Member {
            object,
            access: MemberAccessKind::Bang,
            ..
        } => {
            if let Some(member_use) =
                bang_default_member_use(expression, DefaultMemberAccess::Get, None)
            {
                out.push(member_use);
            }
            collect_nested_default_calls(object, source, out);
        }
        Expr::Member { object, .. } => collect_nested_default_calls(object, source, out),
        Expr::NamedArgument { value, .. } => collect_nested_default_calls(value, source, out),
        Expr::Identifier(..) | Expr::Literal(..) | Expr::Unknown(..) => {}
    }
}

fn collect_default_member_calls_in_expression(
    expression: &Expr,
    source: &str,
    access: DefaultMemberAccess,
    assignment_target: Option<String>,
    out: &mut Vec<DefaultMemberIndexUse>,
) {
    match expression {
        Expr::Member {
            object,
            access: MemberAccessKind::Bang,
            ..
        } => {
            if let Some(member_use) = bang_default_member_use(expression, access, assignment_target)
            {
                out.push(member_use);
            }
            collect_nested_default_calls(object, source, out);
        }
        Expr::Call { callee, args, .. } => {
            if let Expr::Identifier(receiver_name, span) = callee.as_ref() {
                out.push(DefaultMemberIndexUse {
                    receiver_name: receiver_name.clone(),
                    span: *span,
                    arguments: args
                        .iter()
                        .map(|argument| expression_source(source, argument))
                        .collect(),
                    access,
                    assignment_target,
                });
                for argument in args {
                    collect_default_member_calls_in_expression(
                        argument,
                        source,
                        DefaultMemberAccess::Get,
                        None,
                        out,
                    );
                }
            } else {
                collect_nested_default_calls(expression, source, out);
            }
        }
        _ => collect_nested_default_calls(expression, source, out),
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum CallByNameKind {
    Method,
    Get,
    Let,
    Set,
}

#[derive(Clone)]
struct CallByNameUse {
    receiver: Option<Expr>,
    member_name: Option<String>,
    member_span: Span,
    call_type: Option<CallByNameKind>,
    outer_arguments: Vec<String>,
    member_arguments: Vec<String>,
    callee_span: Span,
    assignment_target: Option<String>,
}

#[derive(Clone)]
struct ExcelApplicationRunUse {
    call_span: Span,
    callee_span: Span,
    macro_name: Option<(String, Span)>,
    arguments: Vec<String>,
    has_named_arguments: bool,
}

#[derive(Clone)]
struct ExcelOnTimeUse {
    call_span: Span,
    callee_span: Span,
    procedure_name: Option<(String, Span)>,
    arguments: Vec<String>,
    has_required_arguments: bool,
    schedule_false: bool,
}

#[derive(Clone, Copy)]
struct ExcelApplicationRunAnalysis<'a> {
    project: &'a Project,
    module_index: usize,
    module: &'a Module,
    procedure: &'a Procedure,
    source: &'a str,
    host_profile: HostProfile,
}

fn collect_excel_application_run_candidates(
    project: &Project,
    module_index: usize,
    module: &Module,
    host_profile: HostProfile,
    calls: &mut Vec<CallFact>,
    references: &mut Vec<ReferenceFact>,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if host_profile != HostProfile::Excel {
        return;
    }
    for procedure in &module.procedures {
        let mut uses = Vec::new();
        collect_excel_application_run_uses(
            &procedure.statements,
            ExcelApplicationRunAnalysis {
                project,
                module_index,
                module,
                procedure,
                source: &module.analysis_text,
                host_profile,
            },
            &mut uses,
        );
        let mut seen = HashSet::new();
        uses.retain(|usage| seen.insert((usage.call_span.start, usage.call_span.end)));
        for usage in uses {
            let (resolution, dispatch_candidates) = if usage.has_named_arguments {
                diagnostics.push(Diagnostic {
                    code: "VBA2141",
                    severity: Severity::Error,
                    message: "Excel Application.Run does not support named arguments".into(),
                    source: module.source_name.clone(),
                    span: usage.callee_span,
                });
                ("invalid_application_run_named_arguments", Vec::new())
            } else if let Some((macro_name, _)) = &usage.macro_name {
                let candidates = excel_macro_candidates(project, macro_name);
                let resolution = match candidates.len() {
                    1 => "literal_macro_target_candidate",
                    2.. => "ambiguous_literal_macro_target_candidates",
                    _ => "dynamic_macro_invocation_candidate",
                };
                (resolution, candidates)
            } else {
                ("dynamic_macro_invocation_candidate", Vec::new())
            };

            if let Some(existing) = calls.iter_mut().find(|call| {
                call.module.eq_ignore_ascii_case(&module.name)
                    && call
                        .procedure
                        .as_deref()
                        .is_some_and(|name| name.eq_ignore_ascii_case(&procedure.name))
                    && canon(&call.target) == "run"
                    && call.span.start >= usage.call_span.start
                    && call.span.end <= usage.call_span.end
            }) {
                existing.target = "Application.Run".into();
                existing.resolution = resolution.into();
                existing.argument_count = Some(usage.arguments.len());
                existing.arguments = usage.arguments.clone();
                existing.dispatch_candidates = dispatch_candidates.clone();
            } else {
                calls.push(CallFact {
                    module: module.name.clone(),
                    procedure: Some(procedure.name.clone()),
                    target: "Application.Run".into(),
                    resolution: resolution.into(),
                    argument_count: Some(usage.arguments.len()),
                    arguments: usage.arguments.clone(),
                    dispatch_candidates: dispatch_candidates.clone(),
                    span: usage.callee_span,
                    ..CallFact::default()
                });
            }

            if let Some((macro_name, span)) = usage.macro_name
                && !references.iter().any(|reference| {
                    reference.module.eq_ignore_ascii_case(&module.name)
                        && reference
                            .procedure
                            .as_deref()
                            .is_some_and(|name| name.eq_ignore_ascii_case(&procedure.name))
                        && reference.span == span
                        && reference.resolution == "application_run_macro_name_candidate"
                })
            {
                references.push(ReferenceFact {
                    module: module.name.clone(),
                    procedure: Some(procedure.name.clone()),
                    name: macro_name,
                    resolution: "application_run_macro_name_candidate".into(),
                    span,
                    ..ReferenceFact::default()
                });
            }
        }
    }
}

fn collect_excel_application_run_uses(
    statements: &[Statement],
    analysis: ExcelApplicationRunAnalysis<'_>,
    out: &mut Vec<ExcelApplicationRunUse>,
) {
    for statement in statements {
        if let Some(expression) = &statement.parsed_expression {
            collect_excel_application_run_uses_in_expression(expression, analysis, out);
        }
        if let Some(target) = &statement.parsed_target {
            collect_excel_application_run_uses_in_expression(target, analysis, out);
        }
        collect_excel_application_run_uses(&statement.children, analysis, out);
    }
}

fn collect_excel_application_run_uses_in_expression(
    expression: &Expr,
    analysis: ExcelApplicationRunAnalysis<'_>,
    out: &mut Vec<ExcelApplicationRunUse>,
) {
    match expression {
        Expr::Call { callee, args, span } => {
            if let Expr::Member {
                object,
                member,
                access: MemberAccessKind::Dot,
                ..
            } = callee.as_ref()
                && canon(member) == "run"
                && is_excel_application_receiver(analysis, object)
            {
                let macro_argument = args.first();
                out.push(ExcelApplicationRunUse {
                    call_span: *span,
                    callee_span: callee.span(),
                    macro_name: macro_argument.and_then(|argument| {
                        static_string_expression(argument).map(|name| (name, argument.span()))
                    }),
                    arguments: args
                        .iter()
                        .map(|argument| expression_source(analysis.source, argument))
                        .collect(),
                    has_named_arguments: args
                        .iter()
                        .any(|argument| matches!(argument, Expr::NamedArgument { .. })),
                });
            }
            collect_excel_application_run_uses_in_expression(callee, analysis, out);
            for argument in args {
                collect_excel_application_run_uses_in_expression(argument, analysis, out);
            }
        }
        Expr::Unary { value, .. }
        | Expr::Group(value, _)
        | Expr::TypeOfIs {
            expression: value, ..
        } => {
            collect_excel_application_run_uses_in_expression(value, analysis, out);
        }
        Expr::Binary { left, right, .. } => {
            collect_excel_application_run_uses_in_expression(left, analysis, out);
            collect_excel_application_run_uses_in_expression(right, analysis, out);
        }
        Expr::Member { object, .. } => {
            collect_excel_application_run_uses_in_expression(object, analysis, out)
        }
        Expr::NamedArgument { value, .. } => {
            collect_excel_application_run_uses_in_expression(value, analysis, out)
        }
        Expr::Identifier(..) | Expr::Literal(..) | Expr::Unknown(..) => {}
    }
}

fn is_excel_application_receiver(
    analysis: ExcelApplicationRunAnalysis<'_>,
    expression: &Expr,
) -> bool {
    let ExcelApplicationRunAnalysis {
        project,
        module_index,
        module,
        procedure,
        source,
        host_profile,
    } = analysis;
    if host_profile != HostProfile::Excel {
        return false;
    }
    let mut local_names = HashSet::new();
    collect_declared_variable_names(&procedure.statements, &mut local_names);
    let is_shadowed = |name: &str| {
        let key = canon(name);
        procedure
            .parameters
            .iter()
            .any(|parameter| canon(&parameter.name) == key)
            || module
                .declarations
                .iter()
                .any(|declaration| canon(&declaration.name) == key)
            || local_names.contains(&key)
    };
    let syntax_known = match expression {
        Expr::Identifier(name, _) => canon(name) == "application" && !is_shadowed(name),
        Expr::Member {
            object,
            member,
            access: MemberAccessKind::Dot,
            ..
        } if canon(member) == "application" => {
            if let Expr::Identifier(receiver, _) = object.as_ref() {
                let receiver_name = canon(receiver);
                matches!(receiver_name.as_str(), "thisworkbook" | "activeworkbook")
                    && !is_shadowed(receiver)
            } else {
                false
            }
        }
        Expr::Group(value, _) => {
            return is_excel_application_receiver(analysis, value);
        }
        _ => false,
    };
    if syntax_known {
        return true;
    }
    let has_shadow_type =
        project.modules.iter().any(|candidate| {
            is_object_module(candidate) && canon(&candidate.name) == "application"
        }) || module.declarations.iter().any(|declaration| {
            declaration.kind == "user_type" && canon(&declaration.name) == "application"
        });
    if has_shadow_type {
        return false;
    }
    let receiver_source = expression_source(source, expression);
    infer_expression_type(
        project,
        module_index,
        module,
        &procedure.name,
        &receiver_source,
        host_profile,
    )
    .is_some_and(|type_name| {
        matches!(
            canon(&type_name).as_str(),
            "application" | "excel.application"
        )
    })
}

fn static_string_expression(expression: &Expr) -> Option<String> {
    match expression {
        Expr::Literal(value, crate::model::LiteralKind::String, _) => Some(value.clone()),
        Expr::Group(value, _) => static_string_expression(value),
        Expr::Binary {
            left, op, right, ..
        } if op == "&" || op == "+" => Some(format!(
            "{}{}",
            static_string_expression(left)?,
            static_string_expression(right)?
        )),
        _ => None,
    }
}

fn excel_macro_candidates(project: &Project, target: &str) -> Vec<String> {
    if target.is_empty()
        || target.contains(['!', '\'', '"'])
        || target.chars().any(char::is_whitespace)
    {
        return Vec::new();
    }
    let parts = target.split('.').collect::<Vec<_>>();
    if !(1..=2).contains(&parts.len()) || parts.iter().any(|part| part.is_empty()) {
        return Vec::new();
    }
    let (module_qualifier, procedure_name) = if parts.len() == 2 {
        (Some(parts[0]), parts[1])
    } else {
        (None, parts[0])
    };
    let mut candidates = Vec::new();
    for module in &project.modules {
        if !matches!(module.module_kind.as_deref(), Some("standard") | None)
            || module_qualifier.is_some_and(|qualifier| canon(&module.name) != canon(qualifier))
        {
            continue;
        }
        for procedure in &module.procedures {
            if canon(&procedure.name) == canon(procedure_name)
                && procedure.visibility.eq_ignore_ascii_case("public")
                && matches!(
                    procedure.kind.to_ascii_lowercase().as_str(),
                    "sub" | "function"
                )
            {
                candidates.push(format!("{}.{}", module.name, procedure.name));
            }
        }
    }
    candidates.sort_by_key(|candidate| canon(candidate));
    candidates.dedup_by(|left, right| canon(left) == canon(right));
    candidates
}

fn excel_ontime_macro_candidates(project: &Project, target: &str) -> Vec<String> {
    excel_macro_candidates(project, target)
        .into_iter()
        .filter(|candidate| {
            let Some((module_name, procedure_name)) = candidate.split_once('.') else {
                return false;
            };
            project
                .modules
                .iter()
                .find(|module| canon(&module.name) == canon(module_name))
                .and_then(|module| {
                    module.procedures.iter().find(|procedure| {
                        canon(&procedure.name) == canon(procedure_name)
                            && procedure.visibility.eq_ignore_ascii_case("public")
                            && procedure.parameters.is_empty()
                            && matches!(
                                procedure.kind.to_ascii_lowercase().as_str(),
                                "sub" | "function"
                            )
                    })
                })
                .is_some()
        })
        .collect()
}

fn collect_excel_ontime_call_facts(
    project: &Project,
    module_index: usize,
    module: &Module,
    host_profile: HostProfile,
    calls: &mut Vec<CallFact>,
    references: &mut Vec<ReferenceFact>,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if host_profile != HostProfile::Excel {
        return;
    }
    for procedure in &module.procedures {
        let mut uses = Vec::new();
        collect_excel_ontime_uses(
            &procedure.statements,
            ExcelApplicationRunAnalysis {
                project,
                module_index,
                module,
                procedure,
                source: &module.analysis_text,
                host_profile,
            },
            &mut uses,
        );
        let mut seen = HashSet::new();
        uses.retain(|usage| seen.insert((usage.call_span.start, usage.call_span.end)));
        for usage in uses {
            let candidates = if usage.has_required_arguments {
                usage
                    .procedure_name
                    .as_ref()
                    .map(|(name, _)| excel_ontime_macro_candidates(project, name))
                    .unwrap_or_default()
            } else {
                diagnostics.push(Diagnostic {
                    code: "VBA2142",
                    severity: Severity::Error,
                    message:
                        "Excel Application.OnTime requires EarliestTime and Procedure arguments"
                            .into(),
                    source: module.source_name.clone(),
                    span: usage.callee_span,
                });
                Vec::new()
            };
            let resolution = if !usage.has_required_arguments {
                "invalid_excel_ontime_required_arguments"
            } else if usage.schedule_false {
                "excel_ontime_cancel_candidate"
            } else {
                match candidates.len() {
                    1 => "excel_ontime_schedule_target_candidate",
                    2.. => "ambiguous_excel_ontime_schedule_targets",
                    _ => "dynamic_excel_ontime_schedule_candidate",
                }
            };
            if let Some(existing) = calls.iter_mut().find(|call| {
                call.module.eq_ignore_ascii_case(&module.name)
                    && call
                        .procedure
                        .as_deref()
                        .is_some_and(|name| name.eq_ignore_ascii_case(&procedure.name))
                    && canon(&call.target) == "ontime"
                    && call.span.start >= usage.call_span.start
                    && call.span.end <= usage.call_span.end
            }) {
                existing.target = "Application.OnTime".into();
                existing.resolution = resolution.into();
                existing.argument_count = Some(usage.arguments.len());
                existing.arguments = usage.arguments.clone();
                existing.dispatch_candidates = candidates.clone();
            } else {
                calls.push(CallFact {
                    module: module.name.clone(),
                    procedure: Some(procedure.name.clone()),
                    target: "Application.OnTime".into(),
                    resolution: resolution.into(),
                    argument_count: Some(usage.arguments.len()),
                    arguments: usage.arguments.clone(),
                    dispatch_candidates: candidates.clone(),
                    span: usage.callee_span,
                    ..CallFact::default()
                });
            }
            if let Some((macro_name, span)) = usage.procedure_name
                && !references.iter().any(|reference| {
                    reference.module.eq_ignore_ascii_case(&module.name)
                        && reference
                            .procedure
                            .as_deref()
                            .is_some_and(|name| name.eq_ignore_ascii_case(&procedure.name))
                        && reference.span == span
                        && reference.resolution == "application_ontime_procedure_name_candidate"
                })
            {
                references.push(ReferenceFact {
                    module: module.name.clone(),
                    procedure: Some(procedure.name.clone()),
                    name: macro_name,
                    resolution: "application_ontime_procedure_name_candidate".into(),
                    span,
                    ..ReferenceFact::default()
                });
            }
        }
    }
}

fn collect_excel_ontime_uses(
    statements: &[Statement],
    analysis: ExcelApplicationRunAnalysis<'_>,
    out: &mut Vec<ExcelOnTimeUse>,
) {
    for statement in statements {
        if let Some(expression) = &statement.parsed_expression {
            collect_excel_ontime_uses_in_expression(expression, analysis, out);
        }
        if let Some(target) = &statement.parsed_target {
            collect_excel_ontime_uses_in_expression(target, analysis, out);
        }
        collect_excel_ontime_uses(&statement.children, analysis, out);
    }
}

fn collect_excel_ontime_uses_in_expression(
    expression: &Expr,
    analysis: ExcelApplicationRunAnalysis<'_>,
    out: &mut Vec<ExcelOnTimeUse>,
) {
    match expression {
        Expr::Call { callee, args, span } => {
            if let Expr::Member {
                object,
                member,
                access: MemberAccessKind::Dot,
                ..
            } = callee.as_ref()
                && canon(member) == "ontime"
                && is_excel_application_receiver(analysis, object)
            {
                let earliest_time_argument = excel_ontime_argument(args, "earliesttime", 0);
                let procedure_argument = excel_ontime_argument(args, "procedure", 1);
                let schedule_argument = excel_ontime_argument(args, "schedule", 3);
                out.push(ExcelOnTimeUse {
                    call_span: *span,
                    callee_span: callee.span(),
                    procedure_name: procedure_argument.and_then(|argument| {
                        static_string_expression(argument).map(|name| (name, argument.span()))
                    }),
                    has_required_arguments: earliest_time_argument.is_some()
                        && procedure_argument.is_some(),
                    arguments: args
                        .iter()
                        .map(|argument| expression_source(analysis.source, argument))
                        .collect(),
                    schedule_false: schedule_argument.is_some_and(is_false_literal),
                });
            }
            collect_excel_ontime_uses_in_expression(callee, analysis, out);
            for argument in args {
                collect_excel_ontime_uses_in_expression(argument, analysis, out);
            }
        }
        Expr::Unary { value, .. }
        | Expr::Group(value, _)
        | Expr::TypeOfIs {
            expression: value, ..
        } => collect_excel_ontime_uses_in_expression(value, analysis, out),
        Expr::Binary { left, right, .. } => {
            collect_excel_ontime_uses_in_expression(left, analysis, out);
            collect_excel_ontime_uses_in_expression(right, analysis, out);
        }
        Expr::Member { object, .. } => {
            collect_excel_ontime_uses_in_expression(object, analysis, out)
        }
        Expr::NamedArgument { value, .. } => {
            collect_excel_ontime_uses_in_expression(value, analysis, out)
        }
        Expr::Identifier(..) | Expr::Literal(..) | Expr::Unknown(..) => {}
    }
}

fn excel_ontime_argument<'a>(
    args: &'a [Expr],
    parameter_name: &str,
    position: usize,
) -> Option<&'a Expr> {
    let mut positional_index = 0;
    let mut named_argument_seen = false;
    let mut found = None;
    for argument in args {
        if let Expr::NamedArgument { name, value, .. } = argument {
            named_argument_seen = true;
            if canon(name) == parameter_name {
                if found.is_some() {
                    return None;
                }
                found = Some(value.as_ref());
            }
        } else {
            if named_argument_seen {
                return None;
            }
            if positional_index == position {
                if found.is_some() {
                    return None;
                }
                found = Some(argument);
            }
            positional_index += 1;
        }
    }
    found
}

fn is_false_literal(expression: &Expr) -> bool {
    match expression {
        Expr::Identifier(name, _) => canon(name) == "false",
        Expr::Group(value, _) => is_false_literal(value),
        Expr::Literal(value, crate::model::LiteralKind::Number, _) => {
            parse_integer_bound(value) == Some(0)
        }
        _ => false,
    }
}

fn callbyname_kind(expression: &Expr) -> Option<CallByNameKind> {
    match expression {
        Expr::Identifier(name, _) => match canon(name).as_str() {
            "vbmethod" => Some(CallByNameKind::Method),
            "vbget" => Some(CallByNameKind::Get),
            "vblet" => Some(CallByNameKind::Let),
            "vbset" => Some(CallByNameKind::Set),
            _ => None,
        },
        Expr::Literal(value, crate::model::LiteralKind::Number, _) => {
            match parse_integer_bound(value)? {
                1 => Some(CallByNameKind::Method),
                2 => Some(CallByNameKind::Get),
                4 => Some(CallByNameKind::Let),
                8 => Some(CallByNameKind::Set),
                _ => None,
            }
        }
        _ => None,
    }
}

fn collect_callbyname_member_candidates(
    analysis: DefaultMemberAnalysis<'_>,
    facts: DefaultMemberFacts<'_>,
) {
    let DefaultMemberAnalysis {
        project,
        module_index,
        module,
        host_profile: _host_profile,
    } = analysis;
    let DefaultMemberFacts {
        diagnostics,
        calls,
        references,
        data_flow,
    } = facts;
    for procedure in &module.procedures {
        let mut uses = Vec::new();
        collect_callbyname_uses_in_statements(
            &procedure.statements,
            &module.analysis_text,
            &mut uses,
        );
        for use_fact in uses {
            update_callbyname_fact(
                calls,
                references,
                module,
                procedure,
                &use_fact,
                "dynamic_invocation_candidate",
                &[],
            );
            let Some(member_name) = use_fact.member_name.as_deref() else {
                continue;
            };
            if !references.iter().any(|reference| {
                reference.module == module.name
                    && reference.procedure.as_deref() == Some(&procedure.name)
                    && reference.span == use_fact.member_span
                    && reference.name == member_name
            }) {
                references.push(ReferenceFact {
                    module: module.name.clone(),
                    procedure: Some(procedure.name.clone()),
                    name: member_name.to_string(),
                    resolution: "callbyname_member_name_candidate".into(),
                    implicit_type: None,
                    span: use_fact.member_span,
                });
            }
            let (Some(receiver), Some(call_type)) =
                (use_fact.receiver.as_ref(), use_fact.call_type)
            else {
                continue;
            };
            let Some((owner, _)) =
                crate::typecheck::member_owner(project, module_index, module, procedure, receiver)
            else {
                continue;
            };
            let target_module = &project.modules[owner];
            let mut named_candidates = target_module
                .procedures
                .iter()
                .filter(|candidate| {
                    canon(&candidate.name) == canon(member_name)
                        && candidate.visibility.eq_ignore_ascii_case("public")
                })
                .collect::<Vec<_>>();
            if call_type == CallByNameKind::Method {
                named_candidates.retain(|candidate| {
                    candidate.kind.eq_ignore_ascii_case("Sub")
                        || candidate.kind.eq_ignore_ascii_case("Function")
                });
            } else {
                let kind = match call_type {
                    CallByNameKind::Get => "Property Get",
                    CallByNameKind::Let => "Property Let",
                    CallByNameKind::Set => "Property Set",
                    CallByNameKind::Method => unreachable!(),
                };
                named_candidates.retain(|candidate| candidate.kind.eq_ignore_ascii_case(kind));
            }
            let matching = named_candidates
                .iter()
                .copied()
                .filter_map(|candidate| {
                    bind_default_member_arguments(
                        &candidate.parameters,
                        &use_fact.member_arguments,
                        matches!(call_type, CallByNameKind::Let | CallByNameKind::Set),
                    )
                    .map(|bindings| (candidate, bindings))
                })
                .collect::<Vec<_>>();
            let dispatch_candidates = if !matching.is_empty() {
                matching
                    .iter()
                    .map(|(candidate, _)| format!("{}.{}", target_module.name, candidate.name))
                    .collect::<Vec<_>>()
            } else {
                named_candidates
                    .iter()
                    .map(|candidate| format!("{}.{}", target_module.name, candidate.name))
                    .collect::<Vec<_>>()
            };
            let resolution = match (matching.len(), named_candidates.is_empty()) {
                (1, _) => "typed_late_bound_member_candidate",
                (n, _) if n > 1 => "ambiguous_late_bound_member_candidates",
                (0, false) => "late_bound_argument_shape_unresolved",
                _ => "unresolved_typed_late_bound_member",
            };
            if matching.is_empty() {
                diagnostics.push(Diagnostic {
                    code: if named_candidates.is_empty() {
                        "VBA2125"
                    } else {
                        "VBA2124"
                    },
                    severity: Severity::Warning,
                    message: if named_candidates.is_empty() {
                        format!(
                            "CallByName member '{}' was not found among the accessible members of in-project type '{}'; a base type or runtime member may still exist",
                            member_name, target_module.name
                        )
                    } else {
                        format!(
                            "CallByName arguments do not match the available in-project signatures for '{}.{}'",
                            target_module.name, member_name
                        )
                    },
                    source: module.source_name.clone(),
                    span: use_fact.callee_span,
                });
            } else if matching.len() == 1 {
                let (callee, bindings) = &matching[0];
                append_argument_input_facts(
                    CallInputContext {
                        project,
                        module_index,
                        module,
                        procedure: Some(procedure.name.clone()),
                    },
                    &format!("{}.{}", target_module.name, callee.name),
                    (&callee.parameters, bindings),
                    "late_bound_argument_input_candidate",
                    use_fact.callee_span,
                    data_flow,
                );
                if let Some(target) = use_fact.assignment_target.as_deref()
                    && matches!(
                        callee.kind.to_ascii_lowercase().as_str(),
                        "function" | "property get"
                    )
                {
                    let return_sources = data_flow
                        .iter()
                        .filter(|fact| {
                            fact.module.eq_ignore_ascii_case(&target_module.name)
                                && fact
                                    .procedure
                                    .as_deref()
                                    .is_some_and(|name| name.eq_ignore_ascii_case(&callee.name))
                                && canon(&fact.target) == canon(&callee.name)
                                && matches!(
                                    fact.transfer.as_str(),
                                    "assignment" | "object_assignment"
                                )
                        })
                        .cloned()
                        .collect::<Vec<_>>();
                    append_function_return_facts(
                        project,
                        (module, Some(procedure.name.clone()), target),
                        (target_module, callee),
                        (bindings, &return_sources),
                        use_fact.callee_span,
                        data_flow,
                    );
                }
            }
            update_callbyname_fact(
                calls,
                references,
                module,
                procedure,
                &use_fact,
                resolution,
                &dispatch_candidates,
            );
        }
    }
}

fn update_callbyname_fact(
    calls: &mut Vec<CallFact>,
    references: &mut Vec<ReferenceFact>,
    module: &Module,
    procedure: &Procedure,
    callbyname: &CallByNameUse,
    resolution: &str,
    dispatch_candidates: &[String],
) {
    if let Some(call) = calls.iter_mut().find(|call| {
        call.module == module.name
            && call.procedure.as_deref() == Some(&procedure.name)
            && canon(&call.target) == "callbyname"
            && call.span.start == callbyname.callee_span.start
    }) {
        call.resolution = resolution.into();
        call.dispatch_candidates = dispatch_candidates.to_vec();
    } else {
        calls.push(CallFact {
            module: module.name.clone(),
            procedure: Some(procedure.name.clone()),
            target: "CallByName".into(),
            resolution: resolution.into(),
            argument_count: Some(callbyname.outer_arguments.len()),
            arguments: callbyname.outer_arguments.clone(),
            dispatch_candidates: dispatch_candidates.to_vec(),
            span: callbyname.callee_span,
            ..CallFact::default()
        });
    }
    if let Some(member_name) = &callbyname.member_name
        && !references.iter().any(|reference| {
            reference.module == module.name
                && reference.procedure.as_deref() == Some(&procedure.name)
                && reference.span == callbyname.member_span
                && reference.name == *member_name
        })
    {
        references.push(ReferenceFact {
            module: module.name.clone(),
            procedure: Some(procedure.name.clone()),
            name: member_name.clone(),
            resolution: "callbyname_member_name_candidate".into(),
            implicit_type: None,
            span: callbyname.member_span,
        });
    }
}

fn collect_callbyname_uses_in_statements(
    statements: &[Statement],
    source: &str,
    out: &mut Vec<CallByNameUse>,
) {
    for statement in statements {
        if let Some(expression) = &statement.parsed_expression {
            let assignment_target = (statement.kind == "assignment"
                && matches!(expression, Expr::Call { callee, .. } if matches!(callee.as_ref(), Expr::Identifier(name, _) if canon(name) == "callbyname")))
                .then(|| statement.parsed_target.as_ref().map(|target| expression_source(source, target)))
                .flatten();
            collect_callbyname_uses_in_expression(expression, source, assignment_target, out);
        }
        if let Some(target) = &statement.parsed_target {
            collect_callbyname_uses_in_expression(target, source, None, out);
        }
        collect_callbyname_uses_in_statements(&statement.children, source, out);
    }
}

fn collect_callbyname_uses_in_expression(
    expression: &Expr,
    source: &str,
    assignment_target: Option<String>,
    out: &mut Vec<CallByNameUse>,
) {
    match expression {
        Expr::Call { callee, args, .. } => {
            if matches!(callee.as_ref(), Expr::Identifier(name, _) if canon(name) == "callbyname")
                && args.len() >= 3
            {
                let fixed_arguments_are_positional = !args[..3]
                    .iter()
                    .any(|argument| matches!(argument, Expr::NamedArgument { .. }));
                let member = match &args[1] {
                    Expr::Literal(name, crate::model::LiteralKind::String, span) => {
                        Some((name.clone(), *span))
                    }
                    _ => None,
                };
                out.push(CallByNameUse {
                    receiver: fixed_arguments_are_positional.then(|| args[0].clone()),
                    member_name: fixed_arguments_are_positional
                        .then(|| member.as_ref().map(|(name, _)| name.clone()))
                        .flatten(),
                    member_span: member
                        .map(|(_, span)| span)
                        .unwrap_or_else(|| args[1].span()),
                    call_type: fixed_arguments_are_positional
                        .then(|| callbyname_kind(&args[2]))
                        .flatten(),
                    outer_arguments: args
                        .iter()
                        .map(|argument| expression_source(source, argument))
                        .collect(),
                    member_arguments: args[3..]
                        .iter()
                        .map(|argument| expression_source(source, argument))
                        .collect(),
                    callee_span: callee.span(),
                    assignment_target,
                });
            }
            collect_callbyname_uses_in_expression(callee, source, None, out);
            for argument in args {
                collect_callbyname_uses_in_expression(argument, source, None, out);
            }
        }
        Expr::Unary { value, .. }
        | Expr::Group(value, _)
        | Expr::TypeOfIs {
            expression: value, ..
        } => {
            collect_callbyname_uses_in_expression(value, source, None, out);
        }
        Expr::Binary { left, right, .. } => {
            collect_callbyname_uses_in_expression(left, source, None, out);
            collect_callbyname_uses_in_expression(right, source, None, out);
        }
        Expr::Member { object, .. } => {
            collect_callbyname_uses_in_expression(object, source, None, out);
        }
        Expr::NamedArgument { value, .. } => {
            collect_callbyname_uses_in_expression(value, source, None, out);
        }
        Expr::Identifier(..) | Expr::Literal(..) | Expr::Unknown(..) => {}
    }
}

fn assignment_callable_names(
    project: &Project,
    module_index: usize,
    module: &Module,
) -> HashSet<String> {
    let mut names = module
        .procedures
        .iter()
        .map(|procedure| canon(&procedure.name))
        .collect::<HashSet<_>>();
    names.extend(
        module
            .declarations
            .iter()
            .filter(|declaration| declaration.kind == "external_declare")
            .map(|declaration| canon(&declaration.name)),
    );
    for (owner, candidate) in project.modules.iter().enumerate() {
        if owner == module_index
            || !matches!(candidate.module_kind.as_deref(), Some("standard") | None)
        {
            continue;
        }
        names.extend(
            candidate
                .procedures
                .iter()
                .filter(|procedure| {
                    procedure.visibility.eq_ignore_ascii_case("public")
                        || procedure.visibility.eq_ignore_ascii_case("global")
                })
                .map(|procedure| canon(&procedure.name)),
        );
        names.extend(
            candidate
                .declarations
                .iter()
                .filter(|declaration| {
                    declaration.kind == "external_declare"
                        && (declaration.visibility.eq_ignore_ascii_case("public")
                            || declaration.visibility.eq_ignore_ascii_case("global"))
                })
                .map(|declaration| canon(&declaration.name)),
        );
    }
    names
}

fn assignment_value_names(
    project: &Project,
    module_index: usize,
    module: &Module,
    procedure: &Procedure,
) -> HashSet<String> {
    let mut names = assignment_local_value_names(module, procedure);
    for (owner, candidate) in project.modules.iter().enumerate() {
        if owner == module_index
            || !matches!(candidate.module_kind.as_deref(), Some("standard") | None)
        {
            continue;
        }
        names.extend(
            candidate
                .declarations
                .iter()
                .filter(|declaration| {
                    (is_variable_declaration(declaration) || declaration.kind == "enum_member")
                        && (declaration.visibility.eq_ignore_ascii_case("public")
                            || declaration.visibility.eq_ignore_ascii_case("global"))
                })
                .map(|declaration| canon(&declaration.name)),
        );
    }
    names
}

fn assignment_local_value_names(module: &Module, procedure: &Procedure) -> HashSet<String> {
    let mut names = procedure
        .parameters
        .iter()
        .map(|parameter| canon(&parameter.name))
        .collect::<HashSet<_>>();
    collect_declared_variable_names(&procedure.statements, &mut names);
    collect_loop_control_variable_names(&procedure.statements, &mut names);
    names.extend(
        module
            .declarations
            .iter()
            .filter(|declaration| is_variable_declaration(declaration))
            .map(|declaration| canon(&declaration.name)),
    );
    names
}

struct AssignmentInputScope {
    value_names: HashSet<String>,
    local_value_names: HashSet<String>,
    callable_names: HashSet<String>,
    standard_module_names: HashSet<String>,
    qualified_value_names: HashSet<String>,
}

fn assignment_input_scope(
    project: &Project,
    module_index: usize,
    module: &Module,
    procedure: &Procedure,
) -> AssignmentInputScope {
    let standard_modules = project
        .modules
        .iter()
        .enumerate()
        .filter(|(_, candidate)| {
            matches!(candidate.module_kind.as_deref(), Some("standard") | None)
        })
        .collect::<Vec<_>>();
    let standard_module_names = standard_modules
        .iter()
        .map(|(_, candidate)| canon(&candidate.name))
        .collect::<HashSet<_>>();
    let mut qualified_value_names = HashSet::new();
    for (owner, candidate) in &standard_modules {
        for declaration in &candidate.declarations {
            let visible = *owner == module_index
                || declaration.visibility.eq_ignore_ascii_case("public")
                || declaration.visibility.eq_ignore_ascii_case("global");
            if visible
                && (is_variable_declaration(declaration) || declaration.kind == "enum_member")
            {
                qualified_value_names
                    .insert(canon(&format!("{}.{}", candidate.name, declaration.name)));
            }
        }
    }
    AssignmentInputScope {
        value_names: assignment_value_names(project, module_index, module, procedure),
        local_value_names: assignment_local_value_names(module, procedure),
        callable_names: assignment_callable_names(project, module_index, module),
        standard_module_names,
        qualified_value_names,
    }
}

fn collect_assignment_facts(
    project: &Project,
    module_index: usize,
    m: &Module,
    out: &mut Vec<DataFlowFact>,
) {
    for declaration in &m.declarations {
        if declaration.kind == "constant" {
            append_constant_fact(m, None, declaration, out);
        }
    }
    for p in &m.procedures {
        let input_scope = assignment_input_scope(project, module_index, m, p);
        collect_assignments_in(m, p, &p.statements, &input_scope, out);
    }
}

struct ExpressionReadScope<'a> {
    project: &'a Project,
    module_index: usize,
    module: &'a Module,
    procedure: &'a Procedure,
    host_profile: HostProfile,
    intrinsic_name_set: &'a HashSet<&'static str>,
    public_symbol_index: &'a HashMap<String, Vec<(usize, usize)>>,
    procedure_index: &'a HashMap<String, Vec<(usize, usize)>>,
    module_names: &'a HashSet<String>,
    predeclared_module_names: &'a HashSet<String>,
    public_external_names: &'a HashSet<String>,
    module_value_names: &'a HashSet<String>,
    module_external_names: &'a HashSet<String>,
    procedure_value_names: &'a HashSet<String>,
}

fn collect_loop_control_variable_names(statements: &[Statement], names: &mut HashSet<String>) {
    for statement in statements {
        if let Some(control) = statement.loop_control_variable.as_deref()
            && let Some(Expr::Identifier(name, _)) = parse_expression_source(control)
        {
            names.insert(canon(&name));
        }
        collect_loop_control_variable_names(&statement.children, names);
    }
}

fn collect_procedure_expression_reads(
    scope: &ExpressionReadScope<'_>,
    statements: &[Statement],
    out: &mut Vec<DataFlowFact>,
) {
    let mut seen_expressions = HashSet::new();
    collect_expression_reads_in_statements(scope, statements, &mut seen_expressions, out);
}

fn collect_expression_reads_in_statements(
    scope: &ExpressionReadScope<'_>,
    statements: &[Statement],
    seen_expressions: &mut HashSet<(usize, usize)>,
    out: &mut Vec<DataFlowFact>,
) {
    for statement in statements {
        match statement.kind.as_str() {
            "if" | "elseif_branch" | "select_case" | "for_each" | "while" | "do_pre" | "with" => {
                if let Some(expression) = statement.parsed_expression.as_ref() {
                    collect_expression_read_fact(scope, expression, seen_expressions, out);
                }
            }
            "for" => {
                for expression in [
                    statement.parsed_loop_start.as_ref(),
                    statement.parsed_loop_end.as_ref(),
                    statement.parsed_loop_step.as_ref(),
                ]
                .into_iter()
                .flatten()
                {
                    collect_expression_read_fact(scope, expression, seen_expressions, out);
                }
            }
            "do" => {
                if let Some(expression) = statement.parsed_exit_condition.as_ref() {
                    collect_expression_read_fact(scope, expression, seen_expressions, out);
                }
            }
            "case" => {
                for range in &statement.case_ranges {
                    for expression in [
                        range.parsed_expression.as_ref(),
                        range.parsed_start_value.as_ref(),
                        range.parsed_end_value.as_ref(),
                    ]
                    .into_iter()
                    .flatten()
                    {
                        collect_expression_read_fact(scope, expression, seen_expressions, out);
                    }
                }
            }
            _ => {}
        }
        collect_expression_reads_in_statements(scope, &statement.children, seen_expressions, out);
    }
}

fn collect_expression_read_fact(
    scope: &ExpressionReadScope<'_>,
    expression: &Expr,
    seen_expressions: &mut HashSet<(usize, usize)>,
    out: &mut Vec<DataFlowFact>,
) {
    let span = expression.span();
    if !seen_expressions.insert((span.start, span.end)) {
        return;
    }
    let mut seen_names = HashSet::new();
    let mut inputs = Vec::new();
    collect_expression_read_names(scope, expression, &mut seen_names, &mut inputs);
    if inputs.is_empty() {
        return;
    }
    out.push(DataFlowFact {
        module: scope.module.name.clone(),
        procedure: Some(scope.procedure.name.clone()),
        target: "expression_read_candidate".into(),
        inputs,
        transfer: "expression_read_candidate".into(),
        span,
        ..DataFlowFact::default()
    });
}

fn collect_expression_read_names(
    scope: &ExpressionReadScope<'_>,
    expression: &Expr,
    seen: &mut HashSet<String>,
    inputs: &mut Vec<String>,
) {
    let mut add_name = |name: &str| {
        let key = canon(name);
        if is_expression_read_name(scope, name) && seen.insert(key) {
            inputs.push(name.to_owned());
        }
    };
    match expression {
        Expr::Identifier(name, _) => add_name(name),
        Expr::Call { callee, args, .. } => {
            match callee.as_ref() {
                Expr::Identifier(name, _) if is_declared_expression_value(scope, name) => {
                    add_name(name);
                }
                Expr::Member { object, .. } => {
                    collect_expression_read_names(scope, object, seen, inputs)
                }
                Expr::Group(inner, _) | Expr::Unary { value: inner, .. } => {
                    collect_expression_read_names(scope, inner, seen, inputs)
                }
                _ => {}
            }
            for argument in args {
                collect_expression_read_names(scope, argument, seen, inputs);
            }
        }
        Expr::Member { object, .. }
        | Expr::Group(object, _)
        | Expr::Unary { value: object, .. }
        | Expr::TypeOfIs {
            expression: object, ..
        } => {
            collect_expression_read_names(scope, object, seen, inputs);
        }
        Expr::NamedArgument { value, .. } => {
            collect_expression_read_names(scope, value, seen, inputs)
        }
        Expr::Binary { left, right, .. } => {
            collect_expression_read_names(scope, left, seen, inputs);
            collect_expression_read_names(scope, right, seen, inputs);
        }
        Expr::Literal(..) | Expr::Unknown(..) => {}
    }
}

fn is_expression_read_name(scope: &ExpressionReadScope<'_>, name: &str) -> bool {
    let key = canon(name);
    if is_keyword(name) {
        return false;
    }
    if canon(&scope.procedure.name) == key || is_declared_expression_value(scope, name) {
        return true;
    }
    if scope.module_names.contains(&key) {
        return scope.predeclared_module_names.contains(&key);
    }
    if scope.intrinsic_name_set.contains(key.as_str())
        || is_intrinsic_constant(name)
        || scope.host_profile == HostProfile::Excel && excel::is_constant(name)
        || scope.module_external_names.contains(&key)
        || scope.public_external_names.contains(&key)
        || is_visible_procedure_name(scope, name)
    {
        return false;
    }
    true
}

fn is_declared_expression_value(scope: &ExpressionReadScope<'_>, name: &str) -> bool {
    let key = canon(name);
    scope.procedure_value_names.contains(&key)
        || scope.module_value_names.contains(&key)
        || scope.public_symbol_index.contains_key(&key)
}

fn is_visible_procedure_name(scope: &ExpressionReadScope<'_>, name: &str) -> bool {
    scope
        .procedure_index
        .get(&canon(name))
        .is_some_and(|candidates| {
            candidates.iter().any(|(owner, procedure_index)| {
                let Some(module) = scope.project.modules.get(*owner) else {
                    return false;
                };
                let Some(procedure) = module.procedures.get(*procedure_index) else {
                    return false;
                };
                *owner == scope.module_index
                    || matches!(module.module_kind.as_deref(), Some("standard") | None)
                        && (procedure.visibility.eq_ignore_ascii_case("public")
                            || procedure.visibility.eq_ignore_ascii_case("global"))
                        && !public_procedure_requires_qualification(scope.project, procedure)
            })
        })
}

fn assignment_expression_input_names(
    expression: &Expr,
    scope: &AssignmentInputScope,
) -> Vec<String> {
    fn add_name(name: &str, seen: &mut HashSet<String>, inputs: &mut Vec<String>) {
        let key = canon(name);
        if !is_keyword(name) && !intrinsic_names().contains(key.as_str()) && seen.insert(key) {
            inputs.push(name.to_owned());
        }
    }

    fn visit(
        expression: &Expr,
        scope: &AssignmentInputScope,
        seen: &mut HashSet<String>,
        inputs: &mut Vec<String>,
    ) {
        match expression {
            Expr::Identifier(name, _) => add_name(name, seen, inputs),
            Expr::Call { callee, args, .. } => {
                match callee.as_ref() {
                    Expr::Identifier(name, _)
                        if scope.value_names.contains(&canon(name))
                            || !scope.callable_names.contains(&canon(name)) =>
                    {
                        add_name(name, seen, inputs);
                    }
                    Expr::Identifier(..) => {}
                    _ => visit(callee, scope, seen, inputs),
                }
                for argument in args {
                    visit(argument, scope, seen, inputs);
                }
            }
            Expr::Member {
                object,
                member,
                access: MemberAccessKind::Dot,
                ..
            } if matches!(object.as_ref(), Expr::Identifier(name, _) if scope.standard_module_names.contains(&canon(name)) && !scope.local_value_names.contains(&canon(name))) => {
                if let Expr::Identifier(qualifier, _) = object.as_ref() {
                    let qualified = format!("{}.{}", qualifier, member);
                    if scope.qualified_value_names.contains(&canon(&qualified)) {
                        add_name(&qualified, seen, inputs);
                    }
                }
            }
            Expr::Member { object, .. } => visit(object, scope, seen, inputs),
            Expr::Unary { op, .. }
                if op.eq_ignore_ascii_case("new") || op.eq_ignore_ascii_case("addressof") => {}
            Expr::Unary { value, .. } | Expr::Group(value, _) => visit(value, scope, seen, inputs),
            Expr::TypeOfIs { expression, .. } => visit(expression, scope, seen, inputs),
            Expr::Binary { left, right, .. } => {
                visit(left, scope, seen, inputs);
                visit(right, scope, seen, inputs);
            }
            Expr::NamedArgument { value, .. } => visit(value, scope, seen, inputs),
            Expr::Literal(..) | Expr::Unknown(..) => {}
        }
    }

    let mut seen = HashSet::new();
    let mut inputs = Vec::new();
    visit(expression, scope, &mut seen, &mut inputs);
    inputs
}

fn collect_assignments_in(
    m: &Module,
    p: &Procedure,
    statements: &[Statement],
    input_scope: &AssignmentInputScope,
    out: &mut Vec<DataFlowFact>,
) {
    for s in statements {
        if s.kind == "declaration" {
            for child in &s.children {
                if let Some(d) = &child.declaration
                    && d.kind == "constant"
                {
                    append_constant_fact(m, Some(&p.name), d, out);
                }
            }
        }
        if s.kind == "redim" {
            for child in &s.children {
                let Some(declaration) = &child.declaration else {
                    continue;
                };
                let transfer = if declaration.kind == "redim_preserve" {
                    "redim_preserve_array_write_candidate"
                } else {
                    "redim_array_write_candidate"
                };
                out.push(DataFlowFact {
                    module: m.name.clone(),
                    procedure: Some(p.name.clone()),
                    target: declaration.name.clone(),
                    transfer: transfer.into(),
                    span: child.span,
                    ..DataFlowFact::default()
                });
            }
        }
        if s.kind == "erase" {
            for child in &s.children {
                if child.kind != "erase_target" {
                    continue;
                }
                out.push(DataFlowFact {
                    module: m.name.clone(),
                    procedure: Some(p.name.clone()),
                    target: child.expression.clone().unwrap_or_default(),
                    transfer: "erase_array_write_candidate".into(),
                    span: child.span,
                    ..DataFlowFact::default()
                });
            }
        }
        if matches!(s.kind.as_str(), "for" | "for_each")
            && let Some(control_variable) = &s.loop_control_variable
        {
            out.push(DataFlowFact {
                module: m.name.clone(),
                procedure: Some(p.name.clone()),
                target: control_variable.clone(),
                transfer: "loop_control_write_candidate".into(),
                span: s.span,
                ..DataFlowFact::default()
            });
        }
        if s.kind == "assignment"
            && let Some(source) = &s.expression
        {
            let (tokens, _) = lex(source, 16_384);
            let tokens = tokens
                .into_iter()
                .filter(|t| t.kind != TokenKind::Newline && t.kind != TokenKind::Eof)
                .collect::<Vec<_>>();
            let mut depth = 0i32;
            let mut eq = None;
            for (i, t) in tokens.iter().enumerate() {
                match t.text.as_str() {
                    "(" | "[" => depth += 1,
                    ")" | "]" => depth -= 1,
                    "=" if depth == 0 && t.kind == TokenKind::Symbol => {
                        eq = Some(i);
                        break;
                    }
                    _ => {}
                }
            }
            if let Some(e) = eq
                && e > 0
                && e + 1 < tokens.len()
            {
                let first = canon(&tokens[0].text);
                let lhs_start = if matches!(first.as_str(), "set" | "let") {
                    1
                } else {
                    0
                };
                let target = render_ids(&tokens[lhs_start..e]);
                if !target.is_empty() {
                    let inputs = if let Some(expression) = s.parsed_expression.as_ref() {
                        assignment_expression_input_names(expression, input_scope)
                    } else {
                        let mut inputs = Vec::new();
                        let mut seen = HashSet::new();
                        for (i, t) in tokens[e + 1..].iter().enumerate() {
                            if t.kind != TokenKind::Identifier
                                || i > 0 && matches!(tokens[e + i].text.as_str(), "." | "!")
                                || is_keyword(&t.text)
                                || intrinsic_names().contains(canon(&t.text).as_str())
                            {
                                continue;
                            }
                            if seen.insert(canon(&t.text)) {
                                inputs.push(t.text.clone());
                            }
                        }
                        inputs
                    };
                    out.push(DataFlowFact {
                        module: m.name.clone(),
                        procedure: Some(p.name.clone()),
                        target,
                        inputs,
                        transfer: if first == "set" {
                            "object_assignment"
                        } else {
                            "assignment"
                        }
                        .into(),
                        value_expression: Some(render_call_argument(&tokens[e + 1..])),
                        span: s.span,
                        ..DataFlowFact::default()
                    });
                }
            }
        }
        collect_assignments_in(m, p, &s.children, input_scope, out);
    }
}
fn append_constant_fact(
    module: &Module,
    procedure: Option<&str>,
    declaration: &Declaration,
    out: &mut Vec<DataFlowFact>,
) {
    let Some(initializer) = &declaration.initializer else {
        return;
    };
    let (tokens, _) = lex(initializer, 4096);
    let mut inputs = Vec::new();
    let mut seen = HashSet::new();
    for token in tokens {
        if token.kind == TokenKind::Identifier
            && !is_keyword(&token.text)
            && !intrinsic_names().contains(canon(&token.text).as_str())
            && seen.insert(canon(&token.text))
        {
            inputs.push(token.text);
        }
    }
    out.push(DataFlowFact {
        module: module.name.clone(),
        procedure: procedure.map(str::to_owned),
        target: declaration.name.clone(),
        inputs,
        transfer: "constant_initializer".into(),
        span: declaration.span,
        ..DataFlowFact::default()
    });
}
fn render_ids(ts: &[Token]) -> String {
    let mut s = String::new();
    for t in ts {
        if t.kind == TokenKind::Newline {
            continue;
        }
        if !s.is_empty()
            && !matches!(t.text.as_str(), "." | "!" | "(" | ")" | "[")
            && !s.ends_with('.')
            && !s.ends_with('!')
        {
            s.push(' ');
        }
        if t.bracket_delimited {
            s.push('[');
            s.push_str(&t.text);
            s.push(']');
        } else {
            s.push_str(&t.text);
        }
    }
    s.trim().to_string()
}
fn collect_declared_variable_names(statements: &[Statement], out: &mut HashSet<String>) {
    for statement in statements {
        if let Some(declaration) = &statement.declaration {
            out.insert(canon(&declaration.name));
        }
        collect_declared_variable_names(&statement.children, out);
    }
}
fn build_public_symbol_index(project: &Project) -> HashMap<String, Vec<(usize, usize)>> {
    let mut index = HashMap::new();
    for (module_index, module) in project.modules.iter().enumerate() {
        let standard_module = matches!(module.module_kind.as_deref(), Some("standard") | None);
        let public_enums = module
            .declarations
            .iter()
            .filter(|declaration| {
                declaration.kind == "enum"
                    && (declaration.visibility.eq_ignore_ascii_case("public")
                        || declaration.visibility.eq_ignore_ascii_case("global"))
            })
            .map(|declaration| canon(&declaration.name))
            .collect::<HashSet<_>>();
        for (declaration_index, declaration) in module.declarations.iter().enumerate() {
            let is_module_value = matches!(
                declaration.kind.as_str(),
                "variable" | "global" | "static" | "constant" | "with_events" | "enum_member"
            );
            let public = declaration.visibility.eq_ignore_ascii_case("public")
                || declaration.visibility.eq_ignore_ascii_case("global");
            let enum_is_public = declaration.kind != "enum_member"
                || declaration
                    .type_name
                    .as_deref()
                    .is_some_and(|enum_name| public_enums.contains(&canon(enum_name)));
            let visible_module_scope =
                standard_module || (declaration.kind == "enum_member" && enum_is_public);
            if is_module_value && public && enum_is_public && visible_module_scope {
                index
                    .entry(canon(&declaration.name))
                    .or_insert_with(Vec::new)
                    .push((module_index, declaration_index));
            }
        }
    }
    index
}
fn build_standard_module_name_index(project: &Project) -> HashMap<String, usize> {
    let mut candidates: HashMap<String, Vec<usize>> = HashMap::new();
    for (index, module) in project.modules.iter().enumerate() {
        if matches!(module.module_kind.as_deref(), Some("standard") | None) {
            candidates
                .entry(canon(&module.name))
                .or_default()
                .push(index);
        }
    }
    candidates
        .into_iter()
        .filter_map(|(name, indices)| (indices.len() == 1).then_some((name, indices[0])))
        .collect()
}
fn interface_implementation_candidates(
    project: &Project,
    interface: &str,
    member: &str,
    member_kind: Option<&str>,
) -> Vec<String> {
    let interface_name = canon(interface);
    let implementation_name = canon(&format!("{interface}_{member}"));
    let mut candidates = Vec::new();
    for module in &project.modules {
        if !module
            .implemented_interfaces
            .iter()
            .any(|name| canon(name) == interface_name)
        {
            continue;
        }
        for procedure in &module.procedures {
            if canon(&procedure.name) == implementation_name
                && member_kind.is_none_or(|kind| procedure.kind.eq_ignore_ascii_case(kind))
            {
                candidates.push(format!("{}.{}", module.name, procedure.name));
            }
        }
    }
    candidates
}
fn declaration_is_public_value(module: &Module, declaration: &Declaration) -> bool {
    let public = declaration.visibility.eq_ignore_ascii_case("public")
        || declaration.visibility.eq_ignore_ascii_case("global");
    public
        && matches!(
            declaration.kind.as_str(),
            "variable" | "global" | "static" | "constant" | "with_events" | "enum_member"
        )
        && (declaration.kind != "enum_member"
            || declaration.type_name.as_deref().is_some_and(|enum_name| {
                module.declarations.iter().any(|enum_declaration| {
                    enum_declaration.kind == "enum"
                        && (enum_declaration.visibility.eq_ignore_ascii_case("public")
                            || enum_declaration.visibility.eq_ignore_ascii_case("global"))
                        && canon(&enum_declaration.name) == canon(enum_name)
                })
            }))
}
fn procedure_candidates_for_call(
    project: &Project,
    index: &HashMap<String, Vec<(usize, usize)>>,
    current_module: usize,
    name: &str,
) -> Vec<(usize, usize)> {
    let Some(all) = index.get(name) else {
        return Vec::new();
    };
    let local = all
        .iter()
        .copied()
        .filter(|(owner, _)| *owner == current_module)
        .collect::<Vec<_>>();
    let mut visible = if local.is_empty() {
        all.iter()
            .copied()
            .filter(|(owner, procedure)| {
                *owner != current_module
                    && matches!(
                        project.modules[*owner].module_kind.as_deref(),
                        Some("standard") | None
                    )
                    && !project.modules[*owner].procedures[*procedure]
                        .visibility
                        .eq_ignore_ascii_case("private")
                    && !public_procedure_requires_qualification(
                        project,
                        &project.modules[*owner].procedures[*procedure],
                    )
            })
            .collect::<Vec<_>>()
    } else {
        local
    };
    let only_property_accessors = visible.iter().all(|(owner, procedure)| {
        project.modules[*owner].procedures[*procedure]
            .kind
            .to_ascii_lowercase()
            .starts_with("property ")
    });
    if only_property_accessors
        && visible.iter().any(|(owner, procedure)| {
            project.modules[*owner].procedures[*procedure]
                .kind
                .eq_ignore_ascii_case("Property Get")
        })
    {
        visible.retain(|(owner, procedure)| {
            project.modules[*owner].procedures[*procedure]
                .kind
                .eq_ignore_ascii_case("Property Get")
        });
    }
    visible
}

fn public_procedure_requires_qualification(project: &Project, procedure: &Procedure) -> bool {
    if !procedure.visibility.eq_ignore_ascii_case("public")
        && !procedure.visibility.eq_ignore_ascii_case("global")
    {
        return false;
    }
    let name = canon(&procedure.name);
    project
        .name
        .as_deref()
        .is_some_and(|project_name| canon(project_name) == name)
        || project
            .modules
            .iter()
            .any(|module| canon(&module.name) == name)
}

fn unqualified_procedure_requires_qualification(
    project: &Project,
    index: &HashMap<String, Vec<(usize, usize)>>,
    current_module: usize,
    name: &str,
) -> bool {
    if project.modules.get(current_module).is_some_and(|module| {
        module
            .procedures
            .iter()
            .any(|p| canon(&p.name) == canon(name))
    }) {
        return false;
    }
    index.get(name).is_some_and(|candidates| {
        candidates.iter().any(|(owner, procedure_index)| {
            *owner != current_module
                && matches!(
                    project.modules[*owner].module_kind.as_deref(),
                    Some("standard") | None
                )
                && public_procedure_requires_qualification(
                    project,
                    &project.modules[*owner].procedures[*procedure_index],
                )
        })
    })
}

fn fixed_length_string_type_error(type_name: &str) -> Option<String> {
    let normalized = type_name
        .chars()
        .filter(|character| !character.is_whitespace())
        .collect::<String>()
        .to_ascii_lowercase();
    let length_name = normalized.strip_prefix("string*")?;
    if let Some(length) = parse_fixed_string_integer_token(length_name) {
        if (1..=65_526).contains(&length) {
            return None;
        }
        return Some(format!(
            "fixed-length String size {} is outside the permitted range 1 through 65526",
            length
        ));
    }
    if is_fixed_string_longlong_integer_literal(length_name) {
        return Some(
            "fixed-length String size LongLong literal cannot be implicitly Let-coerced to Long"
                .into(),
        );
    }
    if is_fixed_string_length_name(length_name) {
        return None;
    }
    Some("fixed-length String requires an integer size or constant name".into())
}

fn fixed_length_string_constant_name(type_name: &str) -> Option<String> {
    let normalized = type_name
        .chars()
        .filter(|character| !character.is_whitespace())
        .collect::<String>()
        .to_ascii_lowercase();
    let length_name = normalized.strip_prefix("string*")?;
    if parse_fixed_string_integer_token(length_name).is_some()
        || is_fixed_string_longlong_integer_literal(length_name)
        || !is_fixed_string_length_name(length_name)
    {
        return None;
    }
    Some(length_name.to_string())
}

fn parse_fixed_string_integer_token(expression: &str) -> Option<i64> {
    let (tokens, errors) = lex(expression, 8);
    if !errors.is_empty() {
        return None;
    }
    let values = tokens
        .into_iter()
        .filter(|token| !matches!(token.kind, TokenKind::Newline | TokenKind::Eof))
        .collect::<Vec<_>>();
    let [token] = values.as_slice() else {
        return None;
    };
    if token.kind != TokenKind::Number || !is_integer_literal_text(&token.text) {
        return None;
    }
    parse_integer_literal(&token.text)
}

fn is_fixed_string_longlong_integer_literal(expression: &str) -> bool {
    let (tokens, errors) = lex(expression, 8);
    if !errors.is_empty() {
        return false;
    }
    let values = tokens
        .into_iter()
        .filter(|token| !matches!(token.kind, TokenKind::Newline | TokenKind::Eof))
        .collect::<Vec<_>>();
    matches!(values.as_slice(), [token] if token.kind == TokenKind::Number
        && token.text.ends_with('^')
        && is_integer_literal_text(&token.text))
}

fn is_integer_literal_text(literal: &str) -> bool {
    let suffix = literal
        .chars()
        .next_back()
        .filter(|character| matches!(character, '%' | '&' | '^'));
    let body = suffix
        .map(|_| &literal[..literal.len() - 1])
        .unwrap_or(literal);
    let lower = body.to_ascii_lowercase();
    if let Some(hex) = lower.strip_prefix("&h") {
        !hex.is_empty() && hex.bytes().all(|byte| byte.is_ascii_hexdigit())
    } else if let Some(octal) = lower.strip_prefix("&o") {
        !octal.is_empty() && octal.bytes().all(|byte| (b'0'..=b'7').contains(&byte))
    } else {
        !body.is_empty() && body.bytes().all(|byte| byte.is_ascii_digit())
    }
}

fn is_fixed_string_length_name(name: &str) -> bool {
    let valid_identifier = |part: &str| {
        let mut characters = part.chars();
        let Some(first) = characters.next() else {
            return false;
        };
        (first == '_' || first.is_alphabetic() || first as u32 >= 0x80)
            && characters.all(|character| {
                character == '_' || character.is_alphanumeric() || character as u32 >= 0x80
            })
    };
    name.trim_end_matches(['%', '&', '^', '@', '!', '#', '$'])
        .split('.')
        .all(valid_identifier)
}

fn validate_declared_type_name(
    context: TypeValidationContext<'_>,
    type_name: &str,
    span: Span,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let TypeValidationContext {
        project,
        module_index,
        module,
        procedure,
        host_profile,
    } = context;
    if let Some(message) = fixed_length_string_type_error(type_name) {
        diagnostics.push(Diagnostic {
            code: "VBA1036",
            severity: Severity::Error,
            message,
            source: module.source_name.clone(),
            span,
        });
        return;
    }
    if let Some(length_name) = fixed_length_string_constant_name(type_name) {
        let Some((constant_module_index, constant_module, constant)) =
            resolve_fixed_length_string_constant(
                project,
                module_index,
                module,
                procedure,
                &length_name,
            )
        else {
            diagnostics.push(Diagnostic {
                code: "VBA1037",
                severity: Severity::Warning,
                message: format!(
                    "fixed-length String size '{}' was not resolved to an explicit constant",
                    length_name
                ),
                source: module.source_name.clone(),
                span,
            });
            return;
        };
        let declared_constant_type = constant
            .type_name
            .clone()
            .or_else(|| type_suffix_name(&constant.name));
        if declared_constant_type.is_some_and(|type_name| {
            effective_project_type_name(project, constant_module_index, constant_module, &type_name)
                .eq_ignore_ascii_case("LongLong")
        }) {
            diagnostics.push(Diagnostic {
                code: "VBA1038",
                severity: Severity::Error,
                message: format!(
                    "fixed-length String size constant '{}' has type LongLong, which cannot be implicitly Let-coerced to Long",
                    constant.name
                ),
                source: module.source_name.clone(),
                span,
            });
            return;
        }
        let constant_procedure = procedure.filter(|candidate| {
            constant_module_index == module_index
                && local_variable_declaration(&candidate.statements, &constant.name)
                    .is_some_and(|local| std::ptr::eq(local, constant))
        });
        match fixed_string_constant_length(
            project,
            constant_module_index,
            constant_module,
            constant_procedure,
            constant,
        ) {
            Some(length) if !(1..=65_526).contains(&length) => {
                diagnostics.push(Diagnostic {
                    code: "VBA1036",
                    severity: Severity::Error,
                    message: format!(
                        "fixed-length String size constant '{}' evaluates to {}, outside the permitted range 1 through 65526",
                        constant.name, length
                    ),
                    source: module.source_name.clone(),
                    span,
                });
                return;
            }
            Some(_) => {}
            None => diagnostics.push(Diagnostic {
                code: "VBA1039",
                severity: Severity::Warning,
                message: format!(
                    "fixed-length String size constant '{}' could not be folded to a known integer; its resulting type remains unresolved",
                    constant.name
                ),
                source: module.source_name.clone(),
                span,
            }),
        }
    }
    let base = type_name
        .trim()
        .trim_start_matches("New ")
        .trim_end_matches("()");
    if !type_is_known(project, module_index, base, host_profile) {
        diagnostics.push(Diagnostic {
            code: "VBA2003",
            severity: Severity::Warning,
            message: format!(
                "type '{}' needs a project declaration or referenced type library",
                base
            ),
            source: module.source_name.clone(),
            span,
        });
    }
}

fn fixed_string_constant_length(
    project: &Project,
    module_index: usize,
    module: &Module,
    procedure: Option<&Procedure>,
    constant: &Declaration,
) -> Option<i64> {
    let mut state = FixedStringFoldState {
        active: HashSet::new(),
        remaining_references: 512,
    };
    let value = fold_fixed_string_constant_expression(
        project,
        module_index,
        module,
        procedure,
        constant,
        0,
        &mut state,
    )?;
    coerce_fixed_string_constant_to_long(project, module_index, module, constant, value)
}

struct FixedStringFoldState {
    active: HashSet<(usize, usize)>,
    remaining_references: usize,
}

fn fold_fixed_string_constant_expression(
    project: &Project,
    module_index: usize,
    module: &Module,
    procedure: Option<&Procedure>,
    constant: &Declaration,
    depth: usize,
    state: &mut FixedStringFoldState,
) -> Option<FoldedInteger> {
    if depth >= 128 || constant.initializer.as_ref()?.len() > 256 {
        return None;
    }
    let identity = (module_index, constant.span.start);
    if !state.active.insert(identity) {
        return None;
    }
    let Some(expression) = parse_expression_source(constant.initializer.as_deref()?) else {
        state.active.remove(&identity);
        return None;
    };
    let value = {
        let mut resolver = |reference: &Expr| {
            if state.remaining_references == 0 {
                return None;
            }
            let name = fixed_string_constant_reference_name(reference)?;
            let (owner_index, owner, referenced) = resolve_fixed_length_string_constant(
                project,
                module_index,
                module,
                procedure,
                &name,
            )?;
            state.remaining_references -= 1;
            let local_procedure = procedure.filter(|candidate| {
                owner_index == module_index
                    && local_variable_declaration(&candidate.statements, &referenced.name)
                        .is_some_and(|local| std::ptr::eq(local, referenced))
            });
            let value = fold_fixed_string_constant_expression(
                project,
                owner_index,
                owner,
                local_procedure,
                referenced,
                depth + 1,
                state,
            )?;
            fold_integral_constant_reference_value(project, owner_index, owner, referenced, value)
        };
        evaluate_integer_constant_expression_with(&expression, 0, &mut resolver)
    };
    state.active.remove(&identity);
    value
}

fn fixed_string_constant_reference_name(expression: &Expr) -> Option<String> {
    match expression {
        Expr::Identifier(name, _) => Some(name.clone()),
        Expr::Member {
            object,
            member,
            access: MemberAccessKind::Dot,
            ..
        } => Some(format!(
            "{}.{}",
            fixed_string_constant_reference_name(object)?,
            member
        )),
        _ => None,
    }
}

fn fold_integral_constant_reference_value(
    project: &Project,
    module_index: usize,
    module: &Module,
    constant: &Declaration,
    value: FoldedInteger,
) -> Option<FoldedInteger> {
    let declared_type = constant
        .type_name
        .clone()
        .or_else(|| type_suffix_name(&constant.name));
    let Some(declared_type) = declared_type else {
        return Some(value);
    };
    let declared_type = effective_project_type_name(project, module_index, module, &declared_type);
    match declared_type.to_ascii_lowercase().as_str() {
        "byte" => FoldedInteger::new(value.value, FoldedIntegerWidth::Byte),
        "integer" => FoldedInteger::new(value.value, FoldedIntegerWidth::Integer),
        "long" => FoldedInteger::new(value.value, FoldedIntegerWidth::Long),
        "boolean" => FoldedInteger::new(
            if value.value == 0 { 0 } else { -1 },
            FoldedIntegerWidth::Integer,
        ),
        "variant" => Some(value),
        // Floating, fixed-point, String, Date, and LongLong references need value types or
        // conversions outside this integer-only expression folder.
        _ => None,
    }
}

fn coerce_fixed_string_constant_to_long(
    project: &Project,
    module_index: usize,
    module: &Module,
    constant: &Declaration,
    value: FoldedInteger,
) -> Option<i64> {
    let declared_type = constant
        .type_name
        .clone()
        .or_else(|| type_suffix_name(&constant.name));
    let Some(declared_type) = declared_type else {
        return value.coerce_to_long();
    };
    let declared_type = effective_project_type_name(project, module_index, module, &declared_type);
    match declared_type.to_ascii_lowercase().as_str() {
        "byte" if (0..=u8::MAX as i64).contains(&value.value) => value.coerce_to_long(),
        "integer" if (i16::MIN as i64..=i16::MAX as i64).contains(&value.value) => {
            value.coerce_to_long()
        }
        "long" | "double" | "currency" | "variant" | "string"
            if (i32::MIN as i64..=i32::MAX as i64).contains(&value.value) =>
        {
            value.coerce_to_long()
        }
        "single"
            if (i32::MIN as i64..=i32::MAX as i64).contains(&value.value)
                && (value.value as f32) as f64 == value.value as f64 =>
        {
            value.coerce_to_long()
        }
        "boolean" => Some(if value.value == 0 { 0 } else { -1 }),
        // LongLong is rejected with its dedicated diagnostic before reaching this helper.
        // Other source types need conversions whose behavior is outside this integer-only fold.
        _ => None,
    }
}

fn resolve_fixed_length_string_constant<'a>(
    project: &'a Project,
    module_index: usize,
    module: &'a Module,
    procedure: Option<&'a Procedure>,
    constant_name: &str,
) -> Option<(usize, &'a Module, &'a Declaration)> {
    if let Some((module_name, name)) = constant_name.split_once('.') {
        let candidates = project
            .modules
            .iter()
            .enumerate()
            .filter(|(_, candidate)| canon(&candidate.name) == canon(module_name))
            .collect::<Vec<_>>();
        if candidates.len() != 1 {
            return None;
        }
        let (owner_index, owner) = candidates[0];
        let declaration = owner.declarations.iter().find(|declaration| {
            declaration.kind == "constant"
                && canon(&declaration.name) == canon(name)
                && (owner_index == module_index
                    || declaration.visibility.eq_ignore_ascii_case("public")
                    || declaration.visibility.eq_ignore_ascii_case("global"))
        })?;
        return Some((owner_index, owner, declaration));
    }

    if let Some(procedure) = procedure
        && let Some(declaration) = local_variable_declaration(&procedure.statements, constant_name)
    {
        return (declaration.kind == "constant").then_some((module_index, module, declaration));
    }
    if let Some(declaration) = module
        .declarations
        .iter()
        .find(|declaration| canon(&declaration.name) == canon(constant_name))
    {
        return (declaration.kind == "constant").then_some((module_index, module, declaration));
    }

    let candidates = project
        .modules
        .iter()
        .enumerate()
        .filter(|(owner_index, owner)| {
            *owner_index != module_index
                && matches!(owner.module_kind.as_deref(), Some("standard") | None)
        })
        .flat_map(|(owner_index, owner)| {
            owner.declarations.iter().filter_map(move |declaration| {
                (declaration.kind == "constant"
                    && (declaration.visibility.eq_ignore_ascii_case("public")
                        || declaration.visibility.eq_ignore_ascii_case("global"))
                    && canon(&declaration.name) == canon(constant_name))
                .then_some((owner_index, owner, declaration))
            })
        })
        .collect::<Vec<_>>();
    (candidates.len() == 1).then(|| candidates[0])
}

fn type_is_known(
    project: &Project,
    module_index: usize,
    name: &str,
    host_profile: HostProfile,
) -> bool {
    if known_type(name) || (host_profile == HostProfile::Excel && excel::is_known_type(name)) {
        return true;
    }
    let target = canon(name);
    if project.modules.get(module_index).is_some_and(|module| {
        (matches!(
            module.module_kind.as_deref(),
            Some(
                "class"
                    | "form"
                    | "workbook_document"
                    | "worksheet_document"
                    | "document_or_class"
                    | "class_or_document"
            )
        ) && canon(&module.name) == target)
            || module.declarations.iter().any(|declaration| {
                matches!(declaration.kind.as_str(), "user_type" | "enum")
                    && canon(&declaration.name) == target
            })
    }) {
        return true;
    }
    project.modules.iter().enumerate().any(|(index, module)| {
        if index == module_index {
            return false;
        }
        let class_type = matches!(
            module.module_kind.as_deref(),
            Some(
                "class" | "form" | "workbook_document" | "worksheet_document" | "document_or_class"
            )
        ) && canon(&module.name) == target;
        let public_declared_type = module.declarations.iter().any(|declaration| {
            matches!(declaration.kind.as_str(), "user_type" | "enum")
                && (declaration.visibility.eq_ignore_ascii_case("public")
                    || declaration.visibility.eq_ignore_ascii_case("global"))
                && canon(&declaration.name) == target
        });
        class_type || public_declared_type
    })
}

struct EnumConstantFoldState {
    active: HashSet<(usize, usize)>,
    remaining_references: usize,
}

enum EnumMemberInitializerError {
    FunctionCall,
    RuntimeTypeTest,
    VariableReference(String),
    LongLong,
    OutOfLongRange(String),
    FloatingOutOfLongRange(String),
}

fn enum_constant_expression_problem(
    module: &Module,
    expression: &Expr,
) -> Option<EnumMemberInitializerError> {
    let module_variable = |name: &str| {
        module.declarations.iter().any(|declaration| {
            matches!(
                declaration.kind.as_str(),
                "variable" | "global" | "static" | "with_events"
            ) && canon(&declaration.name) == canon(name)
        })
    };
    let procedure_name = |name: &str| {
        module
            .procedures
            .iter()
            .any(|procedure| canon(&procedure.name) == canon(name))
    };
    match expression {
        Expr::TypeOfIs { .. } => Some(EnumMemberInitializerError::RuntimeTypeTest),
        Expr::Call { callee, .. } => {
            if let Expr::Identifier(name, _) = callee.as_ref()
                && module_variable(name)
            {
                return Some(EnumMemberInitializerError::VariableReference(name.clone()));
            }
            Some(EnumMemberInitializerError::FunctionCall)
        }
        Expr::Unary { value, .. } | Expr::Group(value, _) => {
            enum_constant_expression_problem(module, value)
        }
        Expr::Binary { left, right, .. } => enum_constant_expression_problem(module, left)
            .or_else(|| enum_constant_expression_problem(module, right)),
        Expr::Member { object, .. } => {
            if let Expr::Identifier(name, _) = object.as_ref() {
                if module_variable(name) {
                    return Some(EnumMemberInitializerError::VariableReference(name.clone()));
                }
                if procedure_name(name) {
                    return Some(EnumMemberInitializerError::FunctionCall);
                }
            }
            enum_constant_expression_problem(module, object)
        }
        Expr::Identifier(name, _) => {
            if module_variable(name) {
                Some(EnumMemberInitializerError::VariableReference(name.clone()))
            } else if procedure_name(name) {
                Some(EnumMemberInitializerError::FunctionCall)
            } else {
                None
            }
        }
        Expr::NamedArgument { value, .. } => enum_constant_expression_problem(module, value),
        Expr::Literal(..) | Expr::Unknown(..) => None,
    }
}

fn enum_decimal_integer_expression_value(expression: &Expr) -> Option<i128> {
    match expression {
        Expr::Group(value, _) => enum_decimal_integer_expression_value(value),
        Expr::Unary { op, value, .. } if op == "+" => enum_decimal_integer_expression_value(value),
        Expr::Unary { op, value, .. } if op == "-" => {
            enum_decimal_integer_expression_value(value)?.checked_neg()
        }
        Expr::Literal(value, LiteralKind::Number, _) => {
            let suffix = value
                .chars()
                .next_back()
                .filter(|character| matches!(character, '%' | '&' | '^' | '!' | '#'));
            let digits = suffix
                .map(|_| &value[..value.len() - 1])
                .unwrap_or(value.as_str());
            (!digits.is_empty() && digits.bytes().all(|byte| byte.is_ascii_digit()))
                .then(|| digits.parse::<i128>().ok())
                .flatten()
        }
        _ => None,
    }
}

fn enum_currency_literal_expression_value(expression: &Expr) -> Option<f64> {
    match expression {
        Expr::Group(value, _) => enum_currency_literal_expression_value(value),
        Expr::Unary { op, value, .. } if op == "+" => enum_currency_literal_expression_value(value),
        Expr::Unary { op, value, .. } if op == "-" => {
            enum_currency_literal_expression_value(value).map(|number| -number)
        }
        Expr::Literal(text, LiteralKind::Number, _) => {
            if !text.ends_with('@') {
                return None;
            }
            let body = &text[..text.len() - 1];
            let normalized = body
                .chars()
                .map(|character| {
                    if matches!(character, 'd' | 'D') {
                        'E'
                    } else {
                        character
                    }
                })
                .collect::<String>();
            let value = normalized.parse::<f64>().ok()?;
            crate::preprocessor::coerce_numeric_value_to_currency(value)
        }
        _ => None,
    }
}

fn enum_floating_expression_value(expression: &Expr, allow_integral_literal: bool) -> Option<f64> {
    match expression {
        Expr::Group(value, _) => enum_floating_expression_value(value, allow_integral_literal),
        Expr::Unary { op, value, .. } if op == "+" => {
            enum_floating_expression_value(value, allow_integral_literal)
        }
        Expr::Unary { op, value, .. } if op == "-" => {
            enum_floating_expression_value(value, allow_integral_literal).map(|number| -number)
        }
        Expr::Literal(text, LiteralKind::Number, _) => {
            let suffix = text
                .chars()
                .next_back()
                .filter(|character| matches!(character, '%' | '&' | '^' | '!' | '#' | '@'));
            if matches!(suffix, Some('%' | '&' | '^' | '@')) {
                return None;
            }
            let body = suffix
                .map(|_| &text[..text.len() - 1])
                .unwrap_or(text.as_str());
            let is_single = suffix == Some('!');
            let has_floating_form = is_single
                || suffix == Some('#')
                || body.contains('.')
                || body.contains(['e', 'E', 'd', 'D']);
            let has_integral_form = allow_integral_literal
                && !body.is_empty()
                && body.bytes().all(|byte| byte.is_ascii_digit());
            if !(has_floating_form || has_integral_form) {
                return None;
            }
            let normalized = body
                .chars()
                .map(|character| {
                    if matches!(character, 'd' | 'D') {
                        'E'
                    } else {
                        character
                    }
                })
                .collect::<String>();
            let value = normalized.parse::<f64>().ok()?;
            if !value.is_finite() {
                return None;
            }
            if is_single {
                let single = value as f32;
                single.is_finite().then_some(single as f64)
            } else {
                Some(value)
            }
        }
        _ => None,
    }
}

fn enum_expression_contains_binary(expression: &Expr) -> bool {
    match expression {
        Expr::Binary { .. } => true,
        Expr::TypeOfIs { .. } => true,
        Expr::Unary { value, .. } | Expr::Group(value, _) => enum_expression_contains_binary(value),
        Expr::Member { object, .. } => enum_expression_contains_binary(object),
        Expr::Call { callee, args, .. } => {
            enum_expression_contains_binary(callee)
                || args.iter().any(enum_expression_contains_binary)
        }
        Expr::NamedArgument { value, .. } => enum_expression_contains_binary(value),
        Expr::Identifier(..) | Expr::Literal(..) | Expr::Unknown(..) => false,
    }
}

fn enum_float_rounding_boundary_uncertain(value: f64, source_type: &str) -> bool {
    if !value.is_finite() {
        return true;
    }
    let nearest_half = value.floor() + 0.5;
    let epsilon = if source_type == "single" {
        f32::EPSILON as f64
    } else {
        f64::EPSILON
    };
    let tolerance = epsilon * value.abs().max(1.0) * 8.0;
    (value - nearest_half).abs() <= tolerance
}

fn enum_floating_constant_reference_value(
    project: &Project,
    module_index: usize,
    module: &Module,
    reference: &Expr,
    state: &mut EnumConstantFoldState,
) -> Option<f64> {
    let (owner_index, owner, constant) =
        resolve_enum_constant_reference(project, module_index, module, reference)?;
    if state.remaining_references == 0 {
        return None;
    }
    state.remaining_references -= 1;
    let identity = (owner_index, constant.span.start);
    if !state.active.insert(identity) {
        return None;
    }
    let value = (|| {
        let initializer_source = constant.initializer.as_deref()?;
        if initializer_source.len() > 256 {
            return None;
        }
        let initializer = parse_expression_source(initializer_source)?;
        let declared_type = constant
            .type_name
            .clone()
            .or_else(|| type_suffix_name(&constant.name))
            .map(|type_name| effective_project_type_name(project, owner_index, owner, &type_name));
        let inferred_type = declared_type.unwrap_or_else(|| {
            crate::typecheck::infer_expression_type_in_module(
                project,
                owner_index,
                owner,
                &initializer,
                HostProfile::Unknown,
            )
        });
        let value =
            enum_numeric_expression_value_as_f64(project, owner_index, owner, &initializer, state)?;
        match canon(&inferred_type).as_str() {
            "single" => {
                let single = value as f32;
                let value = single as f64;
                (single.is_finite()
                    && (!enum_expression_contains_binary(&initializer)
                        || !enum_float_rounding_boundary_uncertain(value, "single")))
                .then_some(value)
            }
            "double"
                if !enum_expression_contains_binary(&initializer)
                    || !enum_float_rounding_boundary_uncertain(value, "double") =>
            {
                Some(value)
            }
            "currency" => crate::preprocessor::coerce_numeric_value_to_currency(value),
            _ => None,
        }
    })();
    state.active.remove(&identity);
    value
}

fn enum_numeric_expression_value_as_f64(
    project: &Project,
    module_index: usize,
    module: &Module,
    expression: &Expr,
    state: &mut EnumConstantFoldState,
) -> Option<f64> {
    if let Some(value) = enum_currency_literal_expression_value(expression)
        .or_else(|| enum_floating_expression_value(expression, true))
    {
        return Some(value);
    }
    let mut integer_state = EnumConstantFoldState {
        active: HashSet::new(),
        remaining_references: state.remaining_references,
    };
    let integer_value = fold_enum_expression_with_constants(
        project,
        module_index,
        module,
        expression,
        0,
        &mut integer_state,
    );
    state.remaining_references = state
        .remaining_references
        .min(integer_state.remaining_references);
    if let Some(value) = integer_value {
        return Some(value.value as f64);
    }
    match expression {
        Expr::Group(value, _) => {
            enum_numeric_expression_value_as_f64(project, module_index, module, value, state)
        }
        Expr::Unary { op, value, .. } if matches!(canon(op).as_str(), "+" | "-") => {
            let value =
                enum_numeric_expression_value_as_f64(project, module_index, module, value, state)?;
            Some(if op == "-" { -value } else { value })
        }
        Expr::Binary {
            left, op, right, ..
        } if matches!(op.as_str(), "+" | "-" | "*" | "/" | "\\" | "^")
            || op.eq_ignore_ascii_case("mod") =>
        {
            let left =
                enum_numeric_expression_value_as_f64(project, module_index, module, left, state)?;
            let right =
                enum_numeric_expression_value_as_f64(project, module_index, module, right, state)?;
            let normalized_operator = if op.eq_ignore_ascii_case("mod") {
                "mod"
            } else {
                op.as_str()
            };
            let value = match normalized_operator {
                "+" => left + right,
                "-" => left - right,
                "*" => left * right,
                "/" if right != 0.0 => left / right,
                "\\" | "mod"
                    if enum_integer_operator_has_known_long_operands(
                        project,
                        module_index,
                        module,
                        expression,
                    ) =>
                {
                    let left = coerce_enum_floating_value_to_long(left).ok()?;
                    let right = coerce_enum_floating_value_to_long(right).ok()?;
                    if right == 0 {
                        return None;
                    }
                    if op == "\\" {
                        left.checked_div(right)? as f64
                    } else {
                        let quotient = left.checked_div(right)?;
                        left.checked_sub(quotient.checked_mul(right)?)?
                            .checked_abs()? as f64
                    }
                }
                "^" => left.powf(right),
                _ => return None,
            };
            if !value.is_finite() {
                return None;
            }
            let result_type = canon(&crate::typecheck::infer_expression_type_in_module(
                project,
                module_index,
                module,
                expression,
                HostProfile::Unknown,
            ));
            match result_type.as_str() {
                "single" => {
                    let single = value as f32;
                    single.is_finite().then_some(single as f64)
                }
                "double" => Some(value),
                "currency" => crate::preprocessor::coerce_numeric_value_to_currency(value),
                "long"
                    if value.fract() == 0.0
                        && (i32::MIN as f64..=i32::MAX as f64).contains(&value) =>
                {
                    Some(value)
                }
                _ => None,
            }
        }
        Expr::Identifier(..) | Expr::Member { .. } => {
            enum_floating_constant_reference_value(project, module_index, module, expression, state)
        }
        _ => None,
    }
}

fn enum_integer_operator_has_known_long_operands(
    project: &Project,
    module_index: usize,
    module: &Module,
    expression: &Expr,
) -> bool {
    let Expr::Binary {
        left, op, right, ..
    } = expression
    else {
        return false;
    };
    if !(op == "\\" || op.eq_ignore_ascii_case("mod")) {
        return false;
    }
    let left_type = canon(&crate::typecheck::infer_expression_type_in_module(
        project,
        module_index,
        module,
        left,
        HostProfile::Unknown,
    ));
    let right_type = canon(&crate::typecheck::infer_expression_type_in_module(
        project,
        module_index,
        module,
        right,
        HostProfile::Unknown,
    ));
    let numeric = |value: &str| {
        matches!(
            value,
            "byte" | "integer" | "long" | "single" | "double" | "currency"
        )
    };
    // MS-VBAL gives Integer as the effective value type for Boolean/Integer
    // on the left and Single/Double/String/Currency/Date/Decimal on the right.
    // That width is not modeled here, so do not guess a Long conversion.
    numeric(&left_type)
        && numeric(&right_type)
        && !(left_type == "integer"
            && matches!(right_type.as_str(), "single" | "double" | "currency"))
}

fn enum_expression_contains_integer_operator(expression: &Expr) -> bool {
    match expression {
        Expr::Binary {
            left, op, right, ..
        } => {
            (op == "\\" || op.eq_ignore_ascii_case("mod"))
                || enum_expression_contains_integer_operator(left)
                || enum_expression_contains_integer_operator(right)
        }
        Expr::Unary { value, .. } | Expr::Group(value, _) => {
            enum_expression_contains_integer_operator(value)
        }
        Expr::Member { object, .. } => enum_expression_contains_integer_operator(object),
        Expr::Call { callee, args, .. } => {
            enum_expression_contains_integer_operator(callee)
                || args.iter().any(enum_expression_contains_integer_operator)
        }
        Expr::NamedArgument { value, .. } => enum_expression_contains_integer_operator(value),
        Expr::TypeOfIs { expression, .. } => enum_expression_contains_integer_operator(expression),
        Expr::Identifier(..) | Expr::Literal(..) | Expr::Unknown(..) => false,
    }
}

fn enum_member_initializer_forbidden_reference(
    module: &Module,
    enum_span: Span,
    members: &[usize],
    position: usize,
    initializer: &str,
) -> Option<String> {
    let member_index = *members.get(position)?;
    let mut forbidden_names = HashSet::from([canon(&module.declarations.get(member_index)?.name)]);
    for &following_index in members.iter().skip(position + 1) {
        forbidden_names.insert(canon(&module.declarations.get(following_index)?.name));
    }
    let later_enum_spans = module
        .declarations
        .iter()
        .filter(|declaration| {
            declaration.kind == "enum" && declaration.span.start > enum_span.start
        })
        .map(|declaration| declaration.span)
        .collect::<Vec<_>>();
    for declaration in &module.declarations {
        if declaration.kind == "enum_member"
            && later_enum_spans.iter().any(|span| {
                declaration.span.start >= span.start && declaration.span.end <= span.end
            })
        {
            forbidden_names.insert(canon(&declaration.name));
        }
    }
    if let Some(expression) = parse_expression_source(initializer) {
        return enum_expression_forbidden_reference(module, &expression, &forbidden_names);
    }
    let (tokens, _) = lex(initializer, 4096);
    tokens
        .into_iter()
        .find(|token| {
            token.kind == TokenKind::Identifier && forbidden_names.contains(&canon(&token.text))
        })
        .map(|token| token.text)
}

fn enum_expression_forbidden_reference(
    module: &Module,
    expression: &Expr,
    forbidden_names: &HashSet<String>,
) -> Option<String> {
    match expression {
        Expr::Identifier(name, _) => forbidden_names.contains(&canon(name)).then(|| name.clone()),
        Expr::Member {
            object,
            member,
            access: MemberAccessKind::Dot,
            ..
        } => {
            if let Expr::Identifier(enum_name, _) = object.as_ref() {
                let enum_declarations = module
                    .declarations
                    .iter()
                    .filter(|declaration| {
                        declaration.kind == "enum" && canon(&declaration.name) == canon(enum_name)
                    })
                    .collect::<Vec<_>>();
                if enum_declarations.len() == 1 {
                    let enum_span = enum_declarations[0].span;
                    let is_member = module.declarations.iter().any(|declaration| {
                        declaration.kind == "enum_member"
                            && canon(&declaration.name) == canon(member)
                            && declaration.span.start >= enum_span.start
                            && declaration.span.end <= enum_span.end
                    });
                    if is_member && forbidden_names.contains(&canon(member)) {
                        return Some(member.clone());
                    }
                }
            }
            enum_expression_forbidden_reference(module, object, forbidden_names)
        }
        Expr::Unary { value, .. } | Expr::Group(value, _) => {
            enum_expression_forbidden_reference(module, value, forbidden_names)
        }
        Expr::Binary { left, right, .. } => {
            enum_expression_forbidden_reference(module, left, forbidden_names)
                .or_else(|| enum_expression_forbidden_reference(module, right, forbidden_names))
        }
        Expr::Call { args, .. } => args.iter().find_map(|argument| {
            enum_expression_forbidden_reference(module, argument, forbidden_names)
        }),
        Expr::NamedArgument { value, .. } => {
            enum_expression_forbidden_reference(module, value, forbidden_names)
        }
        Expr::TypeOfIs { expression, .. } => {
            enum_expression_forbidden_reference(module, expression, forbidden_names)
        }
        Expr::Literal(..) | Expr::Unknown(..) | Expr::Member { .. } => None,
    }
}

fn coerce_enum_floating_value_to_long(value: f64) -> Result<i32, EnumMemberInitializerError> {
    if !value.is_finite() || !(i32::MIN as f64..=i32::MAX as f64).contains(&value) {
        return Err(EnumMemberInitializerError::FloatingOutOfLongRange(
            value.to_string(),
        ));
    }
    Ok(value.round_ties_even() as i32)
}

fn fold_enum_member_initializer(
    project: &Project,
    module_index: usize,
    module: &Module,
    initializer: &str,
) -> Result<Option<i32>, EnumMemberInitializerError> {
    if initializer.len() > 256 {
        return Ok(None);
    }
    let Some(expression) = parse_expression_source(initializer) else {
        return Ok(None);
    };
    if let Some(problem) = enum_constant_expression_problem(module, &expression) {
        return Err(problem);
    }
    let source_type = crate::typecheck::infer_expression_type_in_module(
        project,
        module_index,
        module,
        &expression,
        HostProfile::Unknown,
    );
    if canon(&source_type) == "longlong" {
        return Err(EnumMemberInitializerError::LongLong);
    }
    if let Some(value) = enum_decimal_integer_expression_value(&expression)
        && !(i32::MIN as i128..=i32::MAX as i128).contains(&value)
    {
        return Err(EnumMemberInitializerError::OutOfLongRange(
            value.to_string(),
        ));
    }
    let source_type = canon(&source_type);
    if enum_expression_contains_integer_operator(&expression) {
        let mut integer_operator_state = EnumConstantFoldState {
            active: HashSet::new(),
            remaining_references: 512,
        };
        if let Some(value) = enum_numeric_expression_value_as_f64(
            project,
            module_index,
            module,
            &expression,
            &mut integer_operator_state,
        ) && let Ok(value) = coerce_enum_floating_value_to_long(value)
        {
            return Ok(Some(value));
        }
    }
    if matches!(source_type.as_str(), "single" | "double" | "currency") {
        let mut floating_state = EnumConstantFoldState {
            active: HashSet::new(),
            remaining_references: 512,
        };
        if let Some(value) = enum_numeric_expression_value_as_f64(
            project,
            module_index,
            module,
            &expression,
            &mut floating_state,
        ) {
            if source_type != "currency"
                && enum_expression_contains_binary(&expression)
                && enum_float_rounding_boundary_uncertain(value, &source_type)
            {
                return Ok(None);
            }
            return coerce_enum_floating_value_to_long(value).map(Some);
        }
    }
    let mut state = EnumConstantFoldState {
        active: HashSet::new(),
        remaining_references: 512,
    };
    let value = fold_enum_expression_with_constants(
        project,
        module_index,
        module,
        &expression,
        0,
        &mut state,
    )
    .and_then(FoldedInteger::coerce_to_long)
    .and_then(|value| i32::try_from(value).ok());
    Ok(value)
}

fn fold_enum_expression_with_constants(
    project: &Project,
    module_index: usize,
    module: &Module,
    expression: &Expr,
    depth: usize,
    state: &mut EnumConstantFoldState,
) -> Option<FoldedInteger> {
    if depth >= 128 {
        return None;
    }
    let mut resolve = |reference: &Expr| {
        if state.remaining_references == 0 {
            return None;
        }
        state.remaining_references -= 1;
        if let Some((owner_index, owner, constant)) =
            resolve_enum_constant_reference(project, module_index, module, reference)
        {
            return fold_enum_constant_declaration(
                project,
                owner_index,
                owner,
                constant,
                depth + 1,
                state,
            );
        }
        let value = resolve_enum_member_value_reference(project, module_index, module, reference)?;
        FoldedInteger::new(value as i64, FoldedIntegerWidth::Long)
    };
    evaluate_integer_constant_expression_with(expression, depth, &mut resolve)
}

fn resolve_enum_member_value_reference(
    project: &Project,
    module_index: usize,
    module: &Module,
    reference: &Expr,
) -> Option<i32> {
    let name = fixed_string_constant_reference_name(reference)?;
    if let Some((qualifier, member_name)) = name.split_once('.') {
        if member_name.contains('.') {
            return None;
        }
        let matching_modules = project
            .modules
            .iter()
            .enumerate()
            .filter(|(_, candidate)| canon(&candidate.name) == canon(qualifier))
            .collect::<Vec<_>>();
        if !matching_modules.is_empty() {
            if matching_modules.len() != 1 {
                return None;
            }
            let (owner_index, owner) = matching_modules[0];
            return enum_member_value_in_module(
                owner,
                owner_index == module_index,
                None,
                member_name,
            );
        }
        let matching_enums = project
            .modules
            .iter()
            .enumerate()
            .flat_map(|(owner_index, owner)| {
                owner.declarations.iter().filter_map(move |declaration| {
                    (declaration.kind == "enum"
                        && canon(&declaration.name) == canon(qualifier)
                        && (owner_index == module_index
                            || declaration.visibility.eq_ignore_ascii_case("public")
                            || declaration.visibility.eq_ignore_ascii_case("global")))
                    .then_some((owner_index, owner, declaration))
                })
            })
            .collect::<Vec<_>>();
        if matching_enums.len() != 1 {
            return None;
        }
        let (owner_index, owner, enum_declaration) = matching_enums[0];
        return enum_member_value_in_module(
            owner,
            owner_index == module_index,
            Some(enum_declaration.span),
            member_name,
        );
    }

    let local_members = module
        .declarations
        .iter()
        .filter(|declaration| {
            declaration.kind == "enum_member" && canon(&declaration.name) == canon(&name)
        })
        .collect::<Vec<_>>();
    if !local_members.is_empty() {
        return (local_members.len() == 1)
            .then(|| local_members[0].enum_value)
            .flatten();
    }
    if module.declarations.iter().any(|declaration| {
        declaration.kind != "enum_member" && canon(&declaration.name) == canon(&name)
    }) || module
        .procedures
        .iter()
        .any(|procedure| canon(&procedure.name) == canon(&name))
    {
        return None;
    }
    let external_name_collision = project
        .modules
        .iter()
        .enumerate()
        .filter(|(owner_index, _)| *owner_index != module_index)
        .any(|(_, owner)| {
            owner.declarations.iter().any(|declaration| {
                declaration.kind != "enum_member"
                    && canon(&declaration.name) == canon(&name)
                    && (declaration.visibility.eq_ignore_ascii_case("public")
                        || declaration.visibility.eq_ignore_ascii_case("global"))
            }) || owner.procedures.iter().any(|procedure| {
                canon(&procedure.name) == canon(&name)
                    && (procedure.visibility.eq_ignore_ascii_case("public")
                        || procedure.visibility.eq_ignore_ascii_case("global"))
            })
        });
    if external_name_collision {
        return None;
    }
    let mut public_members = Vec::new();
    for (owner_index, owner) in project.modules.iter().enumerate() {
        if owner_index == module_index {
            continue;
        }
        for declaration in &owner.declarations {
            if declaration.kind != "enum_member" || canon(&declaration.name) != canon(&name) {
                continue;
            }
            let public_enum_contains_member = owner.declarations.iter().any(|candidate| {
                candidate.kind == "enum"
                    && (candidate.visibility.eq_ignore_ascii_case("public")
                        || candidate.visibility.eq_ignore_ascii_case("global"))
                    && declaration.span.start >= candidate.span.start
                    && declaration.span.end <= candidate.span.end
            });
            if public_enum_contains_member {
                public_members.push(declaration);
            }
        }
    }
    (public_members.len() == 1)
        .then(|| public_members[0].enum_value)
        .flatten()
}

fn enum_member_value_in_module(
    module: &Module,
    is_local_module: bool,
    enum_span: Option<Span>,
    member_name: &str,
) -> Option<i32> {
    let members = module
        .declarations
        .iter()
        .filter(|declaration| {
            declaration.kind == "enum_member"
                && canon(&declaration.name) == canon(member_name)
                && enum_span.is_none_or(|span| {
                    declaration.span.start >= span.start && declaration.span.end <= span.end
                })
        })
        .collect::<Vec<_>>();
    if members.len() != 1 {
        return None;
    }
    let member = members[0];
    if !is_local_module
        && !module.declarations.iter().any(|candidate| {
            candidate.kind == "enum"
                && (candidate.visibility.eq_ignore_ascii_case("public")
                    || candidate.visibility.eq_ignore_ascii_case("global"))
                && member.span.start >= candidate.span.start
                && member.span.end <= candidate.span.end
        })
    {
        return None;
    }
    member.enum_value
}

fn fold_enum_constant_declaration(
    project: &Project,
    module_index: usize,
    module: &Module,
    constant: &Declaration,
    depth: usize,
    state: &mut EnumConstantFoldState,
) -> Option<FoldedInteger> {
    if depth >= 128 || constant.initializer.as_ref()?.len() > 256 {
        return None;
    }
    let identity = (module_index, constant.span.start);
    if !state.active.insert(identity) {
        return None;
    }
    let value = constant
        .initializer
        .as_deref()
        .filter(|initializer| initializer.len() <= 256)
        .and_then(parse_expression_source)
        .and_then(|expression| {
            fold_enum_expression_with_constants(
                project,
                module_index,
                module,
                &expression,
                depth + 1,
                state,
            )
        });
    state.active.remove(&identity);
    fold_integral_constant_reference_value(project, module_index, module, constant, value?)
}

fn resolve_enum_constant_reference<'a>(
    project: &'a Project,
    module_index: usize,
    module: &'a Module,
    reference: &Expr,
) -> Option<(usize, &'a Module, &'a Declaration)> {
    let name = fixed_string_constant_reference_name(reference)?;
    if let Some((module_name, constant_name)) = name.split_once('.') {
        if constant_name.contains('.') {
            return None;
        }
        let modules = project
            .modules
            .iter()
            .enumerate()
            .filter(|(_, candidate)| canon(&candidate.name) == canon(module_name))
            .collect::<Vec<_>>();
        if modules.len() != 1 {
            return None;
        }
        let (owner_index, owner) = modules[0];
        if owner_index != module_index
            && !matches!(owner.module_kind.as_deref(), Some("standard") | None)
        {
            return None;
        }
        let constants = owner
            .declarations
            .iter()
            .filter(|declaration| {
                declaration.kind == "constant"
                    && canon(&declaration.name) == canon(constant_name)
                    && (owner_index == module_index
                        || declaration.visibility.eq_ignore_ascii_case("public")
                        || declaration.visibility.eq_ignore_ascii_case("global"))
            })
            .collect::<Vec<_>>();
        if constants.len() != 1
            || owner.declarations.iter().any(|declaration| {
                declaration.kind == "enum" && canon(&declaration.name) == canon(constant_name)
            })
        {
            return None;
        }
        return Some((owner_index, owner, constants[0]));
    }

    let local_constants = module
        .declarations
        .iter()
        .filter(|declaration| {
            declaration.kind == "constant" && canon(&declaration.name) == canon(&name)
        })
        .collect::<Vec<_>>();
    if !local_constants.is_empty() {
        if local_constants.len() != 1
            || module.declarations.iter().any(|declaration| {
                declaration.kind != "constant" && canon(&declaration.name) == canon(&name)
            })
            || module
                .procedures
                .iter()
                .any(|procedure| canon(&procedure.name) == canon(&name))
            || module.declarations.iter().any(|declaration| {
                declaration.kind == "enum" && canon(&declaration.name) == canon(&name)
            })
        {
            return None;
        }
        return Some((module_index, module, local_constants[0]));
    }
    if module
        .declarations
        .iter()
        .any(|declaration| canon(&declaration.name) == canon(&name))
        || module
            .procedures
            .iter()
            .any(|procedure| canon(&procedure.name) == canon(&name))
    {
        return None;
    }

    let mut public_constants = Vec::new();
    for (owner_index, owner) in project.modules.iter().enumerate() {
        if owner_index == module_index
            || !matches!(owner.module_kind.as_deref(), Some("standard") | None)
            || owner.declarations.iter().any(|declaration| {
                declaration.kind == "enum" && canon(&declaration.name) == canon(&name)
            })
        {
            continue;
        }
        for declaration in &owner.declarations {
            if declaration.kind == "constant"
                && (declaration.visibility.eq_ignore_ascii_case("public")
                    || declaration.visibility.eq_ignore_ascii_case("global"))
                && canon(&declaration.name) == canon(&name)
            {
                public_constants.push((owner_index, owner, declaration));
            }
        }
    }
    let enum_name_collision = project.modules.iter().any(|owner| {
        owner.declarations.iter().any(|declaration| {
            matches!(declaration.kind.as_str(), "enum" | "enum_member")
                && canon(&declaration.name) == canon(&name)
        })
    });
    if enum_name_collision {
        return None;
    }
    (public_constants.len() == 1).then(|| public_constants[0])
}

fn populate_enum_member_values(project: &mut Project, diagnostics: &mut Vec<Diagnostic>) {
    let mut enum_diagnostics = Vec::new();
    for module_index in 0..project.modules.len() {
        let enum_declarations = project.modules[module_index]
            .declarations
            .iter()
            .filter(|declaration| declaration.kind == "enum")
            .map(|declaration| (declaration.name.clone(), declaration.span))
            .collect::<Vec<_>>();
        for (enum_name, enum_span) in enum_declarations {
            let members = project.modules[module_index]
                .declarations
                .iter()
                .enumerate()
                .filter(|(_, declaration)| {
                    declaration.kind == "enum_member"
                        && declaration
                            .type_name
                            .as_deref()
                            .is_some_and(|type_name| canon(type_name) == canon(&enum_name))
                        && declaration.span.start >= enum_span.start
                        && declaration.span.end <= enum_span.end
                })
                .map(|(index, _)| index)
                .collect::<Vec<_>>();
            let mut previous_value = None;
            let mut has_previous_member = false;
            for (position, member_index) in members.iter().copied().enumerate() {
                let member_name = project.modules[module_index].declarations[member_index]
                    .name
                    .clone();
                let initializer = project.modules[module_index].declarations[member_index]
                    .initializer
                    .clone();
                let member_span = project.modules[module_index].declarations[member_index].span;
                let module_source = project.modules[module_index].source_name.clone();
                let implicit_overflow = initializer.is_none()
                    && previous_value == Some(i32::MAX)
                    && has_previous_member;
                let forbidden_reference = initializer.as_deref().and_then(|initializer| {
                    enum_member_initializer_forbidden_reference(
                        &project.modules[module_index],
                        enum_span,
                        &members,
                        position,
                        initializer,
                    )
                });
                let initializer_result = match initializer.as_deref() {
                    Some(_) if forbidden_reference.is_some() => Ok(None),
                    Some(initializer) => fold_enum_member_initializer(
                        project,
                        module_index,
                        &project.modules[module_index],
                        initializer,
                    ),
                    None if !has_previous_member => Ok(Some(0)),
                    None => Ok(previous_value.and_then(|value: i32| value.checked_add(1))),
                };
                let value = match initializer_result {
                    Ok(value) => value,
                    Err(EnumMemberInitializerError::FunctionCall) => {
                        enum_diagnostics.push(Diagnostic {
                            code: "VBA1048",
                            severity: Severity::Error,
                            message: format!(
                                "Enum member '{}' initializer is not a constant expression because it contains a procedure call",
                                member_name
                            ),
                            source: module_source.clone(),
                            span: member_span,
                        });
                        None
                    }
                    Err(EnumMemberInitializerError::RuntimeTypeTest) => {
                        enum_diagnostics.push(Diagnostic {
                            code: "VBA1048",
                            severity: Severity::Error,
                            message: format!(
                                "Enum member '{}' initializer is not a constant expression because it contains a run-time TypeOf...Is test",
                                member_name
                            ),
                            source: module_source.clone(),
                            span: member_span,
                        });
                        None
                    }
                    Err(EnumMemberInitializerError::VariableReference(name)) => {
                        enum_diagnostics.push(Diagnostic {
                            code: "VBA1049",
                            severity: Severity::Error,
                            message: format!(
                                "Enum member '{}' initializer references module variable '{}' instead of a constant expression",
                                member_name, name
                            ),
                            source: module_source.clone(),
                            span: member_span,
                        });
                        None
                    }
                    Err(EnumMemberInitializerError::LongLong) => {
                        enum_diagnostics.push(Diagnostic {
                            code: "VBA2086",
                            severity: Severity::Error,
                            message: format!(
                                "LongLong value for Enum member '{}' cannot be implicitly Let-coerced to Long",
                                member_name
                            ),
                            source: module_source.clone(),
                            span: member_span,
                        });
                        None
                    }
                    Err(EnumMemberInitializerError::OutOfLongRange(value)) => {
                        enum_diagnostics.push(Diagnostic {
                            code: "VBA1046",
                            severity: Severity::Error,
                            message: format!(
                                "integral value {} for Enum member '{}' is outside the Long range",
                                value, member_name
                            ),
                            source: module_source.clone(),
                            span: member_span,
                        });
                        None
                    }
                    Err(EnumMemberInitializerError::FloatingOutOfLongRange(value)) => {
                        enum_diagnostics.push(Diagnostic {
                            code: "VBA1047",
                            severity: Severity::Error,
                            message: format!(
                                "floating-point value {} for Enum member '{}' is outside the Long range",
                                value, member_name
                            ),
                            source: module_source.clone(),
                            span: member_span,
                        });
                        None
                    }
                };
                if implicit_overflow {
                    enum_diagnostics.push(Diagnostic {
                        code: "VBA1043",
                        severity: Severity::Error,
                        message: format!(
                            "implicit value for Enum member '{}' exceeds the Long range after the preceding member value 2147483647",
                            member_name
                        ),
                        source: module_source,
                        span: member_span,
                    });
                }
                project.modules[module_index].declarations[member_index].enum_value = value;
                previous_value = value;
                has_previous_member = true;
            }
        }
    }
    diagnostics.extend(enum_diagnostics);
}

fn populate_cross_module_enum_member_values(
    project: &mut Project,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let enum_member_count = project
        .modules
        .iter()
        .flat_map(|module| &module.declarations)
        .filter(|declaration| declaration.kind == "enum_member")
        .count();
    if enum_member_count == 0 {
        return;
    }
    let max_passes = enum_member_count.min(128);
    let mut diagnosed_overflows = diagnostics
        .iter()
        .filter(|diagnostic| diagnostic.code == "VBA1043")
        .map(|diagnostic| (diagnostic.source.clone(), diagnostic.span.start))
        .collect::<HashSet<_>>();
    for _ in 0..max_passes {
        let mut changed = false;
        let mut remaining_work = 100_000usize;
        'modules: for module_index in 0..project.modules.len() {
            let enum_declarations = project.modules[module_index]
                .declarations
                .iter()
                .filter(|declaration| declaration.kind == "enum")
                .map(|declaration| (declaration.name.clone(), declaration.span))
                .collect::<Vec<_>>();
            for (enum_name, enum_span) in enum_declarations {
                let members = project.modules[module_index]
                    .declarations
                    .iter()
                    .enumerate()
                    .filter(|(_, declaration)| {
                        declaration.kind == "enum_member"
                            && declaration
                                .type_name
                                .as_deref()
                                .is_some_and(|type_name| canon(type_name) == canon(&enum_name))
                            && declaration.span.start >= enum_span.start
                            && declaration.span.end <= enum_span.end
                    })
                    .map(|(index, _)| index)
                    .collect::<Vec<_>>();
                let mut previous_value = None;
                let mut has_previous_member = false;
                for (position, member_index) in members.iter().copied().enumerate() {
                    let (existing, initializer, span, source_name) = {
                        let declaration = &project.modules[module_index].declarations[member_index];
                        (
                            declaration.enum_value,
                            declaration.initializer.clone(),
                            declaration.span,
                            project.modules[module_index].source_name.clone(),
                        )
                    };
                    if existing.is_some() {
                        previous_value = existing;
                        has_previous_member = true;
                        continue;
                    }
                    if remaining_work == 0 {
                        break 'modules;
                    }
                    remaining_work -= 1;
                    let candidate = match initializer.as_deref() {
                        Some(initializer)
                            if enum_member_initializer_forbidden_reference(
                                &project.modules[module_index],
                                enum_span,
                                &members,
                                position,
                                initializer,
                            )
                            .is_some() =>
                        {
                            None
                        }
                        Some(initializer) => fold_enum_member_initializer(
                            project,
                            module_index,
                            &project.modules[module_index],
                            initializer,
                        )
                        .ok()
                        .flatten(),
                        None if !has_previous_member => Some(0),
                        None => previous_value.and_then(|value: i32| value.checked_add(1)),
                    };
                    if candidate.is_some() {
                        project.modules[module_index].declarations[member_index].enum_value =
                            candidate;
                        changed = true;
                    }
                    if initializer.is_none()
                        && has_previous_member
                        && previous_value == Some(i32::MAX)
                        && diagnosed_overflows.insert((source_name.clone(), span.start))
                    {
                        diagnostics.push(Diagnostic {
                            code: "VBA1043",
                            severity: Severity::Error,
                            message: format!(
                                "implicit value for Enum member '{}' exceeds the Long range after the preceding member value 2147483647",
                                project.modules[module_index].declarations[member_index].name
                            ),
                            source: source_name.clone(),
                            span,
                        });
                    }
                    previous_value = existing.or(candidate);
                    has_previous_member = true;
                }
            }
        }
        if !changed {
            break;
        }
    }
}

fn validate_enum_member_name_collisions_and_initializer_order(
    project: &Project,
    diagnostics: &mut Vec<Diagnostic>,
) {
    for module in &project.modules {
        let enums = module
            .declarations
            .iter()
            .filter(|declaration| declaration.kind == "enum")
            .map(|declaration| {
                (
                    declaration.name.clone(),
                    declaration.span,
                    declaration.visibility.clone(),
                )
            })
            .collect::<Vec<_>>();
        for (enum_name, enum_span, visibility) in enums {
            if visibility.eq_ignore_ascii_case("global")
                && matches!(
                    module.module_kind.as_deref(),
                    Some(
                        "class"
                            | "form"
                            | "workbook_document"
                            | "worksheet_document"
                            | "document_or_class"
                            | "class_or_document"
                    )
                )
            {
                diagnostics.push(Diagnostic {
                    code: "VBA1050",
                    severity: Severity::Error,
                    message: format!(
                        "Global Enum '{}' is not allowed in a class module",
                        enum_name
                    ),
                    source: module.source_name.clone(),
                    span: enum_span,
                });
            }
            let member_indices = module
                .declarations
                .iter()
                .enumerate()
                .filter(|(_, declaration)| {
                    declaration.kind == "enum_member"
                        && declaration
                            .type_name
                            .as_deref()
                            .is_some_and(|type_name| canon(type_name) == canon(&enum_name))
                        && declaration.span.start >= enum_span.start
                        && declaration.span.end <= enum_span.end
                })
                .map(|(index, _)| index)
                .collect::<Vec<_>>();

            for (position, &member_index) in member_indices.iter().enumerate() {
                let member = &module.declarations[member_index];
                if let Some(conflict) = module.declarations.iter().find(|declaration| {
                    declaration.kind != "enum_member"
                        && is_variable_declaration(declaration)
                        && canon(&declaration.name) == canon(&member.name)
                }) {
                    diagnostics.push(Diagnostic {
                        code: "VBA1044",
                        severity: Severity::Error,
                        message: format!(
                            "Enum member '{}' conflicts with module declaration '{}'",
                            member.name, conflict.name
                        ),
                        source: module.source_name.clone(),
                        span: member.span,
                    });
                }

                let Some(initializer) = member.initializer.as_deref() else {
                    continue;
                };
                if let Some(reference) = enum_member_initializer_forbidden_reference(
                    module,
                    enum_span,
                    &member_indices,
                    position,
                    initializer,
                ) {
                    diagnostics.push(Diagnostic {
                        code: "VBA1045",
                        severity: Severity::Error,
                        message: format!(
                            "Enum member '{}' initializer references itself or an Enum member that is not yet declared '{}'",
                            member.name, reference
                        ),
                        source: module.source_name.clone(),
                        span: member.span,
                    });
                }
            }
        }
    }
}

fn validate_udt_name_collisions(project: &Project, diagnostics: &mut Vec<Diagnostic>) {
    for (module_index, module) in project.modules.iter().enumerate() {
        for (declaration_index, declaration) in module.declarations.iter().enumerate() {
            if declaration.kind != "user_type" {
                continue;
            }
            let key = canon(&declaration.name);
            let is_public = declaration.visibility.eq_ignore_ascii_case("public")
                || declaration.visibility.eq_ignore_ascii_case("global");
            let type_name_collision = if is_public {
                project
                    .modules
                    .iter()
                    .enumerate()
                    .any(|(other_module_index, other_module)| {
                        other_module.declarations.iter().enumerate().any(
                            |(other_decl_index, other)| {
                                if other_module_index == module_index
                                    && other_decl_index == declaration_index
                                {
                                    return false;
                                }
                                if canon(&other.name) != key {
                                    return false;
                                }
                                other.kind == "enum"
                                    && (other.visibility.eq_ignore_ascii_case("public")
                                        || other.visibility.eq_ignore_ascii_case("global"))
                                    || other.kind == "user_type"
                                        && (other.visibility.eq_ignore_ascii_case("public")
                                            || other.visibility.eq_ignore_ascii_case("global"))
                            },
                        )
                    })
            } else {
                module
                    .declarations
                    .iter()
                    .enumerate()
                    .any(|(other_decl_index, other)| {
                        other_decl_index != declaration_index
                            && matches!(other.kind.as_str(), "user_type" | "enum")
                            && canon(&other.name) == key
                    })
            };
            if type_name_collision {
                diagnostics.push(Diagnostic {
                    code: "VBA1034",
                    severity: Severity::Error,
                    message: format!(
                        "UDT '{}' conflicts with another UDT or Enum name in its visibility scope",
                        declaration.name
                    ),
                    source: module.source_name.clone(),
                    span: declaration.span,
                });
            }
            if !is_public {
                continue;
            }
            let colliding_modules = project
                .modules
                .iter()
                .filter(|candidate| canon(&candidate.name) == key)
                .map(|candidate| candidate.name.as_str())
                .collect::<Vec<_>>();
            let collides_with_project = project
                .name
                .as_deref()
                .is_some_and(|name| canon(name) == key);
            let colliding_references = project
                .references
                .iter()
                .filter(|reference| canon(reference) == key)
                .map(String::as_str)
                .collect::<Vec<_>>();
            if !colliding_modules.is_empty()
                || collides_with_project
                || !colliding_references.is_empty()
            {
                let mut resources = colliding_modules;
                if collides_with_project {
                    resources.push(project.name.as_deref().unwrap_or_default());
                }
                resources.extend(colliding_references);
                resources.sort_unstable();
                resources.dedup();
                diagnostics.push(Diagnostic {
                    code: "VBA1035",
                    severity: Severity::Error,
                    message: format!(
                        "Public UDT '{}' conflicts with project, library, or module name(s): {}",
                        declaration.name,
                        resources.join(", ")
                    ),
                    source: module.source_name.clone(),
                    span: declaration.span,
                });
            }
        }
    }
}

fn validate_enum_type_name_collisions(project: &Project, diagnostics: &mut Vec<Diagnostic>) {
    for (module_index, module) in project.modules.iter().enumerate() {
        for (declaration_index, declaration) in module.declarations.iter().enumerate() {
            if declaration.kind != "enum" {
                continue;
            }
            let name = canon(&declaration.name);
            let is_public = declaration.visibility.eq_ignore_ascii_case("public")
                || declaration.visibility.eq_ignore_ascii_case("global");
            let enum_name_conflict = if is_public {
                project
                    .modules
                    .iter()
                    .enumerate()
                    .any(|(other_module_index, other_module)| {
                        other_module.declarations.iter().enumerate().any(
                            |(other_declaration_index, other)| {
                                let precedes_current = other_module_index < module_index
                                    || (other_module_index == module_index
                                        && other_declaration_index < declaration_index);
                                precedes_current
                                    && other.kind == "enum"
                                    && (other.visibility.eq_ignore_ascii_case("public")
                                        || other.visibility.eq_ignore_ascii_case("global"))
                                    && canon(&other.name) == name
                            },
                        )
                    })
            } else {
                module
                    .declarations
                    .iter()
                    .enumerate()
                    .any(|(other_index, other)| {
                        other_index != declaration_index
                            && other.kind == "enum"
                            && canon(&other.name) == name
                            && (other.visibility.eq_ignore_ascii_case("public")
                                || other.visibility.eq_ignore_ascii_case("global")
                                || other_index < declaration_index)
                    })
            };
            if enum_name_conflict {
                diagnostics.push(Diagnostic {
                    code: "VBA1051",
                    severity: Severity::Error,
                    message: format!(
                        "Enum '{}' conflicts with another Enum in its visibility scope",
                        declaration.name
                    ),
                    source: module.source_name.clone(),
                    span: declaration.span,
                });
            }

            if !is_public {
                let public_udt_conflict = module.declarations.iter().any(|other| {
                    other.kind == "user_type"
                        && (other.visibility.eq_ignore_ascii_case("public")
                            || other.visibility.eq_ignore_ascii_case("global"))
                        && canon(&other.name) == name
                });
                if public_udt_conflict {
                    diagnostics.push(Diagnostic {
                        code: "VBA1051",
                        severity: Severity::Error,
                        message: format!(
                            "Private Enum '{}' conflicts with a public UDT in the same module",
                            declaration.name
                        ),
                        source: module.source_name.clone(),
                        span: declaration.span,
                    });
                }
                continue;
            }

            let mut colliding_names = project
                .modules
                .iter()
                .filter(|candidate| canon(&candidate.name) == name)
                .map(|candidate| candidate.name.clone())
                .collect::<Vec<_>>();
            if project
                .name
                .as_deref()
                .is_some_and(|project_name| canon(project_name) == name)
            {
                colliding_names.push(project.name.clone().unwrap_or_default());
            }
            colliding_names.extend(
                project
                    .references
                    .iter()
                    .filter(|reference| canon(reference) == name)
                    .cloned(),
            );
            colliding_names.sort();
            colliding_names.dedup();
            if !colliding_names.is_empty() {
                diagnostics.push(Diagnostic {
                    code: "VBA1051",
                    severity: Severity::Error,
                    message: format!(
                        "Public Enum '{}' conflicts with project, library, or module name(s): {}",
                        declaration.name,
                        colliding_names.join(", ")
                    ),
                    source: module.source_name.clone(),
                    span: declaration.span,
                });
            }
        }
    }
}
fn collect_labels(statements: &[Statement], labels: &mut HashSet<String>) {
    for s in statements {
        if s.kind == "label"
            && let Some(n) = &s.expression
        {
            labels.insert(canonical_statement_label(n));
        }
        collect_labels(&s.children, labels);
    }
}

fn collect_jump_target_spans(statements: &[Statement], spans: &mut HashSet<(usize, usize)>) {
    for statement in statements {
        if statement.kind == "jump_target" {
            spans.insert((statement.span.start, statement.span.end));
        }
        collect_jump_target_spans(&statement.children, spans);
    }
}

fn validate_label_definitions(
    statements: &[Statement],
    labels: &mut HashMap<String, Span>,
    diagnostics: &mut Vec<Diagnostic>,
    source: &str,
) {
    for s in statements {
        if s.kind == "label"
            && let Some(raw) = &s.expression
        {
            let name = raw.trim_end_matches(':');
            let key = canonical_statement_label(name);
            if let Some(previous) = labels.insert(key, s.span) {
                diagnostics.push(Diagnostic {
                    code: "VBA2042",
                    severity: Severity::Error,
                    message: format!(
                        "duplicate label '{}' (first declared at line {})",
                        name, previous.line
                    ),
                    source: source.into(),
                    span: s.span,
                });
            }
            let numeric = !name.is_empty() && name.bytes().all(|byte| byte.is_ascii_digit());
            if numeric && !matches!(name.parse::<u64>(), Ok(value) if value <= 2_147_483_647) {
                diagnostics.push(Diagnostic {
                    code: "VBA2043",
                    severity: Severity::Error,
                    message: format!(
                        "line-number label '{}' is outside the permitted range 0 through 2147483647",
                        name
                    ),
                    source: source.into(),
                    span: s.span,
                });
            }
        }
        validate_label_definitions(&s.children, labels, diagnostics, source);
    }
}
fn validate_jump_targets(
    statements: &[Statement],
    labels: &HashSet<String>,
    diagnostics: &mut Vec<Diagnostic>,
    source: &str,
) {
    for s in statements {
        if matches!(s.kind.as_str(), "goto" | "gosub" | "on_goto" | "on_gosub") {
            let targets = s
                .children
                .iter()
                .filter(|child| child.kind == "jump_target")
                .filter_map(|child| child.expression.as_deref())
                .collect::<Vec<_>>();
            for target in targets {
                let target = target.trim_end_matches(':');
                if labels.contains(&canonical_statement_label(target)) {
                    continue;
                }
                diagnostics.push(Diagnostic {
                    code: "VBA2041",
                    severity: Severity::Error,
                    message: format!("label '{}' is not defined in this procedure", target),
                    source: source.into(),
                    span: s
                        .children
                        .iter()
                        .find(|child| {
                            child.kind == "jump_target"
                                && child.expression.as_deref() == Some(target)
                        })
                        .map(|child| child.span)
                        .unwrap_or(s.span),
                });
            }
        }
        validate_jump_targets(&s.children, labels, diagnostics, source);
    }
}
fn collect_error_handling_facts(project: &Project) -> Vec<ErrorHandlingFact> {
    let mut out = Vec::new();
    for m in &project.modules {
        for p in &m.procedures {
            let mut labels = HashSet::new();
            collect_labels(&p.statements, &mut labels);
            collect_error_facts_in(&m.name, &p.name, &p.statements, &labels, &mut out);
        }
    }
    out
}
fn collect_error_facts_in(
    module: &str,
    procedure: &str,
    statements: &[Statement],
    labels: &HashSet<String>,
    out: &mut Vec<ErrorHandlingFact>,
) {
    for s in statements {
        if matches!(s.kind.as_str(), "on_error" | "resume") {
            let text = s.expression.as_deref().unwrap_or("");
            let words = text.split_whitespace().collect::<Vec<_>>();
            let low = text.to_ascii_lowercase();
            if s.kind == "on_error" {
                let (operation, target, resolved) = if low.starts_with("on error resume next") {
                    ("resume_next", None, None)
                } else if low.starts_with("on error goto 0") {
                    ("disable", None, None)
                } else if low.starts_with("on error goto -1") {
                    ("clear_active_error", None, None)
                } else if low.starts_with("on error goto ") {
                    let t = words.get(3).map(|x| x.trim_end_matches(':').to_string());
                    (
                        "goto_label",
                        t.clone(),
                        t.as_ref()
                            .map(|x| labels.contains(&canonical_statement_label(x))),
                    )
                } else {
                    ("unknown_policy", None, None)
                };
                out.push(ErrorHandlingFact {
                    module: module.into(),
                    procedure: procedure.into(),
                    operation: operation.into(),
                    target,
                    target_resolved: resolved,
                    path_state_verified: false,
                    span: s.span,
                });
            } else {
                let (operation, target) = if low == "resume" || low == "resume 0" {
                    ("retry_fault", None)
                } else if low == "resume next" {
                    ("resume_next", None)
                } else {
                    (
                        "resume_label",
                        words.get(1).map(|x| x.trim_end_matches(':').to_string()),
                    )
                };
                out.push(ErrorHandlingFact {
                    module: module.into(),
                    procedure: procedure.into(),
                    operation: operation.into(),
                    target: target.clone(),
                    target_resolved: target
                        .as_ref()
                        .map(|x| labels.contains(&canonical_statement_label(x))),
                    path_state_verified: false,
                    span: s.span,
                });
            }
        }
        collect_error_facts_in(module, procedure, &s.children, labels, out);
    }
}
fn line_starts_with(tokens: &[Token], at: usize, word: &str) -> bool {
    let mut start = at;
    while start > 0 && tokens[start - 1].kind != TokenKind::Newline {
        start -= 1;
    }
    tokens
        .get(start)
        .is_some_and(|t| t.text.eq_ignore_ascii_case(word))
}
fn statement_starts_with_keyword(tokens: &[Token], at: usize, word: &str) -> bool {
    let mut start = at;
    while start > 0 {
        let previous = &tokens[start - 1];
        if previous.kind == TokenKind::Newline
            || matches!(previous.text.as_str(), ":")
            || matches!(canon(&previous.text).as_str(), "then" | "else")
        {
            break;
        }
        start -= 1;
    }
    tokens
        .get(start)
        .is_some_and(|token| token.text.eq_ignore_ascii_case(word))
}
fn statement_starts_with_explicit_call(tokens: &[Token], at: usize) -> bool {
    statement_starts_with_keyword(tokens, at, "call")
}
fn is_function_result_assignment(
    module: &Module,
    procedure: Option<&str>,
    tokens: &[Token],
    at: usize,
    name: &str,
) -> bool {
    let Some(p) = procedure.and_then(|n| {
        module
            .procedures
            .iter()
            .find(|p| p.name.eq_ignore_ascii_case(n))
    }) else {
        return false;
    };
    if !matches!(
        p.kind.to_ascii_lowercase().as_str(),
        "function" | "property get"
    ) || canon(&p.name) != canon(name)
    {
        return false;
    }
    let mut start = at;
    while start > 0 && tokens[start - 1].kind != TokenKind::Newline && tokens[start - 1].text != ":"
    {
        start -= 1;
    }
    let target = if tokens
        .get(start)
        .is_some_and(|t| matches!(t.text.to_ascii_lowercase().as_str(), "set" | "let"))
    {
        start + 1
    } else {
        start
    };
    target == at && statement_assignment_eq(tokens, at).is_some_and(|eq| eq > at)
}
fn is_assignment_lvalue(tokens: &[Token], at: usize) -> bool {
    let mut start = at;
    while start > 0 && tokens[start - 1].kind != TokenKind::Newline && tokens[start - 1].text != ":"
    {
        start -= 1;
    }
    let Some(first) = tokens.get(start) else {
        return false;
    };
    if matches!(
        canon(&first.text).as_str(),
        "if" | "elseif" | "for" | "case" | "const" | "dim" | "public" | "private" | "option"
    ) {
        return false;
    }
    let target = if matches!(canon(&first.text).as_str(), "set" | "let") {
        start + 1
    } else {
        start
    };
    let Some(eq) = statement_assignment_eq(tokens, at) else {
        return false;
    };
    target == at && eq > at
}
fn contains_statement(ss: &[Statement], kind: &str) -> bool {
    ss.iter()
        .any(|s| s.kind == kind || contains_statement(&s.children, kind))
}
fn is_declaration_position(prev: Option<&Token>) -> bool {
    prev.is_some_and(|t| {
        matches!(
            canon(&t.text).as_str(),
            "sub"
                | "function"
                | "get"
                | "let"
                | "set"
                | "dim"
                | "const"
                | "as"
                | "byval"
                | "byref"
                | "optional"
                | "paramarray"
                | "withevents"
                | "event"
                | "type"
                | "enum"
                | "declare"
                | "lib"
                | "alias"
        )
    })
}
fn is_bare_call(ts: &[Token], i: usize) -> bool {
    let mut start = i;
    while start > 0 && ts[start - 1].kind != TokenKind::Newline && ts[start - 1].text != ":" {
        start -= 1;
    }
    if start != i {
        return false;
    }
    let Some(n) = ts.get(i + 1) else {
        return false;
    };
    !matches!(
        n.text.as_str(),
        "=" | ":="
            | "."
            | "!"
            | "+"
            | "-"
            | "*"
            | "/"
            | "&"
            | "<"
            | ">"
            | "<="
            | ">="
            | "<>"
            | "as"
            | ","
            | ":"
    )
}
fn statement_assignment_eq(ts: &[Token], at: usize) -> Option<usize> {
    let mut depth = 0i32;
    let mut start = at;
    while start > 0 && ts[start - 1].kind != TokenKind::Newline && ts[start - 1].text != ":" {
        start -= 1;
    }
    for (i, token) in ts.iter().enumerate().skip(start) {
        if token.kind == TokenKind::Newline || token.text == ":" {
            break;
        }
        match token.text.as_str() {
            "(" | "[" => depth += 1,
            ")" | "]" => depth -= 1,
            "=" if depth == 0 => return Some(i),
            _ => {}
        }
    }
    None
}
fn call_target(ts: &[Token], at: usize) -> String {
    let mut out = ts.get(at).map(|t| t.text.clone()).unwrap_or_default();
    let mut i = at + 1;
    if ts.get(i).is_some_and(|t| t.text == "(") {
        let mut d = 0i32;
        while i < ts.len() {
            if ts[i].text == "(" {
                d += 1;
            } else if ts[i].text == ")" {
                d -= 1;
            }
            out.push_str(&ts[i].text);
            i += 1;
            if d == 0 {
                break;
            }
        }
    } else {
        let start = i;
        while i < ts.len()
            && ts[i].kind != TokenKind::Newline
            && ts[i].kind != TokenKind::Eof
            && ts[i].text != ":"
        {
            i += 1;
        }
        if i > start {
            out.push(' ');
            out.push_str(&render_call_argument(&ts[start..i]));
        }
    }
    out
}
fn data_access_target(ts: &[Token], at: usize) -> String {
    let mut start = at;
    while start > 0 && ts[start - 1].kind != TokenKind::Newline && ts[start - 1].text != ":" {
        start -= 1;
    }
    let first = ts
        .get(start)
        .map(|token| canon(&token.text))
        .unwrap_or_default();
    if matches!(
        first.as_str(),
        "if" | "elseif" | "while" | "do" | "select" | "case"
    ) {
        return call_target(ts, at);
    }
    let end = ts[at + 1..]
        .iter()
        .position(|token| token.kind == TokenKind::Newline || token.text == ":")
        .map(|offset| at + 1 + offset)
        .unwrap_or(ts.len());
    match statement_assignment_eq(ts, at) {
        Some(equal) if equal > at => {
            let mut target = render_call_argument(&ts[start..equal]);
            let low = target.to_ascii_lowercase();
            if low.starts_with("set ") || low.starts_with("let ") {
                target = target[4..].trim_start().to_owned();
            }
            target
        }
        Some(equal) if equal < at => render_call_argument(&ts[equal + 1..end]),
        _ => call_target(ts, at),
    }
}
fn call_arguments(ts: &[Token], at: usize) -> Option<Vec<String>> {
    let next = at + 1;
    if statement_starts_with_explicit_call(ts, at)
        && ts.get(next).is_none_or(|token| token.text != "(")
    {
        return Some(Vec::new());
    }
    if ts.get(next).is_some_and(|t| t.text == "(") {
        let mut depth = 0i32;
        let mut close = None;
        for (i, t) in ts.iter().enumerate().skip(next + 1) {
            match t.text.as_str() {
                "(" => depth += 1,
                ")" if depth == 0 => {
                    close = Some(i);
                    break;
                }
                ")" => depth -= 1,
                _ => {}
            }
        }
        let end = close?;
        if end == next + 1 {
            return Some(Vec::new());
        }
        Some(
            split_tokens(&ts[next + 1..end], ",")
                .into_iter()
                .map(render_call_argument)
                .collect(),
        )
    } else {
        let mut end = next;
        while end < ts.len()
            && ts[end].kind != TokenKind::Newline
            && ts[end].kind != TokenKind::Eof
            && ts[end].text != ":"
        {
            end += 1;
        }
        if end == next {
            return Some(Vec::new());
        }
        Some(
            split_tokens(&ts[next..end], ",")
                .into_iter()
                .map(render_call_argument)
                .collect(),
        )
    }
}
fn bind_arguments(
    parameters: &[Parameter],
    arguments: &[String],
    external_procedure: bool,
) -> (Vec<(usize, String)>, Vec<String>) {
    let mut bindings = Vec::new();
    let mut issues = Vec::new();
    let mut assigned = HashSet::new();
    let mut next_positional = 0usize;
    let param_array = parameters.iter().position(|p| p.is_param_array);
    let mut named_seen = false;
    for argument in arguments {
        let argument_value = argument
            .split_once(":=")
            .map(|(_, value)| value)
            .unwrap_or(argument)
            .trim();
        if argument_value.to_ascii_lowercase().starts_with("byref ") {
            issues.push("ByRef is not valid as a call-site argument modifier".into());
        }
        if !external_procedure && argument_value.to_ascii_lowercase().starts_with("byval ") {
            issues.push("ByVal is valid at a call site only for external procedures".into());
        }
        if let Some((name, value)) = argument.split_once(":=") {
            named_seen = true;
            if param_array.is_some() {
                issues.push(
                    "named arguments cannot be used when the signature has a ParamArray".into(),
                );
            }
            let Some(index) = parameters
                .iter()
                .position(|p| canon(&p.name) == canon(name.trim()))
            else {
                issues.push(format!("unknown named argument '{}'", name.trim()));
                continue;
            };
            if !assigned.insert(index) {
                issues.push(format!(
                    "parameter '{}' is supplied more than once",
                    name.trim()
                ));
                continue;
            }
            if value.trim().is_empty() {
                issues.push(format!("named argument '{}' has no value", name.trim()));
                continue;
            }
            bindings.push((index, value.trim().to_string()));
        } else {
            if named_seen {
                issues.push("positional arguments cannot follow named arguments".into());
            }
            while assigned.contains(&next_positional) && next_positional < parameters.len() {
                next_positional += 1;
            }
            let index = if next_positional < parameters.len() {
                let i = next_positional;
                next_positional += 1;
                i
            } else if let Some(i) = param_array {
                i
            } else {
                issues.push("too many positional arguments".into());
                continue;
            };
            if argument.trim().is_empty() {
                if !parameters[index].optional && !parameters[index].is_param_array {
                    issues.push(format!(
                        "required positional parameter '{}' is omitted",
                        parameters[index].name
                    ));
                }
                assigned.insert(index);
                continue;
            }
            if !assigned.insert(index) && Some(index) != param_array {
                issues.push(format!(
                    "parameter '{}' is supplied more than once",
                    parameters[index].name
                ));
                continue;
            }
            bindings.push((index, argument.clone()));
        }
    }
    (bindings, issues)
}

fn argument_binding_issue_severity(issues: &[String]) -> Severity {
    if issues.iter().any(|issue| {
        issue.starts_with("required positional parameter '") && issue.ends_with("' is omitted")
    }) {
        Severity::Error
    } else {
        Severity::Warning
    }
}

struct CallInputContext<'a> {
    project: &'a Project,
    module_index: usize,
    module: &'a Module,
    procedure: Option<String>,
}

fn append_argument_input_facts(
    context: CallInputContext<'_>,
    callee: &str,
    signature: (&[Parameter], &[(usize, String)]),
    transfer: &str,
    span: Span,
    out: &mut Vec<DataFlowFact>,
) {
    let (parameters, bindings) = signature;
    let input_scope = assignment_input_scope_for_procedure(
        context.project,
        context.module_index,
        context.module,
        context.procedure.as_deref(),
    );
    let mut param_array_slots = HashMap::<usize, usize>::new();
    for (parameter_index, actual) in bindings {
        let Some(parameter) = parameters.get(*parameter_index) else {
            continue;
        };
        let argument_slot_index = if parameter.is_param_array {
            let slot = param_array_slots.entry(*parameter_index).or_default();
            let index = *slot;
            *slot = slot.saturating_add(1);
            Some(index)
        } else {
            None
        };
        let inputs = argument_input_names_with_scope(actual, input_scope.as_ref());
        let target = format!("{callee}.{}", parameter.name);
        if !inputs.is_empty() || parameter.is_param_array {
            out.push(DataFlowFact {
                module: context.module.name.clone(),
                procedure: context.procedure.clone(),
                target: target.clone(),
                inputs,
                transfer: transfer.into(),
                argument_slot_index,
                value_expression: parameter.is_param_array.then(|| actual.trim().to_owned()),
                span,
                ..DataFlowFact::default()
            });
        }
        if let Some(input_scope) = input_scope.as_ref() {
            append_nested_function_return_argument_candidates(
                &context,
                &target,
                actual,
                input_scope,
                out,
            );
        }
    }
    append_optional_default_argument_facts(
        &context, callee, parameters, bindings, transfer, span, out,
    );
}

fn append_optional_default_argument_facts(
    context: &CallInputContext<'_>,
    callee: &str,
    parameters: &[Parameter],
    bindings: &[(usize, String)],
    call_transfer: &str,
    span: Span,
    out: &mut Vec<DataFlowFact>,
) {
    if !matches!(
        call_transfer,
        "procedure_argument_input_candidate"
            | "property_set_argument_candidate"
            | "default_member_argument_input_candidate"
    ) {
        return;
    }
    let Some((callee_module_name, callee_procedure_name)) = callee.split_once('.') else {
        return;
    };
    if callee_module_name.is_empty() || callee_procedure_name.is_empty() {
        return;
    }
    let Some((callee_module, callee_procedure)) =
        unique_project_procedure(context.project, callee_module_name, callee_procedure_name)
    else {
        return;
    };
    let callee_module_index = context
        .project
        .modules
        .iter()
        .position(|module| std::ptr::eq(module, callee_module))
        .unwrap_or(context.module_index);
    let supplied_parameters = bindings
        .iter()
        .map(|(parameter_index, _)| *parameter_index)
        .collect::<HashSet<_>>();

    for (parameter_index, parameter) in parameters.iter().enumerate() {
        if !parameter.optional || supplied_parameters.contains(&parameter_index) {
            continue;
        }
        let (transfer, value_expression) = if let Some(expression) = &parameter.default_value {
            (
                "optional_explicit_default_argument_candidate",
                Some(expression.clone()),
            )
        } else {
            match declared_parameter_type(
                context.project,
                callee_module_index,
                callee_module,
                parameter,
            )
            .as_deref()
            .map(canon)
            .as_deref()
            {
                Some("variant") => ("optional_variant_omission_error_448_candidate", None),
                Some(_) => ("optional_declared_type_default_candidate", None),
                None => ("optional_unresolved_default_candidate", None),
            }
        };
        let target = format!(
            "{}.{}.{}",
            callee_module.name, callee_procedure.name, parameter.name
        );
        if out.iter().any(|fact| {
            fact.module.eq_ignore_ascii_case(&context.module.name)
                && fact.procedure.as_deref().unwrap_or_default()
                    == context.procedure.as_deref().unwrap_or_default()
                && fact.span == span
                && fact.target.eq_ignore_ascii_case(&target)
                && fact.transfer == transfer
        }) {
            continue;
        }
        out.push(DataFlowFact {
            module: context.module.name.clone(),
            procedure: context.procedure.clone(),
            target,
            transfer: transfer.into(),
            value_expression,
            call_callee_module: Some(callee_module.name.clone()),
            call_callee_procedure: Some(callee_procedure.name.clone()),
            span,
            ..DataFlowFact::default()
        });
    }
}

fn assignment_input_scope_for_procedure(
    project: &Project,
    module_index: usize,
    module: &Module,
    procedure_name: Option<&str>,
) -> Option<AssignmentInputScope> {
    let procedure = module.procedures.iter().find(|procedure| {
        procedure_name.is_some_and(|name| procedure.name.eq_ignore_ascii_case(name))
    })?;
    Some(assignment_input_scope(
        project,
        module_index,
        module,
        procedure,
    ))
}

fn append_event_handler_argument_facts(
    project: &Project,
    handlers: &[String],
    event_arguments: &[String],
    caller_module: &Module,
    caller_procedure: Option<String>,
    span: Span,
    out: &mut Vec<DataFlowFact>,
) {
    let caller_module_index = project
        .modules
        .iter()
        .position(|module| std::ptr::eq(module, caller_module))
        .expect("caller module is selected from the analyzed project");
    let input_scope = assignment_input_scope_for_procedure(
        project,
        caller_module_index,
        caller_module,
        caller_procedure.as_deref(),
    );
    for handler_name in handlers {
        let Some((handler_module, handler)) = project.modules.iter().find_map(|module| {
            module.procedures.iter().find_map(|procedure| {
                let qualified = format!("{}.{}", module.name, procedure.name);
                (canon(&qualified) == canon(handler_name)).then_some((module, procedure))
            })
        }) else {
            continue;
        };
        for (parameter_index, actual) in event_arguments.iter().enumerate() {
            let Some(parameter) = handler.parameters.get(parameter_index) else {
                break;
            };
            let inputs = argument_input_names_with_scope(actual, input_scope.as_ref());
            if !inputs.is_empty() {
                out.push(DataFlowFact {
                    module: caller_module.name.clone(),
                    procedure: caller_procedure.clone(),
                    target: format!(
                        "{}.{}.{}",
                        handler_module.name, handler.name, parameter.name
                    ),
                    inputs,
                    transfer: "event_handler_argument_candidate".into(),
                    span,
                    ..DataFlowFact::default()
                });
            }
            if parameter.passing.eq_ignore_ascii_case("ByRef")
                && parameter_is_written(handler, &parameter.name)
                && is_assignable_argument(actual)
            {
                out.push(DataFlowFact {
                    module: caller_module.name.clone(),
                    procedure: caller_procedure.clone(),
                    target: actual.clone(),
                    inputs: vec![handler.name.clone(), parameter.name.clone()],
                    transfer: "event_handler_byref_write_candidate".into(),
                    span,
                    ..DataFlowFact::default()
                });
            }
        }
    }
}

fn argument_input_names(source: &str) -> Vec<String> {
    argument_input_names_with_scope(source, None)
}

fn argument_input_names_with_scope(
    source: &str,
    input_scope: Option<&AssignmentInputScope>,
) -> Vec<String> {
    let value = source
        .split_once(":=")
        .map(|(_, value)| value)
        .unwrap_or(source)
        .trim();
    let value = if value
        .get(..6)
        .is_some_and(|prefix| prefix.eq_ignore_ascii_case("ByVal "))
    {
        value.get(6..).unwrap_or(value).trim_start()
    } else {
        value
    };
    if let Some(input_scope) = input_scope
        && let Some(expression) = parse_expression_source(value)
    {
        return assignment_expression_input_names(&expression, input_scope);
    }
    let (tokens, _) = lex(value, 4096);
    let mut inputs = Vec::new();
    let mut seen = HashSet::new();
    for (index, token) in tokens.iter().enumerate() {
        if token.kind != TokenKind::Identifier
            || index > 0 && matches!(tokens[index - 1].text.as_str(), "." | "!")
            || is_keyword(&token.text)
            || intrinsic_names().contains(canon(&token.text).as_str())
        {
            continue;
        }
        if seen.insert(canon(&token.text)) {
            inputs.push(token.text.clone());
        }
    }
    inputs
}

fn nested_function_return_target<'a>(
    project: &'a Project,
    context: &CallInputContext<'a>,
    caller_procedure: &Procedure,
    input_scope: &AssignmentInputScope,
    callee: &Expr,
) -> Option<(&'a Module, &'a Procedure)> {
    let returns_value = |procedure: &Procedure| {
        procedure.kind.eq_ignore_ascii_case("Function")
            || procedure.kind.eq_ignore_ascii_case("Property Get")
    };
    match callee {
        Expr::Identifier(name, _) => {
            if input_scope.value_names.contains(&canon(name)) {
                return None;
            }
            let local = context
                .module
                .procedures
                .iter()
                .filter(|procedure| {
                    canon(&procedure.name) == canon(name) && returns_value(procedure)
                })
                .collect::<Vec<_>>();
            if local.len() == 1 {
                return Some((context.module, local[0]));
            }
            if !local.is_empty() {
                return None;
            }
            let mut visible = Vec::new();
            for module in &project.modules {
                if std::ptr::eq(module, context.module)
                    || !matches!(module.module_kind.as_deref(), Some("standard") | None)
                {
                    continue;
                }
                for procedure in &module.procedures {
                    if canon(&procedure.name) == canon(name)
                        && returns_value(procedure)
                        && (procedure.visibility.eq_ignore_ascii_case("public")
                            || procedure.visibility.eq_ignore_ascii_case("global"))
                    {
                        visible.push((module, procedure));
                    }
                }
            }
            if visible.len() == 1 {
                Some(visible[0])
            } else {
                None
            }
        }
        Expr::Member {
            object,
            member,
            access: MemberAccessKind::Dot,
            ..
        } => {
            if let Expr::Identifier(qualifier, _) = object.as_ref()
                && input_scope
                    .standard_module_names
                    .contains(&canon(qualifier))
                && !input_scope.local_value_names.contains(&canon(qualifier))
            {
                let modules = project
                    .modules
                    .iter()
                    .filter(|module| {
                        canon(&module.name) == canon(qualifier)
                            && matches!(module.module_kind.as_deref(), Some("standard") | None)
                    })
                    .collect::<Vec<_>>();
                if modules.len() != 1 {
                    return None;
                }
                let module = modules[0];
                let procedures = module
                    .procedures
                    .iter()
                    .filter(|procedure| {
                        canon(&procedure.name) == canon(member)
                            && returns_value(procedure)
                            && (procedure.visibility.eq_ignore_ascii_case("public")
                                || procedure.visibility.eq_ignore_ascii_case("global"))
                    })
                    .collect::<Vec<_>>();
                return if procedures.len() == 1 {
                    Some((module, procedures[0]))
                } else {
                    None
                };
            }
            let (owner, self_access) = crate::typecheck::member_owner(
                project,
                context.module_index,
                context.module,
                caller_procedure,
                object,
            )?;
            let module = project.modules.get(owner)?;
            let procedures = module
                .procedures
                .iter()
                .filter(|procedure| {
                    canon(&procedure.name) == canon(member)
                        && returns_value(procedure)
                        && (self_access
                            || owner == context.module_index
                            || !procedure.visibility.eq_ignore_ascii_case("private"))
                })
                .collect::<Vec<_>>();
            if procedures.len() == 1 {
                Some((module, procedures[0]))
            } else {
                None
            }
        }
        _ => None,
    }
}

fn append_nested_function_return_argument_candidates(
    context: &CallInputContext<'_>,
    target: &str,
    actual: &str,
    input_scope: &AssignmentInputScope,
    out: &mut Vec<DataFlowFact>,
) {
    let Some(procedure_name) = context.procedure.as_deref() else {
        return;
    };
    let Some(caller_procedure) = context
        .module
        .procedures
        .iter()
        .find(|procedure| procedure.name.eq_ignore_ascii_case(procedure_name))
    else {
        return;
    };
    let actual = actual
        .split_once(":=")
        .map(|(_, value)| value)
        .unwrap_or(actual)
        .trim();
    let actual = actual
        .get(..6)
        .filter(|prefix| prefix.eq_ignore_ascii_case("ByVal "))
        .and_then(|_| actual.get(6..))
        .unwrap_or(actual)
        .trim_start();
    let Some(expression) = parse_expression_source(actual) else {
        return;
    };

    let mut state = NestedFunctionReturnState {
        context,
        caller_procedure,
        target,
        input_scope,
        seen: HashSet::new(),
    };
    visit_nested_function_returns(&expression, actual, &mut state, out);
}

struct NestedFunctionReturnState<'a, 'context> {
    context: &'a CallInputContext<'context>,
    caller_procedure: &'a Procedure,
    target: &'a str,
    input_scope: &'a AssignmentInputScope,
    seen: HashSet<(usize, usize, String, String)>,
}

fn visit_nested_function_returns(
    expression: &Expr,
    source: &str,
    state: &mut NestedFunctionReturnState<'_, '_>,
    out: &mut Vec<DataFlowFact>,
) {
    match expression {
        Expr::Call { callee, args, span } => {
            if let Some((callee_module, callee_procedure)) = nested_function_return_target(
                state.context.project,
                state.context,
                state.caller_procedure,
                state.input_scope,
                callee,
            ) {
                let identity = (
                    span.start,
                    span.end,
                    canon(&callee_module.name),
                    canon(&callee_procedure.name),
                );
                if state.seen.insert(identity) {
                    let arguments = args
                        .iter()
                        .map(|argument| expression_source(source, argument))
                        .collect::<Vec<_>>();
                    let (bindings, issues) =
                        bind_arguments(&callee_procedure.parameters, &arguments, false);
                    let assigned = bindings
                        .iter()
                        .map(|(index, _)| *index)
                        .collect::<HashSet<_>>();
                    let missing_required =
                        callee_procedure
                            .parameters
                            .iter()
                            .enumerate()
                            .any(|(index, parameter)| {
                                !parameter.optional
                                    && !parameter.is_param_array
                                    && !assigned.contains(&index)
                            });
                    if issues.is_empty() && !missing_required {
                        let return_sources = out
                            .iter()
                            .filter(|fact| {
                                fact.module.eq_ignore_ascii_case(&callee_module.name)
                                    && fact.procedure.as_deref().is_some_and(|name| {
                                        name.eq_ignore_ascii_case(&callee_procedure.name)
                                    })
                                    && canon(&fact.target) == canon(&callee_procedure.name)
                                    && matches!(
                                        fact.transfer.as_str(),
                                        "assignment" | "object_assignment"
                                    )
                            })
                            .cloned()
                            .collect::<Vec<_>>();
                        if !return_sources.is_empty() {
                            let before = out.len();
                            append_function_return_facts(
                                state.context.project,
                                (
                                    state.context.module,
                                    Some(state.caller_procedure.name.clone()),
                                    state.target,
                                ),
                                (callee_module, callee_procedure),
                                (&bindings, &return_sources),
                                *span,
                                out,
                            );
                            for fact in &mut out[before..] {
                                if fact.transfer == "function_return_candidate" {
                                    fact.transfer =
                                        "nested_function_argument_return_candidate".into();
                                }
                            }
                        }
                    }
                }
            }
            visit_nested_function_returns(callee, source, state, out);
            for argument in args {
                visit_nested_function_returns(argument, source, state, out);
            }
        }
        Expr::Unary { value, .. }
        | Expr::Group(value, _)
        | Expr::Member { object: value, .. }
        | Expr::NamedArgument { value, .. }
        | Expr::TypeOfIs {
            expression: value, ..
        } => {
            visit_nested_function_returns(value, source, state, out);
        }
        Expr::Binary { left, right, .. } => {
            visit_nested_function_returns(left, source, state, out);
            visit_nested_function_returns(right, source, state, out);
        }
        Expr::Identifier(..) | Expr::Literal(..) | Expr::Unknown(..) => {}
    }
}

fn append_function_return_facts(
    project: &Project,
    caller: (&Module, Option<String>, &str),
    callee_context: (&Module, &Procedure),
    call: (&[(usize, String)], &[DataFlowFact]),
    span: Span,
    out: &mut Vec<DataFlowFact>,
) {
    let (caller_module, caller_procedure, caller_target) = caller;
    let (callee_module, callee) = callee_context;
    let (bindings, return_sources) = call;
    let caller_module_index = project
        .modules
        .iter()
        .position(|module| std::ptr::eq(module, caller_module))
        .expect("caller module is selected from the analyzed project");
    let caller_input_scope = assignment_input_scope_for_procedure(
        project,
        caller_module_index,
        caller_module,
        caller_procedure.as_deref(),
    );
    let mut actual_inputs: HashMap<usize, Vec<String>> = HashMap::new();
    for (parameter_index, argument) in bindings {
        actual_inputs
            .entry(*parameter_index)
            .or_default()
            .extend(argument_input_names_with_scope(
                argument,
                caller_input_scope.as_ref(),
            ));
    }
    let mut procedure_assignments = Vec::new();
    let callee_module_index = project
        .modules
        .iter()
        .position(|module| std::ptr::eq(module, callee_module))
        .expect("callee module is selected from the analyzed project");
    let assignment_scope =
        assignment_input_scope(project, callee_module_index, callee_module, callee);
    collect_assignments_in(
        callee_module,
        callee,
        &callee.statements,
        &assignment_scope,
        &mut procedure_assignments,
    );
    let mut local_call_results = HashSet::new();
    let intrinsics = intrinsic_names();
    collect_local_call_result_targets(
        callee,
        &callee.statements,
        &mut local_call_results,
        &intrinsics,
    );
    let mut local_sources: HashMap<String, Vec<Vec<String>>> = HashMap::new();
    for fact in &procedure_assignments {
        if matches!(
            fact.transfer.as_str(),
            "assignment" | "object_assignment" | "constant_initializer"
        ) && local_variable_declaration(&callee.statements, &fact.target).is_some()
        {
            local_sources
                .entry(canon(&fact.target))
                .or_default()
                .push(fact.inputs.clone());
        }
    }
    for return_source in return_sources {
        let mut inputs = Vec::new();
        let mut seen = HashSet::new();
        for source in &return_source.inputs {
            let mut visited = HashSet::new();
            let expansion = ReturnSourceExpansion {
                callee_module,
                callee,
                actual_inputs: &actual_inputs,
                local_sources: &local_sources,
                local_call_results: &local_call_results,
            };
            append_return_source_candidates(
                source,
                &expansion,
                &mut visited,
                &mut seen,
                &mut inputs,
                0,
            );
        }
        out.push(DataFlowFact {
            module: caller_module.name.clone(),
            procedure: caller_procedure.clone(),
            target: caller_target.to_owned(),
            inputs,
            transfer: "function_return_candidate".into(),
            argument_slot_index: None,
            value_expression: None,
            call_callee_module: Some(callee_module.name.clone()),
            call_callee_procedure: Some(callee.name.clone()),
            span,
        });
    }
}

struct ReturnSourceExpansion<'a> {
    callee_module: &'a Module,
    callee: &'a Procedure,
    actual_inputs: &'a HashMap<usize, Vec<String>>,
    local_sources: &'a HashMap<String, Vec<Vec<String>>>,
    local_call_results: &'a HashSet<String>,
}

fn append_return_source_candidates(
    source: &str,
    expansion: &ReturnSourceExpansion<'_>,
    visited: &mut HashSet<String>,
    seen: &mut HashSet<String>,
    output: &mut Vec<String>,
    depth: usize,
) {
    const MAX_RETURN_SOURCE_DEPTH: usize = 32;
    let callee = expansion.callee;
    let callee_module = expansion.callee_module;
    if let Some(parameter_index) = callee
        .parameters
        .iter()
        .position(|parameter| canon(&parameter.name) == canon(source))
    {
        if let Some(actuals) = expansion.actual_inputs.get(&parameter_index) {
            for actual in actuals {
                if seen.insert(canon(actual)) {
                    output.push(actual.clone());
                }
            }
        } else if !callee.parameters[parameter_index].optional {
            let unresolved = format!("{}.{}", callee.name, source);
            if seen.insert(canon(&unresolved)) {
                output.push(unresolved);
            }
        }
        return;
    }

    if source.contains('.') {
        // Preserve an already-qualified origin from a nested return summary
        // rather than prefixing the wrapper's module and changing its meaning.
        if seen.insert(canon(source)) {
            output.push(source.to_owned());
        }
        return;
    }

    let local = local_variable_declaration(&callee.statements, source).is_some();
    if local {
        let key = canon(source);
        if depth >= MAX_RETURN_SOURCE_DEPTH || !visited.insert(key.clone()) {
            let scoped = format!("{}.{}.{}", callee_module.name, callee.name, source);
            if seen.insert(canon(&scoped)) {
                output.push(scoped);
            }
            return;
        }
        if expansion.local_call_results.contains(&key) {
            let scoped = format!("{}.{}.{}", callee_module.name, callee.name, source);
            if seen.insert(canon(&scoped)) {
                output.push(scoped);
            }
            visited.remove(&key);
            return;
        }
        if let Some(definitions) = expansion.local_sources.get(&key) {
            let mut unique_definitions = Vec::<&Vec<String>>::new();
            for definition in definitions {
                if !unique_definitions.iter().any(|previous| {
                    previous.len() == definition.len()
                        && previous
                            .iter()
                            .zip(definition)
                            .all(|(left, right)| canon(left) == canon(right))
                }) {
                    unique_definitions.push(definition);
                }
            }
            if unique_definitions.len() == 1 {
                for input in unique_definitions[0] {
                    append_return_source_candidates(
                        input,
                        expansion,
                        visited,
                        seen,
                        output,
                        depth + 1,
                    );
                }
            } else {
                let scoped = format!("{}.{}.{}", callee_module.name, callee.name, source);
                if seen.insert(canon(&scoped)) {
                    output.push(scoped);
                }
            }
        } else {
            let scoped = format!("{}.{}.{}", callee_module.name, callee.name, source);
            if seen.insert(canon(&scoped)) {
                output.push(scoped);
            }
        }
        visited.remove(&key);
        return;
    }

    let qualified = if callee_module.declarations.iter().any(|declaration| {
        is_variable_declaration(declaration) && canon(&declaration.name) == canon(source)
    }) {
        format!("{}.{}", callee_module.name, source)
    } else {
        format!("{}.{}.{}", callee_module.name, callee.name, source)
    };
    if seen.insert(canon(&qualified)) {
        output.push(qualified);
    }
}

fn collect_local_call_result_targets(
    procedure: &Procedure,
    statements: &[Statement],
    targets: &mut HashSet<String>,
    intrinsics: &HashSet<&'static str>,
) {
    for statement in statements {
        if statement.kind == "assignment"
            && let (Some(Expr::Identifier(name, _)), Some(expression)) =
                (&statement.parsed_target, &statement.parsed_expression)
            && local_variable_declaration(&procedure.statements, name).is_some()
            && expression_contains_non_intrinsic_call(expression, intrinsics)
        {
            targets.insert(canon(name));
        }
        collect_local_call_result_targets(procedure, &statement.children, targets, intrinsics);
    }
}

fn expression_contains_non_intrinsic_call(
    expression: &Expr,
    intrinsics: &HashSet<&'static str>,
) -> bool {
    match expression {
        Expr::Call { callee, args, .. } => {
            let is_intrinsic = matches!(callee.as_ref(), Expr::Identifier(name, _) if intrinsics.contains(canon(name).as_str()));
            !is_intrinsic
                || expression_contains_non_intrinsic_call(callee, intrinsics)
                || args
                    .iter()
                    .any(|argument| expression_contains_non_intrinsic_call(argument, intrinsics))
        }
        Expr::Unary { value, .. } | Expr::Group(value, _) => {
            expression_contains_non_intrinsic_call(value, intrinsics)
        }
        Expr::Binary { left, right, .. } => {
            expression_contains_non_intrinsic_call(left, intrinsics)
                || expression_contains_non_intrinsic_call(right, intrinsics)
        }
        Expr::Member { object, .. } => expression_contains_non_intrinsic_call(object, intrinsics),
        Expr::NamedArgument { value, .. } => {
            expression_contains_non_intrinsic_call(value, intrinsics)
        }
        Expr::TypeOfIs { expression, .. } => {
            expression_contains_non_intrinsic_call(expression, intrinsics)
        }
        Expr::Identifier(..) | Expr::Literal(..) | Expr::Unknown(..) => false,
    }
}

type ReturnSummaryKey = (String, String, String);

/// Compose only unique local call-result summaries after every call has been
/// collected, so module order cannot change the candidate sources. This pass
/// does not merge CFG conditions or prove that caller and callee paths align.
fn compose_local_call_return_candidates(project: &Project, data_flow: &mut [DataFlowFact]) {
    const MAX_COMPOSITION_PASSES: usize = 32;
    let argument_inputs = call_argument_input_index(data_flow);
    for _ in 0..MAX_COMPOSITION_PASSES {
        let summaries = function_return_candidate_index(project, data_flow);
        let mut updates = Vec::new();
        for (index, fact) in data_flow.iter().enumerate() {
            if fact.transfer != "function_return_candidate" {
                continue;
            }
            let mut expanded_inputs = Vec::new();
            let mut seen = HashSet::new();
            let mut visited = HashSet::new();
            for input in &fact.inputs {
                if let Some(expanded) = expand_scoped_return_candidate_input(
                    input,
                    fact,
                    project,
                    &argument_inputs,
                    &summaries,
                    &mut visited,
                    0,
                ) {
                    for value in expanded {
                        if seen.insert(canon(&value)) {
                            expanded_inputs.push(value);
                        }
                    }
                } else if seen.insert(canon(input)) {
                    expanded_inputs.push(input.clone());
                }
            }
            if !input_lists_equivalent(&fact.inputs, &expanded_inputs) {
                updates.push((index, expanded_inputs));
            }
        }
        if updates.is_empty() {
            break;
        }
        for (index, inputs) in updates {
            data_flow[index].inputs = inputs;
        }
    }
}

type CallArgumentInputKey = (String, String, usize, usize, String);

fn call_argument_input_index(
    data_flow: &[DataFlowFact],
) -> HashMap<CallArgumentInputKey, Vec<Vec<String>>> {
    let mut index: HashMap<CallArgumentInputKey, Vec<Vec<String>>> = HashMap::new();
    for fact in data_flow.iter().filter(|fact| {
        fact.transfer.ends_with("argument_input_candidate") && fact.procedure.is_some()
    }) {
        let key = (
            canon(&fact.module),
            canon(fact.procedure.as_deref().unwrap_or_default()),
            fact.span.start,
            fact.span.end,
            canon(&fact.target),
        );
        insert_return_summary(&mut index, key, fact.inputs.clone());
    }
    index
}

fn function_return_candidate_index(
    project: &Project,
    data_flow: &[DataFlowFact],
) -> HashMap<ReturnSummaryKey, Vec<Vec<String>>> {
    let mut summaries: HashMap<ReturnSummaryKey, Vec<Vec<String>>> = HashMap::new();
    for fact in data_flow
        .iter()
        .filter(|fact| fact.transfer == "function_return_candidate")
    {
        let Some(procedure_name) = fact.procedure.as_deref() else {
            continue;
        };
        let Some((module, procedure)) =
            unique_project_procedure(project, &fact.module, procedure_name)
        else {
            continue;
        };
        if local_variable_declaration(&procedure.statements, &fact.target).is_some() {
            insert_return_summary(
                &mut summaries,
                (
                    canon(&module.name),
                    canon(&procedure.name),
                    canon(&fact.target),
                ),
                fact.inputs.clone(),
            );
        }
        if canon(&fact.target) == canon(&procedure.name)
            && let Some(callee_procedure) = fact.call_callee_procedure.as_deref()
            && local_variable_declaration(&procedure.statements, callee_procedure).is_none()
        {
            // The unqualified procedure name in a returned call expression is
            // retained as Module.Procedure.Callee until every call site has
            // been collected. This alias removes source-order dependence.
            insert_return_summary(
                &mut summaries,
                (
                    canon(&module.name),
                    canon(&procedure.name),
                    canon(callee_procedure),
                ),
                fact.inputs.clone(),
            );
        }
    }
    summaries
}

fn insert_return_summary<K: Eq + std::hash::Hash>(
    summaries: &mut HashMap<K, Vec<Vec<String>>>,
    key: K,
    inputs: Vec<String>,
) {
    let candidates = summaries.entry(key).or_default();
    if !candidates
        .iter()
        .any(|candidate| input_lists_equivalent(candidate, &inputs))
    {
        candidates.push(inputs);
    }
}

fn input_lists_equivalent(left: &[String], right: &[String]) -> bool {
    let mut left = left.iter().map(|value| canon(value)).collect::<Vec<_>>();
    let mut right = right.iter().map(|value| canon(value)).collect::<Vec<_>>();
    left.sort();
    right.sort();
    left == right
}

fn unique_project_procedure<'a>(
    project: &'a Project,
    module_name: &str,
    procedure_name: &str,
) -> Option<(&'a Module, &'a Procedure)> {
    let mut modules = project
        .modules
        .iter()
        .filter(|module| canon(&module.name) == canon(module_name));
    let module = modules.next()?;
    if modules.next().is_some() {
        return None;
    }
    let mut procedures = module
        .procedures
        .iter()
        .filter(|procedure| canon(&procedure.name) == canon(procedure_name));
    let procedure = procedures.next()?;
    procedures.next().is_none().then_some((module, procedure))
}

fn expand_scoped_return_candidate_input(
    input: &str,
    return_candidate: &DataFlowFact,
    project: &Project,
    argument_inputs: &HashMap<CallArgumentInputKey, Vec<Vec<String>>>,
    summaries: &HashMap<ReturnSummaryKey, Vec<Vec<String>>>,
    visited: &mut HashSet<ReturnSummaryKey>,
    depth: usize,
) -> Option<Vec<String>> {
    const MAX_COMPOSITION_DEPTH: usize = 32;
    let mut parts = input.split('.');
    let (module_name, procedure_name, symbol_name) = (parts.next()?, parts.next()?, parts.next()?);
    if parts.next().is_some()
        || return_candidate
            .call_callee_module
            .as_deref()
            .is_none_or(|module| canon(module) != canon(module_name))
        || return_candidate
            .call_callee_procedure
            .as_deref()
            .is_none_or(|procedure| canon(procedure) != canon(procedure_name))
    {
        return None;
    }
    let key = (
        canon(module_name),
        canon(procedure_name),
        canon(symbol_name),
    );
    if depth >= MAX_COMPOSITION_DEPTH || !visited.insert(key.clone()) {
        return None;
    }
    let Some(candidates) = summaries.get(&key) else {
        visited.remove(&key);
        return None;
    };
    if candidates.len() != 1 {
        visited.remove(&key);
        return None;
    }
    let Some((scope_module, scope_procedure)) =
        unique_project_procedure(project, module_name, procedure_name)
    else {
        visited.remove(&key);
        return None;
    };
    let mut expanded = Vec::new();
    let mut seen = HashSet::new();
    for source in &candidates[0] {
        if let Some(parameter) = scope_procedure
            .parameters
            .iter()
            .find(|parameter| canon(&parameter.name) == canon(source))
        {
            let Some(actuals) = call_argument_inputs_for_parameter(
                return_candidate,
                &scope_module.name,
                &scope_procedure.name,
                &parameter.name,
                argument_inputs,
            ) else {
                visited.remove(&key);
                return None;
            };
            for actual in actuals {
                if seen.insert(canon(&actual)) {
                    expanded.push(actual);
                }
            }
        } else if let Some(nested) = expand_scoped_return_candidate_input(
            source,
            return_candidate,
            project,
            argument_inputs,
            summaries,
            visited,
            depth + 1,
        ) {
            for value in nested {
                if seen.insert(canon(&value)) {
                    expanded.push(value);
                }
            }
        } else if seen.insert(canon(source)) {
            expanded.push(source.clone());
        }
    }
    visited.remove(&key);
    Some(expanded)
}

fn call_argument_inputs_for_parameter(
    return_candidate: &DataFlowFact,
    callee_module: &str,
    callee_procedure: &str,
    parameter: &str,
    argument_inputs: &HashMap<CallArgumentInputKey, Vec<Vec<String>>>,
) -> Option<Vec<String>> {
    let expected_target = format!("{callee_module}.{callee_procedure}.{parameter}");
    let key = (
        canon(&return_candidate.module),
        canon(return_candidate.procedure.as_deref().unwrap_or_default()),
        return_candidate.span.start,
        return_candidate.span.end,
        canon(&expected_target),
    );
    let candidates = argument_inputs.get(&key)?;
    if candidates.len() != 1 {
        return None;
    }
    candidates.first().cloned()
}

type WrittenParameterKey = (String, String, String);

#[derive(Clone)]
struct ByRefCallEdge {
    caller_module: String,
    caller_procedure: Option<String>,
    callee_module: String,
    callee_procedure: String,
    parameter: String,
    actual: String,
    span: Span,
    caller_parameter: Option<WrittenParameterKey>,
}

/// Propagate known in-project ByRef writes backwards across argument bindings.
/// A parameter becomes a write source only when its body writes directly or
/// a nested ByRef call already marks the actual as a write candidate. This
/// pass preserves each call site and stops at ByVal and temporary arguments.
fn compose_transitive_byref_write_candidates(
    project: &Project,
    calls: &[CallFact],
    data_flow: &mut Vec<DataFlowFact>,
) {
    let mut calls_by_site: HashMap<(String, String, usize, usize, String), Vec<&CallFact>> =
        HashMap::new();
    for call in calls {
        calls_by_site
            .entry((
                canon(&call.module),
                canon(call.procedure.as_deref().unwrap_or_default()),
                call.span.start,
                call.span.end,
                canon(&call.target),
            ))
            .or_default()
            .push(call);
    }

    let argument_facts = data_flow
        .iter()
        .filter(|fact| {
            matches!(
                fact.transfer.as_str(),
                "procedure_argument_input_candidate"
                    | "default_member_argument_input_candidate"
                    | "property_set_argument_candidate"
            )
        })
        .cloned()
        .collect::<Vec<_>>();
    let mut incoming: HashMap<WrittenParameterKey, Vec<ByRefCallEdge>> = HashMap::new();
    let mut seen_edges = HashSet::new();
    for fact in &argument_facts {
        let mut target_parts = fact.target.split('.');
        let (Some(callee_module_name), Some(callee_procedure_name), Some(parameter_name)) = (
            target_parts.next(),
            target_parts.next(),
            target_parts.next(),
        ) else {
            continue;
        };
        if target_parts.next().is_some() {
            continue;
        }
        let Some((callee_module, callee)) =
            unique_project_procedure(project, callee_module_name, callee_procedure_name)
        else {
            continue;
        };
        let matching_parameters = callee
            .parameters
            .iter()
            .enumerate()
            .filter(|(_, parameter)| canon(&parameter.name) == canon(parameter_name))
            .collect::<Vec<_>>();
        let [(parameter_index, parameter)] = matching_parameters.as_slice() else {
            continue;
        };
        if !parameter_is_effectively_byref(callee, *parameter_index, parameter) {
            continue;
        }
        let call_key = (
            canon(&fact.module),
            canon(fact.procedure.as_deref().unwrap_or_default()),
            fact.span.start,
            fact.span.end,
            canon(&callee.name),
        );
        let Some([call]) = calls_by_site
            .get(&call_key)
            .map(|matches| matches.as_slice())
        else {
            continue;
        };
        let (bindings, _) = if matches!(
            callee.kind.to_ascii_lowercase().as_str(),
            "property let" | "property set"
        ) {
            bind_property_setter_arguments(&callee.parameters, &call.arguments)
        } else {
            bind_arguments(&callee.parameters, &call.arguments, false)
        };
        let Some(actual) = bindings
            .into_iter()
            .find(|(index, _)| index == parameter_index)
            .map(|(_, actual)| actual)
        else {
            continue;
        };
        if !is_assignable_argument(&actual) {
            continue;
        }

        let caller_parameter = fact.procedure.as_deref().and_then(|caller_procedure_name| {
            let (_, caller_procedure) =
                unique_project_procedure(project, &fact.module, caller_procedure_name)?;
            let target_name = statement_declared_target(&actual)?;
            let matching = caller_procedure
                .parameters
                .iter()
                .enumerate()
                .filter(|(_, candidate)| canon(&candidate.name) == canon(&target_name))
                .collect::<Vec<_>>();
            let [(caller_parameter_index, caller_parameter)] = matching.as_slice() else {
                return None;
            };
            parameter_is_effectively_byref(
                caller_procedure,
                *caller_parameter_index,
                caller_parameter,
            )
            .then(|| {
                (
                    canon(&fact.module),
                    canon(caller_procedure_name),
                    canon(&caller_parameter.name),
                )
            })
        });
        let edge = ByRefCallEdge {
            caller_module: fact.module.clone(),
            caller_procedure: fact.procedure.clone(),
            callee_module: callee_module.name.clone(),
            callee_procedure: callee.name.clone(),
            parameter: parameter.name.clone(),
            actual: actual.clone(),
            span: fact.span,
            caller_parameter,
        };
        let edge_identity = (
            canon(&edge.caller_module),
            canon(edge.caller_procedure.as_deref().unwrap_or_default()),
            edge.span.start,
            edge.span.end,
            canon(&edge.callee_module),
            canon(&edge.callee_procedure),
            canon(&edge.parameter),
            canon(&edge.actual),
        );
        if seen_edges.insert(edge_identity) {
            incoming
                .entry((
                    canon(&callee_module.name),
                    canon(&callee.name),
                    canon(&parameter.name),
                ))
                .or_default()
                .push(edge);
        }
    }

    let mut written = HashSet::<WrittenParameterKey>::new();
    for module in &project.modules {
        for procedure in &module.procedures {
            for (parameter_index, parameter) in procedure.parameters.iter().enumerate() {
                if !parameter_is_effectively_byref(procedure, parameter_index, parameter) {
                    continue;
                }
                let key = (
                    canon(&module.name),
                    canon(&procedure.name),
                    canon(&parameter.name),
                );
                let direct_write = parameter_is_written(procedure, &parameter.name)
                    || data_flow.iter().any(|fact| {
                        fact.module == module.name
                            && fact.procedure.as_deref() == Some(&procedure.name)
                            && fact.transfer == "file_read_candidate"
                            && statement_declared_target(&fact.target)
                                .is_some_and(|target| canon(&target) == canon(&parameter.name))
                    });
                let existing_write = data_flow.iter().any(|fact| {
                    fact.module == module.name
                        && fact.procedure.as_deref() == Some(&procedure.name)
                        && matches!(
                            fact.transfer.as_str(),
                            "byref_argument_write"
                                | "event_handler_byref_write_candidate"
                                | "default_member_byref_write_candidate"
                        )
                        && statement_declared_target(&fact.target)
                            .is_some_and(|target| canon(&target) == canon(&parameter.name))
                });
                if direct_write || existing_write {
                    written.insert(key);
                }
            }
        }
    }

    let mut write_identities = data_flow
        .iter()
        .filter(|fact| fact.transfer == "byref_argument_write")
        .map(byref_write_identity)
        .collect::<HashSet<_>>();
    let mut pending = written.iter().cloned().collect::<VecDeque<_>>();
    let mut new_facts = Vec::new();
    while let Some(mutated_parameter) = pending.pop_front() {
        let Some(edges) = incoming.get(&mutated_parameter) else {
            continue;
        };
        for edge in edges {
            let fact = DataFlowFact {
                module: edge.caller_module.clone(),
                procedure: edge.caller_procedure.clone(),
                target: edge.actual.clone(),
                inputs: vec![edge.callee_procedure.clone(), edge.parameter.clone()],
                transfer: "byref_argument_write".into(),
                argument_slot_index: None,
                value_expression: None,
                call_callee_module: Some(edge.callee_module.clone()),
                call_callee_procedure: Some(edge.callee_procedure.clone()),
                span: edge.span,
            };
            if write_identities.insert(byref_write_identity(&fact)) {
                new_facts.push(fact);
            }
            if let Some(caller_parameter) = &edge.caller_parameter
                && written.insert(caller_parameter.clone())
            {
                pending.push_back(caller_parameter.clone());
            }
        }
    }
    data_flow.extend(new_facts);
}

fn byref_write_identity(
    fact: &DataFlowFact,
) -> (
    String,
    String,
    String,
    usize,
    usize,
    String,
    String,
    Vec<String>,
) {
    (
        canon(&fact.module),
        canon(fact.procedure.as_deref().unwrap_or_default()),
        canon(&fact.target),
        fact.span.start,
        fact.span.end,
        canon(fact.call_callee_module.as_deref().unwrap_or_default()),
        canon(fact.call_callee_procedure.as_deref().unwrap_or_default()),
        fact.inputs.iter().map(|input| canon(input)).collect(),
    )
}

fn call_assignment_target(tokens: &[Token], at: usize, equal: usize) -> Option<String> {
    let mut start = at;
    while start > 0 && tokens[start - 1].kind != TokenKind::Newline && tokens[start - 1].text != ":"
    {
        start -= 1;
    }
    let mut depth = 0i32;
    let mut statement_start = start;
    for (index, token) in tokens.iter().enumerate().take(equal).skip(start) {
        match token.text.as_str() {
            "(" | "[" => depth += 1,
            ")" | "]" => depth -= 1,
            _ => {}
        }
        if depth == 0
            && token.kind == TokenKind::Identifier
            && matches!(canon(&token.text).as_str(), "then" | "else")
        {
            statement_start = index + 1;
        }
    }
    assignment_lhs_name(&render_call_argument(&tokens[statement_start..=equal]))
}

fn diagnose_byval_array_arguments(
    parameters: &[Parameter],
    bindings: &[(usize, String)],
    module: &Module,
    procedure: Option<&str>,
    source: &str,
    span: Span,
    diagnostics: &mut Vec<Diagnostic>,
) {
    for (parameter_index, argument) in bindings {
        let Some(parameter) = parameters.get(*parameter_index) else {
            continue;
        };
        if parameter.is_param_array
            || !parameter.passing.eq_ignore_ascii_case("ByVal")
            || !is_declared_array_argument(module, procedure, argument)
        {
            continue;
        }
        diagnostics.push(Diagnostic {
            code: "VBA2056",
            severity: Severity::Error,
            message: format!(
                "whole array argument '{}' is passed to ByVal parameter '{}'; VBA arrays must be passed ByRef unless explicitly copied",
                argument, parameter.name
            ),
            source: source.into(),
            span,
        });
    }
}

#[derive(Clone, Copy)]
struct CallTypeContext<'a> {
    project: &'a Project,
    caller_module_index: usize,
    caller_module: &'a Module,
    caller_procedure: Option<&'a str>,
    callee_module: &'a Module,
    callee_name: &'a str,
    callee_kind: &'a str,
    source: &'a str,
    host_profile: HostProfile,
    span: Span,
}

fn diagnose_call_argument_type_mismatches(
    call: CallTypeContext<'_>,
    parameters: &[Parameter],
    bindings: &[(usize, String)],
    diagnostics: &mut Vec<Diagnostic>,
) {
    let property_value_parameter = matches!(
        call.callee_kind.to_ascii_lowercase().as_str(),
        "property let" | "property set"
    );
    let caller_procedure = call.caller_procedure.and_then(|name| {
        call.caller_module
            .procedures
            .iter()
            .find(|procedure| procedure.name.eq_ignore_ascii_case(name))
    });
    let callee_module_index = call
        .project
        .modules
        .iter()
        .position(|module| std::ptr::eq(module, call.callee_module))
        .unwrap_or(call.caller_module_index);
    for (parameter_index, argument) in bindings {
        let Some(parameter) = parameters.get(*parameter_index) else {
            continue;
        };
        if parameter.is_param_array {
            continue;
        }
        let Some(formal_type) = declared_parameter_type(
            call.project,
            callee_module_index,
            call.callee_module,
            parameter,
        ) else {
            continue;
        };
        let property_value = property_value_parameter && *parameter_index + 1 == parameters.len();
        let by_ref = parameter.passing.eq_ignore_ascii_case("ByRef") && !property_value;
        let by_val = parameter.passing.eq_ignore_ascii_case("ByVal") || property_value;
        if !by_ref && !by_val {
            continue;
        }
        if parameter.is_array && !by_ref {
            continue;
        }
        let mut argument_expression = argument
            .split_once(":=")
            .map(|(_, expression)| expression.trim())
            .unwrap_or(argument.trim())
            .to_owned();
        if argument_expression
            .get(..6)
            .is_some_and(|prefix| prefix.eq_ignore_ascii_case("byval "))
        {
            argument_expression = argument_expression[6..].trim().to_owned();
        }
        let argument_name = simple_array_target_name(&argument_expression).filter(|name| {
            !name.eq_ignore_ascii_case("Nothing") && !name.eq_ignore_ascii_case("Null")
        });
        if by_ref && let Some(argument_name) = argument_name.as_deref() {
            let Some(caller_procedure) = caller_procedure else {
                continue;
            };
            let Some(actual_info) =
                resolve_array_target(call.caller_module, caller_procedure, argument_name)
            else {
                continue;
            };
            if actual_info.is_constant || !actual_info.type_is_known {
                continue;
            }
            if parameter.is_array && actual_info.is_variant {
                // A Variant can contain an array of a runtime-selected rank
                // and element type, so its actual array shape is not known.
                continue;
            }
            if parameter.is_array != actual_info.is_array {
                if actual_info.is_variant && !parameter.is_array {
                    continue;
                }
                diagnostics.push(Diagnostic {
                    code: "VBA2085",
                    severity: Severity::Error,
                    message: if parameter.is_array {
                        format!(
                            "ByRef argument '{}' is scalar, but parameter '{}' of '{}' requires an array",
                            argument_name, parameter.name, call.callee_name
                        )
                    } else {
                        format!(
                            "ByRef argument '{}' is an array, but parameter '{}' of '{}' is scalar",
                            argument_name, parameter.name, call.callee_name
                        )
                    },
                    source: call.source.into(),
                    span: call.span,
                });
                continue;
            }
            if parameter.is_array && actual_info.is_array {
                if !actual_info.is_param_array
                    && let Some(actual_type) = declared_symbol_type(
                        call.project,
                        call.caller_module_index,
                        call.caller_module,
                        Some(&caller_procedure.name),
                        argument_name,
                    )
                    && let (Some(formal_identity), Some(actual_identity)) = (
                        byref_array_element_type_identity(
                            call.project,
                            callee_module_index,
                            call.callee_module,
                            None,
                            &formal_type,
                        ),
                        byref_array_element_type_identity(
                            call.project,
                            call.caller_module_index,
                            call.caller_module,
                            Some(caller_procedure),
                            &actual_type,
                        ),
                    )
                    && formal_identity != actual_identity
                {
                    diagnostics.push(Diagnostic {
                        code: "VBA2085",
                        severity: Severity::Error,
                        message: format!(
                            "ByRef array argument '{}' has element type {}, but parameter '{}' of '{}' requires an exact match to {}",
                            argument_name, actual_type, parameter.name, call.callee_name, formal_type
                        ),
                        source: call.source.into(),
                        span: call.span,
                    });
                }
                // Array rank is unresolved for an unsized formal array; its
                // syntax does not provide a static dimension contract here.
                continue;
            }
            if !parameter.is_array
                && !actual_info.is_array
                && let Some(actual_type) = declared_symbol_type(
                    call.project,
                    call.caller_module_index,
                    call.caller_module,
                    Some(&caller_procedure.name),
                    argument_name,
                )
                && let Some(matches) = fixed_string_byref_types_match(
                    call.project,
                    TypeResolutionContext {
                        module_index: callee_module_index,
                        module: call.callee_module,
                        procedure: None,
                    },
                    &formal_type,
                    TypeResolutionContext {
                        module_index: call.caller_module_index,
                        module: call.caller_module,
                        procedure: Some(caller_procedure),
                    },
                    &actual_type,
                )
            {
                if !matches {
                    diagnostics.push(Diagnostic {
                        code: "VBA2085",
                        severity: Severity::Error,
                        message: format!(
                            "ByRef argument '{}' has declared type {}, but parameter '{}' of '{}' requires an exact match to {}",
                            argument_name, actual_type, parameter.name, call.callee_name, formal_type
                        ),
                        source: call.source.into(),
                        span: call.span,
                    });
                }
                continue;
            }
            if crate::typecheck::user_type_owner_index(
                call.project,
                callee_module_index,
                &formal_type,
            )
            .is_some()
            {
                if let Some(actual_type) = declared_symbol_type(
                    call.project,
                    call.caller_module_index,
                    call.caller_module,
                    Some(&caller_procedure.name),
                    argument_name,
                ) && let (Some(formal_identity), Some(actual_identity)) = (
                    byref_array_element_type_identity(
                        call.project,
                        callee_module_index,
                        call.callee_module,
                        None,
                        &formal_type,
                    ),
                    byref_array_element_type_identity(
                        call.project,
                        call.caller_module_index,
                        call.caller_module,
                        Some(caller_procedure),
                        &actual_type,
                    ),
                ) && formal_identity != actual_identity
                {
                    diagnostics.push(Diagnostic {
                        code: "VBA2085",
                        severity: Severity::Error,
                        message: format!(
                            "ByRef argument '{}' has declared type {}, but parameter '{}' of '{}' requires an exact match to {}",
                            argument_name, actual_type, parameter.name, call.callee_name, formal_type
                        ),
                        source: call.source.into(),
                        span: call.span,
                    });
                }
                continue;
            }
            if is_object_parameter_type(call.project, &formal_type, call.host_profile) {
                if let Some(actual_type) = declared_symbol_type(
                    call.project,
                    call.caller_module_index,
                    call.caller_module,
                    Some(&caller_procedure.name),
                    argument_name,
                ) && object_argument_compatibility(
                    call.project,
                    call.caller_module_index,
                    call.caller_module,
                    &actual_type,
                    call.host_profile,
                ) == Some(false)
                {
                    push_object_argument_type_diagnostic(
                        call,
                        parameter,
                        &argument_expression,
                        &actual_type,
                        &formal_type,
                        diagnostics,
                    );
                }
                continue;
            }
            if !is_builtin_byref_scalar_type(&formal_type) {
                continue;
            }
            let Some(actual_type) = declared_symbol_type(
                call.project,
                call.caller_module_index,
                call.caller_module,
                Some(&caller_procedure.name),
                argument_name,
            ) else {
                continue;
            };
            if !actual_type.eq_ignore_ascii_case(&formal_type) {
                diagnostics.push(Diagnostic {
                    code: "VBA2085",
                    severity: Severity::Error,
                    message: format!(
                        "ByRef argument '{}' has declared type {}, but parameter '{}' of '{}' requires an exact match to {}",
                        argument_name, actual_type, parameter.name, call.callee_name, formal_type
                    ),
                    source: call.source.into(),
                    span: call.span,
                });
            }
            continue;
        }
        if !by_val && by_ref && argument_name.is_some() {
            continue;
        }
        if argument_name.as_deref().is_some_and(|name| {
            is_declared_array_argument(call.caller_module, call.caller_procedure, name)
        }) {
            continue;
        }
        let actual_type = argument_name
            .as_deref()
            .and_then(|name| {
                declared_symbol_type(
                    call.project,
                    call.caller_module_index,
                    call.caller_module,
                    call.caller_procedure,
                    name,
                )
            })
            .or_else(|| {
                infer_expression_type(
                    call.project,
                    call.caller_module_index,
                    call.caller_module,
                    call.caller_procedure?,
                    &argument_expression,
                    call.host_profile,
                )
            });
        let explicit_null_argument = parse_expression_source(&argument_expression)
            .is_some_and(|expression| crate::typecheck::is_explicit_null_expression(&expression));
        if explicit_null_argument
            && let Some(error_number) = null_call_argument_runtime_error_number(
                call.project,
                callee_module_index,
                call.callee_module,
                parameter,
                &formal_type,
                call.host_profile,
            )
        {
            diagnostics.push(Diagnostic {
                code: "VBA2131",
                severity: Severity::Warning,
                message: format!(
                    "Passing Null to parameter '{}' of '{}' can raise runtime error {error_number}",
                    parameter.name, call.callee_name
                ),
                source: call.source.into(),
                span: call.span,
            });
            continue;
        }
        let explicit_nothing_argument =
            parse_expression_source(&argument_expression).is_some_and(|expression| {
                crate::typecheck::is_explicit_nothing_expression(&expression)
            });
        if explicit_nothing_argument
            && nothing_call_argument_may_raise_error91(
                call.project,
                callee_module_index,
                call.callee_module,
                parameter,
                &formal_type,
                call.host_profile,
            )
        {
            diagnostics.push(Diagnostic {
                code: "VBA2128",
                severity: Severity::Warning,
                message: format!(
                    "Passing Nothing to parameter '{}' of '{}' can raise runtime error 91",
                    parameter.name, call.callee_name
                ),
                source: call.source.into(),
                span: call.span,
            });
            continue;
        }
        if by_val
            && parse_expression_source(&argument_expression).is_some_and(|expression| {
                crate::typecheck::string_literal_let_coercion_error_13(&expression, &formal_type)
            })
        {
            diagnostics.push(Diagnostic {
                code: "VBA2135",
                severity: Severity::Warning,
                message: format!(
                    "String argument for parameter '{}' of '{}' can raise runtime error 13 during Let-coercion",
                    parameter.name, call.callee_name
                ),
                source: call.source.into(),
                span: call.span,
            });
            continue;
        }
        if by_val
            && canon(&formal_type) != "variant"
            && !is_object_parameter_type(call.project, &formal_type, call.host_profile)
            && let Some(actual_type) = actual_type.as_deref()
            && crate::typecheck::class_default_member_let_coercion_invalid(
                call.project,
                call.caller_module_index,
                call.caller_module,
                actual_type,
                callee_module_index,
                call.callee_module,
                &formal_type,
                call.host_profile,
            ) == Some(true)
        {
            diagnostics.push(Diagnostic {
                code: "VBA2132",
                severity: Severity::Error,
                message: format!(
                    "ByVal argument '{}' of '{}' has no default member value that can be Let-coerced to parameter '{}' of type {}",
                    argument_expression, call.callee_name, parameter.name, formal_type
                ),
                source: call.source.into(),
                span: call.span,
            });
            continue;
        }
        if let Some(actual_type) = actual_type.as_deref()
            && byval_udt_coercion_invalid(
                call.project,
                TypeResolutionContext {
                    module_index: callee_module_index,
                    module: call.callee_module,
                    procedure: None,
                },
                &formal_type,
                TypeResolutionContext {
                    module_index: call.caller_module_index,
                    module: call.caller_module,
                    procedure: caller_procedure,
                },
                actual_type,
                call.host_profile,
            ) == Some(true)
        {
            diagnostics.push(Diagnostic {
                code: "VBA2127",
                severity: Severity::Error,
                message: format!(
                    "Argument '{}' with declared type {} cannot be Let-coerced to parameter '{}' of '{}' declared as {}",
                    argument_expression, actual_type, parameter.name, call.callee_name, formal_type
                ),
                source: call.source.into(),
                span: call.span,
            });
            continue;
        }
        if is_object_parameter_type(call.project, &formal_type, call.host_profile)
            && let Some(actual_type) = actual_type.as_deref()
            && object_argument_compatibility(
                call.project,
                call.caller_module_index,
                call.caller_module,
                actual_type,
                call.host_profile,
            ) == Some(false)
        {
            push_object_argument_type_diagnostic(
                call,
                parameter,
                &argument_expression,
                actual_type,
                &formal_type,
                diagnostics,
            );
            continue;
        }
        if matches!(
            canon(&formal_type).as_str(),
            "variant" | "longlong" | "longptr"
        ) {
            continue;
        }
        if actual_type.as_deref() == Some("LongLong") {
            diagnostics.push(Diagnostic {
                code: "VBA2086",
                severity: Severity::Error,
                message: format!(
                    "ByVal argument '{}' of '{}' has type LongLong, which cannot be implicitly Let-coerced to parameter '{}' of type {}",
                    argument_expression, call.callee_name, parameter.name, formal_type
                ),
                source: call.source.into(),
                span: call.span,
            });
        }
    }
}

#[derive(Clone, Copy)]
struct TypeResolutionContext<'a> {
    module_index: usize,
    module: &'a Module,
    procedure: Option<&'a Procedure>,
}

fn fixed_string_byref_types_match(
    project: &Project,
    formal_context: TypeResolutionContext<'_>,
    formal_type: &str,
    actual_context: TypeResolutionContext<'_>,
    actual_type: &str,
) -> Option<bool> {
    let formal_is_fixed = is_fixed_length_string_type(formal_type);
    let actual_is_fixed = is_fixed_length_string_type(actual_type);
    if !formal_is_fixed && !actual_is_fixed {
        return None;
    }
    if formal_is_fixed != actual_is_fixed {
        return Some(false);
    }
    if fixed_length_string_type_error(formal_type).is_some()
        || fixed_length_string_type_error(actual_type).is_some()
    {
        return None;
    }
    let formal_size = fixed_length_string_declared_size(
        project,
        formal_context.module_index,
        formal_context.module,
        formal_context.procedure,
        formal_type,
    )?;
    let actual_size = fixed_length_string_declared_size(
        project,
        actual_context.module_index,
        actual_context.module,
        actual_context.procedure,
        actual_type,
    )?;
    Some(formal_size == actual_size)
}

fn is_fixed_length_string_type(type_name: &str) -> bool {
    let normalized = type_name
        .chars()
        .filter(|character| !character.is_whitespace())
        .collect::<String>()
        .to_ascii_lowercase();
    normalized.starts_with("string*")
}

fn fixed_length_string_declared_size(
    project: &Project,
    module_index: usize,
    module: &Module,
    procedure: Option<&Procedure>,
    type_name: &str,
) -> Option<i64> {
    let normalized = type_name
        .chars()
        .filter(|character| !character.is_whitespace())
        .collect::<String>()
        .to_ascii_lowercase();
    if let Some(size) = normalized
        .strip_prefix("string*")
        .and_then(parse_fixed_string_integer_token)
    {
        return (1..=65_526).contains(&size).then_some(size);
    }
    let constant_name = fixed_length_string_constant_name(type_name)?;
    let (constant_module_index, constant_module, constant) = resolve_fixed_length_string_constant(
        project,
        module_index,
        module,
        procedure,
        &constant_name,
    )?;
    let constant_procedure = procedure.filter(|candidate| {
        constant_module_index == module_index
            && local_variable_declaration(&candidate.statements, &constant.name)
                .is_some_and(|local| std::ptr::eq(local, constant))
    });
    fixed_string_constant_length(
        project,
        constant_module_index,
        constant_module,
        constant_procedure,
        constant,
    )
    .filter(|size| (1..=65_526).contains(size))
}

fn is_builtin_byref_scalar_type(type_name: &str) -> bool {
    matches!(
        canon(type_name).as_str(),
        "boolean"
            | "byte"
            | "integer"
            | "long"
            | "longlong"
            | "currency"
            | "single"
            | "double"
            | "date"
            | "string"
    )
}

fn is_object_parameter_type(project: &Project, type_name: &str, host_profile: HostProfile) -> bool {
    let key = canon(type_name);
    key == "object"
        || crate::typecheck::class_type_owner_index(project, type_name).is_some()
        || (host_profile == HostProfile::Excel && excel::is_known_type(type_name))
}

/// `Some(true/false)` describes statically known object compatibility. Unknown
/// referenced or host types remain `None` and do not produce a hard finding.
fn object_argument_compatibility(
    project: &Project,
    module_index: usize,
    module: &Module,
    type_name: &str,
    host_profile: HostProfile,
) -> Option<bool> {
    let effective =
        crate::typecheck::effective_project_type_name(project, module_index, module, type_name);
    let key = canon(&effective);
    if matches!(key.as_str(), "object" | "variant" | "nothing")
        || crate::typecheck::class_type_owner_index(project, &effective).is_some()
        || (host_profile == HostProfile::Excel && excel::is_known_type(&effective))
    {
        return Some(true);
    }
    if matches!(
        key.as_str(),
        "boolean"
            | "byte"
            | "integer"
            | "long"
            | "longlong"
            | "longptr"
            | "currency"
            | "single"
            | "double"
            | "date"
            | "string"
            | "decimal"
    ) || key.starts_with("string *")
        || crate::typecheck::user_type_owner_index(project, module_index, &effective).is_some()
    {
        return Some(false);
    }
    None
}

fn nothing_call_argument_may_raise_error91(
    project: &Project,
    formal_module_index: usize,
    formal_module: &Module,
    parameter: &Parameter,
    formal_type: &str,
    host_profile: HostProfile,
) -> bool {
    if parameter.is_array {
        return true;
    }
    if canon(formal_type) == "variant"
        || is_object_parameter_type(project, formal_type, host_profile)
    {
        return false;
    }
    crate::typecheck::user_type_owner_index(project, formal_module_index, formal_type).is_some()
        || crate::typecheck::known_non_udt_type(
            project,
            formal_module_index,
            formal_module,
            formal_type,
            host_profile,
        )
}

fn null_call_argument_runtime_error_number(
    project: &Project,
    formal_module_index: usize,
    formal_module: &Module,
    parameter: &Parameter,
    formal_type: &str,
    host_profile: HostProfile,
) -> Option<u8> {
    if parameter.is_array {
        return Some(13);
    }
    if canon(formal_type) == "variant" {
        return None;
    }
    if crate::typecheck::user_type_owner_index(project, formal_module_index, formal_type).is_some()
    {
        return Some(13);
    }
    crate::typecheck::known_non_udt_type(
        project,
        formal_module_index,
        formal_module,
        formal_type,
        host_profile,
    )
    .then_some(94)
}

fn push_object_argument_type_diagnostic(
    call: CallTypeContext<'_>,
    parameter: &Parameter,
    argument_expression: &str,
    actual_type: &str,
    formal_type: &str,
    diagnostics: &mut Vec<Diagnostic>,
) {
    diagnostics.push(Diagnostic {
        code: "VBA2126",
        severity: Severity::Error,
        message: format!(
            "Argument '{}' has known type {}, which is incompatible with object parameter '{}' of '{}' declared as {}",
            argument_expression, actual_type, parameter.name, call.callee_name, formal_type
        ),
        source: call.source.into(),
        span: call.span,
    });
}

fn byval_udt_coercion_invalid(
    project: &Project,
    formal_context: TypeResolutionContext<'_>,
    formal_type: &str,
    actual_context: TypeResolutionContext<'_>,
    actual_type: &str,
    host_profile: HostProfile,
) -> Option<bool> {
    if canon(actual_type) == "nothing" {
        return None;
    }
    let formal_udt =
        crate::typecheck::user_type_owner_index(project, formal_context.module_index, formal_type);
    let actual_udt =
        crate::typecheck::user_type_owner_index(project, actual_context.module_index, actual_type);
    match (formal_udt, actual_udt) {
        (Some(formal_owner), Some(actual_owner)) => {
            Some(formal_owner != actual_owner || canon(formal_type) != canon(actual_type))
        }
        (Some(_), None) => {
            let actual_type = crate::typecheck::effective_project_type_name(
                project,
                actual_context.module_index,
                actual_context.module,
                actual_type,
            );
            if canon(&actual_type) == "variant" {
                return Some(false);
            }
            object_argument_compatibility(
                project,
                actual_context.module_index,
                actual_context.module,
                &actual_type,
                host_profile,
            )
            .map(|_| true)
        }
        (None, Some(_)) => {
            let formal_type = crate::typecheck::effective_project_type_name(
                project,
                formal_context.module_index,
                formal_context.module,
                formal_type,
            );
            if canon(&formal_type) == "variant" {
                return Some(true);
            }
            object_argument_compatibility(
                project,
                formal_context.module_index,
                formal_context.module,
                &formal_type,
                host_profile,
            )
            .map(|_| true)
        }
        (None, None) => None,
    }
}

fn byref_array_element_type_identity(
    project: &Project,
    module_index: usize,
    module: &Module,
    procedure: Option<&Procedure>,
    type_name: &str,
) -> Option<String> {
    let type_name =
        crate::typecheck::effective_project_type_name(project, module_index, module, type_name);
    let key = canon(&type_name);
    if is_fixed_length_string_type(&type_name) {
        if fixed_length_string_type_error(&type_name).is_some() {
            return None;
        }
        let size = fixed_length_string_declared_size(
            project,
            module_index,
            module,
            procedure,
            &type_name,
        )?;
        return Some(format!("fixed-string:{size}"));
    }
    if matches!(
        key.as_str(),
        "boolean"
            | "byte"
            | "integer"
            | "long"
            | "longlong"
            | "currency"
            | "single"
            | "double"
            | "date"
            | "string"
            | "variant"
            | "object"
    ) {
        return Some(format!("builtin:{key}"));
    }
    if let Some(owner) = crate::typecheck::user_type_owner_index(project, module_index, &type_name)
    {
        return Some(format!("udt:{owner}:{key}"));
    }
    crate::typecheck::class_type_owner_index(project, &type_name)
        .map(|owner| format!("class:{owner}:{key}"))
}

fn is_declared_array_argument(module: &Module, procedure: Option<&str>, argument: &str) -> bool {
    let text = argument.trim();
    let base = text.strip_suffix("()").unwrap_or(text).trim();
    let (tokens, _) = lex(base, 32);
    let identifiers = tokens
        .iter()
        .filter(|t| !matches!(t.kind, TokenKind::Newline | TokenKind::Eof))
        .collect::<Vec<_>>();
    if identifiers.len() != 1 || identifiers[0].kind != TokenKind::Identifier {
        return false;
    }
    let name = canon(&identifiers[0].text);
    if module
        .declarations
        .iter()
        .any(|d| d.is_array && canon(&d.name) == name)
    {
        return true;
    }
    let Some(proc) = procedure.and_then(|n| {
        module
            .procedures
            .iter()
            .find(|p| p.name.eq_ignore_ascii_case(n))
    }) else {
        return false;
    };
    proc.parameters
        .iter()
        .any(|p| p.is_array && canon(&p.name) == name)
        || statements_declare_array(&proc.statements, &name)
}

fn statements_declare_array(statements: &[Statement], name: &str) -> bool {
    statements.iter().any(|statement| {
        statement
            .declaration
            .as_ref()
            .is_some_and(|d| d.is_array && canon(&d.name) == name)
            || statements_declare_array(&statement.children, name)
    })
}

#[derive(Clone, Copy)]
struct ArgumentBindingSite<'a> {
    source: &'a str,
    span: Span,
}

fn diagnose_argument_binding(
    name: &str,
    parameters: &[Parameter],
    argument_count: usize,
    bindings: &[(usize, String)],
    binding_issues: &[String],
    site: ArgumentBindingSite<'_>,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let assigned = bindings.iter().map(|(i, _)| *i).collect::<HashSet<_>>();
    let explicitly_omitted_required = binding_issues
        .iter()
        .filter_map(|issue| {
            issue
                .strip_prefix("required positional parameter '")
                .and_then(|issue| issue.strip_suffix("' is omitted"))
        })
        .map(canon)
        .collect::<HashSet<_>>();
    let missing = parameters
        .iter()
        .enumerate()
        .filter(|(i, p)| {
            !p.optional
                && !p.is_param_array
                && !assigned.contains(i)
                && !explicitly_omitted_required.contains(&canon(&p.name))
        })
        .map(|(_, p)| p.name.as_str())
        .collect::<Vec<_>>();
    if !missing.is_empty() {
        diagnostics.push(Diagnostic {
            code: "VBA2020",
            severity: Severity::Error,
            message: format!(
                "call to '{}' supplies {argument_count} arguments but omits required parameter(s): {}",
                name,
                missing.join(", ")
            ),
            source: site.source.into(),
            span: site.span,
        });
    }
}

fn split_tokens<'a>(ts: &'a [Token], separator: &str) -> Vec<&'a [Token]> {
    let mut out = Vec::new();
    let (mut start, mut depth) = (0usize, 0i32);
    for (i, t) in ts.iter().enumerate() {
        match t.text.as_str() {
            "(" | "[" => depth += 1,
            ")" | "]" => depth -= 1,
            _ => {}
        }
        if depth == 0 && t.text == separator {
            out.push(&ts[start..i]);
            start = i + 1;
        }
    }
    out.push(&ts[start..]);
    out
}
fn render_call_argument(ts: &[Token]) -> String {
    let mut s = String::new();
    let mut prev = "";
    for t in ts {
        let tight = matches!(t.text.as_str(), ")" | "." | "," | ":" | "!" | "(")
            || matches!(prev, "." | "!" | "(");
        if !s.is_empty() && !tight {
            s.push(' ');
        }
        if t.bracket_delimited {
            s.push('[');
            s.push_str(&t.text);
            s.push(']');
        } else if t.kind == TokenKind::String {
            s.push('"');
            s.push_str(&t.text.replace('"', "\"\""));
            s.push('"');
        } else {
            s.push_str(&t.text);
        }
        prev = &t.text;
    }
    s
}
fn is_assignable_argument(arg: &str) -> bool {
    let text = arg.split_once(":=").map(|x| x.1).unwrap_or(arg).trim();
    if text.is_empty() || text.to_ascii_lowercase().starts_with("byval ") {
        return false;
    }
    let (tokens, _) = lex(text, 1024);
    let ids = tokens
        .into_iter()
        .filter(|t| t.kind != TokenKind::Newline && t.kind != TokenKind::Eof)
        .collect::<Vec<_>>();
    ids.first().is_some_and(|t| t.kind == TokenKind::Identifier)
        && !ids.iter().any(|t| {
            matches!(
                t.text.as_str(),
                "+" | "-" | "*" | "/" | "&" | "=" | "<>" | "<" | ">"
            )
        })
}
fn parameter_is_written(procedure: &Procedure, name: &str) -> bool {
    statements_write_name(&procedure.statements, name)
}

fn parameter_is_effectively_byref(
    procedure: &Procedure,
    parameter_index: usize,
    parameter: &Parameter,
) -> bool {
    let property_value_parameter = matches!(
        procedure.kind.to_ascii_lowercase().as_str(),
        "property let" | "property set"
    ) && parameter_index + 1 == procedure.parameters.len();
    !parameter.is_param_array
        && !property_value_parameter
        && parameter.passing.eq_ignore_ascii_case("ByRef")
}

fn statements_write_name(statements: &[Statement], name: &str) -> bool {
    statements.iter().any(|s| {
        let direct = match s.kind.as_str() {
            "assignment" => assignment_lhs_name(s.expression.as_deref().unwrap_or(""))
                .is_some_and(|n| canon(&n) == canon(name)),
            "redim" => {
                s.children.iter().any(|target| {
                    target
                        .declaration
                        .as_ref()
                        .is_some_and(|declaration| canon(&declaration.name) == canon(name))
                }) || statement_declared_target(s.expression.as_deref().unwrap_or(""))
                    .is_some_and(|n| canon(&n) == canon(name))
            }
            "erase" | "erase_target" | "for" | "for_each" => {
                statement_declared_target(s.expression.as_deref().unwrap_or(""))
                    .is_some_and(|n| canon(&n) == canon(name))
            }
            _ => false,
        };
        direct || statements_write_name(&s.children, name)
    })
}
fn assignment_lhs_name(source: &str) -> Option<String> {
    let mut lhs = source.split_once('=')?.0.trim().to_owned();
    if lhs.to_ascii_lowercase().starts_with("set ") || lhs.to_ascii_lowercase().starts_with("let ")
    {
        lhs = lhs[4..].trim().to_owned();
    }
    statement_declared_target(&lhs)
}
fn statement_declared_target(source: &str) -> Option<String> {
    let (tokens, _) = lex(source, 128);
    tokens
        .into_iter()
        .find(|t| {
            t.kind == TokenKind::Identifier
                && !matches!(
                    canon(&t.text).as_str(),
                    "redim"
                        | "preserve"
                        | "erase"
                        | "for"
                        | "each"
                        | "next"
                        | "let"
                        | "set"
                        | "byref"
                        | "byval"
                        | "optional"
                        | "paramarray"
                        | "in"
                        | "to"
                        | "step"
                        | "while"
                        | "until"
                        | "do"
                )
        })
        .map(|t| t.text)
}
fn canon(s: &str) -> String {
    s.trim_end_matches(['%', '&', '^', '@', '!', '#', '$'])
        .to_lowercase()
}
fn known_type(s: &str) -> bool {
    if fixed_length_string_type_error(s).is_none()
        && s.chars()
            .filter(|character| !character.is_whitespace())
            .collect::<String>()
            .to_ascii_lowercase()
            .starts_with("string*")
    {
        return true;
    }
    matches!(
        s.trim().to_ascii_lowercase().as_str(),
        "variant"
            | "boolean"
            | "byte"
            | "integer"
            | "long"
            | "longlong"
            | "longptr"
            | "single"
            | "double"
            | "currency"
            | "decimal"
            | "date"
            | "string"
            | "object"
            | "error"
    )
}
fn is_intrinsic_constant(s: &str) -> bool {
    matches!(
        canon(s).as_str(),
        "true"
            | "false"
            | "nothing"
            | "empty"
            | "null"
            | "vbnullstring"
            | "vbget"
            | "vblet"
            | "vbmethod"
            | "vbset"
            | "vbcr"
            | "vbcrlf"
            | "vblf"
            | "vbtab"
            | "vbnewline"
            | "vbobjecterror"
            | "me"
            | "app"
            | "thisworkbook"
    )
}

fn is_variant_type_constant(s: &str) -> bool {
    matches!(
        canon(s).as_str(),
        "vbempty"
            | "vbnull"
            | "vbinteger"
            | "vblong"
            | "vbsingle"
            | "vbdouble"
            | "vbcurrency"
            | "vbdate"
            | "vbstring"
            | "vbobject"
            | "vberror"
            | "vbboolean"
            | "vbvariant"
            | "vbdataobject"
            | "vbdecimal"
            | "vbbyte"
            | "vblonglong"
            | "vbuserdefinedtype"
            | "vbarray"
    )
}
fn is_compare_method_constant(s: &str) -> bool {
    matches!(
        canon(s).as_str(),
        "vbbinarycompare" | "vbtextcompare" | "vbusecompareoption"
    )
}
fn external_operation(s: &str, tokens: &[Token], at: usize) -> Option<&'static str> {
    if canon(s) == "line" {
        return tokens
            .get(at + 1)
            .is_some_and(|token| token.text.eq_ignore_ascii_case("input"))
            .then_some("file_io_candidate");
    }
    Some(match canon(s).as_str() {
        "shell" => "process_execution_candidate",
        "createobject" | "getobject" => "automation_or_com_object_candidate",
        "open" | "close" | "print" | "write" | "input" | "put" | "get" | "seek" | "reset"
        | "lock" | "unlock" => "file_io_candidate",
        "kill" | "filecopy" | "mkdir" | "rmdir" | "chdir" | "chdrive" | "name" | "setattr" => {
            "filesystem_operation_candidate"
        }
        "filelen" | "filedatetime" | "getattr" | "dir" => "filesystem_metadata_read_candidate",
        "callbyname" | "run" => "dynamic_invocation_candidate",
        "environ" => "environment_read_candidate",
        "executeexcel4macro" => "legacy_macro_execution_candidate",
        _ => return None,
    })
}

fn append_vba_file_flow_fact(
    tokens: &[Token],
    at: usize,
    operation: &str,
    module: &Module,
    procedure: Option<String>,
    span: Span,
    out: &mut Vec<DataFlowFact>,
) {
    let mut kind = canon(operation);
    let mut argument_start = at + 1;
    if kind == "line" {
        if !tokens
            .get(argument_start)
            .is_some_and(|token| token.text.eq_ignore_ascii_case("input"))
        {
            return;
        }
        kind = "line_input".into();
        argument_start += 1;
    }
    if !matches!(
        kind.as_str(),
        "input" | "line_input" | "get" | "put" | "print" | "write"
    ) || !line_starts_with(tokens, at, operation)
    {
        return;
    }
    let mut statement_end = at + 1;
    while statement_end < tokens.len()
        && tokens[statement_end].kind != TokenKind::Newline
        && tokens[statement_end].kind != TokenKind::Eof
        && tokens[statement_end].text != ":"
    {
        statement_end += 1;
    }
    let has_hash = tokens
        .get(argument_start)
        .is_some_and(|token| token.text == "#");
    if matches!(kind.as_str(), "input" | "line_input" | "print" | "write") && !has_hash {
        return;
    }
    let file_start = argument_start + usize::from(has_hash);
    let mut depth = 0i32;
    let first_separator = (file_start..statement_end).find(|&index| {
        match tokens[index].text.as_str() {
            "(" | "[" => depth += 1,
            ")" | "]" => depth -= 1,
            _ => {}
        }
        depth == 0
            && (tokens[index].text == ","
                || matches!(kind.as_str(), "print" if tokens[index].text == ";"))
    });
    let Some(first_separator) = first_separator else {
        return;
    };
    let file_number = render_call_argument(&tokens[file_start..first_separator]);
    let values_start = if matches!(kind.as_str(), "get" | "put") {
        let mut depth = 0i32;
        (first_separator + 1..statement_end)
            .find(|&index| {
                match tokens[index].text.as_str() {
                    "(" | "[" => depth += 1,
                    ")" | "]" => depth -= 1,
                    _ => {}
                }
                depth == 0 && tokens[index].text == ","
            })
            .map(|separator| separator + 1)
            .unwrap_or(first_separator + 1)
    } else {
        first_separator + 1
    };
    if values_start >= statement_end {
        return;
    }
    let values = split_file_values(&tokens[values_start..statement_end]);
    let transfer = if matches!(kind.as_str(), "input" | "line_input" | "get") {
        "file_read_candidate"
    } else {
        "file_write_candidate"
    };
    if transfer == "file_read_candidate" {
        let input = format!("file#{file_number}");
        for value in values.into_iter().filter(|value| !value.is_empty()) {
            out.push(DataFlowFact {
                module: module.name.clone(),
                procedure: procedure.clone(),
                target: render_call_argument(value),
                inputs: vec![input.clone()],
                transfer: transfer.into(),
                span,
                ..DataFlowFact::default()
            });
        }
    } else {
        let inputs = values
            .into_iter()
            .flat_map(|value| argument_input_names(&render_call_argument(value)))
            .collect::<Vec<_>>();
        out.push(DataFlowFact {
            module: module.name.clone(),
            procedure,
            target: format!("file#{file_number}"),
            inputs,
            transfer: transfer.into(),
            span,
            ..DataFlowFact::default()
        });
    }
}

fn split_file_values(tokens: &[Token]) -> Vec<&[Token]> {
    let mut values = Vec::new();
    let mut start = 0usize;
    let mut depth = 0i32;
    for (index, token) in tokens.iter().enumerate() {
        match token.text.as_str() {
            "(" | "[" => depth += 1,
            ")" | "]" => depth -= 1,
            _ => {}
        }
        if depth == 0 && matches!(token.text.as_str(), "," | ";") {
            values.push(&tokens[start..index]);
            start = index + 1;
        }
    }
    values.push(&tokens[start..]);
    values
}
