    #[test]
    fn preserves_effective_module_option_settings() {
        let source = SourceUnit {
            name: "Options.bas".into(),
            text: "Option Explicit ' prevent implicit variants\nOption Compare Text\nOption Base 1\nOption Private Module\nPublic values(5) As Long\nPublic Sub Run()\nEnd Sub\n".into(),
        };
        let a = analyze(&[source], &AnalysisOptions::default()).unwrap();
        let options = &a.project.modules[0].options;
        assert!(options.explicit);
        assert_eq!(options.compare_mode, "Text");
        assert!(options.compare_explicit);
        assert!(options.compare_valid);
        assert_eq!(options.array_base, 1);
        assert!(options.array_base_explicit);
        assert!(options.array_base_valid);
        assert!(options.private_module);
        let json = crate::export::to_json(&a, None, crate::export::Disclosure::StructureOnly);
        assert!(json.contains("\"compare_valid\":true"));
        assert!(!a.diagnostics.iter().any(|d| {
            matches!(
                d.code,
                "VBA2066" | "VBA2067" | "VBA2068" | "VBA2069" | "VBA2070" | "VBA2071"
            )
        }));
    }

    #[test]
    fn applies_module_local_deftype_to_untyped_symbols_and_type_facts() {
        let sources = [
            SourceUnit {
                name: "Accounting.bas".into(),
                text: "Option Explicit\nDefInt A-C\nDefStr D-G\nPrivate amountModule\nPublic Function AddOne(amount)\nAddOne = amount + 1\nEnd Function\nPublic Sub SetValues()\nDim currentAmount\nDim displayText\namountModule = 3\ncurrentAmount = 1\ndisplayText = \"ready\"\namountMissing = 2\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "Other.bas".into(),
                text: "DefStr A-Z\nPublic Sub SetText()\nDim amount\namount = \"text\"\nEnd Sub\nPublic Sub UseOne()\nDim result As Long\nresult = AddOne(2)\nEnd Sub\n".into(),
            },
        ];
        let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
        let accounting = &analysis.project.modules[0];
        assert_eq!(
            accounting.implicit_types.by_initial.get(&'A'),
            Some(&"Integer".into())
        );
        assert_eq!(
            accounting.implicit_types.by_initial.get(&'D'),
            Some(&"String".into())
        );
        assert!(accounting.implicit_types.valid);
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.module == "Accounting"
                && fact.target == "amountModule"
                && fact.target_type.as_deref() == Some("Integer")
                && fact.status == "compatible"
        }));
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.module == "Accounting"
                && fact.target == "currentAmount"
                && fact.target_type.as_deref() == Some("Integer")
                && fact.status == "compatible"
        }));
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.module == "Accounting"
                && fact.target == "displayText"
                && fact.target_type.as_deref() == Some("String")
                && fact.status == "compatible"
        }));
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.module == "Accounting"
                && fact.target == "AddOne"
                && fact.target_type.as_deref() == Some("Integer")
                && fact.value_type == "Integer"
        }));
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.module == "Other"
                && fact.target == "amount"
                && fact.target_type.as_deref() == Some("String")
        }));
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.module == "Other"
                && fact.target == "result"
                && fact.value_type == "Integer"
                && fact.status == "numeric_conversion_possible"
        }));
        assert!(analysis.references.iter().any(|fact| {
            fact.module == "Accounting"
                && fact.name == "amountMissing"
                && fact.implicit_type.as_deref() == Some("Integer")
        }));
        assert!(analysis.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "VBA2030" && diagnostic.message.contains("Integer")
        }));
        assert_eq!(
            analysis.project.modules[1]
                .implicit_types
                .universal_type
                .as_deref(),
            Some("String")
        );
    }

    #[test]
    fn supports_each_ms_vbal_deftype_keyword() {
        let mappings = [
            ("DefBool", "Boolean"),
            ("DefByte", "Byte"),
            ("DefCur", "Currency"),
            ("DefDate", "Date"),
            ("DefDbl", "Double"),
            ("DefInt", "Integer"),
            ("DefLng", "Long"),
            ("DefLngLng", "LongLong"),
            ("DefLngPtr", "LongPtr"),
            ("DefObj", "Object"),
            ("DefSng", "Single"),
            ("DefStr", "String"),
            ("DefVar", "Variant"),
        ];
        let sources = mappings
            .iter()
            .enumerate()
            .map(|(index, (directive, _))| SourceUnit {
                name: format!("Type{index}.bas"),
                text: format!("{directive} A\nPublic Sub S()\nEnd Sub\n"),
            })
            .collect::<Vec<_>>();
        let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
        for (module, (_, expected)) in analysis.project.modules.iter().zip(mappings) {
            assert_eq!(
                module
                    .implicit_types
                    .by_initial
                    .get(&'A')
                    .map(String::as_str),
                Some(expected)
            );
            assert!(module.implicit_types.valid);
        }
    }

    #[test]
    fn deftype_accepts_descending_case_insensitive_letter_ranges() {
        let analysis = analyze(
            &[SourceUnit {
                name: "DescendingDefType.bas".into(),
                text: "dEfLng z-a\nPublic Sub S()\nDim amount\namount = 1\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let rules = &analysis.project.modules[0].implicit_types;
        assert!(rules.valid);
        assert_eq!(rules.by_initial.len(), 26);
        assert_eq!(rules.by_initial.get(&'A').map(String::as_str), Some("Long"));
        assert_eq!(rules.by_initial.get(&'Z').map(String::as_str), Some("Long"));
        assert!(rules.universal_type.is_none());
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.target == "amount" && fact.target_type.as_deref() == Some("Long")
        }));
    }

    #[test]
    fn recognizes_and_validates_fixed_length_string_types() {
        let valid = analyze(
            &[SourceUnit {
                name: "FixedString.bas".into(),
                text: "Private Const FieldSize As Long = 12\nPrivate Const ComputedSize As Long = (2 + 3) * 2\nPrivate Type RecordData\nName As String * FieldSize\nOtherName As String * ComputedSize\nEnd Type\nPublic Sub Read(ByVal name As String * 12)\nConst BufferSize As Long = 32\nDim buffer As String * BufferSize\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        assert!(
            !valid
                .diagnostics
                .iter()
                .any(|diagnostic| { matches!(diagnostic.code, "VBA1036" | "VBA1039" | "VBA2003") }),
            "{:?}",
            valid.diagnostics
        );

        let invalid = analyze(
            &[SourceUnit {
                name: "InvalidFixedString.bas".into(),
                text: "Private Const WideSize^ = 12^\nPrivate Const TooLarge As Long = 65527\nPrivate Const TooLargeExpression As Long = 65526 + 1\nPrivate Const BaseSize As Long = 12\nPrivate Const DerivedSize As Long = BaseSize + 1\nPublic Sub Read(ByVal zero As String * 0, ByVal tooLong As String * 65527)\nDim negative As String * -1\nDim missing As String * NotDeclared\nDim longLongSize As String * WideSize^\nDim longLongLiteral As String * 1^\nDim malformedExpression As String * 2 + 3\nDim floatingLiteral As String * 1.0\nDim radixNegative As String * &HDEAD\nDim tooBigConstant As String * TooLarge\nDim tooBigExpression As String * TooLargeExpression\nDim resolvedExpression As String * DerivedSize\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        assert_eq!(
            invalid
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == "VBA1036")
                .count(),
            9,
            "{:?}",
            invalid.diagnostics
        );
        assert!(invalid.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "VBA1037"
                && diagnostic
                    .message
                    .to_ascii_lowercase()
                    .contains("notdeclared")
        }));
        assert!(invalid.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "VBA1038" && diagnostic.message.contains("LongLong")
        }));
        assert!(!invalid.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "VBA1039" && diagnostic.message.contains("DerivedSize")
        }));
    }

    #[test]
    fn folds_bounded_integer_constant_expressions_and_signs_radix_values() {
        assert_eq!(parse_integer_bound("2 * (3 + 4)"), Some(14));
        assert_eq!(parse_integer_bound("5 \\ 2"), Some(2));
        assert_eq!(parse_integer_bound("5 Mod 2"), Some(1));
        assert_eq!(parse_integer_bound("30000 + 30000"), None);
        assert_eq!(parse_integer_bound("30000& + 30000"), Some(60_000));
        assert_eq!(parse_integer_bound("32767 + 1"), None);
        assert_eq!(parse_integer_bound("32767& + 1"), Some(32_768));
        assert_eq!(parse_integer_bound("&HFFFF"), Some(-1));
        assert_eq!(parse_integer_bound("&HFFFF&"), Some(65_535));
        assert_eq!(parse_integer_bound("&HFFFFFFFF&"), Some(-1));
        assert_eq!(parse_integer_bound("&O177777"), Some(-1));
        assert_eq!(parse_integer_bound("&HDEAD"), Some(-8_531));
        assert_eq!(parse_integer_bound("2.5"), None);
        assert_eq!(parse_integer_bound("1 / 2"), None);
        assert_eq!(parse_integer_bound("BaseSize + 1"), None);
    }

