    #[test]
    fn folds_visible_local_and_qualified_fixed_string_constant_references() {
        let sources = [
            SourceUnit {
                name: "Sizes.bas".into(),
                text: "Public Const SharedBase As Long = 120\nPrivate Const ModuleBase As Long = 12\nPrivate Const ModuleTotal As Long = ModuleBase * 2\nPrivate Const ByteComponent As Byte = 200\nPrivate Const ByteOverflow As Byte = ByteComponent + ByteComponent\nPublic Sub CheckInternal()\nDim moduleBuffer As String * ModuleTotal\nDim byteBuffer As String * ByteOverflow\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "Reader.bas".into(),
                text: "Public Sub Read()\nConst Multiplier As Long = 2\nConst LocalTotal As Long = Sizes.SharedBase * Multiplier\nConst LocalBase As Integer = 12\nConst LocalDerived As Integer = LocalBase + 5\nDim moduleBuffer As String * LocalTotal\nDim localBuffer As String * LocalDerived\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "Cycle.bas".into(),
                text: "Public Sub Check()\nConst CycleA As Long = CycleB + 1\nConst CycleB As Long = CycleA + 1\nDim buffer As String * CycleA\nEnd Sub\n".into(),
            },
        ];
        let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
        let unresolved = analysis
            .diagnostics
            .iter()
            .filter(|diagnostic| diagnostic.code == "VBA1039")
            .collect::<Vec<_>>();
        assert_eq!(unresolved.len(), 2, "{:?}", analysis.diagnostics);
        assert!(
            unresolved
                .iter()
                .any(|diagnostic| diagnostic.message.contains("ByteOverflow"))
        );
        assert!(
            unresolved
                .iter()
                .any(|diagnostic| diagnostic.message.contains("CycleA"))
        );
        assert!(!analysis.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "VBA1036"
                && (diagnostic.message.contains("ModuleTotal")
                    || diagnostic.message.contains("LocalTotal")
                    || diagnostic.message.contains("LocalDerived"))
        }));
    }

    #[test]
    fn type_suffix_overrides_deftype_and_invalid_ranges_do_not_assign_a_type() {
        let sources = [
            SourceUnit {
                name: "Suffix.bas".into(),
                text: "DefInt A-Z\nPublic Sub S()\nDim amount$\nDim count\nDim explicitRate As Double\namount$ = \"text\"\ncount = 1\nexplicitRate = 1\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "Overlap.bas".into(),
                text: "DefInt A-C\nDefStr C-F\nPublic Sub S()\nDim amount\namount = 1\nEnd Sub\n"
                    .into(),
            },
            SourceUnit {
                name: "Late.bas".into(),
                text: "Public value As Long\nDefInt A-Z\nPublic Sub S()\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "InProcedure.bas".into(),
                text: "Public Sub S()\nDefInt A-Z\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "Unsupported.bas".into(),
                text: "DefDec A-Z\nPublic Sub S()\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "DuplicateUniversal.bas".into(),
                text: "DefInt A-Z, A-Z\nPublic Sub S()\nEnd Sub\n".into(),
            },
        ];
        let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.module == "Suffix"
                && fact.target == "amount$"
                && fact.target_type.as_deref() == Some("String")
                && fact.status == "compatible"
        }));
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.module == "Suffix"
                && fact.target == "count"
                && fact.target_type.as_deref() == Some("Integer")
        }));
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.module == "Suffix"
                && fact.target == "explicitRate"
                && fact.target_type.as_deref() == Some("Double")
        }));
        assert!(!analysis.project.modules[1].implicit_types.valid);
        assert!(!analysis.project.modules[2].implicit_types.valid);
        assert!(!analysis.project.modules[3].implicit_types.valid);
        assert!(!analysis.project.modules[4].implicit_types.valid);
        assert!(!analysis.project.modules[5].implicit_types.valid);
        assert!(
            analysis
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == "VBA2081")
        );
        assert_eq!(
            analysis
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == "VBA2082")
                .count(),
            2
        );
        assert!(
            analysis
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == "VBA2080")
        );
        assert!(
            !analysis
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == "VBA1006")
        );
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.module == "Overlap" && fact.target == "amount" && fact.target_type.is_none()
        }));
    }

