    #[test]
    fn validates_optional_udt_parameters_and_constant_default_expressions() {
        let sources = [
            SourceUnit {
                name: "OptionalDefaults.bas".into(),
                text: "Private Type RecordData\nValue As Long\nEnd Type\nPrivate Const LocalLimit As Long = 4\nPrivate count As Long\nPrivate Function CurrentValue() As Long\nCurrentValue = 1\nEnd Function\nPrivate Sub InvalidUdt(Optional record As RecordData)\nEnd Sub\nPrivate Sub VariableDefault(Optional amount As Long = count)\nEnd Sub\nPrivate Sub CallDefault(Optional amount As Long = CurrentValue())\nEnd Sub\nPrivate Sub IsDefault(Optional value As Boolean = Nothing Is Nothing)\nEnd Sub\nPrivate Sub ConstantDefault(Optional amount As Long = LocalLimit + 1)\nEnd Sub\nPrivate Sub QualifiedDefault(Optional amount As Long = ConstData.Limit)\nEnd Sub\nPrivate Sub VariantWithoutDefault(Optional value As Variant)\nEnd Sub\nPrivate Sub NullDefaultScalar(Optional amount As Long = Null)\nEnd Sub\nPrivate Sub NullDefaultArray(Optional values() As Long = Null)\nEnd Sub\nPrivate Sub NullDefaultVariant(Optional value As Variant = Null)\nEnd Sub\nPrivate Sub LongLongDefault(Optional amount As Long = 1^)\nEnd Sub\nPrivate Sub ObjectDefault(Optional value As Object = 1)\nEnd Sub\nPrivate Sub ArrayDefault(Optional values() As Long = 1)\nEnd Sub\nPrivate Sub ObjectNothingDefault(Optional value As Object = Nothing)\nEnd Sub\nPrivate Sub ByteArrayDefault(Optional values() As Byte = 1)\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "ConstData.bas".into(),
                text: "Public Const Limit As Long = 9\n".into(),
            },
        ];
        let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
        let udt_errors = analysis
            .diagnostics
            .iter()
            .filter(|diagnostic| diagnostic.code == "VBA2059")
            .collect::<Vec<_>>();
        let default_errors = analysis
            .diagnostics
            .iter()
            .filter(|diagnostic| diagnostic.code == "VBA2133")
            .collect::<Vec<_>>();
        assert_eq!(udt_errors.len(), 1, "{:?}", analysis.diagnostics);
        assert_eq!(default_errors.len(), 3, "{:?}", analysis.diagnostics);
        assert_eq!(udt_errors[0].span.line, 9);
        let mut default_lines = default_errors
            .iter()
            .map(|diagnostic| diagnostic.span.line)
            .collect::<Vec<_>>();
        default_lines.sort_unstable();
        assert_eq!(default_lines, [11, 13, 15]);
        assert!(analysis.diagnostics.iter().all(|diagnostic| {
            !((diagnostic.span.line == 17
                || diagnostic.span.line == 19
                || diagnostic.span.line == 21)
                && matches!(diagnostic.code, "VBA2059" | "VBA2133"))
        }));
        let null_warnings = analysis
            .diagnostics
            .iter()
            .filter(|diagnostic| diagnostic.code == "VBA2131")
            .collect::<Vec<_>>();
        assert_eq!(null_warnings.len(), 2, "{:?}", analysis.diagnostics);
        assert!(null_warnings.iter().any(|diagnostic| {
            diagnostic.span.line == 23 && diagnostic.message.contains("runtime error 94")
        }));
        assert!(null_warnings.iter().any(|diagnostic| {
            diagnostic.span.line == 25 && diagnostic.message.contains("runtime error 13")
        }));
        assert!(
            !analysis
                .diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == "VBA2131" && diagnostic.span.line == 27 })
        );
        for (code, line) in [("VBA2086", 29), ("VBA2129", 31), ("VBA2130", 33)] {
            assert!(
                analysis
                    .diagnostics
                    .iter()
                    .any(|diagnostic| diagnostic.code == code && diagnostic.span.line == line),
                "missing {code} on line {line}: {:?}",
                analysis.diagnostics
            );
        }
        assert!(
            analysis
                .diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == "VBA2130" && diagnostic.span.line == 37 })
        );
        assert!(!analysis.diagnostics.iter().any(|diagnostic| {
            diagnostic.span.line == 35
                && matches!(diagnostic.code, "VBA2086" | "VBA2129" | "VBA2130")
        }));
    }

    #[test]
    fn warns_for_string_literals_that_cannot_be_parsed_as_numeric_or_boolean() {
        let source = SourceUnit {
            name: "StringCoercion.bas".into(),
            text: "Private Sub NeedLong(ByVal value As Long)\nEnd Sub\nPrivate Sub NeedBoolean(ByVal value As Boolean)\nEnd Sub\nPrivate Sub OptionalLong(Optional value As Long = \"not a number\")\nEnd Sub\nPrivate Sub OptionalBoolean(Optional value As Boolean = \"unknown\")\nEnd Sub\nPrivate Sub OptionalBooleanLiteral(Optional value As Boolean = \"True\")\nEnd Sub\nPublic Sub Check()\nDim amount As Long\nDim flag As Boolean\namount = \"letters\"\namount = \"1e2\"\nflag = \"yes\"\nflag = \"False\"\nNeedLong \"words\"\nNeedLong \"1e2\"\nNeedBoolean \"nope\"\nNeedBoolean \"True\"\nNeedLong \"12 kr\"\nEnd Sub\n".into(),
        };
        let analysis = analyze(&[source], &AnalysisOptions::default()).unwrap();
        let warnings = analysis
            .diagnostics
            .iter()
            .filter(|diagnostic| diagnostic.code == "VBA2135")
            .collect::<Vec<_>>();
        assert_eq!(warnings.len(), 6, "{:?}", analysis.diagnostics);
        let mut lines = warnings
            .iter()
            .map(|diagnostic| diagnostic.span.line)
            .collect::<Vec<_>>();
        lines.sort_unstable();
        assert_eq!(lines, [5, 7, 14, 16, 18, 20]);
        assert!(warnings.iter().all(|diagnostic| {
            diagnostic.severity == Severity::Warning
                && diagnostic.message.contains("runtime error 13")
        }));
        assert!(!analysis.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "VBA2135"
                && matches!(diagnostic.span.line, 9 | 12 | 15 | 17 | 19 | 21 | 22)
        }));
    }

    #[test]
    fn leaves_deftype_unresolved_when_conditional_branches_are_unknown() {
        let source = SourceUnit {
            name: "ConditionalDefType.bas".into(),
            text: "#If VBA7 Then\nDefInt A-Z\n#Else\nDefStr A-Z\n#End If\nPublic Sub S()\nDim amount\namount = 1\nEnd Sub\n".into(),
        };
        let unresolved =
            analyze(std::slice::from_ref(&source), &AnalysisOptions::default()).unwrap();
        assert!(!unresolved.project.modules[0].implicit_types.valid);
        assert!(unresolved.diagnostics.iter().any(|d| d.code == "VBA2084"));
        assert!(!unresolved.diagnostics.iter().any(|d| d.code == "VBA2081"));
        assert!(
            unresolved
                .type_facts
                .iter()
                .any(|fact| { fact.target == "amount" && fact.target_type.is_none() })
        );

        let selected = analyze(
            &[source],
            &AnalysisOptions {
                conditional_constants: [("VBA7".into(), "True".into())].into(),
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        assert!(selected.project.modules[0].implicit_types.valid);
        assert_eq!(
            selected.project.modules[0]
                .implicit_types
                .universal_type
                .as_deref(),
            Some("Integer")
        );
        assert!(selected.type_facts.iter().any(|fact| {
            fact.target == "amount" && fact.target_type.as_deref() == Some("Integer")
        }));
        assert!(!selected.diagnostics.iter().any(|d| d.code == "VBA2084"));
    }

