    #[test]
    fn composes_local_and_direct_function_calls_through_return_summaries_independent_of_source_order()
     {
        let provider = SourceUnit {
            name: "Provider.bas".into(),
            text: "Option Explicit\nPrivate Const HiddenLimit As Long = 19\nPrivate Function Inner(ByVal value As Long) As Long\nDim localCopy As Long\nlocalCopy = value\nInner = localCopy\nEnd Function\nPublic Function Wrapper(ByVal amount As Long) As Long\nDim intermediate As Long\nintermediate = Inner(amount)\nWrapper = intermediate\nEnd Function\nPublic Function Direct(ByVal amount As Long) As Long\nDirect = Inner(amount)\nEnd Function\nPrivate Function InnerConstant() As Long\nInnerConstant = HiddenLimit\nEnd Function\nPublic Function ConstantWrapper() As Long\nDim constantCopy As Long\nconstantCopy = InnerConstant()\nConstantWrapper = constantCopy\nEnd Function\n".into(),
        };
        let consumer = SourceUnit {
            name: "Consumer.bas".into(),
            text: "Option Explicit\nPublic Sub Run()\nDim inputAmount As Long\nDim wrapped As Long\nDim direct As Long\nDim constantResult As Long\nwrapped = Provider.Wrapper(inputAmount)\ndirect = Provider.Direct(inputAmount)\nconstantResult = Provider.ConstantWrapper()\nEnd Sub\n".into(),
        };

        for sources in [
            vec![provider.clone(), consumer.clone()],
            vec![consumer.clone(), provider.clone()],
        ] {
            let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
            for target in ["wrapped", "direct"] {
                let returned = analysis
                    .data_flow
                    .iter()
                    .find(|fact| {
                        fact.procedure.as_deref() == Some("Run")
                            && fact.target.eq_ignore_ascii_case(target)
                            && fact.transfer == "function_return_candidate"
                    })
                    .unwrap();
                assert_eq!(returned.inputs, ["inputAmount"], "{:#?}", returned);
            }
            let constant_source = analysis
                .data_flow
                .iter()
                .position(|fact| {
                    fact.module == "Provider"
                        && fact.procedure.is_none()
                        && fact.target == "HiddenLimit"
                        && fact.transfer == "constant_initializer"
                })
                .unwrap();
            let constant_return = analysis
                .data_flow
                .iter()
                .position(|fact| {
                    fact.procedure.as_deref() == Some("Run")
                        && fact.target == "constantResult"
                        && fact.transfer == "function_return_candidate"
                        && fact.inputs == ["Provider.HiddenLimit"]
                })
                .unwrap();
            assert!(analysis.path_value_flows.iter().any(|flow| {
                flow.source_data_flow_index == Some(constant_source)
                    && flow.target_data_flow_index == constant_return
            }));
        }
    }

