    #[test]
    fn narrows_callbyname_with_typed_receivers_literal_names_and_call_types() {
        let sources = [
            SourceUnit {
                name: "Widget.cls".into(),
                text: "Private stored As String\nPublic Sub Save(ByRef value As Long)\nvalue = value + 1\nEnd Sub\nPublic Function Scale(ByVal value As Long) As Long\nScale = value * 2\nEnd Function\nPublic Property Get Caption() As String\nCaption = stored\nEnd Property\n".into(),
            },
            SourceUnit {
                name: "Reader.bas".into(),
                text: "Option Explicit\nPrivate widget As Widget\nPublic Sub Run()\nDim amount As Long\nDim result As Long\nDim title As String\nDim memberName As String\namount = 3\nCallByName widget, \"Save\", vbMethod, amount\nresult = CallByName(widget, \"Scale\", vbMethod, amount)\ntitle = CallByName(widget, \"Caption\", vbGet)\nCallByName widget, memberName, vbMethod, amount\nEnd Sub\n".into(),
            },
        ];
        let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
        for (member, expected) in [
            ("Save", "Widget.Save"),
            ("Scale", "Widget.Scale"),
            ("Caption", "Widget.Caption"),
        ] {
            assert!(
                analysis.calls.iter().any(|call| {
                    call.target == "CallByName"
                        && call.resolution == "typed_late_bound_member_candidate"
                        && call.dispatch_candidates == [expected]
                }),
                "missing CallByName candidate for {member}: {:?}",
                analysis.calls
            );
        }
        assert!(analysis.calls.iter().any(|call| {
            call.target == "CallByName"
                && call.resolution == "dynamic_invocation_candidate"
                && call.dispatch_candidates.is_empty()
        }));
        assert!(analysis.data_flow.iter().any(|fact| {
            fact.transfer == "late_bound_argument_input_candidate"
                && fact.target == "Widget.Save.value"
                && fact.inputs == ["amount"]
        }));
        assert_eq!(
            analysis
                .data_flow
                .iter()
                .filter(|fact| {
                    fact.transfer == "late_bound_argument_input_candidate"
                        && fact.target == "Widget.Save.value"
                })
                .count(),
            1
        );
        assert!(analysis.data_flow.iter().any(|fact| {
            fact.transfer == "function_return_candidate"
                && fact.target == "result"
                && fact.inputs == ["amount"]
        }));
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.target == "title" && fact.value_type == "String" && fact.status == "compatible"
        }));
    }

    #[test]
    fn records_excel_application_run_macro_name_candidates_without_claiming_dispatch() {
        let sources = [
            SourceUnit {
                name: "Macros.bas".into(),
                text: "Attribute VB_Name = \"Macros\"\nPublic Sub SaveOrder(ByVal amount As Long)\nEnd Sub\nPublic Function Total() As Long\nTotal = 1\nEnd Function\nPrivate Sub Hidden()\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "Caller.bas".into(),
                text: "Option Explicit\nPublic Sub Run(ByVal macroName As String)\nDim app As Excel.Application\nApplication.Run \"SaveOrder\", 42\nApplication.Run \"Macros.SaveOrder\", 43\nApplication.Run \"Total\"\nApplication.Run \"Hidden\"\nApplication.Run \"Save\" & \"Order\"\nApplication.Run macroName\nApplication.Run MacroName:=\"SaveOrder\"\napp.Run \"Macros.SaveOrder\"\nThisWorkbook.Application.Run \"Macros.SaveOrder\"\nActiveWorkbook.Application.Run \"Macros.SaveOrder\"\nEnd Sub\n".into(),
            },
        ];
        let analysis = analyze(
            &sources,
            &AnalysisOptions {
                host_profile: HostProfile::Excel,
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        let run_calls = analysis
            .calls
            .iter()
            .filter(|call| call.module == "Caller" && call.target == "Application.Run")
            .collect::<Vec<_>>();
        assert_eq!(run_calls.len(), 10, "{run_calls:#?}");
        assert!(run_calls.iter().any(|call| {
            call.resolution == "literal_macro_target_candidate"
                && call.dispatch_candidates == ["Macros.SaveOrder"]
                && call
                    .arguments
                    .first()
                    .is_some_and(|arg| arg == "\"SaveOrder\"")
        }));
        assert!(run_calls.iter().any(|call| {
            call.resolution == "literal_macro_target_candidate"
                && call.dispatch_candidates == ["Macros.SaveOrder"]
                && call
                    .arguments
                    .first()
                    .is_some_and(|arg| arg == "\"Macros.SaveOrder\"")
        }));
        assert!(run_calls.iter().any(|call| {
            call.resolution == "literal_macro_target_candidate"
                && call.dispatch_candidates == ["Macros.Total"]
        }));
        assert!(run_calls.iter().any(|call| {
            call.resolution == "literal_macro_target_candidate"
                && call.dispatch_candidates == ["Macros.SaveOrder"]
                && call
                    .arguments
                    .first()
                    .is_some_and(|arg| arg.contains("\"Save\"") && arg.contains("\"Order\""))
        }));
        assert_eq!(
            run_calls
                .iter()
                .filter(|call| {
                    call.resolution == "literal_macro_target_candidate"
                        && call.dispatch_candidates == ["Macros.SaveOrder"]
                })
                .count(),
            6,
            "unqualified, module-qualified, concatenated, typed, and workbook application receivers should each produce one candidate"
        );
        assert!(run_calls.iter().any(|call| {
            call.resolution == "dynamic_macro_invocation_candidate"
                && call.dispatch_candidates.is_empty()
                && call.arguments.first().is_some_and(|arg| arg == "macroName")
        }));
        assert!(run_calls.iter().any(|call| {
            call.resolution == "invalid_application_run_named_arguments"
                && call.dispatch_candidates.is_empty()
        }));
        assert_eq!(
            analysis
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == "VBA2141")
                .count(),
            1
        );
        assert!(analysis.references.iter().any(|reference| {
            reference.module == "Caller"
                && reference.name == "Macros.SaveOrder"
                && reference.resolution == "application_run_macro_name_candidate"
        }));
    }

