    #[test]
    fn resolves_default_member_index_calls_and_argument_flows() {
        let sources = [
            SourceUnit {
                name: "Indexed.cls".into(),
                text: "Private stored As String\nPublic Property Get Item(ByVal index As Long) As String\nItem = stored\nEnd Property\nAttribute Item.VB_UserMemId = 0\nPublic Property Let Item(ByVal index As Long, ByVal value As String)\nstored = value\nEnd Property\nAttribute Item.VB_UserMemId = 0\n".into(),
            },
            SourceUnit {
                name: "Plain.cls".into(),
                text: "Public Sub Ping()\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "Reader.bas".into(),
                text: "Private values As Indexed\nPrivate indexedArray(1 To 4) As Indexed\nPrivate plain As Plain\nPublic Sub Read()\nDim index As Long\nDim item As String\nDim indexedValue As Indexed\nDim invalidIndex As Variant\nindex = 1\nitem = values(index)\nvalues(index) = item\nindexedValue = indexedArray(index)\ninvalidIndex = plain(index)\nEnd Sub\n".into(),
            },
        ];
        let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
        let accesses = analysis
            .calls
            .iter()
            .filter(|call| call.target == "Item")
            .collect::<Vec<_>>();
        assert_eq!(accesses.len(), 2, "{accesses:?}");
        assert!(accesses.iter().all(|call| {
            call.resolution == "resolved_default_member_candidate"
                && call.dispatch_candidates == ["Indexed.Item"]
        }));
        assert!(accesses.iter().any(|call| call.arguments == ["index"]));
        assert!(
            accesses
                .iter()
                .any(|call| call.arguments == ["index", "item"])
        );
        assert!(analysis.data_flow.iter().any(|fact| {
            fact.transfer == "function_return_candidate"
                && fact.target == "item"
                && fact.inputs == ["Indexed.stored"]
        }));
        assert!(analysis.data_flow.iter().any(|fact| {
            fact.transfer == "default_member_argument_input_candidate"
                && fact.target == "Indexed.Item.value"
                && fact.inputs == ["item"]
        }));
        assert_eq!(
            analysis
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == "VBA2110")
                .count(),
            1,
            "{:?}",
            analysis.diagnostics
        );
        assert!(
            !analysis
                .diagnostics
                .iter()
                .any(|diagnostic| { matches!(diagnostic.code, "VBA2111" | "VBA2112" | "VBA2113") })
        );
    }

    #[test]
    fn property_set_paramarray_value_is_not_folded_into_index_arguments() {
        let sources = [
            SourceUnit {
                name: "VariadicIndexed.cls".into(),
                text: "Public Property Get Item(ParamArray indices() As Variant) As Variant\nEnd Property\nAttribute Item.VB_UserMemId = 0\nPublic Property Let Item(ParamArray indices() As Variant, ByRef value As Variant)\nvalue = Empty\nEnd Property\nAttribute Item.VB_UserMemId = 0\n".into(),
            },
            SourceUnit {
                name: "Writer.bas".into(),
                text: "Private values As VariadicIndexed\nPrivate firstIndex As Long\nPrivate secondIndex As Long\nPrivate payload As Variant\nPublic Sub Save()\nvalues(firstIndex, secondIndex) = payload\nEnd Sub\nPublic Sub SaveExplicit()\nvalues.Item(firstIndex, secondIndex) = payload\nEnd Sub\n".into(),
            },
        ];
        let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
        let call = analysis
            .calls
            .iter()
            .find(|call| {
                call.module == "Writer"
                    && call.procedure.as_deref() == Some("Save")
                    && call.target == "Item"
            })
            .expect("the default property setter is resolved");
        assert_eq!(call.arguments, ["firstIndex", "secondIndex", "payload"]);
        let index_inputs = analysis
            .data_flow
            .iter()
            .filter(|fact| {
                fact.transfer == "default_member_argument_input_candidate"
                    && fact.target == "VariadicIndexed.Item.indices"
            })
            .flat_map(|fact| fact.inputs.iter().cloned())
            .collect::<std::collections::HashSet<_>>();
        assert!(index_inputs.contains("firstIndex"));
        assert!(index_inputs.contains("secondIndex"));
        assert!(!index_inputs.contains("payload"));
        assert!(analysis.data_flow.iter().any(|fact| {
            fact.transfer == "default_member_argument_input_candidate"
                && fact.target == "VariadicIndexed.Item.value"
                && fact.inputs == ["payload"]
        }));
        let explicit_indices = analysis
            .data_flow
            .iter()
            .filter(|fact| {
                fact.transfer == "property_set_argument_candidate"
                    && fact.target == "VariadicIndexed.Item.indices"
            })
            .flat_map(|fact| fact.inputs.iter().cloned())
            .collect::<std::collections::HashSet<_>>();
        assert!(explicit_indices.contains("firstIndex"));
        assert!(explicit_indices.contains("secondIndex"));
        assert!(!explicit_indices.contains("payload"));
        assert!(analysis.data_flow.iter().any(|fact| {
            fact.transfer == "property_set_argument_candidate"
                && fact.target == "VariadicIndexed.Item.value"
                && fact.inputs == ["payload"]
        }));
        assert!(!analysis.data_flow.iter().any(|fact| {
            fact.transfer == "default_member_byref_write_candidate" && fact.target == "payload"
        }));
        assert!(
            !analysis
                .interprocedural_byref_write_paths
                .iter()
                .any(|path| {
                    analysis
                        .data_flow
                        .get(path.caller_write_data_flow_index)
                        .is_some_and(|fact| fact.target == "payload")
                })
        );
        assert!(!analysis.diagnostics.iter().any(|diagnostic| {
            matches!(
                diagnostic.code,
                "VBA2020" | "VBA2022" | "VBA2077" | "VBA2078" | "VBA2079"
            )
        }));
    }

    #[test]
    fn resolves_bang_dictionary_access_through_string_default_member() {
        let sources = [
            SourceUnit {
                name: "Indexed.cls".into(),
                text: "Public Property Get Item(ByVal key As String) As Long\nItem = 1\nEnd Property\nAttribute Item.VB_UserMemId = 0\nPublic Property Let Item(ByVal key As String, ByVal value As Long)\nEnd Property\nAttribute Item.VB_UserMemId = 0\n".into(),
            },
            SourceUnit {
                name: "Reader.bas".into(),
                text: "Private records As Indexed\nPublic Sub Consume(ByVal amount As Long)\nEnd Sub\nPublic Sub Read()\nDim value As Long\nDim nameValue As Long\nvalue = records!Customer\nrecords!Customer = 5\nnameValue = records![Customer Name]\nrecords![Customer Name] = 6\nConsume records!Customer\nConsume records![Customer Name]\nEnd Sub\n".into(),
            },
        ];
        let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
        let value = analysis
            .type_facts
            .iter()
            .find(|fact| fact.target == "value")
            .unwrap();
        assert_eq!(value.value_type, "Long");
        assert_eq!(value.status, "compatible");

        let accesses = analysis
            .calls
            .iter()
            .filter(|call| call.module == "Reader" && call.target == "Item")
            .collect::<Vec<_>>();
        assert_eq!(accesses.len(), 6, "{accesses:?}");
        assert!(accesses.iter().all(|call| {
            call.resolution == "resolved_default_member_candidate"
                && call.dispatch_candidates == ["Indexed.Item"]
        }));
        assert!(
            accesses
                .iter()
                .any(|call| call.arguments == ["\"Customer\""])
        );
        assert!(
            accesses
                .iter()
                .any(|call| call.arguments == ["\"Customer\"", "5"])
        );
        assert!(
            accesses
                .iter()
                .any(|call| call.arguments == ["\"Customer Name\""])
        );
        assert!(
            accesses
                .iter()
                .any(|call| call.arguments == ["\"Customer Name\"", "6"])
        );
        assert!(
            !analysis.references.iter().any(|reference| {
                reference.module == "Reader"
                    && reference.procedure.as_deref() == Some("Read")
                    && matches!(reference.name.as_str(), "Customer" | "Customer Name")
            }),
            "{:#?}",
            analysis.references
        );
        let argument_flows = analysis
            .data_flow
            .iter()
            .filter(|fact| {
                fact.transfer == "procedure_argument_input_candidate"
                    && fact.target == "Reader.Consume.amount"
            })
            .collect::<Vec<_>>();
        assert_eq!(argument_flows.len(), 2, "{argument_flows:#?}");
        assert!(argument_flows.iter().all(|fact| fact.inputs == ["records"]));
        for target in ["value", "nameValue"] {
            let assignment = analysis
                .data_flow
                .iter()
                .find(|fact| fact.transfer == "assignment" && fact.target == target)
                .unwrap();
            assert_eq!(assignment.inputs, ["records"], "{assignment:#?}");
        }
        assert!(!analysis.diagnostics.iter().any(|diagnostic| {
            matches!(
                diagnostic.code,
                "VBA2110" | "VBA2111" | "VBA2112" | "VBA2113"
            )
        }));
    }

