    #[test]
    fn validates_property_accessor_parameter_and_value_contracts() {
        let source = "Private stored As Long\nPublic Property Get Item(ByVal index As Long) As String\nEnd Property\nPublic Property Let Item(ByVal key As Integer, ByVal value As String)\nEnd Property\nPublic Property Get Name() As String\nEnd Property\nPublic Property Let Name(ByVal value As Long)\nEnd Property\nPublic Property Set Owner(ByVal value As Long)\nEnd Property\nPublic Property Set Missing()\nEnd Property\nPublic Property Get Compatible(ByVal key As Long) As String\nEnd Property\nPublic Property Let Compatible(ByVal key As Long, ByVal value As String)\nEnd Property\nPublic Property Set RecordOwner(ByVal value As RecordData)\nEnd Property\nPublic Property Set ObjectOwner(ByRef value As Payload)\nEnd Property\nPublic Property Get OptionalValue(Optional index As Long = 1) As String\nEnd Property\nPublic Property Let OptionalValue(Optional ByRef index As Long = 2, ByVal value As String)\nEnd Property\nPublic Property Get ObjectItem(ByVal index As Long) As Payload\nEnd Property\nPublic Property Set ObjectItem(ByVal index As Long, ByRef value As Payload)\nEnd Property\nPublic Property Get Expand(ParamArray items() As Variant) As Variant\nEnd Property\nPublic Property Let Expand(ParamArray items() As Variant, ByVal value As Variant)\nEnd Property\nPublic Property Let OptionalSetter(Optional ByVal value As Long = 0)\nEnd Property\nPublic Property Let ParamArraySetter(ParamArray values() As Variant)\nEnd Property\nPublic Property Let ArraySetter(ByRef values() As Variant)\nEnd Property\n";
        let analysis = analyze(
            &[
                SourceUnit {
                    name: "PropertyContracts.cls".into(),
                    text: source.into(),
                },
                SourceUnit {
                    name: "Types.bas".into(),
                    text: "Public Type RecordData\nValue As Long\nEnd Type\n".into(),
                },
                SourceUnit {
                    name: "Payload.cls".into(),
                    text: String::new(),
                },
            ],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let diagnostics = &analysis.diagnostics;
        assert!(
            diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == "VBA2077" && diagnostic.span.line == 4 })
        );
        assert!(
            diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == "VBA2078" && diagnostic.span.line == 8 })
        );
        assert!(
            diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == "VBA2078" && diagnostic.span.line == 10 })
        );
        assert!(
            diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == "VBA2079" && diagnostic.span.line == 12 })
        );
        assert!(
            diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == "VBA2079" && diagnostic.span.line == 34 })
        );
        assert!(
            diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == "VBA2079" && diagnostic.span.line == 36 })
        );
        assert!(
            diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == "VBA2078" && diagnostic.span.line == 18 })
        );
        assert!(!diagnostics.iter().any(|diagnostic| {
            matches!(diagnostic.code, "VBA2077" | "VBA2078") && diagnostic.span.line >= 20
        }));
        assert_eq!(
            diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == "VBA2079")
                .map(|diagnostic| diagnostic.span.line)
                .collect::<std::collections::BTreeSet<_>>(),
            [12, 34, 36, 38].into_iter().collect()
        );
        assert!(
            !diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == "VBA2051"),
            "{:?}",
            diagnostics
        );
        assert!(
            !diagnostics
                .iter()
                .any(|diagnostic| matches!(diagnostic.code, "VBA2052" | "VBA2053"))
        );
    }
    #[test]
    fn property_setter_paramarray_binding_keeps_the_value_parameter_out_of_the_array() {
        let parameters = [
            Parameter {
                name: "indices".into(),
                type_name: Some("Variant".into()),
                passing: "ByRef".into(),
                is_array: true,
                is_param_array: true,
                ..Parameter::default()
            },
            Parameter {
                name: "value".into(),
                type_name: Some("Variant".into()),
                passing: "ByVal".into(),
                ..Parameter::default()
            },
        ];
        let arguments = vec!["1".into(), "2".into(), "\"stored\"".into()];
        let (bindings, issues) = bind_property_setter_arguments(&parameters, &arguments);
        assert!(issues.is_empty(), "{issues:?}");
        assert_eq!(
            bindings,
            [
                (0, "1".to_string()),
                (0, "2".to_string()),
                (1, "\"stored\"".to_string())
            ]
        );

        let named = vec!["indices:=Array(1)".into(), "\"stored\"".into()];
        let (_, issues) = bind_property_setter_arguments(&parameters, &named);
        assert!(issues.iter().any(|issue| issue.contains("ParamArray")));
    }
