    #[test]
    fn resolves_public_enum_types_and_members_across_standard_modules() {
        let sources = [
            SourceUnit {
                name: "Kinds.bas".into(),
                text: "Public Enum Mode\nReady = 1\nEnd Enum\n".into(),
            },
            SourceUnit {
                name: "Worker.bas".into(),
                text: "Option Explicit\nPrivate current As Mode\nPrivate Sub RequireLong(ByRef value As Long)\nEnd Sub\nPrivate Function ReadMode() As Mode\nReadMode = Ready\nEnd Function\nPublic Sub SetReady()\ncurrent = Ready\nDim result As Long\nresult = ReadMode()\nRequireLong current\nEnd Sub\n".into(),
            },
        ];
        let a = analyze(&sources, &AnalysisOptions::default()).unwrap();
        assert!(!a.diagnostics.iter().any(|d| d.code == "VBA2003"));
        assert!(
            a.references
                .iter()
                .any(|r| { r.name == "Ready" && r.resolution == "resolved_public_project_symbol" })
        );
        assert!(a.type_facts.iter().any(|f| {
            f.target == "current"
                && f.target_type.as_deref() == Some("Long")
                && f.value_type == "Long"
        }));
        assert!(a.type_facts.iter().any(|fact| {
            fact.target == "result"
                && fact.target_type.as_deref() == Some("Long")
                && fact.value_type == "Long"
        }));
        assert!(
            !a.diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == "VBA2085")
        );
        let json = crate::export::to_json(&a, None, crate::export::Disclosure::IncludeSource);
        assert!(json.contains("\"type\":\"Mode\",\"effective_type\":\"Long\""));
        assert!(json.contains("\"effective_return_type\":\"Long\""));
    }

    #[test]
    fn folds_supported_enum_values_and_marks_implicit_long_overflow() {
        let analysis = analyze(
            &[SourceUnit {
                name: "EnumValues.bas".into(),
                text: "Public Enum Sequence\nZero\nOne\nExplicit = 20\nExpression = 12 + 3\nAfterExpression\nMaximum = 2147483647&\nOverflow\nEnd Enum\nPublic Enum Unsupported\nLarge = 2147483648\nEnd Enum\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let sequence = analysis.project.modules[0]
            .declarations
            .iter()
            .filter(|declaration| {
                declaration.kind == "enum_member"
                    && declaration
                        .type_name
                        .as_deref()
                        .is_some_and(|type_name| type_name == "Sequence")
            })
            .map(|declaration| (declaration.name.as_str(), declaration.enum_value))
            .collect::<Vec<_>>();
        assert_eq!(
            sequence,
            [
                ("Zero", Some(0)),
                ("One", Some(1)),
                ("Explicit", Some(20)),
                ("Expression", Some(15)),
                ("AfterExpression", Some(16)),
                ("Maximum", Some(i32::MAX)),
                ("Overflow", None),
            ]
        );
        assert!(analysis.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "VBA1043"
                && diagnostic.span.line == 8
                && diagnostic.severity == Severity::Error
        }));
        let unsupported = analysis.project.modules[0]
            .declarations
            .iter()
            .find(|declaration| declaration.name == "Large")
            .unwrap();
        assert_eq!(unsupported.enum_value, None);

        let structure =
            crate::export::to_json(&analysis, None, crate::export::Disclosure::StructureOnly);
        assert!(structure.contains("\"enum_value_status\":\"computed\",\"enum_value\":null"));
        let source =
            crate::export::to_json(&analysis, None, crate::export::Disclosure::IncludeSource);
        assert!(source.contains("\"enum_value_status\":\"computed\",\"enum_value\":0"));
        assert!(source.contains("\"enum_value_status\":\"unresolved\",\"enum_value\":null"));
    }

    #[test]
    fn folds_unique_module_constant_references_in_enum_initializers() {
        let analysis = analyze(
            &[
                SourceUnit {
                    name: "Enums.bas".into(),
                    text: "Private Const LocalBase As Long = 40\nPrivate Const LocalOffset As Long = LocalBase + 2\nPublic Enum Codes\nLocalConstant = LocalBase\nDerivedConstant = LocalOffset + 1\nQualifiedPublic = Constants.SharedBase + 1\nUnqualifiedPublic = SharedBase + 2\nFollowing\nEnd Enum\n".into(),
                },
                SourceUnit {
                    name: "Constants.bas".into(),
                    text: "Public Const SharedBase As Long = 100\n".into(),
                },
                SourceUnit {
                    name: "OtherConstants.bas".into(),
                    text: "Public Const SharedBase As Long = 200\n".into(),
                },
                SourceUnit {
                    name: "CyclicConstants.bas".into(),
                    text: "Private Const CycleA As Long = CycleB\nPrivate Const CycleB As Long = CycleA\nPublic Enum CyclicCodes\nCycleValue = CycleA\nFollowing\nEnd Enum\n".into(),
                },
            ],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let values = analysis.project.modules[0]
            .declarations
            .iter()
            .filter(|declaration| declaration.kind == "enum_member")
            .map(|declaration| (declaration.name.as_str(), declaration.enum_value))
            .collect::<Vec<_>>();
        assert_eq!(
            values,
            [
                ("LocalConstant", Some(40)),
                ("DerivedConstant", Some(43)),
                ("QualifiedPublic", Some(101)),
                ("UnqualifiedPublic", None),
                ("Following", None),
            ]
        );
        let cyclic_values = analysis.project.modules[3]
            .declarations
            .iter()
            .filter(|declaration| declaration.kind == "enum_member")
            .map(|declaration| (declaration.name.as_str(), declaration.enum_value))
            .collect::<Vec<_>>();
        assert_eq!(cyclic_values, [("CycleValue", None), ("Following", None)]);
    }

