    #[test]
    fn resolves_unique_public_enum_members_across_modules_with_bounded_cycles() {
        let analysis = analyze(
            &[
                SourceUnit {
                    name: "Consumer.bas".into(),
                    text: "Public Enum Derived\nQualifiedByType = Numbers.Base + 1\nQualifiedByModule = EnumSource.Base + 2\nUnqualified = Base + 3\nTwoHop = MidNumbers.Middle + 1\nAmbiguous = Shared + 1\nPrivateMember = EnumSource.Hidden + 1\nAfterMax = Numbers.MaxValue\nAfterMaxImplicit\nEnd Enum\n".into(),
                },
                SourceUnit {
                    name: "EnumSource.bas".into(),
                    text: "Public Enum Numbers\nBase = 10\nMaxValue = 2147483647\nEnd Enum\nPublic Enum NumbersTwo\nShared = 20\nEnd Enum\nPrivate Enum HiddenCodes\nHidden = 40\nEnd Enum\n".into(),
                },
                SourceUnit {
                    name: "OtherEnum.bas".into(),
                    text: "Public Enum OtherNumbers\nShared = 30\nEnd Enum\n".into(),
                },
                SourceUnit {
                    name: "MidEnum.bas".into(),
                    text: "Public Enum MidNumbers\nMiddle = BaseNumbers.CoreBase + 1\nEnd Enum\n".into(),
                },
                SourceUnit {
                    name: "BaseEnum.bas".into(),
                    text: "Public Enum BaseNumbers\nCoreBase = 5\nEnd Enum\n".into(),
                },
                SourceUnit {
                    name: "CycleLeft.bas".into(),
                    text: "Public Enum LeftValues\nLeft = CycleRight.Right + 1\nEnd Enum\n".into(),
                },
                SourceUnit {
                    name: "CycleRight.bas".into(),
                    text: "Public Enum RightValues\nRight = CycleLeft.Left + 1\nEnd Enum\n".into(),
                },
            ],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let values = |module_name: &str| {
            analysis
                .project
                .modules
                .iter()
                .find(|module| module.name == module_name)
                .unwrap()
                .declarations
                .iter()
                .filter(|declaration| declaration.kind == "enum_member")
                .map(|declaration| (declaration.name.as_str(), declaration.enum_value))
                .collect::<std::collections::BTreeMap<_, _>>()
        };
        let consumer = values("Consumer");
        assert_eq!(consumer.get("QualifiedByType"), Some(&Some(11)));
        assert_eq!(consumer.get("QualifiedByModule"), Some(&Some(12)));
        assert_eq!(consumer.get("Unqualified"), Some(&Some(13)));
        assert_eq!(consumer.get("TwoHop"), Some(&Some(7)));
        assert_eq!(consumer.get("Ambiguous"), Some(&None));
        assert_eq!(consumer.get("PrivateMember"), Some(&None));
        assert_eq!(consumer.get("AfterMax"), Some(&Some(i32::MAX)));
        assert_eq!(consumer.get("AfterMaxImplicit"), Some(&None));
        assert_eq!(values("CycleLeft").get("Left"), Some(&None));
        assert_eq!(values("CycleRight").get("Right"), Some(&None));
        assert!(analysis.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "VBA1043"
                && diagnostic.source == "Consumer.bas"
                && diagnostic.span.line == 9
        }));
    }

