    #[test]
    fn associates_dataflow_with_only_the_path_conditions_before_each_transfer() {
        let source = SourceUnit {
            name: "Guarded.bas".into(),
            text: "Public Sub Decide()\nIf ready Then\namount = 1\nElse\namount = 0\nEnd If\nIf laterCheck Then\nsink = amount\nEnd If\nEnd Sub\n".into(),
        };
        let analysis = analyze(std::slice::from_ref(&source), &AnalysisOptions::default()).unwrap();
        let repeated = analyze(std::slice::from_ref(&source), &AnalysisOptions::default()).unwrap();
        assert_eq!(analysis.data_flow_paths, repeated.data_flow_paths);
        assert!(!analysis.data_flow_paths_truncated);
        assert_eq!(analysis.data_flow_path_unassociated_count, 0);
        assert!(!analysis.data_flow_paths.is_empty());
        assert!(
            analysis
                .data_flow_paths
                .iter()
                .all(|fact| fact.feasibility == "not_checked")
        );

        let amount_flow = analysis
            .data_flow
            .iter()
            .enumerate()
            .filter(|(_, fact)| fact.target == "amount")
            .map(|(index, _)| index)
            .collect::<std::collections::HashSet<_>>();
        assert_eq!(amount_flow.len(), 2);
        let amount_paths = analysis
            .data_flow_paths
            .iter()
            .filter(|fact| amount_flow.contains(&fact.data_flow_index))
            .collect::<Vec<_>>();
        assert!(!amount_paths.is_empty());
        assert!(amount_paths.iter().all(|fact| {
            fact.conditions
                .iter()
                .any(|condition| condition.contains("ready"))
                && !fact
                    .conditions
                    .iter()
                    .any(|condition| condition.contains("laterCheck"))
        }));
        assert!(amount_paths.iter().any(|fact| {
            fact.conditions
                .iter()
                .any(|condition| condition.contains("= True"))
        }));
        assert!(amount_paths.iter().any(|fact| {
            fact.conditions
                .iter()
                .any(|condition| condition.contains("= False"))
        }));

        let sink_index = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.target == "sink" && fact.inputs.iter().any(|name| name == "amount")
            })
            .unwrap();
        let sink_paths = analysis
            .data_flow_paths
            .iter()
            .filter(|fact| fact.data_flow_index == sink_index)
            .collect::<Vec<_>>();
        assert!(!sink_paths.is_empty());
        assert!(sink_paths.iter().all(|fact| {
            fact.conditions
                .iter()
                .any(|condition| condition.contains("ready"))
                && fact
                    .conditions
                    .iter()
                    .any(|condition| condition.contains("laterCheck"))
        }));
        assert!(!analysis.path_value_flows_truncated);
        let sink_flows = analysis
            .path_value_flows
            .iter()
            .filter(|flow| {
                analysis.data_flow[flow.target_data_flow_index].target == "sink"
                    && analysis.data_flow[flow.target_data_flow_index].transfer == "assignment"
            })
            .collect::<Vec<_>>();
        assert_eq!(sink_flows.len(), 2);
        assert!(sink_flows.iter().all(|flow| {
            flow.source_data_flow_index
                .is_some_and(|index| analysis.data_flow[index].target == "amount")
                && analysis.data_flow[flow.target_data_flow_index].target == "sink"
                && flow.variable.eq_ignore_ascii_case("amount")
                && flow
                    .conditions
                    .iter()
                    .any(|condition| condition.contains("ready"))
                && flow
                    .conditions
                    .iter()
                    .any(|condition| condition.contains("laterCheck"))
                && flow.feasibility == "not_checked"
        }));
        let ready_condition_read = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "expression_read_candidate" && fact.inputs == ["ready"]
            })
            .unwrap();
        assert!(analysis.path_value_flows.iter().any(|flow| {
            flow.target_data_flow_index == ready_condition_read
                && flow.variable == "ready"
                && flow.resolution == "no_prior_local_definition_on_path"
        }));

        let excel_analysis = analyze(
            &[SourceUnit {
                name: "ExcelPaths.bas".into(),
                text: "Public Sub WriteIfApproved()\nIf writeApproved Then\namount = Worksheets(\"Orders\").Range(\"A1\").Value\nWorksheets(\"Orders\").Range(\"A2\").Value = amount\nEnd If\nEnd Sub\n".into(),
            }],
            &AnalysisOptions {
                host_profile: HostProfile::Excel,
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        assert!(excel_analysis.data_access_paths.iter().any(|relation| {
            excel_analysis.data_accesses[relation.data_access_index].operation == "write_candidate"
                && relation
                    .conditions
                    .iter()
                    .any(|condition| condition.contains("writeApproved"))
                && relation.feasibility == "not_checked"
        }));
        assert!(excel_analysis.data_access_value_flows.iter().any(|fact| {
            fact.role == "excel_read_to_variable_candidate" && fact.variable == "amount"
        }));
        assert!(excel_analysis.data_access_value_flows.iter().any(|fact| {
            fact.role == "variable_to_excel_write_candidate" && fact.variable == "amount"
        }));
        assert!(excel_analysis.data_access_value_flows.iter().all(|fact| {
            fact.conditions
                .iter()
                .any(|condition| condition.contains("writeApproved"))
        }));

        let predicate_analysis = analyze(
            &[SourceUnit {
                name: "ExcelPredicate.bas".into(),
                text: "Public Sub Guard()\nIf Worksheets(\"Orders\").Range(\"A1\").Value > 0 Then\namount = 1\nEnd If\nEnd Sub\n".into(),
            }],
            &AnalysisOptions {
                host_profile: HostProfile::Excel,
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        assert!(predicate_analysis.data_access_paths.iter().any(|relation| {
            predicate_analysis.data_accesses[relation.data_access_index].operation
                == "read_candidate"
                && predicate_analysis.control_flow[0].nodes[relation.flow_node_id].kind
                    == "decision"
        }));
        assert!(
            predicate_analysis
                .data_access_predicates
                .iter()
                .any(|fact| fact.outcome_condition.contains("= True"))
        );
        assert!(
            predicate_analysis
                .data_access_predicates
                .iter()
                .any(|fact| fact.outcome_condition.contains("= False"))
        );

        let case_analysis = analyze(
            &[SourceUnit {
                name: "ExcelCase.bas".into(),
                text: "Public Sub GuardCase()\nSelect Case state\nCase Worksheets(\"Orders\").Range(\"A1\").Value, Worksheets(\"Orders\").Range(\"A2\").Value\namount = 1\nCase 0\namount = 2\nCase Else\namount = 0\nEnd Select\nEnd Sub\n".into(),
            }],
            &AnalysisOptions {
                host_profile: HostProfile::Excel,
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        assert!(
            case_analysis.data_access_predicates.iter().any(|fact| {
                case_analysis.data_accesses[fact.data_access_index]
                    .target
                    .contains("A1")
                    && fact.outcome_condition.contains("A1")
                    && fact.conditions_before.is_empty()
            }),
            "{:?}",
            case_analysis.data_access_predicates
        );
        assert!(
            case_analysis.data_access_predicates.iter().any(|fact| {
                case_analysis.data_accesses[fact.data_access_index]
                    .target
                    .contains("A2")
                    && fact.outcome_condition.contains("A2")
                    && fact.conditions_before.iter().any(|condition| {
                        condition.contains("does not match Case") && condition.contains("A1")
                    })
            }),
            "{:?}",
            case_analysis.data_access_predicates
        );

        let bounded = analyze(
            std::slice::from_ref(&source),
            &AnalysisOptions {
                limits: Limits {
                    max_path_fact_associations: 1,
                    ..Limits::default()
                },
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        assert_eq!(bounded.data_flow_paths.len(), 1);
        assert!(bounded.data_flow_paths_truncated);
        assert!(bounded.data_flow_path_unassociated_count > 0);

        let scan_bounded = analyze(
            std::slice::from_ref(&source),
            &AnalysisOptions {
                limits: Limits {
                    max_path_fact_association_steps: 0,
                    ..Limits::default()
                },
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        assert!(scan_bounded.data_flow_paths.is_empty());
        assert!(scan_bounded.data_flow_paths_truncated);
        assert!(scan_bounded.data_flow_path_unassociated_count > 0);

        let value_bounded = analyze(
            std::slice::from_ref(&source),
            &AnalysisOptions {
                limits: Limits {
                    max_path_value_flows: 1,
                    ..Limits::default()
                },
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        assert_eq!(value_bounded.path_value_flows.len(), 1);
        assert!(value_bounded.path_value_flows_truncated);

        let step_bounded = analyze(
            std::slice::from_ref(&source),
            &AnalysisOptions {
                limits: Limits {
                    max_path_value_flow_steps: 0,
                    ..Limits::default()
                },
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        assert!(step_bounded.path_value_flows.is_empty());
        assert!(step_bounded.path_value_flows_truncated);
    }

    #[test]
