    #[test]
    fn connects_direct_call_arguments_to_parameter_uses_on_caller_and_callee_paths() {
        let source = SourceUnit {
            name: "Interprocedural.bas".into(),
            text: "Option Explicit\nPrivate Sub Increment(ByRef value As Long)\nDim observed As Long\nvalue = value + 1\nobserved = value\nEnd Sub\nPublic Sub Caller()\nDim amount As Long\namount = 4\nIf ready Then\nIncrement amount\nEnd If\nEnd Sub\n".into(),
        };
        let analysis = analyze(std::slice::from_ref(&source), &AnalysisOptions::default()).unwrap();

        let argument_index = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "procedure_argument_input_candidate"
                    && fact.target == "Interprocedural.Increment.value"
                    && fact.inputs == ["amount"]
            })
            .unwrap();
        let parameter_use_indices = analysis
            .data_flow
            .iter()
            .enumerate()
            .filter(|(_, fact)| {
                fact.module == "Interprocedural"
                    && fact.procedure.as_deref() == Some("Increment")
                    && fact
                        .inputs
                        .iter()
                        .any(|input| input.eq_ignore_ascii_case("value"))
            })
            .map(|(index, _)| index)
            .collect::<std::collections::HashSet<_>>();
        assert_eq!(parameter_use_indices.len(), 2);

        let relations = analysis
            .interprocedural_data_flow_paths
            .iter()
            .filter(|fact| fact.argument_data_flow_index == argument_index)
            .collect::<Vec<_>>();
        assert_eq!(relations.len(), 2, "{relations:?}");
        assert!(relations.iter().all(|fact| {
            parameter_use_indices.contains(&fact.callee_use_data_flow_index)
                && fact.caller_module == "Interprocedural"
                && fact.caller_procedure == "Caller"
                && fact.callee_module == "Interprocedural"
                && fact.callee_procedure == "Increment"
                && fact.parameter == "value"
                && fact
                    .caller_conditions
                    .iter()
                    .any(|condition| condition.contains("ready"))
                && fact.callee_conditions.is_empty()
                && fact.feasibility == "not_checked"
        }));
        assert!(!analysis.interprocedural_data_flow_paths_truncated);

        let limited = analyze(
            std::slice::from_ref(&source),
            &AnalysisOptions {
                limits: Limits {
                    max_path_value_flow_steps: 0,
                    ..Limits::default()
                },
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        assert!(limited.interprocedural_data_flow_paths.is_empty());
        assert!(limited.interprocedural_data_flow_paths_truncated);
    }

    #[test]
    fn folds_private_byval_parameter_conditions_for_named_and_positional_literals() {
        let agreed = analyze(
            &[SourceUnit {
                name: "ByValCallsite.bas".into(),
                text: "Option Explicit\nPrivate Const SAFE_AMOUNT As Integer = 50\nPrivate Sub CheckAmount(ByVal amount As Integer)\nDim result As Long\nIf amount > 100 Then\nresult = 1\nElse\nresult = 0\nEnd If\nEnd Sub\nPrivate Sub FirstCaller()\nCall CheckAmount(50)\nEnd Sub\nPrivate Sub SecondCaller()\nCheckAmount amount:=SAFE_AMOUNT\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let callsite_values = crate::paths::build_static_private_parameter_values(
            &agreed.project,
            &agreed.calls,
            100_000,
        );
        assert!(
            callsite_values.contains_key(&("byvalcallsite".into(), "checkamount".into())),
            "{callsite_values:?}"
        );
        let agreed_paths = agreed
            .paths
            .iter()
            .filter(|path| path.procedure == "CheckAmount")
            .collect::<Vec<_>>();
        assert_eq!(agreed_paths.len(), 2);
        assert_eq!(
            agreed_paths
                .iter()
                .filter(|path| path.feasibility == "infeasible_constant_condition")
                .count(),
            1,
            "{agreed_paths:?}; calls={:#?}",
            agreed.calls
        );
        assert!(!agreed.path_enumeration_truncated);

        let mixed = analyze(
            &[SourceUnit {
                name: "MixedByValCallsite.bas".into(),
                text: "Option Explicit\nPrivate Sub CheckAmount(ByVal amount As Integer)\nDim result As Long\nIf amount > 100 Then\nresult = 1\nElse\nresult = 0\nEnd If\nEnd Sub\nPrivate Sub FirstCaller()\nCall CheckAmount(50)\nEnd Sub\nPrivate Sub SecondCaller()\nCall CheckAmount(150)\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let mixed_paths = mixed
            .paths
            .iter()
            .filter(|path| path.procedure == "CheckAmount")
            .collect::<Vec<_>>();
        assert_eq!(mixed_paths.len(), 2);
        assert!(
            mixed_paths
                .iter()
                .all(|path| path.feasibility == "not_checked"),
            "{mixed_paths:?}"
        );

        let overwritten = analyze(
            &[SourceUnit {
                name: "OverwrittenByValCallsite.bas".into(),
                text: "Option Explicit\nPrivate Sub CheckAmount(ByVal amount As Integer)\nDim result As Long\namount = 200\nIf amount > 100 Then\nresult = 1\nElse\nresult = 0\nEnd If\nEnd Sub\nPublic Sub Caller()\nCall CheckAmount(50)\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let overwritten_paths = overwritten
            .paths
            .iter()
            .filter(|path| path.procedure == "CheckAmount")
            .collect::<Vec<_>>();
        assert_eq!(overwritten_paths.len(), 2);
        assert_eq!(
            overwritten_paths
                .iter()
                .filter(|path| path.feasibility == "infeasible_constant_condition")
                .count(),
            1,
            "{overwritten_paths:?}"
        );
    }

