    #[test]
    fn records_caller_path_argument_snapshots_for_mutable_values() {
        let analysis = analyze(
            &[SourceUnit {
                name: "CallerPathArgumentValues.bas".into(),
                text: "Option Explicit\nPrivate Sub Accept(ByVal amount As Integer)\nEnd Sub\nPublic Sub Caller()\nDim amount As Integer\nIf high Then\namount = 150\nElse\namount = 50\nEnd If\nCall Accept(amount)\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let snapshots = &analysis.interprocedural_argument_value_paths;
        assert_eq!(snapshots.len(), 2, "{snapshots:?}");
        let values = snapshots
            .iter()
            .filter_map(|fact| fact.resolved_value.as_deref())
            .collect::<std::collections::HashSet<_>>();
        assert_eq!(values, std::collections::HashSet::from(["150", "50"]));
        assert!(
            snapshots
                .iter()
                .all(|fact| fact.callee_procedure == "Accept"
                    && fact.parameter == "amount"
                    && fact.resolution == "caller_path_snapshot")
        );
        assert_eq!(analysis.interprocedural_argument_composition_paths.len(), 2);
        let composed_values = analysis
            .interprocedural_argument_composition_paths
            .iter()
            .filter_map(|fact| fact.resolved_value.as_deref())
            .collect::<std::collections::HashSet<_>>();
        assert_eq!(
            composed_values,
            std::collections::HashSet::from(["150", "50"])
        );
        assert!(
            analysis
                .interprocedural_argument_composition_paths
                .iter()
                .any(|fact| fact.resolved_value.as_deref() == Some("150")
                    && fact.callee_feasibility == "not_checked")
        );
    }

