    #[test]
    fn composes_callsite_byval_values_into_function_return_paths() {
        let analysis = analyze(
            &[SourceUnit {
                name: "ReturnByValPath.bas".into(),
                text: "Option Explicit\nPrivate Function Classify(ByVal amount As Integer) As Long\nIf amount > 100 Then\nClassify = 1\nElse\nClassify = 0\nEnd If\nEnd Function\nPublic Sub Caller()\nDim result As Long\nresult = Classify(50)\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let caller_return = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "function_return_candidate"
                    && fact.target == "result"
                    && fact.call_callee_procedure.as_deref() == Some("Classify")
            })
            .unwrap();
        let return_paths = analysis
            .interprocedural_return_paths
            .iter()
            .filter(|fact| fact.caller_return_data_flow_index == caller_return)
            .collect::<Vec<_>>();
        assert!(
            return_paths.iter().any(|fact| {
                fact.callee_procedure == "Classify"
                    && fact.feasibility == "infeasible_constant_condition"
                    && fact
                        .callee_conditions
                        .iter()
                        .any(|condition| condition.contains("amount > 100"))
            }),
            "{return_paths:?}"
        );
        assert!(
            return_paths.iter().any(|fact| {
                fact.callee_procedure == "Classify"
                    && fact.feasibility == "not_checked"
                    && fact
                        .callee_conditions
                        .iter()
                        .any(|condition| condition.contains("amount > 100"))
            }),
            "{return_paths:?}"
        );
    }

