    #[test]
    fn connects_omitted_optional_defaults_to_parameter_uses() {
        let source = SourceUnit {
            name: "OptionalFlow.bas".into(),
            text: "Option Explicit\nPrivate Sub Consume(Optional explicitLimit As Long = 7, Optional implicitLimit As Long, Optional missingValue As Variant)\nDim result As Long\nresult = explicitLimit + implicitLimit\nIf missingValue = 0 Then\nresult = result + 1\nEnd If\nEnd Sub\nPublic Sub Caller()\nConsume\nEnd Sub\n".into(),
        };
        let analysis = analyze(&[source], &AnalysisOptions::default()).unwrap();
        let explicit_index = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "optional_explicit_default_argument_candidate"
                    && fact.target == "OptionalFlow.Consume.explicitLimit"
                    && fact.value_expression.as_deref() == Some("7")
            })
            .unwrap();
        let implicit_index = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "optional_declared_type_default_candidate"
                    && fact.target == "OptionalFlow.Consume.implicitLimit"
                    && fact.value_expression.is_none()
            })
            .unwrap();
        let variant_index = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "optional_variant_omission_error_448_candidate"
                    && fact.target == "OptionalFlow.Consume.missingValue"
            })
            .unwrap();
        for argument_index in [explicit_index, implicit_index, variant_index] {
            assert!(analysis.interprocedural_data_flow_paths.iter().any(|fact| {
                fact.argument_data_flow_index == argument_index
                    && fact.caller_procedure == "Caller"
                    && fact.callee_procedure == "Consume"
                    && fact.feasibility == "not_checked"
            }));
        }
        let structure =
            crate::export::to_json(&analysis, None, crate::export::Disclosure::StructureOnly);
        let source_report =
            crate::export::to_json(&analysis, None, crate::export::Disclosure::IncludeSource);
        assert!(structure.contains("optional_default_to_parameter_use_candidate"));
        assert!(structure.contains("\"value_expression\":null"));
        assert!(!structure.contains("\"value_expression\":\"7\""));
        assert!(source_report.contains("\"value_expression\":\"7\""));
    }

