    #[test]
    fn folds_string_constant_paths_only_under_known_comparison_semantics() {
        let binary = analyze(
            &[SourceUnit {
                name: "BinaryStrings.bas".into(),
                text: "Option Compare Binary\nPrivate Const APPROVED As String = \"Approved\"\nPrivate Const JOINED As String = \"App\" & \"roved\"\nPublic Sub Check()\nIf APPROVED = \"approved\" Then\na = 1\nElse\na = 0\nEnd If\nIf JOINED = \"Approved\" Then\nb = 1\nElse\nb = 0\nEnd If\nIf \"A\"\"B\" = \"A\"\"B\" Then\nc = 1\nElse\nc = 0\nEnd If\nIf \"FILE7\" Like \"FILE#\" Then\nd = 1\nElse\nd = 0\nEnd If\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        assert!(binary.project.modules[0].options.compare_valid);
        assert_eq!(binary.paths.len(), 16);
        assert_eq!(
            binary
                .paths
                .iter()
                .filter(|path| path.feasibility == "infeasible_constant_condition")
                .count(),
            15,
            "module={:#?}, paths={:#?}, diagnostics={:#?}",
            binary.project.modules[0].options,
            binary.paths,
            binary.diagnostics
        );
        assert_eq!(
            binary
                .paths
                .iter()
                .filter(|path| path.feasibility == "not_checked")
                .count(),
            1
        );

        let text_compare = analyze(
            &[SourceUnit {
                name: "TextStrings.bas".into(),
                text: "Option Compare Text\nPrivate Const APPROVED As String = \"Approved\"\nPublic Sub Check()\nIf APPROVED = \"approved\" Then\na = 1\nElse\na = 0\nEnd If\nIf \"FILE7\" Like \"file#\" Then\nb = 1\nElse\nb = 0\nEnd If\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        assert!(text_compare.project.modules[0].options.compare_valid);
        assert!(
            text_compare
                .paths
                .iter()
                .all(|path| path.feasibility == "not_checked")
        );

        let conditional_compare = analyze(
            &[SourceUnit {
                name: "ConditionalCompare.bas".into(),
                text: "#If UNKNOWN_COMPARE_MODE Then\nOption Compare Text\n#End If\nPrivate Const APPROVED As String = \"Approved\"\nPublic Sub Check()\nIf APPROVED = \"approved\" Then\na = 1\nElse\na = 0\nEnd If\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        assert!(!conditional_compare.project.modules[0].options.compare_valid);
        assert!(
            conditional_compare
                .paths
                .iter()
                .all(|path| path.feasibility == "not_checked")
        );

        let invalid_compare = analyze(
            &[SourceUnit {
                name: "InvalidCompare.bas".into(),
                text: "Option Compare Local\nPrivate Const APPROVED As String = \"Approved\"\nPublic Sub Check()\nIf APPROVED = \"approved\" Then\na = 1\nElse\na = 0\nEnd If\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        assert!(!invalid_compare.project.modules[0].options.compare_valid);
        assert!(
            invalid_compare
                .paths
                .iter()
                .all(|path| path.feasibility == "not_checked")
        );
        assert!(
            invalid_compare
                .diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.code == "VBA2068" })
        );

        let non_ascii = analyze(
            &[SourceUnit {
                name: "NonAsciiStrings.bas".into(),
                text: "Option Compare Binary\nPrivate Const UPPER As String = \"É\"\nPublic Sub Check()\nIf UPPER = \"é\" Then\na = 1\nElse\na = 0\nEnd If\nIf UPPER Like \"[É]\" Then\nb = 1\nElse\nb = 0\nEnd If\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        assert!(
            non_ascii
                .paths
                .iter()
                .all(|path| path.feasibility == "not_checked")
        );
    }

    #[test]
    fn folds_isnull_and_isempty_calls_only_for_known_variant_values() {
        let analysis = analyze(
            &[SourceUnit {
                name: "VariantTests.bas".into(),
                text: "Option Explicit\nPrivate Const NULL_VALUE As Variant = Null\nPrivate Const EMPTY_VALUE As Variant = Empty\nPublic Sub CheckKnown()\nDim nullTest As Boolean\nDim emptyTest As Boolean\nnullTest = IsNull(NULL_VALUE)\nemptyTest = IsEmpty(EMPTY_VALUE)\nIf IsNull(NULL_VALUE) Then\na = 1\nElse\na = 0\nEnd If\nIf IsNull(Empty) Then\nb = 1\nElse\nb = 0\nEnd If\nIf IsEmpty(EMPTY_VALUE) Then\nc = 1\nElse\nc = 0\nEnd If\nIf IsEmpty(NULL_VALUE) Then\nd = 1\nElse\nd = 0\nEnd If\nIf IsNull(\"value\") Then\ne = 1\nElse\ne = 0\nEnd If\nEnd Sub\nPublic Sub CheckUnknown()\nDim dynamicValue As Variant\nIf IsNull(dynamicValue) Then\nf = 1\nElse\nf = 0\nEnd If\nEnd Sub\nPublic Sub BadArity()\nDim result As Boolean\nresult = IsNull()\nresult = IsEmpty(Null, Empty)\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let known = analysis
            .paths
            .iter()
            .filter(|path| path.procedure == "CheckKnown")
            .collect::<Vec<_>>();
        assert_eq!(known.len(), 32);
        assert_eq!(
            known
                .iter()
                .filter(|path| path.feasibility == "infeasible_constant_condition")
                .count(),
            31
        );
        assert_eq!(
            known
                .iter()
                .filter(|path| path.feasibility == "not_checked")
                .count(),
            1
        );
        let unknown = analysis
            .paths
            .iter()
            .filter(|path| path.procedure == "CheckUnknown")
            .collect::<Vec<_>>();
        assert_eq!(unknown.len(), 2);
        assert!(unknown.iter().all(|path| path.feasibility == "not_checked"));

        let shadowed = analyze(
            &[SourceUnit {
                name: "ShadowedIsNull.bas".into(),
                text: "Private Const IsNull As Boolean = False\nPublic Sub Check()\nIf IsNull(Null) Then\na = 1\nElse\na = 0\nEnd If\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        assert_eq!(shadowed.paths.len(), 2);
        assert!(
            shadowed
                .paths
                .iter()
                .all(|path| path.feasibility == "not_checked")
        );

        assert_eq!(
            analysis
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == "VBA2148")
                .count(),
            2
        );
        for target in ["nullTest", "emptyTest"] {
            assert!(analysis.type_facts.iter().any(|fact| {
                fact.target.eq_ignore_ascii_case(target) && fact.value_type == "Boolean"
            }));
        }
    }

