    #[test]
    fn composes_ismissing_for_private_optional_variant_call_sites_only_when_unambiguous() {
        let analysis = analyze(
            &[SourceUnit {
                name: "MissingCallSites.bas".into(),
                text: "Option Explicit\nPrivate Sub Omitted(Optional value As Variant)\nDim seen As Long\nIf IsMissing(value) Then\nseen = 1\nElse\nseen = 0\nEnd If\nEnd Sub\nPrivate Sub Supplied(Optional value As Variant)\nDim seen As Long\nIf IsMissing(value) Then\nseen = 1\nElse\nseen = 0\nEnd If\nEnd Sub\nPrivate Sub Mixed(Optional value As Variant)\nDim seen As Long\nIf IsMissing(value) Then\nseen = 1\nElse\nseen = 0\nEnd If\nEnd Sub\nPrivate Sub Defaulted(Optional value As Variant = Null)\nDim seen As Long\nIf IsMissing(value) Then\nseen = 1\nElse\nseen = 0\nEnd If\nEnd Sub\nPublic Sub PublicEntry(Optional value As Variant)\nDim seen As Long\nIf IsMissing(value) Then\nseen = 1\nElse\nseen = 0\nEnd If\nEnd Sub\nPublic Sub Caller()\nCall Omitted()\nCall Supplied(Null)\nCall Mixed()\nCall Mixed(Null)\nCall Defaulted()\nCall PublicEntry()\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        for (procedure, infeasible, unchecked) in [
            ("Omitted", 1, 1),
            ("Supplied", 1, 1),
            ("Mixed", 0, 2),
            ("Defaulted", 1, 1),
            ("PublicEntry", 0, 2),
        ] {
            let paths = analysis
                .paths
                .iter()
                .filter(|path| path.procedure == procedure)
                .collect::<Vec<_>>();
            assert_eq!(paths.len(), 2, "{procedure}: {paths:?}");
            assert_eq!(
                paths
                    .iter()
                    .filter(|path| path.feasibility == "infeasible_constant_condition")
                    .count(),
                infeasible,
                "{procedure}: {paths:?}"
            );
            assert_eq!(
                paths
                    .iter()
                    .filter(|path| path.feasibility == "not_checked")
                    .count(),
                unchecked,
                "{procedure}: {paths:?}"
            );
        }
    }

