    #[test]
    fn tracks_set_nothing_into_variant_but_not_invalid_let_coercion() {
        let analysis = analyze(
            &[SourceUnit {
                name: "VariantNothingState.bas".into(),
                text: "Option Explicit\nPrivate objectValue As Variant\nPublic Sub SetNothing()\nDim seen As Long\nSet objectValue = Nothing\nIf IsObject(objectValue) Then\nseen = 1\nElse\nseen = 0\nEnd If\nEnd Sub\nPublic Sub LetNothing()\nDim seen As Long\nobjectValue = Nothing\nIf IsObject(objectValue) Then\nseen = 1\nElse\nseen = 0\nEnd If\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        for (procedure, infeasible, unchecked) in [("SetNothing", 1, 1), ("LetNothing", 0, 2)] {
            let paths = analysis
                .paths
                .iter()
                .filter(|path| path.procedure == procedure)
                .collect::<Vec<_>>();
            assert_eq!(paths.len(), 2, "{procedure}: {paths:?}");
            assert_eq!(
                paths
                    .iter()
                    .filter(|path| path.feasibility == "infeasible_constant_condition")
                    .count(),
                infeasible,
                "{procedure}: {paths:?}"
            );
            assert_eq!(
                paths
                    .iter()
                    .filter(|path| path.feasibility == "not_checked")
                    .count(),
                unchecked,
                "{procedure}: {paths:?}"
            );
        }
        assert!(
            analysis
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == "VBA2128")
        );
    }

