    fn folds_bounded_date_values_and_date_arithmetic_in_path_predicates() {
        let analysis = analyze(
            &[SourceUnit {
                name: "DatePathValues.bas".into(),
                text: "Option Explicit\nPublic Sub Check()\nIf DateSerial(2024, 2, 3) > DateSerial(2024, 2, 2) Then\na = 1\nElse\na = 0\nEnd If\nIf #January 2, 2024# + 1 = #January 3, 2024# Then\nb = 1\nElse\nb = 0\nEnd If\nIf DateAdd(\"d\", 1, #January 2, 2024#) = #January 3, 2024# Then\nc = 1\nElse\nc = 0\nEnd If\nIf DateAdd(\"m\", 1, #January 31, 2024#) = #February 29, 2024# Then\ncm = 1\nElse\ncm = 0\nEnd If\nIf DateAdd(\"yyyy\", 1, #February 29, 2024#) = #February 28, 2025# Then\ncy = 1\nElse\ncy = 0\nEnd If\nIf DateDiff(\"d\", #January 1, 2024#, #January 3, 2024#) = 2 Then\ndd = 1\nElse\ndd = 0\nEnd If\nIf DatePart(\"m\", #January 3, 2024#) = 1 Then\ndp = 1\nElse\ndp = 0\nEnd If\nIf TypeName(DateSerial(2024, 2, 3)) = \"Date\" Then\nd = 1\nElse\nd = 0\nEnd If\nIf VarType(DateSerial(2024, 2, 3)) = 7 Then\ne = 1\nElse\ne = 0\nEnd If\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let paths = analysis
            .paths
            .iter()
            .filter(|path| path.procedure == "Check")
            .collect::<Vec<_>>();
        assert!(!paths.is_empty());
        assert!(
            paths
                .iter()
                .any(|path| { path.feasibility == "not_checked" && path.complete })
        );
        assert!(
            paths
                .iter()
                .any(|path| path.feasibility == "infeasible_constant_condition")
        );
    }

