    #[test]
    fn folds_lbound_and_ubound_for_path_local_redim_shapes_and_forgets_erase() {
        let analysis = analyze(
            &[SourceUnit {
                name: "DynamicArrayShapePaths.bas".into(),
                text: "Option Base 1\nPublic Sub Resize()\nDim values() As Long\nDim lowerKnown As Long\nDim upperKnown As Long\nDim afterErase As Long\nReDim values(2 To 4)\nIf LBound(values) = 2 Then\nlowerKnown = 1\nElse\nlowerKnown = 0\nEnd If\nIf UBound(values) = 4 Then\nupperKnown = 1\nElse\nupperKnown = 0\nEnd If\nErase values\nIf UBound(values) = 4 Then\nafterErase = 1\nElse\nafterErase = 0\nEnd If\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let infeasible = analysis
            .paths
            .iter()
            .filter(|path| path.feasibility == "infeasible_constant_condition")
            .count();
        assert_eq!(
            infeasible, 6,
            "all contradictory arms before Erase are fixed while the post-Erase predicate is unknown: {:#?}",
            analysis.paths
        );
        assert!(analysis.paths.iter().any(|path| {
            path.feasibility == "not_checked"
                && path
                    .conditions
                    .iter()
                    .any(|condition| condition.contains("UBound(values) = 4"))
        }));
    }

