    #[test]
    fn folds_instr_for_ascii_binary_searches_and_known_start_positions() {
        let mut options = AnalysisOptions::default();
        options.limits.max_paths = 1024;
        let source = concat!(
            "Option Explicit\nOption Compare Binary\nPublic Sub Check()\n",
            "Dim dynamicText As String\nDim result As Long\n",
            "If InStr(\"abc\", \"b\") = 2 Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If InStr(2, \"abcabc\", \"a\") = 4 Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If InStr(1, \"abc\", \"B\", 0) = 0 Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If InStr(\"abc\", \"B\") = 0 Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If InStr(\"abc\", \"z\") = 0 Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If InStr(\"\", \"x\") = 0 Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If InStr(\"abc\", \"\") = 1 Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If InStr(dynamicText, \"z\") = 0 Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If InStr(\"x\", Null) = 0 Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "End Sub\nPublic Sub BadArity()\nDim value As Long\n",
            "value = InStr(\"only one\")\nvalue = InStr(1, 2, 3, 4, 5)\nEnd Sub\n"
        );
        let analysis = analyze(
            &[SourceUnit {
                name: "InStrTests.bas".into(),
                text: source.into(),
            }],
            &options,
        )
        .unwrap();
        let paths = analysis
            .paths
            .iter()
            .filter(|path| path.procedure == "Check")
            .collect::<Vec<_>>();
        assert_eq!(paths.len(), 512);
        assert_eq!(
            paths
                .iter()
                .filter(|path| path.feasibility == "infeasible_constant_condition")
                .count(),
            510
        );
        assert_eq!(
            paths
                .iter()
                .filter(|path| path.feasibility == "not_checked")
                .count(),
            2
        );
        assert!(!analysis.path_enumeration_truncated);
        assert_eq!(
            analysis
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == "VBA2148")
                .count(),
            2
        );
        assert!(
            !analysis
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == "VBA2030"),
            "recognized Option directives and comparison constants must not be unresolved"
        );
    }

    #[test]
    fn leaves_instr_unresolved_for_collation_non_ascii_and_shadowed_calls() {
        let analysis = analyze(
            &[
                SourceUnit {
                    name: "TextCompare.bas".into(),
                    text: "Option Compare Text\nPublic Sub CheckText()\nDim result As Long\nIf InStr(\"abc\", \"A\") = 1 Then\nresult = 1\nElse\nresult = 0\nEnd If\nEnd Sub\nPublic Sub CheckExplicitBinary()\nDim result As Long\nIf InStr(1, \"abc\", \"A\", vbBinaryCompare) = 0 Then\nresult = 1\nElse\nresult = 0\nEnd If\nEnd Sub\n".into(),
                },
                SourceUnit {
                    name: "UnicodeCompare.bas".into(),
                    text: "Option Compare Binary\nPublic Sub CheckUnicode()\nDim result As Long\nIf InStr(\"あ\", \"あ\") = 1 Then\nresult = 1\nElse\nresult = 0\nEnd If\nEnd Sub\n".into(),
                },
            ],
            &AnalysisOptions::default(),
        )
        .unwrap();
        for procedure in ["CheckText", "CheckUnicode"] {
            let paths = analysis
                .paths
                .iter()
                .filter(|path| path.procedure == procedure)
                .collect::<Vec<_>>();
            assert_eq!(paths.len(), 2, "{procedure}");
            assert!(
                paths.iter().all(|path| path.feasibility == "not_checked"),
                "{procedure}: {paths:?}"
            );
        }
        let explicit_binary = analysis
            .paths
            .iter()
            .filter(|path| path.procedure == "CheckExplicitBinary")
            .collect::<Vec<_>>();
        assert_eq!(explicit_binary.len(), 2);
        assert_eq!(
            explicit_binary
                .iter()
                .filter(|path| path.feasibility == "infeasible_constant_condition")
                .count(),
            1,
            "{explicit_binary:?}"
        );

        let shadowed = analyze(
            &[SourceUnit {
                name: "ShadowedInStr.bas".into(),
                text: "Public Function InStr(value As String, sought As String) As Long\nInStr = 0\nEnd Function\nPublic Sub CheckShadowed()\nDim result As Long\nIf InStr(\"abc\", \"b\") = 2 Then\nresult = 1\nElse\nresult = 0\nEnd If\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let shadow_paths = shadowed
            .paths
            .iter()
            .filter(|path| path.procedure == "CheckShadowed")
            .collect::<Vec<_>>();
        assert_eq!(shadow_paths.len(), 2);
        assert!(
            shadow_paths
                .iter()
                .all(|path| path.feasibility == "not_checked")
        );
    }

