    #[test]
    fn folds_replace_for_known_ascii_values_under_binary_compare() {
        let mut options = AnalysisOptions::default();
        options.limits.max_paths = 1024;
        let source_prefix = concat!(
            "Option Explicit\nOption Compare Binary\nPublic Sub Check()\n",
            "Dim knownText As Variant\nDim dynamicText As String\nDim result As Long\n",
            "knownText = \"a-b-a\"\n",
            "If Replace(knownText, \"a\", \"X\") = \"X-b-X\" Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If Replace(\"a--a\", \"--\", \"\") = \"aa\" Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If Replace(\"abc\", \"z\", \"q\") = \"abc\" Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If Replace(\"abc\", \"\", \"q\") = \"abc\" Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If Replace(\"ABC\", \"b\", \"X\") = \"ABC\" Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If Replace(dynamicText, \"a\", \"b\") = \"b\" Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If Replace(\"あ\", \"あ\", \"x\") = \"x\" Then\nresult = 1\nElse\nresult = 0\nEnd If\n",
            "If Replace(Null, \"a\", \"x\") = \"x\" Then\nresult = 1\nElse\nresult = 0\nEnd If\n"
        );
        let source = format!(
            "{source_prefix}If Replace(\"{}\", \"a\", \"bb\") = \"\" Then\nresult = 1\nElse\nresult = 0\nEnd If\nEnd Sub\nPublic Sub BadArity()\nDim value As String\nvalue = Replace(\"x\", \"y\")\nvalue = Replace(\"x\", \"y\", \"z\", 1, 2, 0, 7)\nEnd Sub\n",
            "a".repeat(9000)
        );
        let analysis = analyze(
            &[SourceUnit {
                name: "ReplaceTests.bas".into(),
                text: source,
            }],
            &options,
        )
        .unwrap();
        let paths = analysis
            .paths
            .iter()
            .filter(|path| path.procedure == "Check")
            .collect::<Vec<_>>();
        assert_eq!(paths.len(), 512);
        assert_eq!(
            paths
                .iter()
                .filter(|path| path.feasibility == "infeasible_constant_condition")
                .count(),
            496
        );
        assert_eq!(
            paths
                .iter()
                .filter(|path| path.feasibility == "not_checked")
                .count(),
            16
        );
        assert!(!analysis.path_enumeration_truncated);
        assert_eq!(
            analysis
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == "VBA2148")
                .count(),
            2
        );
        assert!(
            !analysis
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == "VBA2030")
        );
    }

