    #[test]
    fn connects_call_arguments_to_formal_reads_in_callee_conditions() {
        let analysis = analyze(
            &[SourceUnit {
                name: "PredicateCall.bas".into(),
                text: "Option Explicit\nPrivate Function IsAllowed(ByVal SECRET_VALUE As Long) As Boolean\nIf SECRET_VALUE > 0 Then\nIsAllowed = True\nElse\nIsAllowed = False\nEnd If\nEnd Function\nPublic Sub Caller()\nDim amount As Long\nDim allowed As Boolean\namount = 1\nIf SECRET_READY Then\nallowed = IsAllowed(amount)\nEnd If\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let condition_read = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "expression_read_candidate"
                    && fact.procedure.as_deref() == Some("IsAllowed")
                    && fact.inputs == ["SECRET_VALUE"]
            })
            .unwrap();
        let relations = analysis
            .interprocedural_data_flow_paths
            .iter()
            .filter(|fact| fact.callee_use_data_flow_index == condition_read)
            .collect::<Vec<_>>();
        assert_eq!(relations.len(), 2, "{relations:?}");
        assert!(
            relations.iter().all(|fact| {
                fact.parameter == "SECRET_VALUE"
                    && fact.caller_procedure == "Caller"
                    && fact.callee_procedure == "IsAllowed"
                    && fact
                        .caller_conditions
                        .iter()
                        .any(|condition| condition.contains("SECRET_READY"))
                    && fact.callee_conditions.is_empty()
            }),
            "{relations:#?}"
        );
    }

    #[test]
    fn traces_local_and_module_constant_initializers_into_path_flows() {
        let analysis = analyze(
            &[SourceUnit {
                name: "ConstantFlow.bas".into(),
                text: "Option Explicit\nPrivate Const ModuleLimit As Long = 8\nPublic Sub Read()\nDim fromModule As Long\nDim fromLocal As Long\nDim localValue As Long\nDim sink As Long\nConst LocalLimit As Long = ModuleLimit\nfromModule = ModuleLimit\nfromLocal = LocalLimit\nlocalValue = LocalLimit\nsink = localValue\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();

        let module_constant = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "constant_initializer"
                    && fact.target == "ModuleLimit"
                    && fact.procedure.is_none()
            })
            .unwrap();
        let local_constant = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "constant_initializer"
                    && fact.target == "LocalLimit"
                    && fact.procedure.as_deref() == Some("Read")
            })
            .unwrap();
        let module_read = analysis
            .data_flow
            .iter()
            .position(|fact| fact.target == "fromModule" && fact.inputs == ["ModuleLimit"])
            .unwrap();
        let local_read = analysis
            .data_flow
            .iter()
            .position(|fact| fact.target == "fromLocal" && fact.inputs == ["LocalLimit"])
            .unwrap();

        assert!(
            analysis.path_value_flows.iter().any(|flow| {
                flow.source_data_flow_index == Some(module_constant)
                    && flow.target_data_flow_index == local_constant
                    && flow.resolution == "constant_initializer_candidate"
            }),
            "{:?}",
            analysis.path_value_flows
        );
        assert!(analysis.path_value_flows.iter().any(|flow| {
            flow.source_data_flow_index == Some(module_constant)
                && flow.target_data_flow_index == module_read
                && flow.resolution == "constant_initializer_candidate"
        }));
        assert!(analysis.path_value_flows.iter().any(|flow| {
            flow.source_data_flow_index == Some(local_constant)
                && flow.target_data_flow_index == local_read
                && flow.resolution == "constant_initializer_candidate"
        }));

        let cross_module = analyze(
            &[
                SourceUnit {
                    name: "SharedConstants.bas".into(),
                    text: "Public Const PublicLimit As Long = 12\n".into(),
                },
                SourceUnit {
                    name: "Consumer.bas".into(),
                    text: "Public Sub Read()\nDim result As Long\nresult = PublicLimit\nEnd Sub\n"
                        .into(),
                },
            ],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let public_constant = cross_module
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "constant_initializer"
                    && fact.target == "PublicLimit"
                    && fact.procedure.is_none()
            })
            .unwrap();
        let public_read = cross_module
            .data_flow
            .iter()
            .position(|fact| fact.target == "result" && fact.inputs == ["PublicLimit"])
            .unwrap();
        assert!(cross_module.path_value_flows.iter().any(|flow| {
            flow.source_data_flow_index == Some(public_constant)
                && flow.target_data_flow_index == public_read
                && flow.resolution == "constant_initializer_candidate"
        }));

        let shadowed = analyze(
            &[SourceUnit {
                name: "ShadowedConstant.bas".into(),
                text: "Private Const Limit As Long = 12\nPublic Sub Read()\nDim Limit As Long\nDim result As Long\nresult = Limit\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let module_limit = shadowed
            .data_flow
            .iter()
            .position(|fact| fact.transfer == "constant_initializer" && fact.target == "Limit")
            .unwrap();
        let shadowed_read = shadowed
            .data_flow
            .iter()
            .position(|fact| fact.target == "result" && fact.inputs == ["Limit"])
            .unwrap();
        assert!(!shadowed.path_value_flows.iter().any(|flow| {
            flow.source_data_flow_index == Some(module_limit)
                && flow.target_data_flow_index == shadowed_read
        }));
    }

    #[test]
    fn traces_qualified_module_constants_through_function_return_candidates_independent_of_source_order()
     {
        let provider = SourceUnit {
            name: "Provider.bas".into(),
            text: "Option Explicit\nPrivate Const HiddenLimit As Long = 19\nPublic Function ReadLimit() As Long\nConst localLimit As Long = HiddenLimit\nDim localCopy As Long\nlocalCopy = localLimit\nReadLimit = localCopy\nEnd Function\n".into(),
        };
        let consumer = SourceUnit {
            name: "Consumer.bas".into(),
            text: "Option Explicit\nPublic Sub Read()\nDim result As Long\nresult = Provider.ReadLimit()\nEnd Sub\n".into(),
        };

        for sources in [
            vec![provider.clone(), consumer.clone()],
            vec![consumer.clone(), provider.clone()],
        ] {
            let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
            let constant = analysis
                .data_flow
                .iter()
                .position(|fact| {
                    fact.module == "Provider"
                        && fact.procedure.is_none()
                        && fact.transfer == "constant_initializer"
                        && fact.target == "HiddenLimit"
                })
                .unwrap();
            let returned = analysis
                .data_flow
                .iter()
                .position(|fact| {
                    fact.module == "Consumer"
                        && fact.target == "result"
                        && fact.transfer == "function_return_candidate"
                        && fact.inputs == ["Provider.HiddenLimit"]
                })
                .unwrap();
            assert!(
                analysis.path_value_flows.iter().any(|flow| {
                    flow.source_data_flow_index == Some(constant)
                        && flow.target_data_flow_index == returned
                        && flow.variable == "Provider.HiddenLimit"
                        && flow.resolution == "constant_initializer_candidate"
                }),
                "{:#?}",
                analysis.path_value_flows
            );
        }
    }

    #[test]
