    #[test]
    fn links_function_return_candidates_to_callee_return_paths_across_a_wrapper() {
        let source = SourceUnit {
            name: "ReturnChain.bas".into(),
            text: "Option Explicit\nPrivate Function Inner(ByVal value As Long) As Long\nInner = value + 1\nEnd Function\nPrivate Function Wrapper(ByVal value As Long) As Long\nWrapper = Inner(value)\nEnd Function\nPublic Sub Caller()\nDim amount As Long\nDim result As Long\namount = 1\nresult = Wrapper(amount)\nEnd Sub\n".into(),
        };
        let analysis = analyze(std::slice::from_ref(&source), &AnalysisOptions::default()).unwrap();
        let caller_return = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "function_return_candidate"
                    && fact.target == "result"
                    && fact.call_callee_procedure.as_deref() == Some("Wrapper")
            })
            .unwrap();
        let wrapper_return_call = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "function_return_candidate"
                    && fact.target == "Wrapper"
                    && fact.call_callee_procedure.as_deref() == Some("Inner")
            })
            .unwrap();
        let inner_return_assignment = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "assignment"
                    && fact.procedure.as_deref() == Some("Inner")
                    && fact.target == "Inner"
            })
            .unwrap();
        assert!(
            analysis.interprocedural_return_paths.iter().any(|fact| {
                fact.caller_return_data_flow_index == caller_return
                    && fact.callee_return_data_flow_index == wrapper_return_call
                    && fact.callee_procedure == "Wrapper"
            }),
            "{:?}",
            analysis.interprocedural_return_paths
        );
        assert!(analysis.interprocedural_return_paths.iter().any(|fact| {
            fact.caller_return_data_flow_index == caller_return
                && fact.callee_procedure == "Wrapper"
                && fact.callee_return_expression.is_some()
        }));
        assert!(
            analysis.interprocedural_return_paths.iter().any(|fact| {
                fact.caller_return_data_flow_index == wrapper_return_call
                    && fact.callee_return_data_flow_index == inner_return_assignment
                    && fact.callee_procedure == "Inner"
            }),
            "{:?}",
            analysis.interprocedural_return_paths
        );
        assert!(
            analysis
                .interprocedural_return_compositions
                .iter()
                .any(|fact| {
                    fact.outer_return_data_flow_index == caller_return
                        && fact.inner_return_data_flow_index == inner_return_assignment
                        && fact.composition_depth == 2
                        && fact.intermediate_procedure == "Wrapper"
                        && fact.inner_procedure == "Inner"
                }),
            "{:?}",
            analysis.interprocedural_return_compositions
        );
        assert!(!analysis.interprocedural_return_compositions_truncated);
        assert!(!analysis.interprocedural_return_paths_truncated);

        let limited = analyze(
            std::slice::from_ref(&source),
            &AnalysisOptions {
                limits: Limits {
                    max_path_value_flow_steps: 0,
                    ..Limits::default()
                },
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        assert!(limited.interprocedural_return_paths.is_empty());
        assert!(limited.interprocedural_return_paths_truncated);
    }

