    #[test]
    fn type_of_is_conditions_track_the_object_and_resolve_the_tested_type_separately() {
        let sources = [
            SourceUnit {
                name: "IThing.cls".into(),
                text: "Public Sub Ping(ByVal value As Long)\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "Widget.cls".into(),
                text: "Implements IThing\nPrivate Sub IThing_Ping(ByVal value As Long)\nEnd Sub\nPublic Sub Refresh()\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "Reader.bas".into(),
                text: "Option Explicit\nPrivate widget As Widget\nPublic Sub Inspect()\nDim compatible As Boolean\nDim amount As Long\ncompatible = TypeOf widget Is Widget\nIf TypeOf widget Is IThing Then\ncompatible = True\nEnd If\nIf TypeOf widget Is Excel.Range Then\nwidget.Refresh\nEnd If\nIf TypeOf amount Is Widget Then\ncompatible = False\nEnd If\nIf TypeOf Nothing Is Widget Then\ncompatible = False\nEnd If\nEnd Sub\n".into(),
            },
        ];
        let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
        assert!(analysis.references.iter().any(|reference| {
            reference.module == "Reader"
                && reference.name == "Widget"
                && reference.resolution == "typeof_type_reference_candidate"
        }));
        assert!(analysis.references.iter().any(|reference| {
            reference.module == "Reader"
                && reference.name == "Excel.Range"
                && reference.resolution == "unresolved_typeof_type_reference"
        }));
        assert!(!analysis.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "VBA2030" && diagnostic.message.contains("Widget")
        }));
        assert!(analysis.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "VBA2145" && diagnostic.message.contains("amount")
        }));
        assert!(analysis.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "VBA2146" && diagnostic.message.contains("Nothing")
        }));
        assert!(analysis.data_flow.iter().any(|fact| {
            fact.transfer == "assignment"
                && fact.target == "compatible"
                && fact.inputs == ["widget"]
        }));
        assert!(analysis.data_flow.iter().any(|fact| {
            fact.transfer == "expression_read_candidate"
                && fact.inputs == ["widget"]
                && fact.procedure.as_deref() == Some("Inspect")
        }));
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.target == "compatible"
                && fact.value_type == "Boolean"
                && fact.status == "compatible"
        }));
        assert!(analysis.type_facts.iter().any(|fact| {
            fact.target == "widget"
                && fact.target_type.as_deref() == Some("IThing")
                && fact.value_type == "Widget"
                && fact.status == "implemented_interface_candidate"
        }));
        let excel_analysis = analyze(
            &sources,
            &AnalysisOptions {
                host_profile: HostProfile::Excel,
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        assert!(excel_analysis.references.iter().any(|reference| {
            reference.name == "Excel.Range"
                && reference.resolution == "typeof_type_reference_candidate"
        }));
        let structure =
            crate::export::to_json(&analysis, None, crate::export::Disclosure::StructureOnly);
        assert!(!structure.contains("IThing"));
        assert!(!structure.contains("Widget"));
        let full =
            crate::export::to_json(&analysis, None, crate::export::Disclosure::IncludeSource);
        assert!(full.contains("implemented_interface_candidate"));
        assert!(full.contains("IThing"));
    }

