    #[test]
    fn tracks_writes_through_byref_arguments_but_not_byval_arguments() {
        let source=SourceUnit{name:"ByRef.bas".into(),text:"Option Explicit\nPrivate Sub Bump(ByRef value As Long)\nvalue = value + 1\nEnd Sub\nPrivate Sub ReadOnly(ByVal value As Long)\nvalue = value + 1\nEnd Sub\nPublic Sub Caller()\nDim amount As Long\nDim result As Long\namount = 50\nBump amount\nresult = amount\nReadOnly amount\nCall Bump((amount))\nEnd Sub\n".into()};
        let a = analyze(&[source], &AnalysisOptions::default()).unwrap();
        assert_eq!(
            a.data_flow
                .iter()
                .filter(|f| f.transfer == "byref_argument_write")
                .count(),
            1
        );
        assert!(
            a.data_flow
                .iter()
                .any(|f| f.transfer == "byref_argument_write" && f.target == "amount")
        );
        let mutation_index = a
            .data_flow
            .iter()
            .position(|fact| fact.transfer == "byref_argument_write" && fact.target == "amount")
            .unwrap();
        let result_index = a
            .data_flow
            .iter()
            .position(|fact| fact.target == "result" && fact.inputs == ["amount"])
            .unwrap();
        assert!(a.path_value_flows.iter().any(|flow| {
            flow.source_data_flow_index == Some(mutation_index)
                && flow.target_data_flow_index == result_index
        }));
        assert!(
            a.data_flow.iter().any(|f| {
                f.transfer == "procedure_argument_input_candidate"
                    && f.target == "ByRef.Bump.value"
                    && f.inputs == ["amount"]
            }),
            "{:?}",
            a.data_flow
        );
        assert!(
            a.interprocedural_byref_value_paths.iter().any(|fact| {
                fact.callee_procedure == "Bump"
                    && fact.parameter == "value"
                    && fact.caller_value.as_deref() == Some("50")
                    && fact.callee_write_expression.as_deref() == Some("value + 1")
                    && fact.resolved_value.as_deref() == Some("51")
                    && fact.resolution == "caller_snapshot_to_byref_write_value"
            }),
            "{:?}",
            a.interprocedural_byref_value_paths
        );
    }

    #[test]
    fn propagates_byref_mutations_through_nested_calls_without_crossing_byval_or_parentheses() {
        let nested = SourceUnit {
            name: "NestedCalls.bas".into(),
            text: "Option Explicit\nPrivate Sub Leaf(ByRef value As Long)\nvalue = value + 1\nEnd Sub\nPrivate Sub Middle(ByRef nextValue As Long)\nLeaf nextValue\nEnd Sub\nPublic Sub Outer(ByRef thirdValue As Long)\nMiddle thirdValue\nEnd Sub\n".into(),
        };
        let caller = SourceUnit {
            name: "Caller.bas".into(),
            text: "Option Explicit\nPrivate Sub ByValCaller(ByVal localValue As Long)\nNestedCalls.Outer localValue\nEnd Sub\nPublic Sub Caller(ByRef amount As Long)\nDim result As Long\nNestedCalls.Outer amount\nresult = amount\nEnd Sub\nPublic Sub CallerOfByVal(ByRef amount As Long)\nByValCaller amount\nEnd Sub\nPublic Sub ParenthesizedCaller(ByRef amount As Long)\nCall NestedCalls.Outer((amount))\nEnd Sub\n".into(),
        };

        for sources in [
            vec![nested.clone(), caller.clone()],
            vec![caller.clone(), nested.clone()],
        ] {
            let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
            let write_indices = analysis
                .data_flow
                .iter()
                .enumerate()
                .filter(|(_, fact)| fact.transfer == "byref_argument_write")
                .collect::<Vec<_>>();
            assert!(write_indices.iter().any(|(_, fact)| {
                fact.module == "NestedCalls"
                    && fact.procedure.as_deref() == Some("Middle")
                    && fact.target == "nextValue"
            }));
            assert!(write_indices.iter().any(|(_, fact)| {
                fact.module == "NestedCalls"
                    && fact.procedure.as_deref() == Some("Outer")
                    && fact.target == "thirdValue"
            }));
            let caller_write = write_indices
                .iter()
                .find(|(_, fact)| {
                    fact.module == "Caller"
                        && fact.procedure.as_deref() == Some("Caller")
                        && fact.target == "amount"
                })
                .map(|(index, _)| *index)
                .unwrap();
            let outer_write = write_indices
                .iter()
                .find(|(_, fact)| {
                    fact.module == "NestedCalls"
                        && fact.procedure.as_deref() == Some("Outer")
                        && fact.target == "thirdValue"
                })
                .map(|(index, _)| *index)
                .unwrap();
            let middle_write = write_indices
                .iter()
                .find(|(_, fact)| {
                    fact.module == "NestedCalls"
                        && fact.procedure.as_deref() == Some("Middle")
                        && fact.target == "nextValue"
                })
                .map(|(index, _)| *index)
                .unwrap();
            let leaf_write = analysis
                .data_flow
                .iter()
                .position(|fact| {
                    fact.module == "NestedCalls"
                        && fact.procedure.as_deref() == Some("Leaf")
                        && fact.transfer == "assignment"
                        && fact.target == "value"
                })
                .unwrap();
            assert!(
                analysis
                    .interprocedural_byref_write_paths
                    .iter()
                    .any(|fact| {
                        fact.caller_write_data_flow_index == caller_write
                            && fact.callee_write_data_flow_index == outer_write
                            && fact.caller_procedure == "Caller"
                            && fact.callee_procedure == "Outer"
                            && fact.parameter == "thirdValue"
                            && fact.feasibility == "not_checked"
                    }),
                "{:#?}",
                analysis.interprocedural_byref_write_paths
            );
            assert!(
                analysis
                    .interprocedural_byref_write_paths
                    .iter()
                    .any(|fact| {
                        fact.caller_write_data_flow_index == outer_write
                            && fact.callee_write_data_flow_index == middle_write
                            && fact.caller_procedure == "Outer"
                            && fact.callee_procedure == "Middle"
                            && fact.parameter == "nextValue"
                    })
            );
            assert!(
                analysis
                    .interprocedural_byref_write_paths
                    .iter()
                    .any(|fact| {
                        fact.caller_write_data_flow_index == middle_write
                            && fact.callee_write_data_flow_index == leaf_write
                            && fact.caller_procedure == "Middle"
                            && fact.callee_procedure == "Leaf"
                            && fact.parameter == "value"
                    })
            );
            assert!(!analysis.interprocedural_byref_write_paths_truncated);
            assert!(write_indices.iter().any(|(_, fact)| {
                fact.module == "Caller"
                    && fact.procedure.as_deref() == Some("ByValCaller")
                    && fact.target == "localValue"
            }));
            assert!(!write_indices.iter().any(|(_, fact)| {
                fact.module == "Caller"
                    && fact.procedure.as_deref() == Some("CallerOfByVal")
                    && fact.target == "amount"
            }));
            assert!(!write_indices.iter().any(|(_, fact)| {
                fact.module == "Caller"
                    && fact.procedure.as_deref() == Some("ParenthesizedCaller")
                    && fact.target == "amount"
            }));
            let result_read = analysis
                .data_flow
                .iter()
                .position(|fact| {
                    fact.module == "Caller"
                        && fact.procedure.as_deref() == Some("Caller")
                        && fact.target == "result"
                        && fact.inputs == ["amount"]
                })
                .unwrap();
            assert!(analysis.path_value_flows.iter().any(|flow| {
                flow.source_data_flow_index == Some(caller_write)
                    && flow.target_data_flow_index == result_read
            }));
        }
        let limited = analyze(
            &[nested, caller],
            &AnalysisOptions {
                limits: Limits {
                    max_path_value_flow_steps: 0,
                    ..Limits::default()
                },
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        assert!(limited.interprocedural_byref_write_paths.is_empty());
        assert!(limited.interprocedural_byref_write_paths_truncated);
    }

