    #[test]
    fn links_callee_unhandled_error_paths_to_conditioned_call_sites() {
        let source = SourceUnit {
            name: "ErrorCalls.bas".into(),
            text: "Private Sub Worker(ByVal amount As Long)\nDim result As Long\nresult = 1 / amount\nEnd Sub\nPublic Sub Caller(ByVal ready As Boolean, ByVal amount As Long)\nOn Error GoTo Handler\nIf ready Then\nWorker amount\nEnd If\nExit Sub\nHandler:\nResume Next\nEnd Sub\nPublic Sub DefaultCaller(ByVal amount As Long)\nWorker amount\nEnd Sub\nPublic Sub Main()\nWorker 1\nEnd Sub\n".into(),
        };
        let analysis = analyze(std::slice::from_ref(&source), &AnalysisOptions::default()).unwrap();
        let call_index = analysis
            .calls
            .iter()
            .position(|call| {
                call.procedure.as_deref() == Some("Caller")
                    && call.target == "Worker"
                    && call.resolution == "resolved_project_procedure"
            })
            .unwrap();
        let relation = analysis
            .interprocedural_error_paths
            .iter()
            .find(|relation| {
                relation.caller_call_index == call_index
                    && relation.callee_procedure == "Worker"
                    && relation.propagation == "default_error_policy_may_propagate_to_caller"
            })
            .unwrap();
        assert!(
            relation
                .caller_conditions
                .iter()
                .any(|condition| condition.contains("ready"))
        );
        assert_eq!(relation.feasibility, "not_checked");
        assert!(
            analysis.paths[relation.callee_path_index]
                .nodes
                .contains(&relation.callee_fault_node_id)
        );
        assert!(analysis.interprocedural_error_paths.iter().any(|relation| {
            relation.caller_call_index == call_index
                && relation.caller_error_response == "caller_handler_transfer_candidate"
                && relation.caller_recovery_node_id.is_some()
        }));
        assert!(analysis.interprocedural_error_paths.iter().any(|relation| {
            relation.caller_procedure == "DefaultCaller"
                && relation.callee_procedure == "Worker"
                && relation.caller_error_response == "caller_default_policy_context_dependent"
                && !relation.caller_host_entry_candidate
        }));
        assert!(analysis.interprocedural_error_paths.iter().any(|relation| {
            relation.caller_procedure == "Main"
                && relation.callee_procedure == "Worker"
                && relation.caller_host_entry_candidate
                && relation.caller_error_response == "caller_default_policy_context_dependent"
        }));
        let main_graph = analysis
            .control_flow
            .iter()
            .find(|graph| graph.module == "ErrorCalls" && graph.procedure == "Main")
            .unwrap();
        assert!(!main_graph.complete);
        assert!(main_graph.edges.iter().any(|edge| {
            edge.condition.as_deref().is_some_and(|condition| {
                condition.contains("possible unhandled error terminates host entry")
            })
        }));
        assert!(main_graph.edges.iter().any(|edge| {
            edge.condition.as_deref().is_some_and(|condition| {
                condition.contains("possible unhandled error leaves this procedure")
            })
        }));
        assert!(!analysis.interprocedural_error_paths_truncated);

        let handled = analyze(
            &[SourceUnit {
                name: "HandledErrors.bas".into(),
                text: "Private Sub Worker(ByVal amount As Long)\nOn Error Resume Next\nDim result As Long\nresult = 1 / amount\nEnd Sub\nPublic Sub Caller(ByVal amount As Long)\nWorker amount\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        assert!(!handled.interprocedural_error_paths.iter().any(|relation| {
            relation.callee_procedure == "Worker"
                && relation.propagation == "default_error_policy_may_propagate_to_caller"
        }));

        let nested_handler = analyze(
            &[SourceUnit {
                name: "NestedHandler.bas".into(),
                text: "Private Sub Worker(ByVal amount As Long)\nOn Error GoTo Handler\nDim result As Long\nresult = 1 / amount\nExit Sub\nHandler:\nErr.Raise 5\nEnd Sub\nPublic Sub Caller()\nWorker 0\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        assert!(
            nested_handler
                .interprocedural_error_paths
                .iter()
                .any(|relation| {
                    relation.callee_procedure == "Worker"
                        && relation.propagation == "callee_unhandled_error_candidate"
                }),
            "{:#?}",
            nested_handler.interprocedural_error_paths
        );

        let limited = analyze(
            std::slice::from_ref(&source),
            &AnalysisOptions {
                limits: Limits {
                    max_path_value_flow_steps: 0,
                    ..Limits::default()
                },
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        assert!(limited.interprocedural_error_paths.is_empty());
        assert!(limited.interprocedural_error_paths_truncated);
    }

    #[test]
    fn event_handler_errors_stop_event_dispatch_without_becoming_raiseevent_caller_recovery() {
        let analysis = analyze(
            &[
                SourceUnit {
                    name: "Source.cls".into(),
                    text: "Public Event Changed(ByVal amount As Long)\nPublic Sub Trigger()\nRaiseEvent Changed(1)\nEnd Sub\n".into(),
                },
                SourceUnit {
                    name: "Listener.cls".into(),
                    text: "Private WithEvents source As Source\nPrivate Sub source_Changed(ByVal amount As Long)\nDim result As Long\nresult = 1 / amount\nEnd Sub\n".into(),
                },
            ],
            &AnalysisOptions::default(),
        )
        .unwrap();
        assert!(
            analysis.interprocedural_error_paths.iter().any(|relation| {
                relation.caller_module == "Source"
                    && relation.caller_procedure == "Trigger"
                    && relation.callee_module == "Listener"
                    && relation.callee_procedure == "source_Changed"
                    && relation.propagation
                        == "event_handler_unhandled_error_stops_remaining_dispatch"
                    && relation.caller_error_response
                        == "event_handler_error_not_caught_by_raiseevent_caller"
            }),
            "{:#?}",
            analysis.interprocedural_error_paths
        );
    }

    #[test]
    fn handled_event_handler_errors_do_not_stop_event_dispatch() {
        let analysis = analyze(
            &[
                SourceUnit {
                    name: "Source.cls".into(),
                    text: "Attribute VB_Name = \"Source\"\nPublic Event Changed(ByVal amount As Long)\nPublic Sub Trigger()\nRaiseEvent Changed(1)\nEnd Sub\n".into(),
                },
                SourceUnit {
                    name: "ResumeListener.cls".into(),
                    text: "Attribute VB_Name = \"ResumeListener\"\nPrivate WithEvents source As Source\nPrivate Sub source_Changed(ByVal amount As Long)\nOn Error Resume Next\nDim result As Long\nresult = 1 / amount\nEnd Sub\n".into(),
                },
                SourceUnit {
                    name: "HandlerListener.cls".into(),
                    text: "Attribute VB_Name = \"HandlerListener\"\nPrivate WithEvents source As Source\nPrivate Sub source_Changed(ByVal amount As Long)\nOn Error GoTo failed\nDim result As Long\nresult = 1 / amount\nExit Sub\nfailed:\nResume Next\nEnd Sub\n".into(),
                },
            ],
            &AnalysisOptions::default(),
        )
        .unwrap();
        assert!(
            !analysis.interprocedural_error_paths.iter().any(|relation| {
                relation.caller_module == "Source"
                    && relation.caller_procedure == "Trigger"
                    && matches!(
                        relation.callee_module.as_str(),
                        "ResumeListener" | "HandlerListener"
                    )
                    && relation.callee_procedure == "source_Changed"
            }),
            "{:#?}",
            analysis.interprocedural_error_paths
        );
    }

    #[test]
    fn resolves_interprocedural_error_paths_for_qualified_cross_module_calls_independent_of_source_order()
     {
        let library = SourceUnit {
            name: "ErrorLibrary.bas".into(),
            text: "Attribute VB_Name = \"ErrorLibrary\"\nPublic Sub Worker(ByVal amount As Long)\nDim result As Long\nresult = 1 / amount\nEnd Sub\n".into(),
        };
        let caller = SourceUnit {
            name: "ErrorCaller.bas".into(),
            text: "Attribute VB_Name = \"ErrorCaller\"\nPublic Sub Run(ByVal ready As Boolean, ByVal amount As Long)\nOn Error Resume Next\nIf ready Then\nErrorLibrary.Worker amount\nEnd If\nEnd Sub\n".into(),
        };
        let duplicate = SourceUnit {
            name: "DuplicateErrorLibrary.bas".into(),
            text: "Attribute VB_Name = \"OtherLibrary\"\nPublic Sub Worker(ByVal amount As Long)\nEnd Sub\n".into(),
        };
        for sources in [
            vec![library.clone(), duplicate.clone(), caller.clone()],
            vec![caller.clone(), duplicate.clone(), library.clone()],
        ] {
            let analysis = analyze(&sources, &AnalysisOptions::default()).unwrap();
            assert!(
                analysis.interprocedural_error_paths.iter().any(|relation| {
                    relation.caller_module == "ErrorCaller"
                        && relation.caller_procedure == "Run"
                        && relation.callee_module == "ErrorLibrary"
                        && relation.callee_procedure == "Worker"
                        && relation.caller_error_response
                            == "caller_resume_next_after_call_candidate"
                        && relation
                            .caller_conditions
                            .iter()
                            .any(|condition| condition.contains("ready"))
                }),
                "error paths: {:#?}",
                analysis.interprocedural_error_paths
            );
        }
    }

