    #[test]
    fn tracks_all_array_targets_in_redim_and_erase_through_byref_arguments() {
        let source = SourceUnit {
            name: "ByRefArrays.bas".into(),
            text: "Option Explicit\nPrivate Sub ResizeAndClear(ByRef values() As Long, ByRef items() As Long)\nDim local() As Long\nReDim local(1), values(2), items(3)\nErase local, items\nEnd Sub\nPublic Sub Caller()\nDim firstValues() As Long, secondValues() As Long\nResizeAndClear firstValues, secondValues\nEnd Sub\n".into(),
        };
        let analysis = analyze(&[source], &AnalysisOptions::default()).unwrap();
        let writes = analysis
            .data_flow
            .iter()
            .filter(|fact| fact.transfer == "byref_argument_write")
            .collect::<Vec<_>>();
        assert_eq!(writes.len(), 2, "{writes:?}");
        assert!(writes.iter().any(|fact| {
            fact.target == "firstValues" && fact.inputs == ["ResizeAndClear", "values"]
        }));
        assert!(writes.iter().any(|fact| {
            fact.target == "secondValues" && fact.inputs == ["ResizeAndClear", "items"]
        }));
        let first_write = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "byref_argument_write" && fact.target == "firstValues"
            })
            .unwrap();
        let second_write = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.transfer == "byref_argument_write" && fact.target == "secondValues"
            })
            .unwrap();
        let redim_values = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.procedure.as_deref() == Some("ResizeAndClear")
                    && fact.transfer == "redim_array_write_candidate"
                    && fact.target == "values"
            })
            .unwrap();
        let erase_items = analysis
            .data_flow
            .iter()
            .position(|fact| {
                fact.procedure.as_deref() == Some("ResizeAndClear")
                    && fact.transfer == "erase_array_write_candidate"
                    && fact.target == "items"
            })
            .unwrap();
        assert!(
            analysis
                .data_flow_paths
                .iter()
                .any(|path| path.data_flow_index == erase_items),
            "erase target did not attach to CFG paths: {:#?}",
            analysis.data_flow_paths
        );
        assert!(
            analysis
                .interprocedural_byref_write_paths
                .iter()
                .any(|relation| {
                    relation.caller_write_data_flow_index == first_write
                        && relation.callee_write_data_flow_index == redim_values
                        && relation.parameter == "values"
                })
        );
        assert!(
            analysis
                .interprocedural_byref_write_paths
                .iter()
                .any(|relation| {
                    relation.caller_write_data_flow_index == second_write
                        && relation.callee_write_data_flow_index == erase_items
                        && relation.parameter == "items"
                }),
            "caller write: {:?}; callee transfer: {:?}; tail data flow: {:#?}; relations: {:#?}; path facts: {:#?}",
            analysis.data_flow[second_write],
            analysis.data_flow[erase_items],
            &analysis.data_flow[5..],
            analysis.interprocedural_byref_write_paths,
            analysis.data_flow_paths
        );
    }

    #[test]
    fn diagnoses_array_operations_on_declared_scalars_and_fixed_arrays() {
        let analysis = analyze(
            &[SourceUnit {
                name: "ArrayTypes.bas".into(),
                text: "Option Explicit\nPrivate module_fixed(3) As Long\nPublic Sub Check()\nDim fixed_values(5) As Long\nDim scalar As Long\nDim dynamic_values() As Long\nDim maybe_array As Variant\nReDim module_fixed(9)\nReDim fixed_values(10)\nReDim scalar(10)\nReDim dynamic_values(10)\nReDim maybe_array(10)\nErase scalar\nErase dynamic_values\nErase maybe_array\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();

        assert_eq!(
            analysis
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == "VBA2072")
                .count(),
            2
        );
        assert_eq!(
            analysis
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == "VBA2073")
                .count(),
            2
        );
        assert!(
            !analysis
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == "VBA2074")
        );
    }

