    #[test]
    fn checks_preserve_rank_and_nonfinal_bounds_against_adjacent_redim() {
        let analysis = analyze(
            &[SourceUnit {
                name: "PreserveBounds.bas".into(),
                text: "Option Base 1\nPublic Sub Resize()\nDim wrong_rank() As Long, wrong_lower() As Long, wrong_upper() As Long, allowed() As Long\nReDim wrong_rank(0 To 4)\nReDim Preserve wrong_rank(0 To 4, 0 To 3)\nReDim wrong_lower(4)\nReDim Preserve wrong_lower(2 To 9)\nReDim wrong_upper(0 To 4, 0 To 4)\nReDim Preserve wrong_upper(0 To 5, 0 To 10)\nReDim allowed(0 To 4, 1 To 3)\nReDim Preserve allowed(0 To 4, 1 To 8)\nEnd Sub\n".into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let preserve = analysis
            .diagnostics
            .iter()
            .filter(|diagnostic| diagnostic.code == "VBA2076")
            .collect::<Vec<_>>();
        assert_eq!(preserve.len(), 3, "{preserve:?}");
        assert!(preserve.iter().all(|diagnostic| {
            diagnostic.severity == Severity::Warning && diagnostic.message.contains("Error 9")
        }));
        assert!(
            preserve
                .iter()
                .any(|diagnostic| diagnostic.message.contains("wrong_rank"))
        );
        assert!(
            preserve
                .iter()
                .any(|diagnostic| diagnostic.message.contains("wrong_lower"))
        );
        assert!(
            preserve
                .iter()
                .any(|diagnostic| diagnostic.message.contains("wrong_upper"))
        );
    }

