    #[test]
    fn routes_possible_computed_jump_index_errors_through_on_error_handler() {
        let source = SourceUnit {
            name: "ComputedJumpErrors.bas".into(),
            text: "Public Sub Dispatch(ByVal index As Integer)\nOn Error GoTo Handler\nOn index GoTo FirstLabel, SecondLabel\nExit Sub\nFirstLabel:\nExit Sub\nSecondLabel:\nExit Sub\nHandler:\nResume Next\nEnd Sub\n".into(),
        };
        let analysis = analyze(&[source], &AnalysisOptions::default()).unwrap();
        let graph = &analysis.control_flow[0];
        let dispatch = graph
            .nodes
            .iter()
            .find(|node| node.kind == "on_goto")
            .unwrap();
        let handler = graph
            .nodes
            .iter()
            .find(|node| node.kind == "label" && node.label == "Handler")
            .unwrap();
        assert!(graph.edges.iter().any(|edge| {
            edge.from == dispatch.id
                && edge.to == handler.id
                && edge.condition.as_deref().is_some_and(|condition| {
                    condition.contains("possible fault") && condition.contains("handler")
                })
        }));
        assert!(!graph.complete);
    }

