    #[test]
    fn resolves_every_on_jump_label_and_reports_missing_destinations() {
        let source = SourceUnit {
            name: "ComputedJumps.bas".into(),
            text: "Public Sub Choose(ByVal selected As Integer)\nOn selected GoTo First, Missing\nOn selected GoSub Second, First\nExit Sub\nFirst:\nExit Sub\nSecond:\nReturn\nEnd Sub\n".into(),
        };
        let analysis = analyze(&[source], &AnalysisOptions::default()).unwrap();
        let missing = analysis
            .diagnostics
            .iter()
            .filter(|diagnostic| diagnostic.code == "VBA2041")
            .collect::<Vec<_>>();
        assert_eq!(missing.len(), 1, "{:?}", analysis.diagnostics);
        assert!(missing[0].message.contains("Missing"));
        for name in ["First", "Second"] {
            assert!(analysis.references.iter().any(|reference| {
                reference.procedure.as_deref() == Some("Choose")
                    && reference.name == name
                    && reference.resolution == "resolved_local_label"
            }));
        }
        assert!(analysis.references.iter().any(|reference| {
            reference.procedure.as_deref() == Some("Choose")
                && reference.name == "Missing"
                && reference.resolution == "unresolved_label"
        }));
        assert!(
            analysis.control_flow[0]
                .nodes
                .iter()
                .any(|node| node.kind == "on_goto")
        );
        assert!(!analysis.control_flow[0].complete);
    }

