    #[test]
    fn validates_known_excel_workbook_and_worksheet_event_signatures() {
        let sources = [
            SourceUnit {
                name: "ThisWorkbook.cls".into(),
                text: "Private Sub Workbook_Open()\nEnd Sub\nPrivate Sub Workbook_BeforeClose(ByVal Cancel As Long)\nEnd Sub\nPrivate Sub Workbook_BeforeSave(ByVal SaveAsUI As Boolean, Cancel As Boolean)\nEnd Sub\nPrivate Sub Workbook_SheetChange(ByVal Sh As Worksheet, ByVal Target As Range)\nEnd Sub\nPrivate Sub Workbook_SheetBeforeDoubleClick(ByVal Sh As Object, ByVal Target As Range, Cancel As Boolean)\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "Sheet1.cls".into(),
                text: "Private Sub Worksheet_Change(ByVal Target As Range)\nEnd Sub\nPrivate Sub Worksheet_SelectionChange(ByVal Target As Excel.Range)\nEnd Sub\nPrivate Sub Worksheet_BeforeDoubleClick(ByVal Target As Range, Cancel As Long)\nEnd Sub\n".into(),
            },
        ];
        let analysis = analyze(
            &sources,
            &AnalysisOptions {
                host_profile: HostProfile::Excel,
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        let mismatches = analysis
            .diagnostics
            .iter()
            .filter(|diagnostic| diagnostic.code == "VBA2143")
            .collect::<Vec<_>>();
        assert_eq!(mismatches.len(), 3, "{mismatches:#?}");
        assert!(mismatches.iter().all(|diagnostic| {
            diagnostic.severity == Severity::Error && diagnostic.message.contains("does not match")
        }));
        for (module, procedure) in [
            ("ThisWorkbook", "Workbook_Open"),
            ("ThisWorkbook", "Workbook_BeforeSave"),
            ("ThisWorkbook", "Workbook_SheetBeforeDoubleClick"),
            ("Sheet1", "Worksheet_Change"),
            ("Sheet1", "Worksheet_SelectionChange"),
        ] {
            assert!(
                analysis
                    .entry_points
                    .iter()
                    .any(|entry| { entry.module == module && entry.procedure == procedure })
            );
        }
        for (module, procedure) in [
            ("ThisWorkbook", "Workbook_BeforeClose"),
            ("ThisWorkbook", "Workbook_SheetChange"),
            ("Sheet1", "Worksheet_BeforeDoubleClick"),
        ] {
            assert!(
                !analysis
                    .entry_points
                    .iter()
                    .any(|entry| { entry.module == module && entry.procedure == procedure })
            );
        }
    }

    #[test]
    fn resolves_excel_application_withevents_handlers_as_host_entry_candidates() {
        let source = SourceUnit {
            name: "ExcelEvents.cls".into(),
            text: "Private WithEvents app As Excel.Application\nPrivate WithEvents invalidApp As Application\nPrivate Sub app_WorkbookOpen(ByVal Wb As Excel.Workbook)\nEnd Sub\nPrivate Sub app_WorkbookBeforeClose(ByVal Wb As Workbook, Cancel As Boolean)\nEnd Sub\nPrivate Sub app_WorkbookBeforeSave(ByVal Wb As Workbook, ByVal SaveAsUI As Boolean, Cancel As Boolean)\nEnd Sub\nPrivate Sub app_WorkbookActivate(ByVal Wb As Workbook)\nEnd Sub\nPrivate Sub app_WorkbookDeactivate(ByVal Wb As Workbook)\nEnd Sub\nPrivate Sub app_SheetChange(ByVal Sh As Object, ByVal Target As Range)\nEnd Sub\nPrivate Sub app_SheetSelectionChange(ByVal Sh As Object, ByVal Target As Range)\nEnd Sub\nPrivate Sub app_SheetBeforeDoubleClick(ByVal Sh As Object, ByVal Target As Range, Cancel As Boolean)\nEnd Sub\nPrivate Sub app_SheetBeforeRightClick(ByVal Sh As Object, ByVal Target As Range, Cancel As Boolean)\nEnd Sub\nPrivate Sub app_SheetActivate(ByVal Sh As Object)\nEnd Sub\nPrivate Sub app_SheetDeactivate(ByVal Sh As Object)\nEnd Sub\nPrivate Sub app_SheetCalculate(ByVal Sh As Object)\nEnd Sub\nPrivate Sub invalidApp_WorkbookOpen(ByVal Wb As Long)\nEnd Sub\n".into(),
        };
        let analysis = analyze(
            &[source],
            &AnalysisOptions {
                host_profile: HostProfile::Excel,
                ..AnalysisOptions::default()
            },
        )
        .unwrap();
        let application_entries = analysis
            .entry_points
            .iter()
            .filter(|entry| entry.trigger == "excel_application_event_handler_candidate")
            .collect::<Vec<_>>();
        assert_eq!(application_entries.len(), 12, "{application_entries:#?}");
        assert!(
            application_entries
                .iter()
                .all(|entry| entry.module == "ExcelEvents")
        );
        assert!(
            !application_entries
                .iter()
                .any(|entry| entry.procedure == "invalidApp_WorkbookOpen")
        );
        assert!(analysis.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "VBA2144" && diagnostic.message.contains("invalidApp_WorkbookOpen")
        }));
        let host_entry_graph = analysis
            .control_flow
            .iter()
            .find(|graph| graph.module == "ExcelEvents" && graph.procedure == "app_WorkbookOpen")
            .unwrap();
        assert!(!host_entry_graph.complete);
    }

    #[test]
    fn tracks_ontime_scheduled_procedure_entry_candidates_and_host_error_context() {
        let sources = [
            SourceUnit {
                name: "Macros.bas".into(),
                text: "Public Sub Tick()\nOn Error GoTo Failed\nErr.Raise 5\nExit Sub\nFailed:\nErr.Raise 6\nResume Next\nEnd Sub\nPublic Sub CancelOnly()\nEnd Sub\nPublic Sub NeedsArgument(ByVal value As Long)\nEnd Sub\nPublic Function NoArgumentFunction() As Long\nNoArgumentFunction = 1\nEnd Function\nPrivate Sub Hidden()\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "Widget.cls".into(),
                text: "Public Sub ClassWorker()\nEnd Sub\n".into(),
            },
            SourceUnit {
                name: "Caller.bas".into(),
                text: "Public Sub Schedule(ByVal macroName As String)\nApplication.OnTime Now, \"Tick\"\nApplication.OnTime EarliestTime:=Now, Procedure:=\"Macros.Tick\", Schedule:=True\nApplication.OnTime Now, \"CancelOnly\", Schedule:=False\nApplication.OnTime Now, \"NeedsArgument\"\nApplication.OnTime Now, \"NoArgumentFunction\"\nApplication.OnTime Now, \"Hidden\"\nApplication.OnTime Now, \"Widget.ClassWorker\"\nApplication.OnTime Now, macroName\nApplication.OnTime Procedure:=\"CancelOnly\"\nApplication.OnTime Now\nEnd Sub\n".into(),
            },
        ];
        let analysis = analyze(
            &sources,
            &AnalysisOptions {
                host_profile: HostProfile::Excel,
                ..AnalysisOptions::default()
            },
        )
        .unwrap();

        let ontime_calls = analysis
            .calls
            .iter()
            .filter(|call| call.module == "Caller" && call.target == "Application.OnTime")
            .collect::<Vec<_>>();
        assert_eq!(ontime_calls.len(), 10, "{ontime_calls:#?}");
        assert_eq!(
            ontime_calls
                .iter()
                .filter(|call| call.resolution == "excel_ontime_schedule_target_candidate")
                .count(),
            3,
            "both Tick schedules and the zero-argument Function remain candidates"
        );
        assert!(ontime_calls.iter().any(|call| {
            call.resolution == "excel_ontime_cancel_candidate"
                && call.dispatch_candidates == ["Macros.CancelOnly"]
        }));
        assert!(ontime_calls.iter().any(|call| {
            call.resolution == "dynamic_excel_ontime_schedule_candidate"
                && call.dispatch_candidates.is_empty()
        }));
        assert_eq!(
            analysis
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == "VBA2142")
                .count(),
            2
        );
        assert_eq!(
            analysis
                .entry_points
                .iter()
                .filter(|entry| entry.trigger == "excel_ontime_scheduled_macro_candidate")
                .count(),
            2
        );
        assert!(analysis.entry_points.iter().any(|entry| {
            entry.module == "Macros"
                && entry.procedure == "Tick"
                && entry.trigger == "excel_ontime_scheduled_macro_candidate"
        }));
        assert!(
            !analysis
                .entry_points
                .iter()
                .any(|entry| { entry.module == "Macros" && entry.procedure == "CancelOnly" })
        );
        let tick_graph = analysis
            .control_flow
            .iter()
            .find(|graph| graph.module == "Macros" && graph.procedure == "Tick")
            .unwrap();
        assert!(tick_graph.edges.iter().any(|edge| {
            edge.condition.as_deref().is_some_and(|condition| {
                condition.contains("possible unhandled error terminates host entry")
            })
        }));
    }

    #[test]
    fn resolves_external_declare_calls_as_a_separate_boundary() {
        let src = "Private Declare PtrSafe Function Sleep Lib \"kernel32\" Alias \"SleepImpl\" (ByVal milliseconds As LongPtr) As Long\nPublic Sub Pause()\nDim milliseconds As LongPtr\nSleep milliseconds\nEnd Sub\n";
        let a = analyze(
            &[SourceUnit {
                name: "Api.bas".into(),
                text: src.into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let call = a.calls.iter().find(|c| c.target == "Sleep").unwrap();
        assert_eq!(call.resolution, "resolved_external_declaration");
        assert_eq!(call.argument_count, Some(1));
        assert_eq!(call.external_library.as_deref(), Some("kernel32"));
        assert_eq!(call.external_alias.as_deref(), Some("SleepImpl"));
        assert!(a.data_flow.iter().any(|fact| {
            fact.transfer == "external_argument_input_candidate"
                && fact.target == "kernel32!SleepImpl.milliseconds"
                && fact.inputs == ["milliseconds"]
        }));
        assert!(
            a.data_accesses
                .iter()
                .any(|d| d.operation == "external_api_call_candidate")
        );
    }
    #[test]
    fn reports_vba_file_io_and_filesystem_statement_candidates() {
        let source = SourceUnit {
            name: "Files.bas".into(),
            text: "Option Explicit\nPublic Sub Process()\nDim path As String\nDim otherPath As String\nDim lineText As String\nDim record As Long\nDim amount As Long\nDim firstValue As Variant\nDim secondValue As Variant\nOpen path For Input As #1\nLine Input #1, lineText\nGet #1, , record\nInput #1, firstValue, secondValue\nPut #1, 2, amount\nWrite #1, amount, record\nPrint #1, lineText\nClose #1\nKill path\nFileCopy path, otherPath\nName path As otherPath\nEnd Sub\n".into(),
        };
        let a = analyze(&[source], &AnalysisOptions::default()).unwrap();
        assert!(a.data_accesses.iter().any(|fact| {
            fact.operation == "file_io_candidate" && fact.target.starts_with("Open path For Input")
        }));
        assert!(
            a.data_accesses.iter().any(|fact| {
                fact.operation == "file_io_candidate" && fact.target.starts_with("Line")
            }),
            "{:?}",
            a.data_accesses
        );
        assert!(a.references.iter().any(|reference| {
            reference.name == "Get" && reference.resolution == "vba_file_io_statement"
        }));
        assert!(a.data_accesses.iter().any(|fact| {
            fact.operation == "filesystem_operation_candidate"
                && fact.target.starts_with("FileCopy")
        }));
        assert!(a.data_accesses.iter().any(|fact| {
            fact.operation == "filesystem_operation_candidate" && fact.target.starts_with("Kill")
        }));
        assert!(a.data_flow.iter().any(|fact| {
            fact.transfer == "file_read_candidate"
                && fact.target == "record"
                && fact.inputs == ["file#1"]
        }));
        assert!(a.data_flow.iter().any(|fact| {
            fact.transfer == "file_write_candidate"
                && fact.target == "file#1"
                && fact.inputs.contains(&"amount".into())
        }));
    }
