    #[test]
    fn keeps_equal_paramarray_text_values_in_distinct_slots() {
        let src = "Private Sub Record(ParamArray values() As Variant)\nEnd Sub\nPublic Sub Caller()\nRecord(\"same\", \"same\")\nEnd Sub\n";
        let a = analyze(
            &[SourceUnit {
                name: "ParamArrayDuplicate.bas".into(),
                text: src.into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        let facts = a
            .data_flow
            .iter()
            .filter(|fact| {
                fact.transfer == "procedure_argument_input_candidate"
                    && fact
                        .target
                        .eq_ignore_ascii_case("ParamArrayDuplicate.Record.values")
            })
            .collect::<Vec<_>>();
        assert_eq!(facts.len(), 2, "{facts:#?}");
        assert_eq!(facts[0].argument_slot_index, Some(0));
        assert_eq!(facts[1].argument_slot_index, Some(1));
        assert_eq!(facts[0].value_expression.as_deref(), Some("\"same\""));
        assert_eq!(facts[1].value_expression.as_deref(), Some("\"same\""));
        let snapshots = a
            .interprocedural_argument_value_paths
            .iter()
            .filter(|fact| fact.parameter.eq_ignore_ascii_case("values"))
            .map(|fact| (fact.argument_slot_index, fact.actual_expression.clone()))
            .collect::<Vec<_>>();
        assert!(
            snapshots.contains(&(Some(0), Some("\"same\"".into()))),
            "{snapshots:#?}"
        );
        assert!(
            snapshots.contains(&(Some(1), Some("\"same\"".into()))),
            "{snapshots:#?}"
        );
        let compositions = a
            .interprocedural_argument_composition_paths
            .iter()
            .filter(|fact| fact.parameter.eq_ignore_ascii_case("values"))
            .map(|fact| fact.argument_slot_index)
            .collect::<Vec<_>>();
        assert!(compositions.contains(&Some(0)), "{compositions:#?}");
        assert!(compositions.contains(&Some(1)), "{compositions:#?}");
    }
