    #[test]
    fn does_not_resolve_a_private_external_declaration_across_modules() {
        let sources = [
            SourceUnit {
                name: "Native.bas".into(),
                text: "Private Declare Function Native Lib \"native\" () As Long\n".into(),
            },
            SourceUnit {
                name: "Caller.bas".into(),
                text: "Public Sub Caller()\nNative()\nEnd Sub\n".into(),
            },
        ];
        let a = analyze(&sources, &AnalysisOptions::default()).unwrap();
        assert!(a.calls.iter().any(|c| {
            c.target == "Native" && c.resolution == "inaccessible_private_external_declaration"
        }));
        assert!(a.diagnostics.iter().any(|d| d.code == "VBA2021"));
    }
    #[test]
    fn retains_both_iif_result_calls_as_evaluated_operands() {
        let src = "Public Function Pick(ByVal condition As Boolean) As String\nPick = IIf(condition, FirstValue(), SecondValue())\nEnd Function\nPrivate Function FirstValue() As String\nFirstValue = \"a\"\nEnd Function\nPrivate Function SecondValue() As String\nSecondValue = \"b\"\nEnd Function\n";
        let a = analyze(
            &[SourceUnit {
                name: "IIf.bas".into(),
                text: src.into(),
            }],
            &AnalysisOptions::default(),
        )
        .unwrap();
        assert!(a.calls.iter().any(|c| c.target == "FirstValue"));
        assert!(a.calls.iter().any(|c| c.target == "SecondValue"));
        assert!(a.diagnostics.iter().any(|d| d.code == "VBA2010"));
    }
